// Source file: nfapi_rx_indication_pdu_manager.c
#include "nfapi_rx_indication_pdu_manager.h"

// Define the default capacity of the RX indication PDU lists and maps
#define NFAPI_RX_INDICATION_PDU_LIST_DEFAULT_CAPACITY 1024
#define NFAPI_RX_INDICATION_PDU_UID_MAP_DEFAULT_CAPACITY 65536

// Define the structure for holding the state of the RX indication PDU manager
typedef struct {
    nfapi_rx_indication_pdu_list_t* pdu_list;   // List of RX indication PDUs
    nfapi_rx_indication_pdu_uid_map_t* uid_map;  // Map of UE IDs to RX indication PDU lists
} nfapi_rx_indication_pdu_manager_state_t;

// Define the global state of the RX indication PDU manager
static nfapi_rx_indication_pdu_manager_state_t nfapi_rx_indication_pdu_manager_state = {NULL, NULL};

// Function for creating a new RX indication PDU list
nfapi_rx_indication_pdu_list_t* nfapi_create_rx_indication_pdu_list(void) {
    // Create the new RX indication PDU list and set its capacity to the default value
    nfapi_rx_indication_pdu_list_t* pdu_list = (nfapi_rx_indication_pdu_list_t*) malloc(sizeof(nfapi_rx_indication_pdu_list_t));
    pdu_list->capacity = NFAPI_RX_INDICATION_PDU_LIST_DEFAULT_CAPACITY;
    pdu_list->size = 0;
    pdu_list->pdus = (nfapi_rx_indication_pdu_t*) malloc(sizeof(nfapi_rx_indication_pdu_t) * pdu_list->capacity);
    return pdu_list;
}

// Function for destroying an existing RX indication PDU list
void nfapi_destroy_rx_indication_pdu_list(nfapi_rx_indication_pdu_list_t* pdu_list) {
    // Free the memory used by the RX indication PDU list
    free(pdu_list->pdus);
    free(pdu_list);
}

// Function for adding a new PDU to an existing RX indication PDU list
bool nfapi_add_rx_indication_pdu(nfapi_rx_indication_pdu_list_t* pdu_list, uint32_t ue_id, uint8_t rrc_state, double snr, int64_t timestamp) {
    // Check if the RX indication PDU list is full
    if (pdu_list->size >= pdu_list->capacity) {
        // If it is full, increase its capacity by 1024 and reallocate more memory for the PDUS
        uint32_t new_capacity = pdu_list->capacity + NFAPI_RX_INDICATION_PDU_LIST_DEFAULT_CAPACITY;
        nfapi_rx_indication_pdu_t* new_pdus = (nfapi_rx_indication_pdu_t*) realloc(pdu_list->pdus, sizeof(nfapi_rx_indication_pdu_t) * new_capacity);
        if (!new_pdus) {
            // If the reallocation fails, return an error
            return false;
        } else {
            pdu_list->pdus = new_pdus;
            pdu_list->capacity = new_capacity;
        }
    }

    // Add the new PDU to the RX indication PDU list
    nfapi_rx_indication_pdu_t* new_pdu = &(pdu_list->pdus[pdu_list->size]);
    new_pdu->ue_id = ue_id;
    new_pdu->rrc_state = rrc_state;
    new_pdu->snr = snr;
    new_pdu->timestamp = timestamp;
    pdu_list->size++;
    return true;
}

// Function for removing a PDU from an existing RX indication PDU list
bool nfapi_remove_rx_indication_pdu(nfapi_rx_indication_pdu_list_t* pdu_list, uint32_t ue_id) {
    // Find the index of the specified UE ID in the RX indication PDU list
    int index = -1;
    for (uint32_t i = 0; i < pdu_list->size; i++) {
        if (pdu_list->pdus[i].ue_id == ue_id) {
            index = i;
            break;
        }
    }

    // Check if the UE ID was found in the RX indication PDU list
    if (index == -1) {
        return false;
    }

    // Shift all the subsequent PDUS to fill the gap caused by removing the specified PDU
    for (uint32_t i = index; i < pdu_list->size - 1; i++) {
        pdu_list->pdus[i] = pdu_list->pdus[i + 1];
    }

    // Decrease the size of the RX indication PDU list by 1
    pdu_list->size--;
    return true;
}

// Function for clearing all PDUS from an existing RX indication PDU list
void nfapi_clear_rx_indication_pdu(nfapi_rx_indication_pdu_list_t* pdu_list) {
    // Reset the size of the RX indication PDU list to 0
    pdu_list->size = 0;
}

// Function for destroying an existing RX indication PDU list
void nfapi_destroy_rx_indication_pdu_list(nfapi_rx_indication_pdu_list_t* pdu_list) {
    // Free the memory used by the RX indication PDU list
    free(pdu_list->pdus);
    free(pdu_list);
}

// Function for creating a new RX data PDU list
nfapi_rx_data_pdu_list_t* nfapi_create_rx_data_pdu_list() {
    // Allocate memory for the RX data PDU list
    nfapi_rx_data_pdu_list_t* pdu_list = (nfapi_rx_data_pdu_list_t*) malloc(sizeof(nfapi_rx_data_pdu_list_t));
    if (!pdu_list) {
        // If the allocation fails, return an error
        return NULL;
    }

    // Initialize the size and capacity of the RX data PDU list to 0
    pdu_list->size = 0;
    pdu_list->capacity = 0;

    // Allocate memory for the array of RX data PDUs
    pdu_list->pdus = (nfapi_rx_data_pdu_t*) malloc(sizeof(nfapi_rx_data_pdu_t) * pdu_list->capacity);
    if (!pdu_list->pdus) {
        // If the allocation fails, free the memory for the RX data PDU list and return an error
        free(pdu_list);
        return NULL;
    }

    // Return the new RX data PDU list
    return pdu_list;
}

// Function for adding a new RX data PDU to an existing RX data PDU list
bool nfapi_add_rx_data_pdu(nfapi_rx_data_pdu_list_t* pdu_list, uint32_t ue_id, uint8_t *data, uint16_t len) {
    // Check if the RX data PDU list is full
    if (pdu_list->size >= pdu_list->capacity) {
        // If it is full, increase its capacity by 1024 and reallocate more memory for the PDUS
        uint32_t new_capacity = pdu_list->capacity + NFAPI_RX_DATA_PDU_LIST_DEFAULT_CAPACITY;
        nfapi_rx_data_pdu_t* new_pdus = (nfapi_rx_data_pdu_t*) realloc(pdu_list->pdus, sizeof(nfapi_rx_data_pdu_t) * new_capacity);
        if (!new_pdus) {
            // If the reallocation fails, return an error
            return false;
        } else {
            pdu_list->pdus = new_pdus;
            pdu_list->capacity = new_capacity;
        }
    }

    // Add the new RX data PDU to the list
    nfapi_rx_data_pdu_t* new_pdu = &(pdu_list->pdus[pdu_list->size]);
    new_pdu->ue_id = ue_id;
    new_pdu->data = data;
    new_pdu->len = len;
    pdu_list->size++;
    return true;
}

// Function for removing a RX data PDU from an existing RX data PDU list
bool nfapi_remove_rx_data_pdu(nfapi_rx_data_pdu_list_t* pdu_list, uint32_t ue_id) {
    // Find the index of the specified UE ID in the RX data PDU list
    int index = -1;
    for (int i = 0; i < pdu_list->size; ++i) {
        if (pdu_list->pdus[i].ue_id == ue_id) {
            index = i;
            break;
        }
    }

    // If the UE ID was not found, return an error
    if (index < 0) {
        return false;
    }

    // Remove the RX data PDU from the list
    for (int i = index; i < pdu_list->size - 1; ++i) {
        pdu_list->pdus[i] = pdu_list->pdus[i + 1];
    }
    pdu_list->size--;
    return true;
}

// Function for clearing all RX data PDUs from an existing RX data PDU list
void nfapi_clear_rx_data_pdu(nfapi_rx_data_pdu_list_t* pdu_list) {
    // Reset the size of the RX data PDU list to 0
    pdu_list->size = 0;
}

// Function for destroying an existing RX data PDU list
void nfapi_destroy_rx_data_pdu_list(nfapi_rx_data_pdu_list_t* pdu_list) {
    // Free the memory used by the RX data PDU list
    free(pdu_list->pdus);
    free(pdu_list);
