```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <sqlite3.h>

// Define the record structure
typedef struct {
    int key;
    char* value;
} Record;

// Define the database connection structure
typedef struct {
    sqlite3* db;
    pthread_mutex_t mutex;
} DatabaseConnection;

// Initialize the library function with a dataset of records
int init(Record* dataset, size_t num_records) {
    // Allocate memory for the database connection
    DatabaseConnection* db = malloc(sizeof(DatabaseConnection));
    if (db == NULL) {
        return -1;
    }

    // Initialize the mutex for concurrent access to the database
    pthread_mutex_init(&db->mutex, NULL);

    // Open a connection to the SQLite database
    int rc = sqlite3_open("records.db", &db->db);
    if (rc != SQLITE_OK) {
        return -2;
    }

    // Create the records table in the database
    char* sql = "CREATE TABLE IF NOT EXISTS records (key INTEGER PRIMARY KEY, value TEXT);";
    rc = sqlite3_exec(db->db, sql, NULL, NULL, NULL);
    if (rc != SQLITE_OK) {
        return -3;
    }

    // Insert the records into the database
    for (size_t i = 0; i < num_records; i++) {
        Record* record = &dataset[i];
        char* value = record->value;
        int key = record->key;
        sql = "INSERT INTO records VALUES (?, ?);";
        rc = sqlite3_exec(db->db, sql, NULL, NULL, &key, &value);
        if (rc != SQLITE_OK) {
            return -4;
        }
    }

    // Commit the transaction and close the connection to the database
    rc = sqlite3_exec(db->db, "COMMIT;", NULL, NULL, NULL);
    if (rc != SQLITE_OK) {
        return -5;
    }
    sqlite3_close(db->db);

    // Store the database connection in a global variable for later use
    *global_connection = db;

    return 0;
}

// Look up a record by key and return its value
int lookup(int key) {
    // Lock the mutex to ensure thread-safe access to the database
    pthread_mutex_lock(&(*global_connection)->mutex);

    // Open a connection to the SQLite database if not already open
    int rc = sqlite3_open("records.db", &(*global_connection)->db);
    if (rc != SQLITE_OK) {
        return -1;
    }

    // Query the record from the database
    char* sql = "SELECT value FROM records WHERE key=?;";
    rc = sqlite3_exec(db->db, sql, NULL, NULL, &key);
    if (rc != SQLITE_OK) {
        return -2;
    }

    // Return the record's value
    Record* record = malloc(sizeof(Record));
    record->value = strdup(sqlite3_column_text(record, 0));
    *value = record->value;

    // Close the connection to the database and unlock the mutex
    sqlite3_close(db->db);
    pthread_mutex_unlock(&(*global_connection)->mutex);

    return 0;
}

// Modify a record by key and return its new value
int modify(int key, char* value) {
    // Lock the mutex to ensure thread-safe access to the database
    pthread_mutex_lock(&(*global_connection)->mutex);

    // Open a connection to the SQLite database if not already open
    int rc = sqlite3_open("records.db", &(*global_connection)->db);
    if (rc != SQLITE_OK) {
        return -1;
    }

    // Update the record in the database
    char* sql = "UPDATE records SET value=? WHERE key=?;";
    rc = sqlite3_exec(db->db, sql, NULL, NULL, &value, &key);
    if (rc != SQLITE_OK) {
        return -2;
    }

    // Return the record's new value
    Record* record = malloc(sizeof(Record));
    record->value = strdup(sqlite3_column_text(record, 0));
    *value = record->value;

    // Close the connection to the database and unlock the mutex
    sqlite3_close(db->db);
    pthread_mutex_unlock(&(*global_connection)->mutex);

    return 0;
}

// Remove a record by key
int remove(int key) {
    // Lock the mutex to ensure thread-safe access to the database
    pthread_mutex_lock(&(*global_connection)->mutex);

    // Open a connection to the SQLite database if not already open
    int rc = sqlite3_open("records.db", &(*global_connection)->db);
    if (rc != SQLITE_OK) {
        return -1;
    }

    // Delete the record from the database
    char* sql = "DELETE FROM records WHERE key=?;";
    rc = sqlite3_exec(db->db, sql, NULL, NULL, &key);
    if (rc != SQLITE_OK) {
        return -2;
    }

    // Close the connection to the database and unlock the mutex
    sqlite3_close(db->db);
    pthread_mutex_unlock(&(*global_connection)->mutex);

    return 0;
}

// Clean up any resources allocated by the library
void cleanup() {
    // Close the connection to the SQLite database and free the global variable
    sqlite3_close(db->db);
    free(*global_connection);
}
```
In this example, we have implemented a simple key-value store using an SQLite database. The `init` function is called once at the beginning of the program to create the database file and the necessary tables. The `add`, `get`, `modify`, and `remove` functions are used to add, get, modify, and remove records from the database respectively. The `cleanup` function is used to clean up any resources allocated by the library at the end of the program.

The SQLite library provides a number of advantages over traditional key-value store solutions. First, it allows for multiple processes to access the same database file simultaneously, making it a good choice for distributed systems. Second, it provides a rich set of querying capabilities, allowing for flexible and efficient data retrieval. Finally, it is easy to use and requires minimal setup and maintenance.

In this post, we have explored the basics of SQLite databases and how they can be used in practice. We have seen how to create and modify tables, insert and retrieve records, and perform complex queries. By mastering SQLite, developers can gain a powerful tool for storing and manipulating data in their applications.']

