// Define a function to count the number of lines in a file
int count_lines(char* input) {
  int line_count = 0;
  char* newline = strchr(input, '\n');
  while (newline) {
    line_count++;
    input = newline + 1;
    newline = strchr(input, '\n');
  }
  return line_count;
}

