// Define a function to get the contents of a file
char* get_file_contents(char* filename) {
  FILE* file = fopen(filename, "r");
  if (file == NULL) {
    printf("Error: could not open %s\n", filename);
    return NULL;
  }

  // Get the size of the file
  fseek(file, 0, SEEK_END);
  long size = ftell(file);
  rewind(file);

  // Allocate memory for the file contents
  char* contents = (char*)malloc(size + 1);
  if (contents == NULL) {
    printf("Error: could not allocate memory for %s\n", filename);
    fclose(file);
    return NULL;
  }

  // Read the file contents into the buffer
  size_t bytes_read = fread(contents, sizeof(char), size, file);
  if (bytes_read != size) {
    printf("Error: could not read entire %s\n", filename);
    free(contents);
    fclose(file);
    return NULL;
  }

  // Close the file and return the contents
  fclose(file);
  return contents;
}

// Define a function to initialize threads for processing input files
void init_threads(char* input_dir, char* output_dir, enum ProcessingMode mode) {
  int num_files = get_num_files(input_dir);

  // Initialize the thread pool
  pthread_t threads[num_files];
  for (int i = 0; i < num_files; i++) {
    InputFileData* input_data = malloc(sizeof(InputFileData));
    if (input_data == NULL) {
      printf("Error: could not allocate memory for thread data\n");
      return;
    }
    input_data->filename = get_file_path(input_dir, i);
    input_data->mode = mode;

    // Create a new thread for processing the file
    int rc = pthread_create(&threads[i], NULL, process_input_file, input_data);
    if (rc) {
      printf("Error: could not create thread for %s\n", input_data->filename);
      free(input_data);
      return;
    }
  }

  // Wait for all threads to complete
  for (int i = 0; i < num_files; i++) {
    pthread_join(threads[i], NULL);
  }
}

// Define a function to process an input file in parallel using threads
void* process_input_file(void* arg) {
  InputFileData* input_data = (InputFileData*)arg;

  // Perform the necessary processing on the input file
  char* output = NULL;
  switch (input_data->mode) {
    case LINE_COUNTING:
      output = count_lines(input_data->filename);
      break;
    case KEYWORD_EXTRACTION:
      output = extract_keywords(input_data->filename);
      break;
  }

  // Write the output to a file
  char* filename = get_file_path(output_dir, input_data->filename);
  FILE* file = fopen(filename, "w");
  if (file == NULL) {
    printf("Error: could not open %s\n", filename);
    free(input_data);
    return;
  }

  // Write the output to the file
  size_t bytes_written = fwrite(output, sizeof(char), strlen(output), file);
  if (bytes_written != strlen(output)) {
    printf("Error: could not write entire %s\n", filename);
    free(input_data);
    return;
  }

  // Close the file and free memory
  fclose(file);
  free(input_data);
  return NULL;
}

