    num_files++;
  }

  // Close the directory and return the number of files
  closedir(dip);
  return num_files;
}

// Define a function to get the path of a file in a directory
char* get_file_path(char* dir, int index) {
  DIR *dip;
  struct dirent *dit;

  // Open the directory
  dip = opendir(dir);
  if (dip == NULL) {
    printf("Error: could not open %s\n", dir);
    return NULL;
  }

  // Read the directory entries until we reach the desired index
  int current_index = 0;
  while ((dit = readdir(dip)) != NULL) {
    if (current_index == index) {
      break;
    }
    current_index++;
  }

  // Close the directory and return the file path
  closedir(dip);
  return dit->d_name;
}

int main() {
  char* input_dir = "/path/to/input/directory";
  char* output_dir = "/path/to/output/directory";
  enum ProcessingMode mode = LINE_COUNTING; // or KEYWORD_EXTRACTION

  init_threads(input_dir, output_dir, mode);
}
```
This code creates a thread pool for processing multiple input files simultaneously using the `pthread` library. The `init_threads()` function initializes the thread pool and starts processing each file in the input directory using a separate thread. Each thread reads the input file, performs the necessary processing (either line counting or keyword extraction), and writes the output to a file in the output directory. The program then waits for all threads to complete before exiting.

This code is quite complex and requires careful attention to detail. For example, it is important to check for errors when reading and writing files, as well as when opening and closing directories. Additionally, it is important to ensure that the output directory exists and is writable by the program. If any of these checks fail, the program should exit with an appropriate error message.

