// Structure to store metadata about the integer array
typedef struct {
    int count; // Total number of integers in the array
    int duplicates; // Number of duplicate integers in the array
    int largest; // Largest integer in the array
} IntArrayMetadata;

// Function to find the largest integer in an array of integers
int int_max_finder(const char *filepath, int max_size) {
    // Initialize variables
    FILE *file = NULL;
    int i = 0, j = 0, count = 0, duplicates = 0, largest = -1;
    int *array = NULL;
    IntArrayMetadata metadata = { 0 };
    char line[256]; // Maximum length of a line in the file is 255 characters + null terminator

    // Open the input file and check for errors
    file = fopen(filepath, "r");
    if (file == NULL) {
        perror("Error opening file");
        return -1;
    }

    // Read each line from the file and store the integers in an array
    while (fgets(line, sizeof(line), file)) {
        count++;
        for (i = 0; i < strlen(line); i++) {
            if (!isspace(line[i])) { // Ignore whitespace characters
                array[j] = atoi(&line[i]);
                j++;
            }
        }
    }

    // Check for errors in reading the file and close it
    if (ferror(file)) {
        perror("Error reading from file");
        fclose(file);
        return -1;
    }
    fclose(file);

    // Initialize the metadata struct with the count of integers read from the file
    metadata.count = count;

    // Sort the array in ascending order using a simple bubble sort algorithm
    for (i = 0; i < count - 1; i++) {
        for (j = i + 1; j < count; j++) {
            if (array[i] > array[j]) {
                int temp = array[i];
                array[i] = array[j];
                array[j] = temp;
            }
        }
    }

    // Find the largest integer in the sorted array and store it in the metadata struct
    for (i = 0; i < count; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    metadata.largest = largest;

    // Check for duplicate integers in the array and update the metadata struct accordingly
    for (i = 0; i < count - 1; i++) {
        if (array[i] == array[i + 1]) {
            duplicates++;
        }
    }
    metadata.duplicates = duplicates;

    // Free the memory allocated for the array
    free(array);

    return largest;
}
