    if (send(sockfd, message->data, message->length, 0) < 0) {
        perror("Error sending message");
        return -1;
    }
    return 0;
}

int receive_message(csp_message* message, int sockfd) {
    // Receive message from CSP over TCP socket
    if (recv(sockfd, &message->data, sizeof(message->data), 0) < 0) {
        perror("Error receiving message");
        return -1;
    }
    return 0;
}

int connect_to_csp() {
    // Connect to CSP over TCP socket
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("Error opening socket");
        return -1;
    }
    struct sockaddr_in server_address;
    memset(&server_address, 0, sizeof(server_address));
    server_address.sin_family = AF_INET;
    server_address.sin_port = htons(CSP_PORT);
    if (inet_pton(AF_INET, CSP_HOST, &server_address.sin_addr) <= 0) {
        perror("Error resolving hostname");
        return -1;
    }
    if (connect(sockfd, (struct sockaddr*)&server_address, sizeof(server_address)) < 0) {
        perror("Error connecting to CSP");
        return -1;
    }
    return sockfd;
}

int disconnect_from_csp(int sockfd) {
    // Disconnect from CSP over TCP socket
    if (close(sockfd) < 0) {
        perror("Error closing socket");
        return -1;
    }
    return 0;
}

