    const char* mode = getenv("MODE");
    if (mode == NULL) {
        printf("Error: MODE not set\n");
        return -1;
    }
    // Initialize cryptographic key and socket to CSP
    cryptographic_key key;
    int sockfd = connect_to_csp();
    if (sockfd < 0) {
        perror("Error connecting to CSP");
        return -1;
    }
    // Loop indefinitely, accepting requests and responding with encryption/decryption results
    while (true) {
        csp_message request;
        if (receive_message(&request, sockfd) < 0) {
            perror("Error receiving message from CSP");
            break;
        }
        // Process the received request, encrypting or decrypting as needed
        cryptographic_key* key_ptr = &key;
        unsigned char* ciphertext = NULL;
        int ret = -1;
        if (strcmp(algorithm, "aes-256-cbc") == 0 && strcmp(mode, "gcm") == 0) {
            ret = encrypt(request.data, request.length, key_ptr, &ciphertext);
        } else if (strcmp(algorithm, "aes-256-cbc") == 0 && strcmp(mode, "gcm") == 0) {
            ret = decrypt(request.data, request.length, key_ptr, &ciphertext);
        } else {
            printf("Error: Unsupported algorithm or mode\n");
        }
        if (ret < 0) {
            // Log error information and provide feedback to operator
            perror("Error processing request");
            csp_message response;
            response.data = "Error processing request";
            response.length = strlen(response.data);
            if (send_message(&response, sockfd) < 0) {
                perror("Error sending message to CSP");
            }
        } else {
            // Send response back to CSP with encryption/decryption results
            csp_message response;
            response.data = ciphertext;
            response.length = strlen(response.data);
            if (send_message(&response, sockfd) < 0) {
                perror("Error sending message to CSP");
            } else {
                free(ciphertext);
            }
        }
    }
    disconnect_from_csp(sockfd);
    return 0;
}']

