#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <semaphore.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <error.h>

// Configuration variables
static char* semaphore_name = "my_semaphore";
static int initial_value = 1;
static int logging_level = 0; // 0: none, 1: error, 2: debug
static char* logging_destination = "/dev/stdout";

// Logging functions
void log_message(int level, const char* message) {
    if (level <= logging_level) {
        fprintf(stderr, "%s\n", message);
    }
}

void log_error(const char* message) {
    log_message(1, "Error: %s", message);
}

// Semaphore functions
void semaphore_init(semaphore_t* semaphore) {
    if ((semaphore->value = initial_value) == 0) {
        // Invalid initial value. Set to 1.
        log_error("Invalid initial value");
        return;
    }

    // Create the semaphore
    semaphore->sem = sem_open(semaphore_name, O_CREAT | O_EXCL, S_IRUSR | S_IWUSR, 0);
    if (semaphore->sem == SEM_FAILED) {
        // Failed to create the semaphore. Error and return.
        log_error("Failed to create semaphore");
        return;
    }
}

void semaphore_destroy(semaphore_t* semaphore) {
    if (semaphore->value != 0) {
        // Semaphore was created. Close it.
        sem_close(semaphore->sem);
    }

    // Remove the semaphore
    sem_unlink(semaphore_name);
}

int semaphore_wait(semaphore_t* semaphore) {
    if (semaphore->value == 0) {
        return -1;
    }

    int ret = sem_wait(semaphore->sem);
    if (ret != 0) {
        log_error("Failed to wait on semaphore");
        return -2;
    }

    // Decrement the value of the semaphore
    semaphore->value--;

    return ret;
}

int semaphore_signal(semaphore_t* semaphore) {
    if (semaphore->value == 0) {
        return -1;
    }

    int ret = sem_post(semaphore->sem);
    if (ret != 0) {
        log_error("Failed to signal on semaphore");
        return -2;
    }

    // Increment the value of the semaphore
    semaphore->value++;

    return ret;
}

int semaphore_query(semaphore_t* semaphore) {
    return semaphore->value;
}

// Thread functions
void thread_start(semaphore_t* semaphore, void (*function)(void)) {
    pthread_create(&semaphore->thread, NULL, function, NULL);
}

void thread_join(semaphore_t* semaphore) {
    pthread_join(&semaphore->thread, NULL);
}

// Main function
int main() {
    // Initialize the semaphore
    semaphore_t semaphore;
    semaphore_init(&semaphore);

    // Create a thread that waits on the semaphore
    thread_start(&semaphore, semaphore_wait);

    // Sleep for 1 second
    sleep(1);

    // Signal on the semaphore
    semaphore_signal(&semaphore);

    // Join the thread
    thread_join(&semaphore);

    // Destroy the semaphore
    semaphore_destroy(&semaphore);

    return 0;
}
