#include <boost/asio.hpp>
#include <boost/beast/http.hpp>
#include <boost/json.hpp>
#include <iostream>
#include <string>

using namespace boost::asio;
using namespace boost::beast::http;

class ServiceManager {
private:
    io_context context_;
    tcp::resolver resolver_;
    tcp::socket socket_;
    std::string serviceName_;
    int instanceId_;
    bool started_;

public:
    ServiceManager(io_context& context, const std::string& serviceName) : context_(context), resolver_(context), serviceName_(serviceName), instanceId_(0), started_(false) {}

    void start() {
        if (started_) return;
        auto endpoint = resolver_.resolve(serviceName_);
        socket_.connect(endpoint);
        started_ = true;
    }

    void stop() {
        if (!started_) return;
        boost::json::object request;
        request["type"] = "stop";
        writeRequest(request);
        started_ = false;
    }

private:
    void writeRequest(const boost::json::object& request) {
        std::string message;
        boost::json::serialize(request, message);
        async_write(socket_, buffer(message), [this](boost::system::error_code ec, size_t) {
            if (ec) return;
            readResponse();
        });
    }

    void readResponse() {
        boost::json::value response;
        async_read(socket_, buffer(response), [this](boost::system::error_code ec, size_t) {
            if (ec) return;
            handleResponse(response);
        });
    }

    void handleResponse(const boost::json::value& response) {
        if (!started_) return;
        if (response.is_object()) {
            auto type = response["type"];
            if (type == "error") {
                std::cerr << "Error: " << response["message"].as_string() << std::endl;
            } else if (type == "stop") {
                started_ = false;
            }
        }
    }
};

int main(int argc, char* argv[]) {
    try {
        io_context context;
        ServiceManager manager(context, "localhost:8080");
        manager.start();
        manager.stop();
        return 0;
    } catch (const std::exception& e) {
        std::cerr << e.what() << std::endl;
        return 1;
    }
}']

