    public async Task<UserAuthenticationResult> AuthenticateAsync(List<UserAuthenticationRequest> requests)
    {
        var results = new List<UserAuthenticationResult>();

        foreach (var request in requests)
        {
            var result = await AuthenticateSingleRequestAsync(request);
            results.Add(result);
        }

        return new UserAuthenticationResult
        {
            Results = results,
            SuccessfulAuthentications = GetSuccessfulAuthentications(results),
            FailedAuthentications = GetFailedAuthentications(results)
        };
    }

    private async Task<UserAuthenticationResult> AuthenticateSingleRequestAsync(UserAuthenticationRequest request)
    {
        var result = new UserAuthenticationResult();

        try
        {
