function refreshDialogFields(resourceId, url) {
  const fieldNamesToRefresh = ['field1', 'field2', 'field3']; // Define the predefined list of fields to refresh
  const regexPatterns = [/Old\sTestament/i]; // Define the regular expressions for identifying references to books from the Old Testament
  const baseUrl = 'https://api.example.com'; // Define the base URL for external data sources

  return new Promise((resolve, reject) => {
    // Send a GET request to the server to fetch updated data for the specified resource ID and URL
    axios.get(`${baseUrl}/data/${resourceId}?url=${url}`)
      .then(response => {
        const updatedData = response.data;

        // Iterate through each field in the dialog and refresh the fields that match the predefined list of field names to refresh
        fieldNamesToRefresh.forEach(fieldName => {
          if (updatedData[fieldName]) {
            // Send a GET request to the server to fetch updated data for the specified field name
            axios.get(`${baseUrl}/data/${fieldName}`)
              .then(response => {
                const updatedFieldData = response.data;

                // Analyze the content of each field and identify references to books from the Old Testament using regular expressions
                Object.keys(updatedFieldData).forEach(key => {
                  if (regexPatterns.some(pattern => pattern.test(key))) {
                    const bookName = key.replace(/\W/g, '').toLowerCase();
                    updatedFieldData[bookName] = updatedFieldData[key];
                    delete updatedFieldData[key];
                  }
                });
              })
              .catch(error => {
                console.log(`Error refreshing field data: ${error}`);
              });
          }
        });

        // Return an object where each key is the name of a book from the Old Testament, and its value is the number of occurrences in the field content
        const bookCounts = {};
        Object.keys(updatedFieldData).forEach(key => {
          if (regexPatterns.some(pattern => pattern.test(key))) {
            bookCounts[key] = updatedFieldData[key];
          }
        });
        resolve(bookCounts);
      })
      .catch(error => {
        console.log(`Error refreshing data: ${error}`);
        reject(error);
      });
  });
}

