#ifndef DYNAMIC_OCTREE_H
#define DYNAMIC_OCTREE_H

#include <iostream>
#include <vector>
#include <map>
#include <thread>
#include <mutex>
#include <condition_variable>

class DynamicOctree {
 public:
  DynamicOctree();
  ~DynamicOctree();

  void insert(const std::pair<int, int>& point);
  void remove(const std::pair<int, int>& point);
  bool contains(const std::pair<int, int>& point) const;

 private:
  struct Node {
    Node* left;
    Node* right;
    std::vector<std::pair<int, int>> points;
  };

  // Root node of the octree
  Node* root_;

  // Mutex for synchronizing access to the octree
  mutable std::mutex mutex_;

  // Condition variable for signaling updates to the octree
  std::condition_variable cv_;

  // Memory quota in bytes
  size_t memoryQuota_;

  // Vector of nodes that need to be garbage collected
  std::vector<Node*> garbageNodes_;

  // Map for tracking leaf nodes and their associated data
  std::map<std::pair<int, int>, std::string> leafData_;

  // Method for inserting a new point into the octree
  void insertInternal(const std::pair<int, int>& point);

  // Method for removing a point from the octree
  void removeInternal(const std::pair<int, int>& point);

  // Method for checking if a point exists in the octree
  bool containsInternal(const std::pair<int, int>& point) const;
};

#endif // DYNAMIC_OCTREE_H
```
DynamicOctree.cpp:
```c++
#include "DynamicOctree.h"

DynamicOctree::DynamicOctree() {
  root_ = nullptr;
}

DynamicOctree::~DynamicOctree() {
  delete root_;
}

void DynamicOctree::insert(const std::pair<int, int>& point) {
  // Acquire lock on the mutex
  std::lock_guard<std::mutex> lock(mutex_);

  // Insert the point into the octree
  insertInternal(point);

  // Signal any waiting threads that an update has occurred
  cv_.notify_all();
}

void DynamicOctree::remove(const std::pair<int, int>& point) {
  // Acquire lock on the mutex
  std::lock_guard<std::mutex> lock(mutex_);

  // Remove the point from the octree
  removeInternal(point);

  // Signal any waiting threads that an update has occurred
  cv_.notify_all();
}

bool DynamicOctree::contains(const std::pair<int, int>& point) const {
  // Acquire lock on the mutex
  std::lock_guard<std::mutex> lock(mutex_);

  // Check if the point exists in the octree
  return containsInternal(point);
}

void DynamicOctree::insertInternal(const std::pair<int, int>& point) {
  // If the root node is null, create a new root node
  if (root_ == nullptr) {
    root_ = new Node;
    root_->left = nullptr;
    root_->right = nullptr;
  }

  // Insert the point into the octree
  insertInternal(point, root_);
}

void DynamicOctree::removeInternal(const std::pair<int, int>& point) {
  // If the root node is null, do nothing
  if (root_ == nullptr) {
    return;
  }

  // Remove the point from the octree
  removeInternal(point, root_);
}

bool DynamicOctree::containsInternal(const std::pair<int, int>& point) const {
  // If the root node is null, do nothing
  if (root_ == nullptr) {
    return false;
  }

  // Check if the point exists in the octree
  return containsInternal(point, root_);
}

void DynamicOctree::insertInternal(const std::pair<int, int>& point, Node* node) {
  // If the node is a leaf node, add the point to its list of points
  if (node->left == nullptr && node->right == nullptr) {
    node->points.push_back(point);
    return;
  }

  // Otherwise, recursively insert the point into the appropriate child node
  int x = point.first;
  int y = point.second;
  if (x < 0) {
    insertInternal(point, node->left);
  } else {
    insertInternal(point, node->right);
  }
}

void DynamicOctree::removeInternal(const std::pair<int, int>& point, Node* node) {
  // If the node is a leaf node, remove the point from its list of points
  if (node->left == nullptr && node->right == nullptr) {
    auto it = std::find(node->points.begin(), node->points.end(), point);
    if (it != node->points.end()) {
      node->points.erase(it);
    }
    return;
  }

  // Otherwise, recursively remove the point from the appropriate child node
  int x = point.first;
  int y = point.second;
  if (x < 0) {
    removeInternal(point, node->left);
  } else {
    removeInternal(point, node->right);
  }
}

bool DynamicOctree::containsInternal(const std::pair<int, int>& point, Node* node) const {
  // If the node is a leaf node, check if the point exists in its list of points
  if (node->left == nullptr && node->right == nullptr) {
    auto it = std::find(node->points.begin(), node->points.end(), point);
    return it != node->points.end();
  }

  // Otherwise, recursively check if the point exists in the appropriate child node
  int x = point.first;
  int y = point.second;
  if (x < 0) {
    return containsInternal(point, node->left);
  } else {
    return containsInternal(point, node->right);
  }
}
