class AsyncReducer {
  constructor(callback) {
    this.callback = callback;
    this.queue = [];
  }

  process(array) {
    const results = [];

    for (const item of array) {
      try {
        const result = await this.callback(item);
        if (result !== undefined) {
          results.push(result);
        }
      } catch (error) {
        console.log(`Error processing item: ${item}`);
