    // Output buffer for the processed string
    char* output_buffer;
    // Size of the output buffer
    size_t output_buffer_size;
} pipeline_state_t;

// Define a function to validate the external logging service connection and retry up to three times if the connection fails
void validate_external_logging_connection(void) {
    int num_attempts = 0;
    while (num_attempts < 3) {
        // Check if the external logging service is connected
        if (!is_external_logging_service_connected()) {
            // If not, attempt to reconnect up to three times
            connect_to_external_logging_service();
            num_attempts++;
        } else {
            break;
        }
    }
}

// Define a function to process a string according to the configurable string processing pipeline
void process_string(char* input_string, size_t size_limit, char** output_buffer) {
    // Validate the external logging service connection and retry up to three times if the connection fails
    validate_external_logging_connection();

    // Check if the input string exceeds the specified size limit
    if (strlen(input_string) > size_limit) {
        // If so, log an error message with the external logging service and return a NULL pointer
        log_error("Input string exceeds maximum size limit");
        *output_buffer = NULL;
        return;
    }

    // Define a pipeline state object to track the current stage being executed and the output buffer
    pipeline_state_t* pipeline_state = malloc(sizeof(pipeline_state_t));
    pipeline_state->current_stage = 0;
    pipeline_state->output_buffer = *output_buffer;
    pipeline_state->output_buffer_size = size_limit + 1;

    // Loop through each stage in the string processing pipeline
    for (int i = 0; i < pipeline_config.num_stages; i++) {
        // Execute the current stage function and update the output buffer accordingly
        pipeline_state->output_buffer = (*(pipeline_config.stages[i]))(input_string, size_limit, pipeline_state->output_buffer);
    }

    // Free the pipeline state object
    free(pipeline_state);
}

// Define a function to append a forward slash to the end of a string and return the modified string
char* add_forward_slash(char* input_string, size_t size_limit, char** output_buffer) {
    // Append a forward slash to the end of the input string
    strncat(*output_buffer, "/", size_limit - strlen(*output_buffer));

    // Return the modified string
    return *output_buffer;
}

// Define a function to handle potential race conditions when multiple threads call this function concurrently
void handle_race_conditions(char* input_string, size_t size_limit, char** output_buffer) {
