int process_line(const char* line, int vertex_count) {
    // Split the line into two parts: the vertex ID and the edge list
    const char* delimiter = " ";
    char* token = strtok(line, delimiter);
    if (token == NULL) {
        fprintf(stderr, "Error: could not split line\n");
        return -1;
    }
    int vertex_id = atoi(token);
    token = strtok(NULL, delimiter);
    if (token == NULL) {
        fprintf(stderr, "Error: could not parse vertex ID\n");
        return -1;
    }
    int edge_list[MAX_VERTEX_COUNT];
    int edge_count = 0;
    while ((token = strtok(NULL, delimiter)) != NULL) {
        int edge_id = atoi(token);
        if (edge_id > vertex_count || edge_id < 0) {
            fprintf(stderr, "Error: invalid edge ID\n");
            return -1;
        }
        edge_list[edge_count++] = edge_id;
    }

    // Compute the average degree of the last two vertices
    int avg_degree = 0;
    if (vertex_count >= 2) {
        avg_degree = (edge_list[vertex_count - 1] + edge_list[vertex_count - 2]) / 2.0;
    }

    // Add the average degree to the output list
    printf("%d %d\n", vertex_id, avg_degree);

    return 0;
}

