// Define the maximum number of digits in a filename (excluding extension)
#define MAX_DIGITS 10

// Define the maximum length of a new filename (including extension)
#define MAX_FILENAME_LEN 256

// Define the default file type if not explicitly present
#define DEFAULT_FILE_TYPE ".txt"

// Function to rename files by modifying their extensions
int renameFiles(const char* oldFilename, const char* newExtension) {
    // Check for valid inputs
    if (!oldFilename || !newExtension) {
        return -1;
    }

    // Get the file type of the original filename (if present)
    int fileTypeLength = strlen(DEFAULT_FILE_TYPE);
    char* fileType = strrchr(oldFilename, '.');
    if (!fileType) {
        fileType = DEFAULT_FILE_TYPE;
        fileTypeLength = strlen(fileType);
    }

    // Calculate the number of digits in the original filename (excluding extension)
    int numDigits = 0;
    for (int i = 0; i < MAX_DIGITS; i++) {
        if (isdigit(oldFilename[i])) {
            numDigits++;
        } else {
            break;
        }
    }

    // Generate the new filename by combining the old filename and the new extension
    char newFilename[MAX_FILENAME_LEN];
    int newFilenameLength = 0;
    for (int i = 0; i < numDigits; i++) {
        newFilename[newFilenameLength++] = oldFilename[i];
    }
    for (int i = 0; i < fileTypeLength; i++) {
        newFilename[newFilenameLength++] = newExtension[i];
    }
    newFilename[newFilenameLength] = '\0';

    // Check if the new filename already exists and handle accordingly
    struct stat fileInfo;
    int result = stat(newFilename, &fileInfo);
    if (result == 0) {
        // The new filename already exists, so we need to decide how to proceed
        // TODO: Add logic for handling existing filenames
        return -2;
    } else if (errno != ENOENT) {
        // Unexpected error checking the new filename, so we'll abort
        perror("Error checking new filename");
        return -3;
    }

    // Rename the file using a temporary name to avoid overwriting an existing file
    char tempFilename[MAX_FILENAME_LEN];
    strcpy(tempFilename, newFilename);
    strcat(tempFilename, ".tmp");
    result = rename(oldFilename, tempFilename);
    if (result != 0) {
        perror("Error renaming file");
        return -4;
    }

    // Rename the temporary file to the final destination
    result = rename(tempFilename, newFilename);
    if (result != 0) {
        perror("Error renaming file");
        return -5;
    }

    return 0;
}
```
