// Generate a secure, unique initialization vector (IV) for each encryption operation
void generate_iv(unsigned char iv[AES_BLOCK_SIZE]) {
    // Use OpenSSL's RAND_bytes function to generate an IV that is cryptographically secure
    RAND_bytes(iv, AES_BLOCK_SIZE);
}

// Encrypt a file using AES-256-CBC and store the encrypted data in a buffer
void encrypt_file(const char* filename, unsigned char* buf) {
    // Load the file into memory
    FILE* f = fopen(filename, "rb");
    if (!f) {
        printf("Error opening file\n");
        return;
    }
    size_t filesize = ftell(f);
    unsigned char* data = (unsigned char*) malloc(filesize);
    fread(data, 1, filesize, f);
    fclose(f);

    // Generate a secure, unique IV for this encryption operation
    unsigned char iv[AES_BLOCK_SIZE];
    generate_iv(iv);

    // Encrypt the file data using AES-256-CBC with the generated IV
    size_t ciphertext_len = filesize + AES_BLOCK_SIZE;
    unsigned char* ciphertext = (unsigned char*) malloc(ciphertext_len);
    AES_KEY key;
    AES_set_encrypt_key(key, 256, &key);
    AES_cbc_encrypt(data, ciphertext, filesize, key, iv, AES_ENCRYPT);

    // Store the encrypted data in the provided buffer
    memcpy(buf, ciphertext, ciphertext_len);

    // Clean up memory
    free(data);
    free(ciphertext);
}

// Decrypt a file using AES-256-CBC and verify its integrity using MD5 hashing
void decrypt_file(const char* filename, unsigned char* buf) {
    // Load the encrypted file into memory
    FILE* f = fopen(filename, "rb");
    if (!f) {
        printf("Error opening file\n");
        return;
    }
    size_t filesize = ftell(f);
    unsigned char* data = (unsigned char*) malloc(filesize);
    fread(data, 1, filesize, f);
    fclose(f);

    // Generate a secure, unique IV for this decryption operation
    unsigned char iv[AES_BLOCK_SIZE];
    generate_iv(iv);

    // Decrypt the file data using AES-256-CBC with the generated IV
    size_t plaintext_len = filesize - AES_BLOCK_SIZE;
    unsigned char* plaintext = (unsigned char*) malloc(plaintext_len);
    AES_KEY key;
    AES_set_decrypt_key(key, 256, &key);
    AES_cbc_encrypt(data, plaintext, filesize, key, iv, AES_DECRYPT);

    // Compute the MD5 hash of the decrypted data
    unsigned char md5[MD5_DIGEST_LENGTH];
    MD5((unsigned char*) plaintext, plaintext_len, md5);

    // Verify that the computed hash matches the stored hash
    if (memcmp(md5, buf, MD5_DIGEST_LENGTH) != 0) {
        printf("Error: file integrity check failed\n");
        return;
    }

    // Clean up memory
    free(data);
    free(plaintext);
}
```
Python Code:
```python
import hashlib
import os
import time

def generate_iv():
    # Use OpenSSL's RAND_bytes function to generate an IV that is cryptographically secure
    return bytes(os.urandom(16))

def encrypt_file(filename, buf):
    # Load the file into memory
    with open(filename, "rb") as f:
        data = f.read()

    # Generate a secure, unique IV for this encryption operation
    iv = generate_iv()

    # Encrypt the file data using AES-256-CBC with the generated IV
    key = bytes(os.urandom(32))
    ciphertext = bytes(AES.new(key, AES.MODE_CBC, iv).encrypt(data))

    # Store the encrypted data in the provided buffer
    buf.write(iv + ciphertext)

def decrypt_file(filename, buf):
    # Load the encrypted file into memory
    with open(filename, "rb") as f:
        data = f.read()

    # Generate a secure, unique IV for this decryption operation
    iv = data[:16]

    # Decrypt the file data using AES-256-CBC with the generated IV
    key = bytes(os.urandom(32))
    plaintext = bytes(AES.new(key, AES.MODE_CBC, iv).decrypt(data[16:]))

    # Compute the MD5 hash of the decrypted data
    md5 = hashlib.md5(plaintext).hexdigest()

    # Verify that the computed hash matches the stored hash
    if buf.read(32) != md5:
        print("Error: file integrity check failed")
        return

    # Clean up memory
    del data
    del plaintext
```
