    num_files = get_file_list(files);

    // Select a service to use
    service = select_service();
    service_arg = create_service_arg();

    // Create threads for each file
    for (i = 0; i < num_files; i++) {
        struct thread_data *thread_data = malloc(sizeof(struct thread_data));
        thread_data->file = files[i];
        thread_data->service_fn = service->convert_file;
        thread_data->service_arg = service_arg;
        pthread_create(&threads[i], NULL, run_thread, thread_data);
    }

    // Wait for threads to finish
    for (j = 0; j < num_files; j++) {
        pthread_join(threads[j], NULL);
    }

    // Destroy the service
    destroy_service(service_arg);

    return 0;
}
