// Semaphore for job submission
sem_t job_sem;

// Semaphore for worker availability
sem_t worker_sem;

// Mutex for critical jobs
pthread_mutex_t critical_jobs_mutex;

// Mutex for non-critical jobs
pthread_mutex_t non_critical_jobs_mutex;

// Condition variable for critical job priority
pthread_cond_t critical_jobs_cv;

// Condition variable for non-critical job priority
pthread_cond_t non_critical_jobs_cv;

// Function to submit a new job
void submit_job(char* command, int priority) {
    // Increment number of jobs and check if max has been reached
    num_jobs++;
    if (num_jobs > max_jobs) {
        return;
    }

    // Create a new job structure
    struct job* new_job = malloc(sizeof(struct job));
    new_job->command = command;
    new_job->priority = priority;
    new_job->is_critical = false;

    // Add the job to the end of the array
    jobs[num_jobs - 1] = new_job;

    // Increment number of dependencies for each dependency in the command string
    int num_dependencies_for_job = count_dependencies(command);
    num_dependencies += num_dependencies_for_job;

    // Signal job submission semaphore
    sem_post(&job_sem);
}

// Function to execute a job
void execute_job(struct job* job) {
    // Check if the job is critical and update the number of critical jobs
    if (job->is_critical) {
        num_critical_jobs++;
    } else {
        num_non_critical_jobs++;
    }

    // Execute the job command
    system(job->command);

    // Decrement number of dependencies for each dependency in the command string
    int num_dependencies_for_job = count_dependencies(job->command);
    num_dependencies -= num_dependencies_for_job;

    // Check if the job is critical and update the priority condition variable accordingly
    if (job->is_critical) {
        pthread_cond_signal(&critical_jobs_cv);
    } else {
        pthread_cond_signal(&non_critical_jobs_cv);
    }
}

// Function to handle job dependencies
void handle_dependencies(struct job* job) {
    // Check if the job has any dependencies and execute them if necessary
    if (num_dependencies > 0) {
        for (int i = 0; i < num_jobs; i++) {
            if (strcmp(job->command, jobs[i]->command) == 0) {
                // Execute the dependent job
                execute_job(jobs[i]);

                // Decrement number of dependencies for each dependency in the command string
                int num_dependencies_for_job = count_dependencies(job->command);
                num_dependencies -= num_dependencies_for_job;
            }
        }
    }
}

// Function to check if a job is critical or not
bool is_critical(struct job* job) {
    // Check if the job has any dependencies that are critical
    for (int i = 0; i < num_jobs; i++) {
        if (strcmp(job->command, jobs[i]->command) == 0 && jobs[i]->is_critical) {
            return true;
        }
    }

    // Check if the job is itself critical
    if (job->is_critical) {
        return true;
    }

    return false;
}

// Function to count the number of dependencies in a command string
int count_dependencies(char* command) {
    // Initialize counter for dependencies
    int num_dependencies = 0;

    // Iterate over each word in the command string
    char* token = strtok(command, " ");
    while (token != NULL) {
        // Check if the word is a dependency
        if (strcmp(token, "&&") == 0 || strcmp(token, ";") == 0) {
            num_dependencies++;
        }

        // Get next word
        token = strtok(NULL, " ");
    }

    return num_dependencies;
}

// Function to handle a worker exiting
void handle_worker_exit(struct worker* worker) {
    // Check if the worker was working on a job
    if (worker->current_job > -1) {
        // Decrement number of jobs and update job dependencies
        num_jobs--;
        int num_dependencies = count_dependencies(jobs[worker->current_job]->command);
        num_dependencies -= num_dependencies;

        // Signal job execution semaphore
        sem_post(&job_sem);
    }

    // Free the worker structure and update the array of workers
    free(workers[worker->pid]);
    workers[worker->pid] = NULL;
}

// Function to create a new worker
void create_new_worker() {
    // Increment number of workers and check if max has been reached
    num_workers++;
    if (num_workers > max_workers) {
        return;
    }

    // Create a new worker structure
    struct worker* new_worker = malloc(sizeof(struct worker));
    new_worker->pid = getpid();
    new_worker->current_job = -1;
    new_worker->is_available = true;

    // Add the worker to the end of the array
    workers[num_workers - 1] = new_worker;
}

// Function to execute a job in a worker
void execute_job_in_worker(struct worker* worker, struct job* job) {
    // Check if the worker is available
    if (worker->is_available) {
        // Update the worker's current job and make it unavailable
        worker->current_job = job->index;
        worker->is_available = false;

        // Execute the job
        execute_job(job);

        // Update the worker's current job and make it available again
        worker->current_job = -1;
        worker->is_available = true;
    }
}

// Main function
int main() {
    // Initialize semaphores
    sem_init(&job_sem, 0, 1);
    sem_init(&worker_sem, 0, num_workers);

    // Create workers
    for (int i = 0; i < max_workers; i++) {
        create_new_worker();
    }

    // Loop until all jobs are executed
    while (num_jobs > 0) {
        // Wait on the job execution semaphore
        sem_wait(&job_sem);

        // Check if a worker is available to execute a job
        for (int i = 0; i < max_workers; i++) {
            if (workers[i] != NULL && workers[i]->is_available) {
                // Execute the job in the worker
                struct job* job = jobs[num_jobs - 1];
                execute_job_in_worker(workers[i], job);

                // Decrement number of jobs and update job dependencies
                num_jobs--;
                int num_dependencies = count_dependencies(job->command);
                num_dependencies -= num_dependencies;
            }
        }
    }

    return 0;
}
```
This solution uses semaphores to synchronize the access to the shared resources and ensures that the jobs are executed in a fair manner. It also handles worker exiting and creating new workers as needed.

### Conclusion
In this blog post, we have discussed how to implement a job scheduler using semaphores. We have seen two different solutions for the problem: one using a single semaphore and another using multiple semaphores. Each solution has its own advantages and disadvantages and can be used depending on the specific requirements of the problem.']

