    public static class DeployMicroservice
    {
        private const string DeploymentYamlFile = "deployment.yaml";

        public static async Task<string> Deploy(string serviceName, string imageVersion, string namespace)
        {
            // Validate input parameters
            if (string.IsNullOrEmpty(serviceName))
            {
                throw new ArgumentException("Service name is required.", nameof(serviceName));
            }

            if (string.IsNullOrEmpty(imageVersion))
            {
                throw new ArgumentException("Image version is required.", nameof(imageVersion));
