                return string.Empty;
            }

            // Load deployment configuration from YAML file
            var deployment = KubernetesClient.Read<Deployment>(deploymentYamlPath);

            // Update service name, image version and namespace in the deployment configuration
            deployment.Metadata.Name = serviceName;
            deployment.Spec.Template.Spec.Containers[0].Image = $"{imageVersion}";
            deployment.Spec.Template.Metadata.Namespace = namespace;

            // Set up retry mechanism with exponential backoff for Kubernetes API calls
            var retryPolicy = new RetryPolicy<ApiException>(
                (ex, count) => ex.StatusCode == HttpStatusCode.InternalServerError && count < 5,
                TimeSpan.FromSeconds(1),
                TimeSpan.FromSeconds(60)
            );

            // Connect to Kubernetes cluster and create deployment
            using var client = new KubernetesClient();
            try
            {
                await retryPolicy.ExecuteAsync(() => client.CreateDeploymentAsync(deployment, default));
            }
            catch (Exception ex) when (ex is ApiException || ex is TaskCanceledException)
            {
                Console.WriteLine($"Error: Deployment failed with exception '{ex.Message}'. Check logs for more information.");
                return string.Empty;
            }

            // Wait for deployment to be ready
            var ready = await retryPolicy.ExecuteAsync(() => client.IsDeploymentReadyAsync(deployment, default));
            if (!ready)
            {
                Console.WriteLine($"Warning: Deployment took longer than expected. Check logs for more information.");
                return string.Empty;
            }

            // Get deployment details and return response
            var deploymentDetails = await retryPolicy.ExecuteAsync(() => client.GetDeploymentAsync(serviceName, namespace, default));
            return JsonConvert.SerializeObject(deploymentDetails);
        }
    }
}
