    private readonly string _key;
    private readonly byte[] _iv;
    private readonly Aes _aes;

    public SensitiveDataService(string bucketName, string key, byte[] iv)
    {
        _bucketName = bucketName;
        _key = key;
        _iv = iv;
        _aes = new AesCryptoServiceProvider();
    }

    public async Task<object> GetSensitiveDataAsync()
    {
        try
        {
            var client = new AmazonS3Client(Amazon.RegionEndpoint.USWest2);
            var request = new GetObjectRequest
            {
                BucketName = _bucketName,
                Key = _key
            };

            using (var response = await client.GetObjectAsync(request))
            {
                using (var stream = response.ResponseStream)
                {
                    var cipherText = new byte[response.ContentLength];
                    await stream.ReadAsync(cipherText, 0, cipherText.Length);

                    var plainText = _aes.Decrypt(cipherText, _iv);

                    using (var memoryStream = new MemoryStream(plainText))
                    {
                        return JsonSerializer.Deserialize<object>(memoryStream);
                    }
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error occurred while fetching sensitive data: {ex}");
            return null;
        }
    }
}
