```
const express = require('express');
const multer = require('multer');
const awsSdk = require('aws-sdk');
const retryRequest = require('retry-request');
const bunyan = require('bunyan');
const winston = require('winston');
const multerS3 = require('multer-s3');
const expressValidator = require('express-validator');
const prometheus = require('prom-client');

const app = express();
app.use(express.json());
app.use(express.urlencoded({ extended: true }));
app.use(multer().single('file'));
app.use(awsSdk);
app.use(retryRequest);
app.use(bunyan);
app.use(winston);
app.use(multerS3);
app.use(expressValidator);
app.use(prometheus);

const AWS_ACCESS_KEY = 'YOUR_AWS_ACCESS_KEY';
const AWS_SECRET_KEY = 'YOUR_AWS_SECRET_KEY';
const S3_BUCKET = 'YOUR_S3_BUCKET';
const S3_REGION = 'YOUR_S3_REGION';

app.post('/upload', async (req, res) => {
  const file = req.file;
  const filename = `${Date.now()}_${file.originalname}`;
  try {
    await awsSdk.config({
      accessKeyId: AWS_ACCESS_KEY,
      secretAccessKey: AWS_SECRET_KEY,
      region: S3_REGION,
    });
    const s3 = new awsSdk.S3();
    const params = {
      Bucket: S3_BUCKET,
      Key: filename,
      Body: file.buffer,
    };
    await s3.upload(params).promise();
    res.json({ message: 'File uploaded successfully!' });
  } catch (error) {
    console.log(error);
    res.status(500).json({ error: 'Something went wrong!' });
  }
});

app.get('/uploads', async (req, res) => {
  const files = await awsSdk.config({
    accessKeyId: AWS_ACCESS_KEY,
    secretAccessKey: AWS_SECRET_KEY,
    region: S3_REGION,
  });
  const s3 = new awsSdk.S3();
  try {
    const filesList = await s3.listObjectsV2({ Bucket: S3_BUCKET }).promise();
    res.json(filesList);
  } catch (error) {
    console.log(error);
    res.status(500).json({ error: 'Something went wrong!' });
  }
});

app.delete('/uploads/:filename', async (req, res) => {
  const filename = req.params.filename;
  try {
    await awsSdk.config({
      accessKeyId: AWS_ACCESS_KEY,
      secretAccessKey: AWS_SECRET_KEY,
      region: S3_REGION,
    });
    const s3 = new awsSdk.S3();
    const params = { Bucket: S3_BUCKET, Key: filename };
    await s3.deleteObject(params).promise();
    res.json({ message: 'File deleted successfully!' });
  } catch (error) {
    console.log(error);
    res.status(500).json({ error: 'Something went wrong!' });
  }
});

const port = process.env.PORT || 3000;
app.listen(port, () => {
  console.log(`Server started on port ${port}`);
