  const response = await fetch(templateURL);
  if (!response.ok) {
    throw new Error(`Failed to fetch template from ${templateURL}`);
  }
  const template = await response.text();

  // Step 2: Validate the Kickstart configuration template against user-provided replacements
  for (const [key, value] of Object.entries(replacements)) {
    if (!template.includes(`%${key}%`)) {
      throw new Error(`Invalid replacement key ${key}`);
    }
  }

  // Step 3: Apply user-provided replacements using a sed-like operation
  const updatedTemplate = template.replace(/%([a-zA-Z0-9_]+)%/g, (match, p1) => {
    return replacements[p1] || match;
  });

  // Step 4: Return the updated Kickstart configuration template
  return updatedTemplate;
}
```
