use tracing::{info, instrument};

struct PluginManager {
    plugin_dir: PathBuf,
}

impl PluginManager {
    async fn new(plugin_dir: PathBuf) -> Self {
        info!("Creating plugin manager");
        Self { plugin_dir }
    }

    async fn load_plugins(&self) -> Vec<Arc<dyn Plugin>> {
        let mut plugins = vec![];
        for entry in tokio::fs::read_dir(self.plugin_dir).await.unwrap() {
            let entry = entry.unwrap();
            if entry.file_type().await.unwrap().is_file() {
                let plugin = Plugin::new(entry.path()).await;
                plugins.push(Arc::new(plugin));
            }
        }
        info!("Loaded {} plugins", plugins.len());
        plugins
    }
}

struct Plugin {
    module: Module,
}

impl Plugin {
    async fn new(path: PathBuf) -> Self {
        let mut file = File::open(&path).await.unwrap();
        let mut bytes = vec![];
        file.read_to_end(&mut bytes).await.unwrap();
        let module = Module::new(&bytes);
        info!("Loaded plugin {}", path.display());
        Self { module }
    }
}

struct Module {
