#include <mutex>
#include <condition_variable>
#include <atomic>
#include <queue>
#include <map>

using namespace std;

// Define constants for file names and path
const string LOG_FILE_NAME = "log.txt";
const string OUTPUT_FILE_NAME = "output.txt";
const string PATH = "/path/to/data/";

// Define data structures for sensor measurements and device IDs
struct SensorMeasurement {
  double measurement;
  int deviceID;
};

// Define a queue for storing incoming sensor measurements
queue<SensorMeasurement> measurementQueue;

// Define a map for tracking the last three valid numerical values per device
map<int, vector<double>> deviceValues;

// Define a mutex and condition variable for synchronizing access to the queue and map
mutex mtx;
condition_variable cv;

// Define an atomic boolean for signaling the thread to shut down
atomic<bool> isRunning(false);

void processMeasurements() {
  // Continuously read new measurements from the queue
  while (isRunning) {
    SensorMeasurement measurement;
    {
      lock_guard<mutex> lock(mtx);
      if (!measurementQueue.empty()) {
        measurement = measurementQueue.front();
        measurementQueue.pop();
      } else {
        // If the queue is empty, wait for a new measurement to be added
        cv.wait(lock);
      }
    }
    // Process the new measurement
    processMeasurement(measurement);
  }
}

void processMeasurement(SensorMeasurement& measurement) {
  // Update the last three valid numerical values for this device
  int deviceID = measurement.deviceID;
  double measurementValue = measurement.measurement;
  vector<double>& values = deviceValues[deviceID];
  if (values.size() == 3) {
    values.erase(values.begin());
  }
  values.push_back(measurementValue);
  // Compute the average of the last three valid numerical values
  double average = 0;
  for (double value : values) {
    average += value;
  }
  average /= values.size();
  // Append the average to the output file
  string outputString = to_string(average);
  ofstream outputFile(PATH + OUTPUT_FILE_NAME, ios::app);
  outputFile << outputString << endl;
}

void readLogFile() {
  ifstream logFile(PATH + LOG_FILE_NAME);
  string line;
  while (getline(logFile, line)) {
    // Parse the line and extract the device ID and measurement value
    int deviceID = -1;
    double measurementValue = -1;
    size_t delimiterPos = line.find(' ');
    if (delimiterPos != string::npos) {
      string deviceIDString = line.substr(0, delimiterPos);
      string measurementValueString = line.substr(delimiterPos + 1);
      try {
        deviceID = stoi(deviceIDString);
        measurementValue = stod(measurementValueString);
      } catch (exception& e) {
        // Handle malformed data formats and potential concurrency issues when processing multiple files simultaneously
        cout << "Malformed data format: " << line << endl;
        continue;
      }
    } else {
      cout << "Malformed data format: " << line << endl;
      continue;
    }
    // Handle lines with fewer than three values by calculating the average of available values
    vector<double>& values = deviceValues[deviceID];
    if (values.size() < 3) {
      values.push_back(measurementValue);
    } else {
      double average = 0;
      for (double value : values) {
        average += value;
      }
      average /= values.size();
      // Append the average to the output file
      string outputString = to_string(average);
      ofstream outputFile(PATH + OUTPUT_FILE_NAME, ios::app);
      outputFile << outputString << endl;
    }
  }
}

int main() {
  // Initialize the queue and map for storing incoming sensor measurements
  measurementQueue = queue<SensorMeasurement>();
  deviceValues = map<int, vector<double>>();

  // Start a thread to process measurements
  isRunning = true;
  thread measurementThread(processMeasurements);

  // Read the log file and add each line to the queue
  readLogFile();

  // Shut down the thread when the queue is empty
  {
    lock_guard<mutex> lock(mtx);
    isRunning = false;
    cv.notify_all();
  }
  measurementThread.join();

  return 0;
}
```
