            random.Next((max - min) + 1) + min;

        public static float[] NextFloats(this IRandom random, int count) =>
            Enumerable.Range(0, count).Select(_ => (float)_random.NextDouble()).ToArray();

        public static int[] NextInts(this IRandom random, int min, int max, int count) =>
            Enumerable.Range(0, count).Select(_ => random.Next(min, max)).ToArray();
    }

