using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace DynamicDataOrchestrator
{
    class AdaptiveLearningExample
    {
        static void Main(string[] args)
        {
            // Initialize the data dictionary
            Dictionary<string, object> data = new Dictionary<string, object>();
            data.Add("customer_id", 12345);
            data.Add("product_type", "book");
            data.Add("order_amount", 20);

            // Create an instance of the adaptive learning class
            AdaptiveLearning adaptiveLearning = new AdaptiveLearning(data);

            // Add adaptive rules to the class
            string adaptiveRule1 = "IF {customer_id} == 12345 THEN {product_type} == 'book' AND {order_amount} == 20";
            string adaptiveRule2 = "ELSE IF {customer_id} != 12345 THEN {product_type} == 'electronics' AND {order_amount} == 50";
            adaptiveLearning.AddAdaptiveRule(adaptiveRule1);
            adaptiveLearning.AddAdaptiveRule(adaptiveRule2);

            // Train the class on the data
            await adaptiveLearning.TrainAsync();
        }
    }
}
