typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Header file for linked list management functions
#include <stdlib.h>
#include <stdio.h>

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
} node;

void insert(NFAPI_CRC_INDICATION_PDU_T data);
void remove(uint32_t RX_UE_INFORMATION_TAG);
node* search(uint16_t RNTI);
void update(NFAPI_CRC_INDICATION_PDU_T data, uint32_t RX_UE_INFORMATION_TAG);
void print();

// Implementation file for linked list management functions
#include "linkedList.h"

node* head = NULL;
int count = 0;
int MAX_LIST_SIZE = 10000;

void insert(NFAPI_CRC_INDICATION_PDU_T data) {
    node *newNode = (node*) malloc(sizeof(node));
    newNode->data = data;
    if (head == NULL) {
        head = newNode;
    } else {
        newNode->next = head;
        head = newNode;
    }
    count++;
}

void remove(uint32_t RX_UE_INFORMATION_TAG) {
    node *temp = head;
    if (temp == NULL) return;
    while (temp->next != NULL && temp->data.RX_UE_INFORMATION_TAG != RX_UE_INFORMATION_TAG) {
        temp = temp->next;
    }
    if (temp->next != NULL && temp->data.RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) {
        node *toRemove = temp->next;
        temp->next = toRemove->next;
        free(toRemove);
        count--;
    }
}

node* search(uint16_t RNTI) {
    node *temp = head;
    while (temp != NULL && temp->data.RNTI != RNTI) {
        temp = temp->next;
    }
    return temp;
}

void update(NFAPI_CRC_INDICATION_PDU_T data, uint32_t RX_UE_INFORMATION_TAG) {
    node *temp = search(RNTI);
    if (temp != NULL && temp->data.RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) {
        temp->data = data;
    }
}

void print() {
    node *temp = head;
    while (temp != NULL) {
        printf("%d\n", temp->data.RX_UE_INFORMATION_TAG);
        temp = temp->next;
    }
}

