#include <pthread.h>
#include <time.h>
#include <unordered_map>

#define MAX_KEY_LEN 64
#define MAX_VALUE_LEN 1024
#define NUM_THREADS 8
#define THREAD_QUIT 0xdeadbeef

using namespace std;

struct KeyValuePair {
    int key;
    char value[MAX_VALUE_LEN];
};

unordered_map<int, string> kvs;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Lock-free data structure for storing the key-value pairs.
struct KeyValueStore {
    unordered_map<int, string>* data;
    pthread_spinlock_t spinlock;
};

KeyValueStore* createKVS() {
    KeyValueStore* kvs = (KeyValueStore*)malloc(sizeof(KeyValueStore));
    if (!kvs) return NULL;
    kvs->data = new unordered_map<int, string>;
    pthread_spinlock_init(&kvs->spinlock, PTHREAD_PROCESS_PRIVATE);
    return kvs;
}

void deleteKVS(KeyValueStore* kvs) {
    if (!kvs) return;
    delete kvs->data;
    pthread_spinlock_destroy(&kvs->spinlock);
    free(kvs);
}

// Thread function to handle a single connection.
void* handleConnection(void* arg) {
    struct sockaddr_in clientAddr;
    int connFd = accept(arg, (struct sockaddr*)&clientAddr, NULL);
    if (connFd == -1) {
        perror("accept");
        return NULL;
    }
    char ip[INET_ADDRSTRLEN];
    inet_ntop(AF_INET, &clientAddr.sin_addr, ip, sizeof(ip));
    printf("Connection from %s:%d\n", ip, ntohs(clientAddr.sin_port));

    // Read the command from the client.
    char cmd[256];
    read(connFd, cmd, 256);
    if (strcmp(cmd, "GET") == 0) {
        int key;
        read(connFd, &key, sizeof(int));

        // Lock the mutex before accessing the shared data structure.
        pthread_mutex_lock(&lock);

        // Look up the value for the given key in the key-value store.
        KeyValueStore* kvs = (KeyValueStore*)arg;
        string value;
        if (!kvs->data->count(key)) {
            value = "";
        } else {
            value = (*kvs->data)[key];
        }

        // Unlock the mutex after accessing the shared data structure.
        pthread_mutex_unlock(&lock);

        // Send the value back to the client.
        write(connFd, value.c_str(), value.length());
    } else if (strcmp(cmd, "PUT") == 0) {
        int key;
        read(connFd, &key, sizeof(int));

        // Lock the mutex before accessing the shared data structure.
        pthread_mutex_lock(&lock);

        // Look up the value for the given key in the key-value store.
        KeyValueStore* kvs = (KeyValueStore*)arg;
        string value;
        if (!kvs->data->count(key)) {
            value = "";
        } else {
            value = (*kvs->data)[key];
        }

        // Unlock the mutex after accessing the shared data structure.
        pthread_mutex_unlock(&lock);

        // Send the old value back to the client.
        write(connFd, value.c_str(), value.length());

        // Read the new value from the client.
        char buffer[MAX_VALUE_LEN];
        read(connFd, buffer, MAX_VALUE_LEN);
        string newValue = buffer;

        // Lock the mutex before modifying the shared data structure.
        pthread_mutex_lock(&lock);

        // Update the key-value store with the new value.
        (*kvs->data)[key] = newValue;

        // Unlock the mutex after modifying the shared data structure.
        pthread_mutex_unlock(&lock);
    } else if (strcmp(cmd, "DEL") == 0) {
        int key;
        read(connFd, &key, sizeof(int));

        // Lock the mutex before accessing the shared data structure.
        pthread_mutex_lock(&lock);

        // Look up the value for the given key in the key-value store.
        KeyValueStore* kvs = (KeyValueStore*)arg;
        string value;
        if (!kvs->data->count(key)) {
            value = "";
        } else {
            value = (*kvs->data)[key];
        }

        // Unlock the mutex after accessing the shared data structure.
        pthread_mutex_unlock(&lock);

        // Send the value back to the client.
        write(connFd, value.c_str(), value.length());

        // Lock the mutex before modifying the shared data structure.
        pthread_mutex_lock(&lock);

        // Remove the key-value pair from the key-value store.
        (*kvs->data).erase(key);

        // Unlock the mutex after modifying the shared data structure.
        pthread_mutex_unlock(&lock);
    } else if (strcmp(cmd, "QUIT") == 0) {
        write(connFd, "OK", 2);
        close(connFd);
    }

    return NULL;
}
