#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <limits.h>
#include <pthread.h>

// Define the integer type and its limits
typedef int64_t int_type;
#define INT_MIN LLONG_MIN
#define INT_MAX LLONG_MAX

// Define a data structure to hold the integer list and metadata
struct IntList {
    int_type *list;
    size_t count, capacity;
};

// Define a data structure to hold the processing settings
struct ProcessingSettings {
    // File sources and destinations
    char **file_sources;
    char *output_file;

    // Data processing settings
    int rate_limit;
    int latency;

    // Histogram settings
    int bin_size;
    int range;
};

// Define a data structure to hold the cache of integer values
struct IntCache {
    int_type *values;
    size_t count, capacity;
};

// Function to read integers from a file source and integrate with an external service
int read_integers(char *file_source, struct IntList *list, struct ProcessingSettings *settings) {
    // Check if the input file is valid
    FILE *fp = fopen(file_source, "r");
    if (!fp) return 0;

    // Read the integers from the file and process them with the external service
    int_type i;
    while (fscanf(fp, "%ld", &i) != EOF) {
        // Check if the integer is valid
        if (i < INT_MIN || i > INT_MAX) continue;

        // Add the integer to the list and process it with the external service
        struct IntCache *cache = settings->cache;
        cache->values[cache->count++] = i;
        if (cache->count >= settings->rate_limit) {
            process_integers(settings, cache);
            cache->count = 0;
        }
    }

    // Close the file and return the number of integers read
    fclose(fp);
    return list->count;
}

// Function to process a batch of integers with an external service and update the cache
void process_integers(struct ProcessingSettings *settings, struct IntCache *cache) {
    // Compute the mean, median, and standard deviation of the integer values in the cache
    int_type sum = 0;
    int count = cache->count;
    for (int i = 0; i < count; i++) {
        sum += cache->values[i];
    }
    double mean = (double)sum / count;

    // Compute the histogram of integer frequency distributions
    int hist[settings->range + 1];
    for (int i = 0; i <= settings->range; i++) {
        hist[i] = 0;
    }
    for (int i = 0; i < count; i++) {
        int bin = cache->values[i] / settings->bin_size;
        if (bin >= settings->range) bin = settings->range - 1;
        hist[bin]++;
    }

    // Print or save the results to a file
    printf("Largest integer: %ld\n", cache->values[count - 1]);
    printf("Second largest integer: %ld\n", cache->values[count - 2]);
    printf("Total count: %d\n", count);
    printf("Presence of duplicates: ");
    if (count == settings->range) {
        printf("no");
    } else {
        printf("yes");
    }
    printf("\nDistribution statistics:\n");
    printf("Mean: %f\n", mean);
    printf("Median: %d\n", median(hist, count));
    printf("Standard deviation: %f\n", standard_deviation(mean, hist, count));
    if (settings->output_file) {
        FILE *fp = fopen(settings->output_file, "w");
        if (!fp) return;
        for (int i = 0; i <= settings->range; i++) {
            fprintf(fp, "%d\t%d\n", i * settings->bin_size, hist[i]);
        }
        fclose(fp);
    }
}

// Function to compute the median of an integer histogram
int median(int hist[], int count) {
    // Check if there are any non-zero values in the histogram
    for (int i = 0; i < count; i++) {
        if (hist[i] != 0) return i * settings->bin_size;
    }

    // If no non-zero values were found, return the mean of the histogram
    double sum = 0;
    for (int i = 0; i < count; i++) {
        sum += i * hist[i];
    }
    return sum / (count - 1);
}

// Function to compute the standard deviation of an integer histogram
double standard_deviation(double mean, int hist[], int count) {
    // Compute the squared differences from the mean
    double diffs = 0;
    for (int i = 0; i < count; i++) {
        diffs += pow((i * settings->bin_size - mean), 2);
    }

    // Return the square root of the sum of squared differences
    return sqrt(diffs / (count - 1));
}

// Function to determine and print the largest and second-largest integers in a list
void find_max_integers(struct IntList *list) {
    // Check if there are any valid integers in the list
    if (list->count == 0) return;

    // Initialize the largest and second-largest integers to the first integer in the list
    int_type max = list->list[0], sec_max = INT_MIN;
    for (int i = 1; i < list->count; i++) {
        if (list->list[i] > max) {
            sec_max = max;
            max = list->list[i];
        } else if (list->list[i] > sec_max && list->list[i] != max) {
            sec_max = list->list[i];
        }
    }

    // Print the largest and second-largest integers in the list
    printf("Largest integer: %ld\n", max);
    if (sec_max == INT_MIN) {
        printf("Second largest integer: no valid integer found\n");
    } else {
        printf("Second largest integer: %ld\n", sec_max);
    }
}

int main() {
    struct IntList *list = create_list();

    // Read the integers from a file and add them to the list
    FILE *fp = fopen("integers.txt", "r");
    if (fp == NULL) return 1;
    while (!feof(fp)) {
        int_type i = read_int(fp);
        if (i != EOF) {
            add_integer(list, i);
        }
    }
    fclose(fp);

    // Print the largest and second-largest integers in the list
    find_max_integers(list);

    return 0;
}
