                # Retrieve the configuration for a specific service from the internal store
                return self.config_store[service]

            except KeyError as e:
                raise ConfigNotFoundException('Service configuration not found: {}'.format(e))

    def update_service_config(self, service, config):
        with self.lock:
            try:
                # Update the configuration for a specific service in the internal store
                self.validate_config(config)

                self.config_store[service] = config

            except ConfigValidationException as e:
                logging.error('Error updating service configuration: {}'.format(e))

            except KeyError as e:
                raise ConfigNotFoundException('Service configuration not found: {}'.format(e))

    def rollback_config_update(self, service):
        with self.lock:
            try:
                # Roll back the last update to a specific service in the internal store
                self.config_store[service] = self.config_history[service].pop()

            except KeyError as e:
                raise ConfigNotFoundException('Service configuration not found: {}'.format(e))

            except IndexError as e:
                logging.error('No history to roll back: {}'.format(e))

    def update_config_history(self, service):
        with self.lock:
            try:
                # Update the history of a specific service in the internal store
                self.config_history[service].append(self.config_store[service])

            except KeyError as e:
                raise ConfigNotFoundException('Service configuration not found: {}'.format(e))

