#include <openssl/ssl.h>

// Define the structure to store algorithm metadata
typedef struct {
  const char *name; // Algorithm name
  int (*init_func)(void); // Initialization function
  int (*op_func)(int, int); // Operation function
  int *params; // Required parameters
} alg_metadata_t;

// Define the library's main structure
typedef struct {
  const char *lib_name; // Library name (e.g., "OpenSSL")
  void *lib_handle; // Library handle
  int num_algorithms; // Number of supported algorithms
  alg_metadata_t *algorithms; // Array of algorithm metadata
} library_t;

// Define the algorithm discovery function
void discover_algorithms(library_t *lib) {
  // Initialize the array of algorithm metadata
  lib->algorithms = (alg_metadata_t *)malloc(sizeof(alg_metadata_t) * lib->num_algorithms);

  // Iterate over each algorithm and store its metadata
  for (int i = 0; i < lib->num_algorithms; ++i) {
    const SSL_METHOD *method = SSL_get_methods();
    SSL_METHOD *curr_method = method[i];

    // Store the algorithm name and initialization function
    strcpy(lib->algorithms[i].name, SSL_get_version(curr_method));
    lib->algorithms[i].init_func = (int (*)(void))SSL_library_init;

    // Store the operation function and required parameters
    lib->algorithms[i].op_func = SSL_connect;
    lib->algorithms[i].params = (int *)malloc(sizeof(int) * 2);
    lib->algorithms[i].params[0] = SSL_OP_ALL;
    lib->algorithms[i].params[1] = 0;
  }
}

// Define the library's initialization function
int init_library(const char *lib_name) {
  // Initialize the library handle and number of algorithms
  library_t *lib = (library_t *)malloc(sizeof(library_t));
  lib->lib_handle = dlopen(lib_name, RTLD_LAZY);
  lib->num_algorithms = SSL_get_number_of_ciphers();

  // Discover and store the supported algorithms
  discover_algorithms(lib);

  // Return the library handle
  return (int)lib;
}

// Define the library's shutdown function
void shutdown_library(library_t *lib) {
  dlclose(lib->lib_handle);
}

// Define the algorithm selection function
int select_algorithm(library_t *lib, const char *alg_name) {
  // Iterate over each algorithm and compare its name with the requested one
  for (int i = 0; i < lib->num_algorithms; ++i) {
    if (strcmp(lib->algorithms[i].name, alg_name) == 0) {
      return i;
    }
  }

  // If no match is found, return -1
  return -1;
}

// Define the algorithm initialization function
int init_algorithm(library_t *lib, int alg_index) {
  // Ensure the requested algorithm index is valid
  if (alg_index < 0 || alg_index >= lib->num_algorithms) {
    return -1;
  }

  // Initialize the selected algorithm's parameters
  int *params = lib->algorithms[alg_index].params;
  for (int i = 0; i < lib->algorithms[alg_index].num_params; ++i) {
    params[i] = SSL_OP_ALL;
  }

  // Initialize the library's handle and return the algorithm index
  int ret = SSL_library_init();
  if (ret == -1) {
    return ret;
  }
  return alg_index;
}

// Define the algorithm operation function
int op_algorithm(library_t *lib, int alg_index, int op) {
  // Ensure the requested algorithm index is valid
  if (alg_index < 0 || alg_index >= lib->num_algorithms) {
    return -1;
  }

  // Perform the requested operation on the selected algorithm
  SSL *ssl = SSL_new(lib->algorithms[alg_index].init_func());
  int ret = SSL_connect(ssl, op);

  // Clean up and return the result
  SSL_free(ssl);
  return ret;
}
```
