// Semaphore Library Header File
#ifndef SEMAPHORE_LIBRARY_H
#define SEMAPHORE_LIBRARY_H

#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>
#include <errno.h>

#ifdef __cplusplus
extern "C" {
#endif

typedef struct semaphore_t {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int count;
} semaphore_t;

// Initializes a new semaphore with the given initial value.
semaphore_t* semaphore_init(int init_val);

// Destroys the given semaphore, releasing all resources.
void semaphore_destroy(semaphore_t* sema);

// Increments the count of the semaphore by 1.
void semaphore_post(semaphore_t* sema);

// Decrements the count of the semaphore by 1, waiting indefinitely for the count to become positive.
void semaphore_wait(semaphore_t* sema);

// Decrements the count of the semaphore by 1, returning immediately if the count is already negative or zero.
int semaphore_trywait(semaphore_t* sema);

#ifdef __cplusplus
}
#endif

#endif // SEMAPHORE_LIBRARY_H

// Semaphore Library Implementation File
#include "semaphore_library.h"

#define MIN(a, b) ((a) < (b) ? (a) : (b))

struct semaphore_t {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int count;
};

semaphore_t* semaphore_init(int init_val) {
    semaphore_t* sema = (semaphore_t*) malloc(sizeof(semaphore_t));
    if (sema == NULL) {
        return NULL;
    }
    pthread_mutex_init(&sema->mutex, NULL);
    pthread_cond_init(&sema->cond, NULL);
    sema->count = init_val;
    return sema;
}

void semaphore_destroy(semaphore_t* sema) {
    if (sema != NULL) {
        pthread_mutex_lock(&sema->mutex);
        while (sema->count > 0) {
            pthread_cond_wait(&sema->cond, &sema->mutex);
        }
        pthread_mutex_unlock(&sema->mutex);
        pthread_cond_destroy(&sema->cond);
        pthread_mutex_destroy(&sema->mutex);
        free(sema);
    }
}

void semaphore_post(semaphore_t* sema) {
    if (sema == NULL) {
        return;
    }
    pthread_mutex_lock(&sema->mutex);
    ++sema->count;
    pthread_cond_broadcast(&sema->cond);
    pthread_mutex_unlock(&sema->mutex);
}

void semaphore_wait(semaphore_t* sema) {
    if (sema == NULL) {
        return;
    }
    pthread_mutex_lock(&sema->mutex);
    while (sema->count <= 0) {
        pthread_cond_wait(&sema->cond, &sema->mutex);
    }
    --sema->count;
    pthread_mutex_unlock(&sema->mutex);
}

int semaphore_trywait(semaphore_t* sema) {
    if (sema == NULL) {
        return -1;
    }
    int ret = 0;
    pthread_mutex_lock(&sema->mutex);
    if (sema->count <= 0) {
        ret = -1;
    } else {
        --sema->count;
    }
    pthread_mutex_unlock(&sema->mutex);
    return ret;
}

// Semaphore Library Logging Functions
#ifdef SEMAPHORE_LOGGING
#include <stdio.h>
#include <string.h>
#include <stdarg.h>

void semaphore_log(const char* format, ...) {
    va_list args;
    va_start(args, format);
    vprintf(format, args);
    printf("\n");
    va_end(args);
}

#endif // SEMAPHORE_LOGGING

// Semaphore Library Error Handling Functions
#ifdef SEMAPHORE_ERRORS

#include <errno.h>

void semaphore_error(const char* msg) {
    perror(msg);
}

#endif // SEMAPHORE_ERRORS']

