using namespace std;

// Define the service instance class
class ServiceInstance {
    private:
        int id;                     // Unique ID for each service instance
        string name;                // Name of the service
        vector<string> endpoints;   // List of endpoints for the service
        bool is_active;             // Flag to indicate if the service is active or not
        chrono::time_point<chrono::system_clock> last_update;  // Time of the last update

    public:
        ServiceInstance(int id, string name, vector<string> endpoints) {
            this->id = id;
            this->name = name;
            this->endpoints = endpoints;
            is_active = true;
            last_update = chrono::system_clock::now();
        }

        int getID() { return id; }
        string getName() { return name; }
        vector<string> getEndpoints() { return endpoints; }
        bool isActive() { return is_active; }
        chrono::time_point<chrono::system_clock> getLastUpdate() { return last_update; }
};

// Define the service registry class
class ServiceRegistry {
    private:
        vector<ServiceInstance> instances;   // List of all service instances
        mutex instances_mutex;             // Mutex to protect access to the instance list
        condition_variable instances_cv;   // Condition variable to signal changes in the instance list

    public:
        ServiceRegistry() {
            instances.clear();
        }

        void addInstance(ServiceInstance instance) {
            lock_guard<mutex> lock(instances_mutex);
            instances.push_back(instance);
            instances_cv.notify_all();
        }

        void removeInstance(int id) {
            lock_guard<mutex> lock(instances_mutex);
            auto it = find(instances.begin(), instances.end(), ServiceInstance(id));
            if (it != instances.end()) {
                instances.erase(it);
            }
        }

        vector<ServiceInstance> getInstances() {
            lock_guard<mutex> lock(instances_mutex);
            return instances;
        }
};

// Define the service client class
class ServiceClient {
    private:
        string name;                // Name of the service to be accessed
        vector<string> endpoints;   // List of endpoints for the service
        bool is_active;             // Flag to indicate if the service is active or not
        chrono::time_point<chrono::system_clock> last_update;  // Time of the last update

    public:
        ServiceClient(string name, vector<string> endpoints) {
            this->name = name;
            this->endpoints = endpoints;
            is_active = true;
            last_update = chrono::system_clock::now();
        }

        string getName() { return name; }
        vector<string> getEndpoints() { return endpoints; }
        bool isActive() { return is_active; }
        chrono::time_point<chrono::system_clock> getLastUpdate() { return last_update; }
};

// Define the service manager class
class ServiceManager {
    private:
        ServiceRegistry registry;                     // Service registry to manage all instances
        vector<ServiceClient> clients;               // List of service clients
        mutex clients_mutex;                         // Mutex to protect access to the client list
        condition_variable clients_cv;               // Condition variable to signal changes in the client list
        chrono::time_point<chrono::system_clock> last_update;   // Time of the last update

    public:
        ServiceManager() {
            registry = ServiceRegistry();
            clients.clear();
            last_update = chrono::system_clock::now();
        }

        void addClient(ServiceClient client) {
            lock_guard<mutex> lock(clients_mutex);
            clients.push_back(client);
            clients_cv.notify_all();
        }

        void removeClient(string name) {
            lock_guard<mutex> lock(clients_mutex);
            auto it = find(clients.begin(), clients.end(), ServiceClient(name));
            if (it != clients.end()) {
                clients.erase(it);
            }
        }

        vector<ServiceClient> getClients() {
            lock_guard<mutex> lock(clients_mutex);
            return clients;
        }

        // Implement the service discovery logic here
};
```
The above code defines a `ServiceInstance` class to represent a single instance of a service, a `ServiceRegistry` class to manage all instances of a service, and a `ServiceManager` class that coordinates the interaction between clients and instances. The `ServiceClient` class represents a client that accesses a service, and the `ServiceManager` class implements the service discovery logic by maintaining a list of active service instances and their corresponding clients.

The `ServiceInstance` class has the following properties:

* `id`: A unique ID for each instance to identify it uniquely in the system.
* `name`: The name of the service instance.
* `endpoints`: A vector of endpoints that the service instance can be accessed through.
* `is_active`: A flag indicating if the service instance is active or not.
* `last_update`: The time of the last update to the service instance.

The `ServiceRegistry` class has the following methods:

* `addInstance(ServiceInstance instance)`: Adds a new service instance to the registry.
* `removeInstance(int id)`: Removes a service instance from the registry by its ID.
* `getInstances()`: Returns a list of all active service instances in the registry.

The `ServiceClient` class has the following properties:

* `name`: The name of the service to be accessed.
* `endpoints`: A vector of endpoints that the client can access the service through.
* `is_active`: A flag indicating if the client is active or not.
* `last_update`: The time of the last update to the client.

The `ServiceManager` class has the following methods:

* `addClient(ServiceClient client)`: Adds a new service client to the manager.
* `removeClient(string name)`: Removes a service client from the manager by its name.
* `getClients()`: Returns a list of all active service clients in the manager.

The `ServiceManager` class also implements the service discovery logic by maintaining a list of active service instances and their corresponding clients. It uses the `ServiceRegistry` class to manage the active instances, and the `ServiceClient` class to manage the active clients. The manager periodically checks the health of each service instance and updates its state accordingly. If an instance is deemed unhealthy, it is removed from the registry and all clients that were using it are notified of the change.

The above code defines a high-level architecture for a service discovery system that can be extended to handle more complex use cases. The specific implementation may vary depending on the requirements of the system being built.']

