    public class Authenticator : IAuthenticator
    {
        private readonly HttpClient _httpClient;
        private readonly DbContext _dbContext;
        private readonly EncryptionHelper _encryptionHelper;

        public Authenticator(HttpClient httpClient, DbContext dbContext, EncryptionHelper encryptionHelper)
        {
            _httpClient = httpClient;
            _dbContext = dbContext;
            _encryptionHelper = encryptionHelper;
        }

        public async Task<User> AuthenticateAsync(string username, string password)
        {
            var user = await _dbContext.Users.FirstOrDefaultAsync(u => u.Username == username && u.Password == password);
            if (user == null) return null;

            // Decrypt sensitive fields
            foreach (var field in user.SensitiveFields)
            {
                var decryptedField = _encryptionHelper.Decrypt(field, password);
                field.Value = decryptedField.ToString();
            }

            return user;
        }

        public async Task<User> AuthenticateAsync(string token)
        {
            // Validate token against external API
            var validationResponse = await _httpClient.PostAsync("https://example.com/api/validate-token", new StringContent(token));
            if (validationResponse.IsSuccessStatusCode)
            {
                var user = JsonConvert.DeserializeObject<User>(await validationResponse.Content.ReadAsStringAsync());
                return user;
            }

            return null;
        }
    }
}
```
