const express = require('express');
const app = express();
const mysql = require('mysql2');
const cache = require('memory-cache');
const { setTimeout } = require('timers').setTimeout;

// Setup MySQL connection pool
const pool = mysql.createPool({
  host: 'localhost',
  user: 'your_username',
  password: 'your_password',
  database: 'your_database'
});

// Setup caching system
cache.set('employees', {});
cache.set('cities', {});
cache.set('addresses', {});

app.get('/employee-records', (req, res) => {
  // Get employee records from cache if available
  const employees = cache.get('employees');
  if (employees) {
    return res.json(employees);
  }

  // Query MySQL database for employee records
  pool.query(`SELECT * FROM Employees`, (err, rows) => {
    if (err) {
      console.error(err);
      return res.status(500).json({ message: 'Error retrieving employee records' });
    }

    // Cache employee records for 1 minute
    cache.set('employees', rows, 60000);

    // Get city and address information for each employee
    const cities = [];
    const addresses = [];
    rows.forEach(row => {
      cities.push(row.city);
      addresses.push(row.address);
    });

    // Query MySQL database for city and address information
    pool.query(`SELECT * FROM Cities WHERE name IN (${cities})`, (err, rows) => {
      if (err) {
        console.error(err);
        return res.status(500).json({ message: 'Error retrieving city information' });
      }

      // Cache city and address information for 1 minute
      cache.set('cities', rows, 60000);
      cache.set('addresses', addresses, 60000);

      res.json({ employees: rows, cities: rows, addresses: addresses });
    });
  });
});
```
