@Injectable()
export class DialogService {
  private readonly apiUrl: string = 'https://api.example.com';

  constructor(private httpClient: HttpClient) {}

  /**
   * Fetches the specified resource from the API and updates the given dialog fields.
   * @param {string} resourceId The ID of the resource to fetch.
   * @param {string[]} fieldNames The names of the fields to update.
   */
  refreshFields(resourceId: string, fieldNames: string[]): Observable<any> {
    // Build API URL and query parameters
    const apiUrl = `${this.apiUrl}/resources/${resourceId}`;
    const queryParams = {};

    // Fetch resource data from API
    return this.httpClient.get(apiUrl, { params: queryParams })
      .pipe(
        // Map response data to field values
        map((response: any) => {
          const fieldValues = {};
          for (const fieldName of fieldNames) {
            fieldValues[fieldName] = response[fieldName];
          }
          return fieldValues;
        }),
        // Catch API errors and handle them gracefully
        catchError((error: any) => {
          console.error(`Error fetching resource ${resourceId}:`, error);
          return Observable.of(null);
        })
      );
