<?php

class ClinicManager {
    private $db;
    private $semaphore;

    public function __construct($db) {
        $this->db = $db;
        $this->semaphore = new Semaphore();
    }

    public function updateClinicStatus($clinicId, $status, $lastModifiedIp, $lastModifiedDate) {
        try {
            $this->semaphore->acquire();
            $this->db->beginTransaction();
            $sql = "UPDATE clinics SET status = ?, last_modified_ip = ?, last_modified_date = ? WHERE id = ?";
            $stmt = $this->db->prepare($sql);
            $stmt->bindValue(1, $status, PDO::PARAM_STR);
            $stmt->bindValue(2, $lastModifiedIp, PDO::PARAM_INT);
            $stmt->bindValue(3, $lastModifiedDate, PDO::PARAM_STR);
            $stmt->bindValue(4, $clinicId, PDO::PARAM_INT);
            $stmt->execute();
            $this->db->commit();
        } catch (Exception $e) {
            $this->db->rollBack();
            throw new Exception("Failed to update clinic status", 0, $e);
        } finally {
            $this->semaphore->release();
        }
    }

    public function retrieveClinicDetails($clinicId) {
        try {
            $this->semaphore->acquire();
            $sql = "SELECT * FROM clinics WHERE id = ?";
            $stmt = $this->db->prepare($sql);
            $stmt->bindValue(1, $clinicId, PDO::PARAM_INT);
            $stmt->execute();
            $result = $stmt->fetchAll(PDO::FETCH_ASSOC);
            return $result;
        } catch (Exception $e) {
            throw new Exception("Failed to retrieve clinic details", 0, $e);
        } finally {
            $this->semaphore->release();
        }
    }

    public function calculateMD5Hash($string) {
        return md5($string);
    }
}
```
