class GameCharacter {
public:
    // Constructor with default cooldown period and attack mode
    GameCharacter(double cooldown_period, std::string initial_attack_mode) :
        cooldown_period_(cooldown_period),
        attack_mode_(initial_attack_mode),
        attack_database_()
    {}

    // Initialize the attack database with an external REST API endpoint
    void initializeAttackDatabase(std::string api_endpoint) {
        attack_database_.reset();
        // Fetch attack details from the API and add to the database
        for (auto& attack : fetchAttacksFromAPI(api_endpoint)) {
            attack_database_.emplace(attack.id, attack);
        }
    }

    // Select an attack based on the current game state and character settings
    void selectAttack() {
        // Check if the cooldown period has expired
        if (cooldown_timer_.hasExpired()) {
            // Select a random attack from the available options in the database
            auto& attack = selectRandomAttack();
            std::cout << "Selected attack: " << attack.name << std::endl;
            // Update the cooldown timer
            cooldown_timer_.start(attack.cooldown);
        } else {
            std::cout << "Cooldown active" << std::endl;
        }
    }

    // Switch between different attack modes dynamically
    void switchAttackMode(std::string new_mode) {
        if (attack_database_.find(new_mode) == attack_database_.end()) {
            throw std::invalid_argument("Invalid attack mode");
        }
        attack_mode_ = new_mode;
    }

    // Reset the cooldown timer when a special event occurs in the game
    void resetCooldown() {
        cooldown_timer_.reset();
    }

private:
    // Cooldown period for each attack type (in seconds)
    double cooldown_period_;
    // Current attack mode
    std::string attack_mode_;
    // Attack database retrieved from an external REST API endpoint
    std::map<std::string, Attack> attack_database_;
    // Cooldown timer for each attack type
    std::vector<CooldownTimer> cooldown_timers_;
    // Mutex to protect concurrent access to the database and timers
    std::mutex mutex_;

    // Fetch attacks from an external REST API endpoint
    std::vector<Attack> fetchAttacksFromAPI(std::string api_endpoint) {
        std::vector<Attack> attacks;
        try {
            auto response = HTTPRequest(api_endpoint).send();
            if (response.ok()) {
                for (auto& attack : json::parse(response.body())) {
                    attacks.push_back(attack);
                }
            } else {
                std::cout << "Error fetching attacks from API: " << response.error() << std::endl;
            }
        } catch (const std::exception& e) {
            std::cout << "Exception thrown while fetching attacks from API: " << e.what() << std::endl;
        }
        return attacks;
    }

    // Select a random attack from the available options in the database
    Attack selectRandomAttack() {
        auto& attack_list = attack_database_[attack_mode_];
        if (attack_list.empty()) {
            throw std::invalid_argument("No attacks available for current mode");
        }
        return attack_list[rand() % attack_list.size()];
    }

    // Cooldown timer class with start/stop/reset methods
    class CooldownTimer {
    public:
        void start(double cooldown) {
            cooldown_ = std::chrono::seconds(cooldown);
            start_time_ = std::chrono::steady_clock::now();
        }

        bool hasExpired() const {
            return std::chrono::steady_clock::now() - start_time_ > cooldown_;
        }

        void reset() {
            cooldown_ = std::chrono::seconds(0);
            start_time_ = std::chrono::steady_clock::now();
        }

    private:
        std::chrono::duration<double> cooldown_;
        std::chrono::steady_clock::time_point start_time_;
    };
};
```
The `GameCharacter` class has a constructor that takes a default cooldown period and an initial attack mode as arguments. The class also has methods for selecting an attack, switching between different attack modes, resetting the cooldown timer, and fetching attacks from an external REST API endpoint.

To handle concurrent access to the database and timers, the class uses a mutex to protect the `attack_database_` and `cooldown_timers_` members. The `fetchAttacksFromAPI()` method retrieves attacks from the API and adds them to the `attack_database_`. The `selectRandomAttack()` method selects a random attack from the available options in the database based on the current game state and character settings.

The `CooldownTimer` class provides a simple way to track cooldown periods for each attack type. The `start()` method sets the start time of the timer, the `hasExpired()` method checks if the cooldown period has expired based on the current time, and the `reset()` method resets the timer.

To handle the case where no attacks are available for the current mode, the class uses an empty attack list to avoid throwing an exception. Instead, it throws an invalid argument error when trying to access an empty attack list. This makes the code more robust and easier to maintain.']

