// AsyncReducer Class
class AsyncReducer {
  constructor(callback) {
    this.callback = callback;
    this.errors = [];
    this.logs = [];
  }

  reduceAsync(array, interval = 0) {
    // Handle errors gracefully
    if (interval < 0 || array.length === 0) {
      return;
    }

    const startTime = Date.now();
    const endTime = startTime + interval;

    // Set up intervals for each asynchronous step
    const intervals = [];
    for (let i = 0; i < array.length - 1; i++) {
      intervals.push(setInterval(() => {
        this.callback(array[i], array[i + 1]);
      }, interval));
    }

    // Clear intervals when all asynchronous steps are complete
    Promise.all(intervals).then(() => {
      clearInterval(intervals);
    });
  }
}

