int connect_to_logging_service(void) {
    int sock;
    struct addrinfo* res;

    // Try to establish a connection to the logging service up to five times with exponential backoff
    for (int i = 0; i < 5; ++i) {
        if ((sock = socket(AF_INET, SOCK_STREAM, 0)) == -1) {
            printf("Error creating socket: %s\n", strerror(errno));
            sleep(pow(2, i)); // Exponential backoff
            continue;
        }

        struct addrinfo hints = {
            .ai_family = AF_INET,
            .ai_socktype = SOCK_STREAM,
            .ai_protocol = 0
        };

        if (getaddrinfo(LOGGING_SERVICE_HOST, NULL, &hints, &res) != 0) {
            printf("Error resolving logging service host: %s\n", strerror(errno));
            close(sock);
            sleep(pow(2, i)); // Exponential backoff
            continue;
        }

        if (connect(sock, res->ai_addr, res->ai_addrlen) == -1) {
            printf("Error connecting to logging service: %s\n", strerror(errno));
            freeaddrinfo(res);
            close(sock);
            sleep(pow(2, i)); // Exponential backoff
            continue;
        }

        break;
