#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <unistd.h>

#define MAX_TOKEN_LENGTH 255
#define EXPIRES_IN_POS 1
#define BEARER_TYPE "Bearer"

typedef struct {
    char* access_token;
    int expires_in;
} token_t;

token_t* parse_token(char* json) {
    // Allocate memory for the token structure
    token_t* token = (token_t*)malloc(sizeof(token_t));
    if (!token) {
        perror("Failed to allocate memory for token");
        return NULL;
    }

    // Initialize variables
    char* error = NULL;
    int token_length = 0;

    // Parse the JSON string
    cJSON* json_obj = cJSON_Parse(json);
    if (!json_obj) {
        error = "Failed to parse JSON";
        goto error;
    }

    // Get the access token and expires in fields
    token->access_token = (char*)cJSON_GetObjectItem(json_obj, "access_token")->valuestring;
    if (!token->access_token) {
        error = "Failed to get access token";
        goto error;
    }
    token->expires_in = cJSON_GetObjectItem(json_obj, "expires_in")->valueint;
    if (token->expires_in < 0) {
        error = "Invalid expiration time";
        goto error;
    }

    // Validate the token type
    char* token_type = cJSON_GetObjectItem(json_obj, "token_type")->valuestring;
    if (!token_type) {
        error = "Failed to get token type";
        goto error;
    }
    if (strcmp(token_type, BEARER_TYPE)) {
        error = "Invalid token type";
        goto error;
    }

    // Validate the access token length
    token_length = strlen(token->access_token);
    if (token_length > MAX_TOKEN_LENGTH) {
        error = "Access token too long";
        goto error;
    }

    // Adjust the extension length based on the access token length
    int extension_length = MAX_TOKEN_LENGTH - token_length;

    // Set the token structure values
    token->expires_in += extension_length;

    // Free the JSON object and return the token structure
    cJSON_Delete(json_obj);
    return token;

error:
    if (error) {
        printf("Error parsing access token: %s\n", error);
    }
    cJSON_Delete(json_obj);
    free(token);
    return NULL;
}

int main() {
    char* json = "{\"access_token\":\"test\",\"expires_in\":3600,\"token_type\":\"Bearer\"}";
    token_t* token = parse_token(json);
    if (!token) {
        printf("Failed to parse access token\n");
        return 1;
    }
    printf("Parsed access token: %s (%d seconds)\n", token->access_token, token->expires_in);
    free(token);
    return 0;
}
