#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>
#include <signal.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/resource.h>
#include <errno.h>

// Define constants for image formats and conversion services
#define JPEG_FORMAT 0
#define PNG_FORMAT 1
#define GIF_FORMAT 2
#define PDF_FORMAT 3
#define IMAGE_CONVERSION_SERVICE 0
#define OTHER_CONVERSION_SERVICE 1

// Define a structure for image conversion metadata
typedef struct {
    char* file_path;
    int format;
    int service;
} image_conversion_metadata_t;

// Define a queue data structure for storing image conversion requests
typedef struct {
    image_conversion_metadata_t* metadata;
    int size;
    int front;
    int rear;
    sem_t mutex;
    sem_t empty;
    sem_t full;
} queue_t;

// Define a thread function for converting images to PDF format
void* convert_images(void* args) {
    // Cast the argument to a queue data structure
    queue_t* queue = (queue_t*)args;

    while (1) {
        // Acquire a lock on the mutex semaphore
        sem_wait(&queue->mutex);

        // Check if there are any items in the queue
        if (queue->size == 0) {
            // Release the lock on the mutex semaphore and exit the thread
            break;
        }

        // Pop an item from the front of the queue
        image_conversion_metadata_t* metadata = &queue->metadata[queue->front];
        queue->front = (queue->front + 1) % queue->size;
        queue->size--;

        // Release the lock on the mutex semaphore
        sem_post(&queue->mutex);

        // Convert the image to PDF format using a third-party library
        int status = convert_image(metadata->file_path, metadata->format, metadata->service);

        if (status != 0) {
            // Handle error by retrying or logging the error
            printf("Error converting image: %s\n", strerror(errno));
        } else {
            // Log conversion success
            printf("Image converted successfully: %s\n", metadata->file_path);
        }
    }
}

// Define a function for handling signals in the main thread
void handle_signal(int sig) {
    // Exit the program if the signal is SIGINT or SIGTERM
    if (sig == SIGINT || sig == SIGTERM) {
        exit(0);
    }
}

// Define a function for initializing the image conversion queue
void initialize_queue() {
    // Allocate memory for the queue data structure
    queue = malloc(sizeof(queue_t));

    // Initialize the mutex semaphore, empty semaphore, and full semaphore
    sem_init(&queue->mutex, 0, 1);
    sem_init(&queue->empty, 0, 0);
    sem_init(&queue->full, 0, 0);

    // Set the size of the queue to zero
    queue->size = 0;

    // Set the front and rear indices to zero
    queue->front = 0;
    queue->rear = 0;
}

// Define a function for enqueuing an image conversion request
void enqueue_request(image_conversion_metadata_t* metadata) {
    // Acquire a lock on the mutex semaphore
    sem_wait(&queue->mutex);

    // Check if the queue is full
    if (queue->size == queue->size) {
        // Release the lock on the mutex semaphore and return
        sem_post(&queue->mutex);
        printf("Queue is full, unable to enqueue request\n");
        return;
    }

    // Copy the image conversion metadata to the queue
    queue->metadata[queue->rear] = *metadata;
    queue->rear = (queue->rear + 1) % queue->size;
    queue->size++;

    // Release the lock on the mutex semaphore
    sem_post(&queue->mutex);
}

// Define a function for dequeuing an image conversion request
image_conversion_metadata_t* dequeue_request() {
    // Acquire a lock on the mutex semaphore
    sem_wait(&queue->mutex);

    // Check if the queue is empty
    if (queue->size == 0) {
        // Release the lock on the mutex semaphore and return NULL
        sem_post(&queue->mutex);
        return NULL;
    }

    // Pop an item from the front of the queue
    image_conversion_metadata_t* metadata = &queue->metadata[queue->front];
    queue->front = (queue->front + 1) % queue->size;
    queue->size--;

    // Release the lock on the mutex semaphore
    sem_post(&queue->mutex);

    return metadata;
}

// Define a function for starting the conversion thread
void start_conversion() {
    pthread_t tid;
    pthread_create(&tid, NULL, convert_images, (void*)&queue);
}

// Define a function for stopping the conversion thread
void stop_conversion() {
    // Send a signal to the conversion thread to exit
    pthread_kill(tid, SIGINT);
}

// Main function for the image conversion application
int main() {
    // Initialize the queue and start the conversion thread
    initialize_queue();
    start_conversion();

    // Set up signal handling in the main thread
    struct sigaction action;
    action.sa_handler = handle_signal;
    action.sa_flags = 0;
    sigfillset(&action.sa_mask);
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    // Loop indefinitely until a signal is received
    while (1) {
        sleep(1);
    }

    return 0;
}
```

This code creates a queue data structure to store image conversion requests and uses pthreads to create a thread that will continuously dequeue requests from the queue, convert the images, and log success or failure. The main function sets up signal handling in the main thread to catch SIGINT and SIGTERM signals and exits the program when one of these signals is received.

This code uses semaphores to protect access to the queue data structure. The mutex semaphore is used to lock the queue during enqueuing or dequeuing operations, while the empty and full semaphores are used to signal when the queue is empty or full, respectively. The main function also sets up signal handling in the main thread to catch SIGINT and SIGTERM signals and exits the program when one of these signals is received.

This code uses a third-party library for image conversion, which is called from within the conversion thread. The `convert_image` function takes three arguments: the file path of the image to convert, the format of the image (either JPEG or PNG), and the service used for image conversion (either Google Cloud Vision API or AWS Rekognition). If the conversion is successful, it returns 0. If there is an error during conversion, it returns a non-zero value and logs the error message.

This code uses a `handle_signal` function to handle SIGINT and SIGTERM signals in the main thread. When one of these signals is received, the program exits gracefully.']

