import java.util.*;
import org.json.*;
import com.google.gson.Gson;
import com.google.gson.JsonObject;

public class TaskOrchestrator {
  private static final String MANIFEST_FILE = "task-manifest.json";
  private static final String LOG_FILE = "task-orchestration.log";
  private static final int DEFAULT_RETRY_DELAY = 10; // seconds
  private static final int MAX_RETRY_ATTEMPTS = 3;
  private static final int CPU_THRESHOLD = 65; // percent of capacity
  private static final int MEMORY_THRESHOLD = 75; // percent of capacity
  private static final int IO_THRESHOLD = 80; // percent of capacity

  public static void main(String[] args) {
    // read configuration from JSON manifest file
    JsonObject manifest = readManifest();
    // create list of tasks to execute
    List<Task> tasks = parseTasks(manifest);
    // execute tasks in parallel with retries and error handling
    executeTasks(tasks);
  }

  private static void executeTasks(List<Task> tasks) {
    for (Task task : tasks) {
      try {
        // execute task and handle errors
        boolean success = task.execute();
        if (!success) {
          logError("Task failed: " + task);
        }
      } catch (Exception e) {
        logError("Task threw exception: " + task, e);
      }
    }
  }

  private static JsonObject readManifest() {
    // read JSON manifest file from disk
    File manifestFile = new File(MANIFEST_FILE);
    try (FileReader reader = new FileReader(manifestFile)) {
      return new Gson().fromJson(reader, JsonObject.class);
    } catch (IOException e) {
      logError("Failed to read JSON manifest file: " + manifestFile, e);
      return null;
    }
  }

  private static List<Task> parseTasks(JsonObject manifest) {
    // parse tasks from manifest object
    List<Task> tasks = new ArrayList<>();
    for (String taskName : manifest.keySet()) {
      JsonObject taskConfig = manifest.getAsJsonObject(taskName);
      Task task = new Task(taskName, taskConfig);
      tasks.add(task);
    }
    return tasks;
  }

  private static void logError(String message) {
    // write error message to log file
    try (FileWriter writer = new FileWriter(LOG_FILE, true)) {
      writer.write("ERROR: " + message + "\n");
    } catch (IOException e) {
      System.out.println("Failed to write to log file: " + LOG_FILE);
    }
  }

  private static void logError(String message, Exception e) {
    // write error message and exception to log file
    try (FileWriter writer = new FileWriter(LOG_FILE, true)) {
      writer.write("ERROR: " + message + "\n");
      e.printStackTrace(writer);
    } catch (IOException e1) {
      System.out.println("Failed to write to log file: " + LOG_FILE);
    }
  }
}
```
