namespace StreamIngestor
{
    public class StreamIngestor : IStreamIngestor
    {
        private readonly IServiceProvider _serviceProvider;
        private readonly IConfigurationService _configurationService;
        private readonly IDataProcessorService _dataProcessorService;
        private readonly IEventHandlerService _eventHandlerService;
        private readonly IErrorHandlingService _errorHandlingService;
        private readonly IMonitoringService _monitoringService;

        public StreamIngestor(IServiceProvider serviceProvider, IConfigurationService configurationService, IDataProcessorService dataProcessorService, IEventHandlerService eventHandlerService, IErrorHandlingService errorHandlingService, IMonitoringService monitoringService)
        {
            _serviceProvider = serviceProvider;
            _configurationService = configurationService;
            _dataProcessorService = dataProcessorService;
            _eventHandlerService = eventHandlerService;
            _errorHandlingService = errorHandlingService;
            _monitoringService = monitoringService;
        }

        public async Task IngestStreamAsync(IStream stream)
        {
            var configuration = await _configurationService.GetConfigurationAsync();
            var dataProcessor = _dataProcessorService.GetDataProcessor(stream.Provider);
            var eventHandler = _eventHandlerService.GetEventHandler(stream.Source);
            var errorHandling = _errorHandlingService.GetErrorHandlingStrategy(stream.Provider, stream.Source);
            var monitoring = _monitoringService.GetMonitoringStrategy(stream.Provider, stream.Source);

            try
            {
                while (true)
                {
                    await dataProcessor.ProcessStreamAsync(stream);
                    await eventHandler.HandleEventsAsync(stream.Events);
                    await monitoring.TrackEventsAsync(stream.Events);
                }
            }
            catch (Exception ex)
            {
                _errorHandlingService.HandleError(ex, stream.Provider, stream.Source);
                throw;
            }
        }
    }
}
