using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;
using Newtonsoft.Json;
using OAuth2Client;
using S3Client;

namespace CryptoService
{
    public class CryptoService : ICryptoService
    {
        private readonly IConfiguration _config;
        private readonly ILogger<CryptoService> _logger;
        private readonly IS3Client _s3Client;
        private readonly OAuth2Client _oauth2Client;

        public CryptoService(IConfiguration config, ILogger<CryptoService> logger, S3Client s3Client, OAuth2Client oauth2Client)
        {
            _config = config;
            _logger = logger;
            _s3Client = s3Client;
            _oauth2Client = oauth2Client;
        }

        public async Task<object> GetSensitiveData(string key, string iv)
        {
            // Check if the provided key and IV are valid
            if (!IsValidKeyAndIV(key, iv))
            {
                throw new ArgumentException("Invalid key or initialization vector");
            }

            // Generate a new AES decryptor with the provided key and IV
            using (var aes = new AesCryptoServiceProvider())
            {
                var decryptor = aes.CreateDecryptor(key, iv);
                try
                {
                    // Download the encrypted data from the cloud storage service
                    var encryptedData = await _s3Client.GetObjectAsync(_config["AwsS3Bucket"], _config["AwsS3Key"]);

                    // Decrypt the downloaded data using the provided key and IV
                    var decryptedData = decryptor.TransformFinalBlock(encryptedData, 0, encryptedData.Length);

                    // Deserialize the decrypted data into a custom data structure
                    return JsonConvert.DeserializeObject<CustomData>(Encoding.UTF8.GetString(decryptedData));
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Failed to download and decrypt sensitive data");
                    throw;
                }
            }
        }

        private bool IsValidKeyAndIV(string key, string iv)
        {
            // Check if the provided key and IV are valid AES-CBC keys and initialization vectors
            return (key.Length == 32 && iv.Length == 16) && !key.Any(char.IsWhiteSpace) && !iv.Any(char.IsWhiteSpace);
        }
    }
}
