use std::{env, path::PathBuf};
use serde::Deserialize;

#[derive(Deserialize)]
struct Config {
    #[serde(default = "default_config_dir")]
    config_dir: PathBuf,
}

fn default_config_dir() -> PathBuf {
    // determine the default configuration directory based on cloud service availability and user preferences
    let mut default_dir = env::var("CONFIG_DIR").unwrap_or_default();
    if default_dir.is_empty() {
        default_dir = "./config".to_string();
    }
    PathBuf::from(default_dir)
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let config: Config = serde_json::from_str(include_str!("config.json"))?;
    let config_dir = config.config_dir;

    // create the configuration directory if it doesn't exist
    std::fs::create_dir_all(&config_dir)?;

    // validate and update the configuration schema with the cloud service API
    validate_schema(config_dir.clone())?;

    // persist the updated schema to disk for future usage
    persist_schema(config_dir)?;

    Ok(())
}

fn validate_schema(config_dir: PathBuf) -> Result<(), Box<dyn std::error::Error>> {
    let mut file = File::open(&config_dir.join("schema.json"))?;
    let schema: Schema = serde_json::from_reader(&mut file)?;

    // validate the schema with the cloud service API
    let validation_result = validate(schema, &config_dir)?;

    if !validation_result {
        return Err("Schema validation failed".into());
    }

    Ok(())
}

fn persist_schema(config_dir: PathBuf) -> Result<(), Box<dyn std::error::Error>> {
    let mut file = File::create(&config_dir.join("schema.json"))?;
    let schema: Schema = serde_json::from_reader(&mut file)?;

    // persist the updated schema to disk for future usage
    Ok(())
}

fn validate(schema: Schema, config_dir: &PathBuf) -> Result<bool, Box<dyn std::error::Error>> {
    let mut validation_result = true;

    // validate the schema with the cloud service API
    for item in schema.items {
        let response = validate_item(item)?;

        if !response.valid {
            validation_result = false;
            break;
        }
    }

    Ok(validation_result)
}

fn validate_item(item: Item) -> Result<bool, Box<dyn std::error::Error>> {
    let mut validation_result = true;

    // validate the item with the cloud service API
    for field in item.fields {
        let response = validate_field(field)?;

        if !response.valid {
            validation_result = false;
            break;
        }
    }

    Ok(validation_result)
}

fn validate_field(field: Field) -> Result<bool, Box<dyn std::error::Error>> {
    let mut validation_result = true;

    // validate the field with the cloud service API
    for validation in field.validations {
        let response = validate_validation(validation)?;

        if !response.valid {
            validation_result = false;
            break;
        }
    }

    Ok(validation_result)
}

fn validate_validation(validation: Validation) -> Result<bool, Box<dyn std::error::Error>> {
    // validate the validation with the cloud service API
    let response = validate(validation.data)?;

    Ok(response.valid)
}

#[derive(Deserialize)]
struct Schema {
    items: Vec<Item>,
}

#[derive(Deserialize)]
struct Item {
    fields: Vec<Field>,
}

#[derive(Deserialize)]
struct Field {
    validations: Vec<Validation>,
}

#[derive(Deserialize)]
struct Validation {
    data: String,
}
