import json
import requests
from threading import RLock
from concurrent.futures import ThreadPoolExecutor

class DynamicJSONStore:
    def __init__(self, api_url, factory_registry):
        self.api_url = api_url
        self.factory_registry = factory_registry
        self.lock = RLock()
        self.executor = ThreadPoolExecutor(max_workers=5)

    def get(self, json_id):
        with self.lock:
            try:
                response = requests.get(f"{self.api_url}/{json_id}")
                if response.status_code == 200:
                    return json.loads(response.content)
                else:
                    raise Exception(f"Failed to retrieve JSON with ID {json_id}. Status code: {response.status_code}")
            except requests.exceptions.RequestException as e:
                print(e)

    def put(self, json_obj):
        with self.lock:
            try:
                response = requests.put(f"{self.api_url}/{json_obj['id']}", data=json.dumps(json_obj))
                if response.status_code == 201:
                    return json_obj
                else:
                    raise Exception(f"Failed to put JSON object with ID {json_obj['id']}. Status code: {response.status_code}")
            except requests.exceptions.RequestException as e:
                print(e)

    def update(self, json_id, updates):
        with self.lock:
            try:
                response = requests.patch(f"{self.api_url}/{json_id}", data=json.dumps(updates))
                if response.status_code == 200:
                    return json.loads(response.content)
                else:
                    raise Exception(f"Failed to update JSON object with ID {json_id}. Status code: {response.status_code}")
            except requests.exceptions.RequestException as e:
                print(e)

    def delete(self, json_id):
        with self.lock:
            try:
                response = requests.delete(f"{self.api_url}/{json_id}")
                if response.status_code == 204:
                    return f"Deleted JSON object with ID {json_id}"
                else:
                    raise Exception(f"Failed to delete JSON object with ID {json_id}. Status code: {response.status_code}")
            except requests.exceptions.RequestException as e:
                print(e)

    def create_factory(self, json_schema):
        with self.lock:
            try:
                response = requests.post(f"{self.api_url}/factories", data=json.dumps({'schema': json_schema}))
                if response.status_code == 201:
                    return json.loads(response.content)['id']
                else:
                    raise Exception(f"Failed to create factory for JSON schema {json_schema}. Status code: {response.status_code}")
            except requests.exceptions.RequestException as e:
                print(e)

    def get_factory(self, json_id):
        with self.lock:
            try:
                response = requests.get(f"{self.api_url}/factories/{json_id}")
                if response.status_code == 200:
                    return json.loads(response.content)['factory']
                else:
                    raise Exception(f"Failed to retrieve factory for JSON ID {json_id}. Status code: {response.status_code}")
            except requests.exceptions.RequestException as e:
                print(e)

    def create(self, json_obj):
        with self.lock:
            try:
                response = requests.post(f"{self.api_url}/create", data=json.dumps(json_obj))
                if response.status_code == 201:
                    return json.loads(response.content)['id']
                else:
                    raise Exception(f"Failed to create JSON object {json_obj}. Status code: {response.status_code}")
            except requests.exceptions.RequestException as e:
                print(e)

    def read(self, json_id):
        with self.lock:
            try:
                response = requests.get(f"{self.api_url}/read/{json_id}")
                if response.status_code == 200:
                    return json.loads(response.content)['obj']
                else:
                    raise Exception(f"Failed to read JSON object with ID {json_id}. Status code: {response.status_code}")
            except requests.exceptions.RequestException as e:
                print(e)

    def write(self, json_obj):
        with self.lock:
            try:
                response = requests.put(f"{self.api_url}/write/{json_obj['id']}", data=json.dumps(json_obj))
                if response.status_code == 201:
                    return json.loads(response.content)
                else:
                    raise Exception(f"Failed to write JSON object {json_obj}. Status code: {response.status_code}")
            except requests.exceptions.RequestException as e:
                print(e)

    def update_factory(self, json_id, updates):
        with self.lock:
            try:
                response = requests.patch(f"{self.api_url}/factories/{json_id}", data=json.dumps(updates))
                if response.status_code == 200:
                    return json.loads(response.content)['factory']
                else:
                    raise Exception(f"Failed to update factory for JSON ID {json_id}. Status code: {response.status_code}")
            except requests.exceptions.RequestException as e:
                print(e)

    def delete_factory(self, json_id):
        with self.lock:
            try:
                response = requests.delete(f"{self.api_url}/factories/{json_id}")
                if response.status_code == 204:
                    return f"Deleted factory for JSON ID {json_id}"
                else:
                    raise Exception(f"Failed to delete factory for JSON ID {json_id}. Status code: {response.status_code}")
            except requests.exceptions.RequestException as e:
                print(e)
