    double temperature;
    double humidity;
    double pressure;
};

// Define a custom middleware layer for data enrichment and transformation
class DataEnrichmentMiddleware {
public:
    // Constructor to initialize the middleware with an API client
    DataEnrichmentMiddleware(std::shared_ptr<ApiClient> api_client) : api_client_(api_client) {}

    // Function to enrich and transform the sensor reading data
    void enrichAndTransform(const SensorReading& reading, std::string& transformed_reading);

private:
    // API client for interacting with external calibration APIs
    std::shared_ptr<ApiClient> api_client_;
};

// Define the queue data structure to store sensor readings
class Queue {
public:
    // Constructor to initialize the queue with a capacity and a middleware layer
    Queue(size_t capacity, DataEnrichmentMiddleware& enrichment_middleware) :
        capacity_(capacity), enrichment_middleware_(enrichment_middleware) {}

    // Function to add a sensor reading to the queue
    void addReading(const SensorReading& reading);

    // Function to remove a sensor reading from the queue
    SensorReading removeReading();

    // Function to retrieve the size of the queue
    size_t size() { return readings_.size(); }

private:
    // Vector to store the sensor readings in the queue
    std::vector<SensorReading> readings_;

    // Maximum capacity of the queue
    size_t capacity_;

    // Middleware layer for data enrichment and transformation
    DataEnrichmentMiddleware& enrichment_middleware_;
};

// Define a thread-safe implementation of the queue
class ThreadSafeQueue : public Queue {
public:
    // Constructor to initialize the thread-safe queue with a capacity and a middleware layer
    ThreadSafeQueue(size_t capacity, DataEnrichmentMiddleware& enrichment_middleware) :
        Queue(capacity, enrichment_middleware), lock_(std::mutex()) {}

    // Function to add a sensor reading to the queue (thread-safe implementation)
    void addReading(const SensorReading& reading) {
        std::lock_guard<std::mutex> guard(lock_);
        readings_.push_back(reading);
    }

    // Function to remove a sensor reading from the queue (thread-safe implementation)
    SensorReading removeReading() {
        std::lock_guard<std::mutex> guard(lock_);
        if (!readings_.empty()) {
            auto reading = readings_.front();
            readings_.pop_front();
            return reading;
        } else {
            return SensorReading();
        }
    }

private:
    // Mutex to ensure thread-safe operations on the queue
    std::mutex lock_;
};

// Define a class for handling the high-throughput, persistent queue
class HighThroughputPersistentQueue {
public:
    // Constructor to initialize the high-throughput, persistent queue with a capacity and a middleware layer
    HighThroughputPersistentQueue(size_t capacity, DataEnrichmentMiddleware& enrichment_middleware) :
        queue_(capacity, enrichment_middleware), lock_(std::mutex()) {}

    // Function to add a sensor reading to the high-throughput, persistent queue
    void addReading(const SensorReading& reading) {
        std::lock_guard<std::mutex> guard(lock_);
        queue_.addReading(reading);
    }

    // Function to remove a sensor reading from the high-throughput, persistent queue
    SensorReading removeReading() {
        std::lock_guard<std::mutex> guard(lock_);
        return queue_.removeReading();
    }

private:
    // Thread-safe implementation of the queue for handling concurrent read/write access
    ThreadSafeQueue queue_;

    // Mutex to ensure thread-safe operations on the queue
    std::mutex lock_;
};

// Implementation of the DataEnrichmentMiddleware class
void DataEnrichmentMiddleware::enrichAndTransform(const SensorReading& reading, std::string& transformed_reading) {
    // Use the API client to enrich and transform the sensor reading data
    Json::Value json_reading = Json::Value(reading);
    Json::Value json_transformed_reading = api_client_->enrichAndTransform(json_reading);

    // Parse the transformed sensor reading data into a string
    std::stringstream ss;
    ss << json_transformed_reading;
    ss >> transformed_reading;
}

// Implementation of the Queue class
void Queue::addReading(const SensorReading& reading) {
    // Add the sensor reading to the vector of readings in the queue
    std::lock_guard<std::mutex> guard(lock_);
    if (readings_.size() < capacity_) {
        readings_.push_back(reading);
    } else {
        throw QueueFullException();
    }
}

SensorReading Queue::removeReading() {
    // Remove the first sensor reading from the vector of readings in the queue
    std::lock_guard<std::mutex> guard(lock_);
    if (!readings_.empty()) {
        auto reading = readings_.front();
        readings_.pop_front();
        return reading;
    } else {
        return SensorReading();
    }
}

// Implementation of the ThreadSafeQueue class
void ThreadSafeQueue::addReading(const SensorReading& reading) {
    // Use the lock to ensure thread-safe operations on the queue
    std::lock_guard<std::mutex> guard(lock_);
    Queue::addReading(reading);
}

SensorReading ThreadSafeQueue::removeReading() {
    // Use the lock to ensure thread-safe operations on the queue
    std::lock_guard<std::mutex> guard(lock_);
    return Queue::removeReading();
}

// Implementation of the HighThroughputPersistentQueue class
void HighThroughputPersistentQueue::addReading(const SensorReading& reading) {
    // Use the lock to ensure thread-safe operations on the queue
    std::lock_guard<std::mutex> guard(lock_);
    Queue::addReading(reading);
}

SensorReading HighThroughputPersistentQueue::removeReading() {
    // Use the lock to ensure thread-safe operations on the queue
    std::lock_guard<std::mutex> guard(lock_);
    return Queue::removeReading();
}
```

In this example, we have defined three classes: `Queue`, `ThreadSafeQueue`, and `HighThroughputPersistentQueue`. The `Queue` class is a basic implementation of a queue that stores sensor readings. It has a capacity, which is the maximum number of sensor readings it can store, and a middleware layer for data enrichment and transformation. The `ThreadSafeQueue` class is a thread-safe implementation of the `Queue` class, meaning that it can handle concurrent read/write operations on the queue. The `HighThroughputPersistentQueue` class is an extension of the `ThreadSafeQueue` class, adding high throughput and persistence to the queue.

We have also defined a `DataEnrichmentMiddleware` class that handles data enrichment and transformation for the sensor readings stored in the queue. This middleware layer can be used by any of the queues defined above to add additional functionality to the queue.

In this example, we have shown how to use multiple inheritance to create a hierarchy of classes that share common behavior and implementation. We have also demonstrated how to use composition to implement thread-safety in the `ThreadSafeQueue` class by using a `std::mutex` object to lock access to the queue.

This example is just one way to approach this problem, and there are many other ways to solve it depending on the specific requirements of your application.']

