        }
        cursor = cursor->next;
    }
}

void processStringThroughStage(struct connection_entry *connection, string_t *input, string_t *output) {
    // Check for null pointers and invalid size limits
    if (input == NULL || output == NULL || input->length < MIN_STRING_LENGTH || input->length > MAX_STRING_LENGTH) {
        printf("Invalid input or output buffer\n");
        return;
    }

    // Process string through stage function
    size_t length = strlen(input->buffer);
    char *buffer = malloc(sizeof(char) * (length + 1));
    memcpy(buffer, input->buffer, length);
    buffer[length] = '/';
    buffer[length + 1] = '\0';
    size_t size = strlen(buffer);

    // Check for output buffer overflow
    if (size > MAX_STRING_LENGTH) {
        printf("Output buffer overflow\n");
        return;
    }

    // Update output buffer with processed string
    memcpy(output->buffer, buffer, size + 1);
}

struct connection_entry* getConnection(struct connection_pool *pool) {
    if (pool == NULL) {
        printf("Invalid pool\n");
        return NULL;
    }
    struct connection_entry *connection = malloc(sizeof(struct connection_entry));
    connection->connection = createConnection();
    connection->next = pool->head;
    pool->head = connection;
    pool->count++;
    return connection;
}

void* createConnection() {
