}

// Function to handle an HTTP DELETE request and send the corresponding response
http_response http_delete(char *path, char *data) {
    // Initialize the connection pool if it hasn't been initialized yet
    if (async_responses == NULL) {
        init_connection_pool();
    }

    // Handle the HTTP DELETE request and send the corresponding response
    struct http_response res;
    res.status_code = "204 No Content";
    res.type = "text/html";
    res.body = delete_response(path, data);
