}

// Function to handle an HTTP PATCH request and send the corresponding response
http_response http_patch(char *path, char *data) {
    // Initialize the connection pool if it hasn't been initialized yet
    if (async_responses == NULL) {
        init_connection_pool();
    }

    // Handle the HTTP PATCH request and send the corresponding response
    struct http_response res;
    res.status_code = "204 No Content";
    res.type = "text/html";
    res.body = patch_response(path, data);
    return res;
}

// Function to handle an HTTP request and send the corresponding response
void http_handle_request(char *data) {
    // Initialize the connection pool if it hasn't been initialized yet
    if (async_responses == NULL) {
        init_connection_pool();
    }

    // Parse the HTTP request message and handle the corresponding HTTP request
    struct http_request req;
    req = parse_http_request(data);
    switch (req.method) {
        case GET:
            http_get(req.path, req.body);
            break;
        case POST:
            http_post(req.path, req.body);
            break;
        case PUT:
            http_put(req.path, req.body);
            break;
        case DELETE:
            http_delete(req.path, req.body);
            break;
        case PATCH:
            http_patch(req.path, req.body);
            break;
        default:
            printf("Invalid HTTP method\n");
    }
}

// Function to handle an HTTP request and send the corresponding response
void http_handle_response(char *data) {
    // Initialize the connection pool if it hasn't been initialized yet
    if (async_responses == NULL) {
        init_connection_pool();
    }

    // Parse the HTTP response message and handle the corresponding HTTP request
    struct http_response res;
    res = parse_http_response(data);
    switch (res.status_code[0]) {
        case '2':
            if (res.status_code[1] == '0') {
                // Handle 200 OK response
                printf("200 OK\n");
            } else if (res.status_code[1] == '1') {
                // Handle 201 Created response
                printf("201 Created\n");
            }
            break;
        case '4':
            if (res.status_code[1] == '0') {
                // Handle 400 Bad Request response
                printf("400 Bad Request\n");
            } else if (res.status_code[1] == '1') {
                // Handle 401 Unauthorized response
