            }
            break;
        case '5':
            if (res.status_code[1] == '0') {
                // Handle 500 Internal Server Error response
                printf("500 Internal Server Error\n");
            } else if (res.status_code[1] == '1') {
                // Handle 501 Not Implemented response
                printf("501 Not Implemented\n");
            }
            break;
        default:
            printf("Invalid HTTP status code\n");
    }
}

// Main function to handle an HTTP request or response and send the corresponding response
int main(int argc, char *argv[]) {
    // Initialize the connection pool if it hasn't been initialized yet
    if (async_responses == NULL) {
        init_connection_pool();
    }

    // Handle the HTTP request or response and send the corresponding response
