```java
import java.util.*;
import java.security.*;

public class ResourceManager {
    private static final int MAX_UUID_BATCH = 100;
    private static final String UUID_PATTERN = "^[a-fA-F0-9]{8}-[a-fA-F0-9]{4}-4[a-fA-F0-9]{3}-[8|9|aA|bB][a-fA-F0-9]{3}-[a-fA-F0-9]{12}$";
    private static final Map<String, String> UUID_MAP = new HashMap<>();

    public void createResource(List<String> uuids) {
        if (uuids.size() > MAX_UUID_BATCH) {
            throw new IllegalArgumentException("Too many UUIDs to process");
        }

        for (String uuid : uuids) {
            if (!uuid.matches(UUID_PATTERN)) {
                throw new IllegalArgumentException("Invalid UUID format: " + uuid);
            }
            if (UUID_MAP.containsKey(uuid)) {
                throw new IllegalStateException("Resource already exists: " + uuid);
            }
        }

        for (String uuid : uuids) {
            UUID_MAP.put(uuid, null);
        }
    }
}
