        if (uuids.size() > MAX_UUID_BATCH) {
            throw new IllegalArgumentException("Too many UUIDs to process");
        }

        for (String uuid : uuids) {
            if (!uuid.matches(UUID_PATTERN)) {
                throw new IllegalArgumentException("Invalid UUID format: " + uuid);
            }
            if (!UUID_MAP.containsKey(uuid)) {
                throw new IllegalStateException("Resource does not exist: " + uuid);
