#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <stdbool.h>
#include <assert.h>
#include <errno.h>
#include <pthread.h>
#include "fsm.h"
#include "networking.h"

struct state_list {
    int *states;
    size_t num_states;
};

struct fsa {
    struct state_list *initial_state;
    struct state_list *final_state;
    struct state_list *current_state;
};

// global variables for error handling
static bool error_occured = false;
static char error_message[256];

// callback function for external validation
void validate(int *states, size_t num_states, void (*callback)(int *, size_t)) {
    if (callback) {
        // run the callback function to validate the state list
        callback(states, num_states);
    } else {
        // external validation is not enabled, just return true
        return true;
    }
}

// function to dynamically allocate memory for a new state list
static struct state_list *allocate_state_list(int *states, size_t num_states) {
    // allocate memory for the state list
    struct state_list *new_state_list = malloc(sizeof(struct state_list));
    if (!new_state_list) {
        error_occured = true;
        snprintf(error_message, 256, "Failed to allocate memory for new state list: %s", strerror(errno));
        return NULL;
    }

    // copy the states and num_states into the new state list
    memcpy(new_state_list->states, states, sizeof(int) * num_states);
    new_state_list->num_states = num_states;

    return new_state_list;
}

// function to traverse the FSA and generate a new state list
static struct state_list *traverse_fsa(struct fsa *fsa, int last_state) {
    // allocate memory for the new state list
    struct state_list *new_state_list = malloc(sizeof(struct state_list));
    if (!new_state_list) {
        error_occured = true;
        snprintf(error_message, 256, "Failed to allocate memory for new state list: %s", strerror(errno));
        return NULL;
    }

    // initialize the new state list with a single initial state
    new_state_list->states[0] = fsa->initial_state->states[last_state];
    new_state_list->num_states = 1;

    // traverse the FSA and generate the new state list
    int i, j;
    for (i = last_state + 1; i < fsa->final_state->num_states; i++) {
        // check if there is a valid transition from the current state to the next state
        bool valid_transition = false;
        for (j = 0; j < fsa->initial_state->num_states; j++) {
            if (fsa->initial_state->states[j] == i) {
                valid_transition = true;
                break;
            }
        }

        // add the next state to the new state list if there is a valid transition
        if (valid_transition) {
            new_state_list->num_states++;
            new_state_list->states[new_state_list->num_states - 1] = i;
        }
    }

    return new_state_list;
}

// function to update the 'next' pointer of a state in the current list
static void update_current_state(struct fsa *fsa, int last_state) {
    // check if there is a valid transition from the current state to the next state
    bool valid_transition = false;
    for (int i = 0; i < fsa->initial_state->num_states; i++) {
        if (fsa->initial_state->states[i] == last_state) {
            valid_transition = true;
            break;
        }
    }

    // update the 'next' pointer of the current state to point to the new state list
    if (valid_transition) {
        fsa->current_state->next = traverse_fsa(fsa, last_state);
    } else {
        fsa->current_state->next = NULL;
    }
}

// function to manage the dynamic list of states from an FSA in a multi-threaded environment
struct fsa *manage_states(int *states, size_t num_states, struct fsa *fsa, int last_state, bool validity, void (*callback)(int *, size_t)) {
    // validate the FSA configuration and ensure that transitions from the current states are consistent and valid
    if (!validate(states, num_states, callback) || !validity) {
        error_occured = true;
        snprintf(error_message, 256, "FSA is invalid or has inconsistent transitions");
        return NULL;
    }

    // dynamically allocate memory for a new state list
    struct state_list *new_state_list = allocate_state_list(states, num_states);
    if (!new_state_list) {
        error_occured = true;
        snprintf(error_message, 256, "Failed to allocate memory for new state list: %s", strerror(errno));
        return NULL;
    }

    // traverse the FSA starting from the last state in the current list and generate a new state list
    struct state_list *new_state_list = traverse_fsa(fsa, last_state);
    if (!new_state_list) {
        error_occured = true;
        snprintf(error_message, 256, "Failed to generate new state list: %s", strerror(errno));
        return NULL;
    }

    // update the 'next' pointer of the current state to point to the new state list
    update_current_state(fsa, last_state);

    return fsa;
}

// example usage
