    unsigned char iv[AES_BLOCK_SIZE];
} EncryptionKey;

// Function to initialize the module with the provided password
void nfapi_crc_indication_pdu_init(const char* password) {
    // Derive the encryption key using PBKDF2 from the provided password
    unsigned char salt[16];
    RAND_bytes(salt, sizeof(salt));
    EncryptionKey *key = (EncryptionKey*)OPENSSL_malloc(sizeof(EncryptionKey));
    EVP_BytesToKey(EVP_aes_256_cbc(), EVP_md5(), salt, password, strlen(password), 1000, key->aesKey.key, key->iv);

