    AES_set_encrypt_key(&key->aesKey, &key->aesKey);
    memcpy(key->iv, key->iv, AES_BLOCK_SIZE);
}

// Function to generate the list of NFAPI_CRC_INDICATION_PDU_T structures
void nfapi_crc_indication_pdu_generate(const char* inputString) {
    // Compute the MD5 hash of the provided string input
    unsigned char md5Hash[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)inputString, strlen(inputString), md5Hash);

    // Create a new NFAPI_CRC_INDICATION_PDU_T structure and populate it with the computed hash
