        memcpy(ueIdentifiers[0], pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        for (int i = 1; i < MAX_UE_IDENTIFIERS - 1; i++) {
            memcpy(ueIdentifiers[i], ueIdentifiers[i + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T));
        }
    }
    pthread_mutex_unlock(&ueIdentifiersLock);

    // Add the new PDU to the list of RNTIs
    pthread_mutex_lock(&rntisLock);
    if (numRNTIs < MAX_RNTIS) {
        memcpy(rntis[numRNTIs], pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        numRNTIs++;
    } else {
        // Handle overflow by removing the oldest entry and adding the new one
        memcpy(rntis[0], pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        for (int i = 1; i < MAX_RNTIS - 1; i++) {
            memcpy(rntis[i], rntis[i + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T));
        }
