{
    public class AdaptiveRandomValueGenerator
    {
        private readonly AdaptiveGeneratorSettings _settings;
        private readonly Random _random = new Random();
        private readonly List<IList<float>> _historicalData = new List<IList<float>>();

        public AdaptiveRandomValueGenerator(AdaptiveGeneratorSettings settings)
        {
            _settings = settings;
        }

        // Generate a single float value within the specified bounds
        public float NextFloat()
        {
            return (float)_random.NextDouble(_settings.Minimum, _settings.Maximum);
        }

        // Generate a list of float values within the specified bounds
        public IList<float> NextFloats(int count)
        {
            return Enumerable.Range(0, count).Select(i => NextFloat()).ToList();
        }

        // Generate a 2D array of float values within the specified bounds
        public float[,] NextFloatArray(int rows, int cols)
        {
            var data = new float[rows, cols];
            for (var i = 0; i < rows; i++)
            {
                for (var j = 0; j < cols; j++)
                {
                    data[i, j] = NextFloat();
                }
            }
            return data;
        }

        // Generate a jagged array of float values within the specified bounds
        public IList<IList<float>> NextJaggedArray(int rows)
        {
            var data = new List<IList<float>>(rows);
            for (var i = 0; i < rows; i++)
            {
                data.Add(NextFloats(_settings.ColumnCount));
            }
            return data;
        }

        // Generate a single int value within the specified bounds
        public int NextInt()
        {
            return _random.Next(_settings.Minimum, _settings.Maximum + 1);
        }

        // Generate a list of int values within the specified bounds
        public IList<int> NextInts(int count)
        {
            return Enumerable.Range(0, count).Select(i => NextInt()).ToList();
        }

        // Generate a 2D array of int values within the specified bounds
        public int[,] NextIntArray(int rows, int cols)
        {
            var data = new int[rows, cols];
            for (var i = 0; i < rows; i++)
            {
                for (var j = 0; j < cols; j++)
                {
                    data[i, j] = NextInt();
                }
            }
            return data;
        }

        // Generate a jagged array of int values within the specified bounds
        public IList<IList<int>> NextJaggedArray(int rows)
        {
            var data = new List<IList<int>>(rows);
            for (var i = 0; i < rows; i++)
            {
                data.Add(NextInts(_settings.ColumnCount));
            }
            return data;
        }

        // Generate a single custom type value using the specified distribution and bounds
        public T NextCustomType<T>(Distribution distribution) where T : IConvertible
        {
            var random = new Random();
            switch (distribution)
            {
                case Distribution.Uniform:
                    return (T)(object)_random.NextDouble(_settings.Minimum, _settings.Maximum);
                case Distribution.Normal:
                    return (T)(object)random.NextGaussian(_settings.Mean, _settings.StandardDeviation);
                default:
                    throw new NotSupportedException($"Distribution {distribution} is not supported.");
            }
        }

        // Generate a list of custom type values using the specified distribution and bounds
        public IList<T> NextCustomTypes<T>(int count, Distribution distribution) where T : IConvertible
        {
            return Enumerable.Range(0, count).Select(i => NextCustomType<T>(distribution)).ToList();
        }

        // Generate a 2D array of custom type values using the specified distribution and bounds
        public T[,] NextCustomArray<T>(int rows, int cols, Distribution distribution) where T : IConvertible
        {
            var data = new T[rows, cols];
            for (var i = 0; i < rows; i++)
            {
                for (var j = 0; j < cols; j++)
                {
                    data[i, j] = NextCustomType<T>(distribution);
                }
            }
            return data;
        }

        // Generate a jagged array of custom type values using the specified distribution and bounds
        public IList<IList<T>> NextJaggedArray<T>(int rows, Distribution distribution) where T : IConvertible
        {
            var data = new List<IList<T>>(rows);
            for (var i = 0; i < rows; i++)
            {
                data.Add(NextCustomTypes<T>(_settings.ColumnCount, distribution));
            }
            return data;
        }
    }
