    std::lock_guard<std::mutex> lock(flow_mutex);
    flows.push_back(flow);
    cv.notify_all();
}

// Function to remove a flow from the vector of flows
void remove_flow(const Flow& flow) {
    std::lock_guard<std::mutex> lock(flow_mutex);
    auto it = std::find(flows.begin(), flows.end(), flow);
    if (it != flows.end()) {
        flows.erase(it);
    }
}

// Function to update the start time of a flow in the vector of flows
void update_start_time(const Flow& flow) {
    std::lock_guard<std::mutex> lock(flow_mutex);
    auto it = std::find(flows.begin(), flows.end(), flow);
    if (it != flows.end()) {
        (*it).start_time = flow.start_time;
    }
}

// Function to update the last update time of a flow in the vector of flows
void update_last_update(const Flow& flow) {
    std::lock_guard<std::mutex> lock(flow_mutex);
    auto it = std::find(flows.begin(), flows.end(), flow);
    if (it != flows.end()) {
        (*it).last_update = flow.last_update;
    }
}

// Function to generate a report for the vector of flows
void generate_report() {
    std::lock_guard<std::mutex> lock(flow_mutex);
    // Calculate the total duration of all flows
    long total_duration = 0;
    for (auto& flow : flows) {
        total_duration += flow.last_update - flow.start_time;
    }
    // Create a new report with the calculated duration
    Report report;
    report.src_ip = "N/A";
    report.dst_ip = "N/A";
    report.src_port = 0;
    report.dst_port = 0;
    report.start_time = flows[0].start_time;
    report.end_time = flows[flows.size() - 1].last_update;
    // Add the report to the vector of reports
    std::lock_guard<std::mutex> lock(report_mutex);
    reports.push_back(report);
}

// Function to check if a flow is valid and can be processed
bool validate_flow(const Flow& flow) {
    // Check if the IP addresses are valid
    if (flow.src_ip == "N/A" || flow.dst_ip == "N/A") {
        return false;
    }
    // Check if the ports are valid
    if (flow.src_port < 0 || flow.dst_port < 0) {
        return false;
    }
    // Check if the start time is valid
    if (flow.start_time <= 0) {
        return false;
    }
    // Check if the last update is valid
    if (flow.last_update <= flow.start_time) {
        return false;
    }
    return true;
}

// Function to handle API failures and retry
void handle_api_failure(const std::string& api_ip, const std::string& error_msg) {
    std::cout << "API failure: " << api_ip << ": " << error_msg << std::endl;
    // Remove the API from the map of API IDs to IP addresses
    apis.erase(api_ids[api_ip]);
    // Remove the API ID from the map of IP addresses to API IDs
    api_ids.erase(api_ip);
}

// Function to handle API timeouts and retries
void handle_api_timeout(const std::string& api_ip) {
    std::cout << "API timeout: " << api_ip << std::endl;
    // Retry the API connection after a delay
    std::this_thread::sleep_for(std::chrono::seconds(API_RETRY_DELAY));
}

// Function to handle invalid flow data and discard it
void handle_invalid_flow(const Flow& flow) {
    std::cout << "Invalid flow: " << flow.src_ip << ", " << flow.dst_ip << ", " << flow.src_port << ", " << flow.dst_port << std::endl;
}

