    apis["API1"] = "192.168.1.100";
    apis["API2"] = "192.168.1.101";
    apis["API3"] = "192.168.1.102";
    // Initialize the map of IP addresses to API IDs
    api_ids["192.168.1.100"] = "API1";
    api_ids["192.168.1.101"] = "API2";
    api_ids["192.168.1.102"] = "API3";
    // Initialize the vector of flows
