    // Initialize the vector of reports
    std::vector<Report> reports;
    // Loop indefinitely until a shutdown signal is received
    while (true) {
        // Check if there are any new flows to process
        std::lock_guard<std::mutex> lock(flow_mutex);
        if (!flows.empty()) {
            // Process the first flow in the vector of flows
            Flow flow = flows[0];
            flows.erase(flows.begin());
            // Check if the flow is valid and can be processed
            if (validate_flow(flow)) {
                // Send the flow to the appropriate API for processing
                std::string api_ip = apis[api_ids[flow.dst_ip]];
                send_flow(api_ip, flow);
            } else {
