                handle_invalid_flow(flow);
            }
        }
        // Check if there are any new reports to generate
        std::lock_guard<std::mutex> lock(report_mutex);
        if (!reports.empty()) {
            // Generate the report for the vector of flows
            generate_report();
        }
    }
    return 0;
}
