#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>

// Define the record structure
typedef struct {
    int key;
    double value;
} Record;

// Define the distributed collection structure
typedef struct {
    // Array to store records
    Record *records;
    // Number of records in the array
    uint32_t num_records;
    // Mutex for protecting the array from concurrent access
    pthread_mutex_t mutex;
    // Semaphore for signaling when a record is added/updated/removed
    sem_t sem;
} DistributedCollection;

// Initialize the distributed collection structure
void init_distributed_collection(DistributedCollection *dc) {
    dc->records = NULL;
    dc->num_records = 0;
    pthread_mutex_init(&(dc->mutex), NULL);
    sem_init(&(dc->sem), 0, 0);
}

// Add a record to the distributed collection
void add_record(DistributedCollection *dc, int key, double value) {
    pthread_mutex_lock(&(dc->mutex));
    // Check if the key already exists in the array
    for (uint32_t i = 0; i < dc->num_records; i++) {
        if (dc->records[i].key == key) {
            printf("Key %d already exists\n", key);
            pthread_mutex_unlock(&(dc->mutex));
            return;
        }
    }
    // If the key doesn't exist, add a new record to the end of the array
    dc->records = realloc(dc->records, (dc->num_records + 1) * sizeof(Record));
    dc->records[dc->num_records].key = key;
    dc->records[dc->num_records].value = value;
    dc->num_records++;
    pthread_mutex_unlock(&(dc->mutex));
    sem_post(&(dc->sem));
}

// Update a record in the distributed collection
void update_record(DistributedCollection *dc, int key, double value) {
    pthread_mutex_lock(&(dc->mutex));
    // Check if the key exists in the array
    for (uint32_t i = 0; i < dc->num_records; i++) {
        if (dc->records[i].key == key) {
            dc->records[i].value = value;
            break;
        }
    }
    pthread_mutex_unlock(&(dc->mutex));
    sem_post(&(dc->sem));
}

// Remove a record from the distributed collection
void remove_record(DistributedCollection *dc, int key) {
    pthread_mutex_lock(&(dc->mutex));
    // Check if the key exists in the array
    for (uint32_t i = 0; i < dc->num_records; i++) {
        if (dc->records[i].key == key) {
            // Shift the remaining records to fill the gap
            memmove(&(dc->records[i]), &(dc->records[i + 1]), sizeof(Record));
            dc->num_records--;
            break;
        }
    }
    pthread_mutex_unlock(&(dc->mutex));
    sem_post(&(dc->sem));
}

// Get the value of a record in the distributed collection
double get_record_value(DistributedCollection *dc, int key) {
    double value = 0;
    pthread_mutex_lock(&(dc->mutex));
    // Check if the key exists in the array
    for (uint32_t i = 0; i < dc->num_records; i++) {
        if (dc->records[i].key == key) {
            value = dc->records[i].value;
            break;
        }
    }
    pthread_mutex_unlock(&(dc->mutex));
    return value;
}

// Clean up the distributed collection structure
void cleanup_distributed_collection(DistributedCollection *dc) {
    free(dc->records);
    dc->num_records = 0;
    pthread_mutex_destroy(&(dc->mutex));
    sem_destroy(&(dc->sem));
}
```
This implementation provides a thread-safe and scalable way to manage a distributed collection of `record` structures in C. The `DistributedCollection` structure contains an array of `Record` structures, a mutex for protecting the array from concurrent access, and a semaphore for signaling when a record is added/updated/removed.

The `add_record`, `update_record`, and `remove_record` functions take in a key and value to be added/updated/removed, respectively, and lock the mutex before searching for the record with the matching key in the array. If the key exists, it updates the corresponding value and unlocks the mutex. If the key doesn't exist, it adds a new record to the end of the array and unlocks the mutex.

The `get_record_value` function takes in a key and returns the corresponding value if the key exists in the array, or 0 otherwise. The function locks the mutex before searching for the record with the matching key in the array, and then unlocks the mutex before returning the value.

The `cleanup_distributed_collection` function frees up the memory allocated for the records and clears the semaphore.

Note that this implementation assumes that the keys are unique and that no key will be removed while it is still being used by another thread. If this is not the case, additional synchronization mechanisms may need to be added to ensure correctness.']

