#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <map>
#include <set>
#include <llvm/IR/LLVMContext.h>
#include <llvm/IR/Module.h>
#include <llvm/IR/Function.h>
#include <llvm/IR/BasicBlock.h>
#include <llvm/IR/Instruction.h>
#include <llvm/IR/Constants.h>
#include <llvm/IR/DebugInfo.h>
#include <llvm/IR/Verifier.h>
#include <llvm/Support/raw_ostream.h>

using namespace llvm;

std::string generateLLVMIRCode(const std::string& filePath) {
    // Initialize the LLVM context
    LLVMContext context;

    // Load the YAML file and parse it using a lexer and parser
    std::ifstream inputFile(filePath);
    if (!inputFile.is_open()) {
        throw "Could not open input file";
    }
    llvm::yaml::Input yamlParser(inputFile);

    // Parse the YAML file and generate the LLVM IR code for the state machine
    std::vector<std::string> states;
    std::map<std::string, std::set<std::string>> transitions;
    std::set<std::string> actions;
    while (!yamlParser.AtEndOfStream()) {
        llvm::yaml::Node* node = yamlParser.begin().getCurrent();
        if (node->getKind() == llvm::yaml::Node::Kind::Map) {
            llvm::yaml::MappingNode* mapNode = llvm::cast<llvm::yaml::MappingNode>(node);
            for (auto it = mapNode->begin(), end = mapNode->end(); it != end; ++it) {
                llvm::yaml::ScalarNode* scalarNode = llvm::dyn_cast<llvm::yaml::ScalarNode>(it->getKey());
                if (!scalarNode) continue;
                std::string key = scalarNode->getValue().str();
                llvm::yaml::MappingNode* mappingNode = llvm::dyn_cast<llvm::yaml::MappingNode>(it->getValue());
                if (key == "states") {
                    for (auto it2 = mappingNode->begin(), end2 = mappingNode->end(); it2 != end2; ++it2) {
                        llvm::yaml::ScalarNode* scalarNode = llvm::dyn_cast<llvm::yaml::ScalarNode>(it2->getKey());
                        if (!scalarNode) continue;
                        std::string state = scalarNode->getValue().str();
                        states.push_back(state);
                    }
                } else if (key == "transitions") {
                    for (auto it2 = mappingNode->begin(), end2 = mappingNode->end(); it2 != end2; ++it2) {
                        llvm::yaml::ScalarNode* scalarNode = llvm::dyn_cast<llvm::yaml::ScalarNode>(it2->getKey());
                        if (!scalarNode) continue;
                        std::string fromState = scalarNode->getValue().str();
                        llvm::yaml::MappingNode* mappingNode2 = llvm::dyn_cast<llvm::yaml::MappingNode>(it2->getValue());
                        for (auto it3 = mappingNode2->begin(), end3 = mappingNode2->end(); it3 != end3; ++it3) {
                            llvm::yaml::ScalarNode* scalarNode2 = llvm::dyn_cast<llvm::yaml::ScalarNode>(it3->getKey());
                            if (!scalarNode2) continue;
                            std::string toState = scalarNode2->getValue().str();
                            transitions[fromState].insert(toState);
                        }
                    }
                } else if (key == "actions") {
                    for (auto it2 = mappingNode->begin(), end2 = mappingNode->end(); it2 != end2; ++it2) {
                        llvm::yaml::ScalarNode* scalarNode = llvm::dyn_cast<llvm::yaml::ScalarNode>(it2->getKey());
                        if (!scalarNode) continue;
                        std::string action = scalarNode->getValue().str();
                        actions.insert(action);
                    }
                }
            }
        }
    }

    // Create the LLVM module and function for the state machine
    Module* module = new Module("StateMachine", context);
    FunctionType* functionType = FunctionType::get(IntegerType::get(context, 32), {}, false);
    Function* function = module->getOrInsertFunction("main", functionType).first;

    // Generate the LLVM IR code for the state transitions and actions
    BasicBlock* entryBB = BasicBlock::Create(context, "entry", function);
    BasicBlock* startBB = BasicBlock::Create(context, "start", function);
    std::vector<BasicBlock*> exitBBs;
    for (std::string state : states) {
        BasicBlock* bb = BasicBlock::Create(context, "bb_" + state, function);
        exitBBs.push_back(bb);
        if (state == startState) {
            BranchInst::Create(bb, entryBB);
        } else {
            BranchInst::Create(bb, startBB);
        }
    }
    BasicBlock* endBB = BasicBlock::Create(context, "end", function);
    BranchInst::Create(endBB, startBB);
    for (std::string state : states) {
        for (std::string action : actions) {
            std::string actionName = "action_" + action;
            Function* actionFunction = module->getOrInsertFunction(actionName, functionType).first;
            CallInst::Create(actionFunction, {}, bb);
        }
    }
    BranchInst::Create(endBB, exitBBs[0]);
    for (int i = 1; i < exitBBs.size(); ++i) {
        BranchInst::Create(exitBBs[i], exitBBs[0]);
    }

    // Print the LLVM IR code
    llvm::raw_string_ostream os(buffer);
    module->print(os, nullptr);

    return buffer;
}']

