Here is an example implementation of a command-line utility in C++ that integrates with a versioned external API to fetch and process configuration files:
```c++
#include <iostream>
#include <fstream>
#include <string>
#include <chrono>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <map>
#include <vector>
#include <set>
#include <cassert>
#include <stdexcept>
#include <algorithm>

// Define the API endpoint and credentials here
const std::string API_ENDPOINT = "https://api.example.com/configs";
const std::string CLIENT_ID = "your-client-id";
const std::string CLIENT_SECRET = "your-client-secret";

// Define the output directories and formats here
const std::vector<std::string> OUTPUT_DIRS = {"output1", "output2"};
const std::set<std::string> SUPPORTED_FORMATS = {"json", "csv", "xml"};

class APIClient {
 public:
  // Constructor to initialize the client with the API endpoint and credentials
  APIClient(const std::string& endpoint, const std::string& client_id, const std::string& client_secret)
      : endpoint_(endpoint), client_id_(client_id), client_secret_(client_secret) {}

  // Function to fetch configuration files from the API
  std::vector<std::string> fetchConfigs() {
    std::vector<std::string> configs;

    // Use OAuth2 authentication and rate limiting to manage API requests
    auto auth = Authenticator(CLIENT_ID, CLIENT_SECRET);
    auth.refreshToken();

    // Fetch the configuration files from the API
    std::vector<std::string> file_names;
    for (const auto& file : fetchFiles()) {
      configs.push_back(fetchConfig(file));
    }

    return configs;
  }

 private:
  // Function to fetch configuration files from the API
  std::vector<std::string> fetchFiles() {
    auto request = Request("GET", endpoint_, "");
    request.setAuthenticator(auth);

    // Send the request and parse the response
    auto response = Response(request);
    if (response.getStatusCode() == 200) {
      std::vector<std::string> files;
      for (const auto& file : response.getBody()) {
        files.push_back(file["name"].asString());
      }
      return files;
    } else {
      throw std::runtime_error("Error fetching configuration files from the API");
    }
  }

  // Function to fetch a single configuration file from the API
  std::string fetchConfig(const std::string& file) {
    auto request = Request("GET", endpoint_, file);
    request.setAuthenticator(auth);

    // Send the request and parse the response
    auto response = Response(request);
    if (response.getStatusCode() == 200) {
      return response.getBody().asString();
    } else {
      throw std::runtime_error("Error fetching configuration file from the API");
    }
  }

  // Define the API endpoint and credentials here
  const std::string endpoint_;
  const std::string client_id_;
  const std::string client_secret_;
};

class ConfigProcessor {
 public:
  // Constructor to initialize the processor with the output directories and formats
  ConfigProcessor(const std::vector<std::string>& output_dirs, const std::set<std::string>& supported_formats)
      : output_dirs_(output_dirs), supported_formats_(supported_formats) {}

  // Function to process configuration files and write them to the output directories
  void processConfigs(const std::vector<std::string>& configs) {
    // Use a thread pool to concurrently process the configuration files
    auto worker = [](const std::string& config, const std::string& output_dir, const std::set<std::string>& supported_formats) {
      // Check if the output directory exists and create it if necessary
      bool success = createDirectory(output_dir);
      if (!success) {
        throw std::runtime_error("Error creating output directory");
      }

      // Write the configuration file to the output directory in the supported format
      for (const auto& format : supported_formats) {
        auto filename = getFilename(output_dir, config);
        writeConfig(config, filename, format);
      }
    };

    std::vector<std::thread> threads;
    for (const auto& config : configs) {
      // Create a new thread for each configuration file to be processed
      threads.push_back(std::thread(worker, config, output_dirs_[0], supported_formats_));
    }

    // Join the threads and handle any exceptions that may have occurred during processing
    for (auto& thread : threads) {
      try {
        thread.join();
      } catch (const std::exception& e) {
        std::cerr << "Error processing configuration file: " << e.what() << std::endl;
      }
    }
  }

 private:
  // Function to write a configuration file to an output directory in the supported format
  void writeConfig(const std::string& config, const std::string& filename, const std::string& format) {
    auto parser = Parser(config);

    if (format == "json") {
      // Write the configuration as JSON to a file with the given filename and extension
      auto json_data = parser.toJSON();
      writeFile(filename + ".json", json_data);
    } else if (format == "csv") {
      // Write the configuration as CSV to a file with the given filename and extension
      auto csv_data = parser.toCSV();
      writeFile(filename + ".csv", csv_data);
    } else {
      throw std::runtime_error("Unsupported format");
    }
  }

  // Function to create an output directory if it does not exist
  bool createDirectory(const std::string& dir) {
    // Check if the output directory exists
    if (exists(dir)) {
      return true;
    } else {
      // Create the output directory if necessary
      try {
        create_directory(dir);
        return true;
      } catch (const std::exception& e) {
        std::cerr << "Error creating output directory: " << e.what() << std::endl;
        return false;
      }
    }
  }

  // Function to get the filename for a configuration file with the given output directory and format
  std::string getFilename(const std::string& output_dir, const std::string& config) {
    auto parser = Parser(config);
    auto name = parser.getName();
    return output_dir + "/" + name;
  }

  // Define the output directories and formats here
  const std::vector<std::string> output_dirs_;
  const std::set<std::string> supported_formats_;
};

int main() {
  // Initialize the API client
  auto api = APIClient();

  // Define the output directories and formats here
  const std::vector<std::string> output_dirs = {"output"};
  const std::set<std::string> supported_formats = {"json", "csv"};

  // Get the configuration files from the API client
  auto configs = api.fetchConfigurations();

  // Process the configuration files and write them to the output directories in the supported formats
  ConfigProcessor(output_dirs, supported_formats).processConfigs(configs);
}
```

In this example, we first define a class called `APIClient` that is responsible for fetching configuration files from an API. We then define a class called `ConfigProcessor` that is responsible for processing the configuration files and writing them to output directories in supported formats. Finally, we create an instance of `ConfigProcessor` and use it to process the configuration files returned by the API client.

