    EDE = 1,
    EDE3 = 2,
    CFB = 3
};

// Define the supported encryption algorithms and their corresponding values
enum EncryptionAlgorithm {
    DES = 0,
    AES = 1
};

// Struct to hold the context of an encryption/decryption operation
struct EncryptionContext {
    uint8_t *key;      // Key used for encryption/decryption
    uint32_t key_size; // Size of the key in bytes
    uint32_t block_size; // Block size of the cipher mode
    enum CipherMode cipher_mode; // Cipher mode used for encryption/decryption
    enum EncryptionAlgorithm algorithm; // Algorithm used for encryption/decryption
};

// Function to select a supported cipher mode and initialize an encryption context
struct EncryptionContext* init_encrypt(uint8_t *key, uint32_t key_size, enum CipherMode cipher_mode) {
    // Validate the input parameters
    if (key == NULL || key_size < 1 || !is_supported_cipher_mode(cipher_mode)) {
        return NULL;
    }

    // Allocate memory for the encryption context
    struct EncryptionContext *context = malloc(sizeof(struct EncryptionContext));
    if (context == NULL) {
        return NULL;
    }

    // Initialize the encryption context
    context->key = key;
    context->key_size = key_size;
    context->block_size = get_cipher_block_size(cipher_mode);
    context->cipher_mode = cipher_mode;
    context->algorithm = DES; // Default to DES as the encryption algorithm

    return context;
}

// Function to encrypt data using a given encryption context and return the encrypted data
uint8_t* encrypt(struct EncryptionContext *context, uint8_t *data, uint32_t data_size) {
    // Validate the input parameters
    if (context == NULL || data == NULL || data_size < 1) {
        return NULL;
    }

    // Calculate the total size of the encrypted data in bytes
    uint32_t encrypted_data_size = ceil((double)data_size / context->block_size) * context->block_size;

    // Allocate memory for the encrypted data
    uint8_t *encrypted_data = malloc(encrypted_data_size);
    if (encrypted_data == NULL) {
        return NULL;
    }

    // Encrypt the data using the selected cipher mode and encryption algorithm
    encrypt_blocks(context->cipher_mode, context->algorithm, context->key, context->key_size, data, data_size, encrypted_data);

    return encrypted_data;
}

// Function to decrypt data using a given encryption context and return the decrypted data
uint8_t* decrypt(struct EncryptionContext *context, uint8_t *encrypted_data, uint32_t encrypted_data_size) {
    // Validate the input parameters
    if (context == NULL || encrypted_data == NULL || encrypted_data_size < 1) {
        return NULL;
    }

    // Calculate the total size of the decrypted data in bytes
    uint32_t decrypted_data_size = ceil((double)encrypted_data_size / context->block_size) * context->block_size;

    // Allocate memory for the decrypted data
    uint8_t *decrypted_data = malloc(decrypted_data_size);
    if (decrypted_data == NULL) {
        return NULL;
    }

    // Decrypt the encrypted data using the selected cipher mode and encryption algorithm
    decrypt_blocks(context->cipher_mode, context->algorithm, context->key, context->key_size, encrypted_data, encrypted_data_size, decrypted_data);

    return decrypted_data;
}

// Function to free the memory allocated for an encryption context
void free_encrypt(struct EncryptionContext *context) {
    if (context != NULL) {
        free(context->key);
        free(context);
    }
}

// Private function to check whether a given cipher mode is supported by the library
int is_supported_cipher_mode(enum CipherMode cipher_mode) {
    switch (cipher_mode) {
        case ECB:
        case EDE:
        case EDE3:
        case CFB:
            return 1;
        default:
            return 0;
    }
}

// Private function to get the block size of a given cipher mode
uint32_t get_cipher_block_size(enum CipherMode cipher_mode) {
    switch (cipher_mode) {
        case ECB:
            return 1; // ECB is a single-block encryption mode
        case EDE:
            return 8; // EDE uses a 64-bit block size
        case EDE3:
            return 8; // EDE3 uses a 64-bit block size
        case CFB:
            return 1; // CFB is a single-block encryption mode
        default:
            return 0;
    }
}

// Private function to encrypt data using the selected cipher mode and encryption algorithm
void encrypt_blocks(enum CipherMode cipher_mode, enum EncryptionAlgorithm algorithm, uint8_t *key, uint32_t key_size, uint8_t *data, uint32_t data_size, uint8_t *encrypted_data) {
    switch (cipher_mode) {
        case ECB:
            encrypt_ecb(algorithm, key, key_size, data, data_size, encrypted_data);
            break;
        case EDE:
            encrypt_ede(algorithm, key, key_size, data, data_size, encrypted_data);
            break;
        case EDE3:
            encrypt_ede3(algorithm, key, key_size, data, data_size, encrypted_data);
            break;
        case CFB:
            encrypt_cfb(algorithm, key, key_size, data, data_size, encrypted_data);
            break;
        default:
            return; // Unsupported cipher mode
    }
}

// Private function to decrypt data using the selected cipher mode and encryption algorithm
void decrypt_blocks(enum CipherMode cipher_mode, enum EncryptionAlgorithm algorithm, uint8_t *key, uint32_t key_size, uint8_t *encrypted_data, uint32_t encrypted_data_size, uint8_t *decrypted_data) {
    switch (cipher_mode) {
        case ECB:
            decrypt_ecb(algorithm, key, key_size, encrypted_data, encrypted_data_size, decrypted_data);
            break;
        case EDE:
            decrypt_ede(algorithm, key, key_size, encrypted_data, encrypted_data_size, decrypted_data);
            break;
        case EDE3:
            decrypt_ede3(algorithm, key, key_size, encrypted_data, encrypted_data_size, decrypted_data);
            break;
        case CFB:
            decrypt_cfb(algorithm, key, key_size, encrypted_data, encrypted_data_size, decrypted_data);
            break;
        default:
            return; // Unsupported cipher mode
    }
}
```

