```scss
// Java Service
import org.springframework.stereotype.Service;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.scheduling.annotation.Async;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutionException;

@Service
public class PokemonService {
  @Autowired
  private PokemonCache cache;
  @Autowired
  private ExternalAPIClient apiClient;

  public CompletableFuture<PokemonData> getPokemonData(String name) {
    return CompletableFuture.supplyAsync(() -> {
      try {
        // Use the cached data if available
        PokemonData data = cache.get(name);
        if (data != null) {
          return data;
        }

        // Fetch data from external API
        data = apiClient.fetchPokemonData(name);

        // Cache the data for future use
        cache.put(name, data);

        return data;
      } catch (ExternalAPIException e) {
        throw new RuntimeException("Failed to fetch Pokemon data", e);
      }
    });
  }
}
```

