    const char* encrypted_message;
    if (strcmp(request_type, "ENCRYPT") == 0) {
        encrypted_message = encrypt_message(provider, algorithm, mode, message);
    } else {
        encrypted_message = decrypt_message(provider, algorithm, mode, message);
    }

    // Check if the encrypted message is null or empty.
    if (encrypted_message == NULL || strlen(encrypted_message) == 0) {
        printf("Error encrypting/decrypting message!\n");
        return;
    }

    // Respond to the client with the encrypted/decrypted message.
    const char* response = create_response(transaction_id, request_type, encrypted_message);
    send(client_socket, response, strlen(response), 0);
}

void handle_connection(const int client_socket) {
    // Receive the request from the client and handle it.
    char buffer[1024];
    recv(client_socket, buffer, 1024, 0);
    handle_request(buffer, client_socket);
}

int main() {
    // Set up the load balancer and bind to the socket.
    struct sockaddr_in server_address;
    int socket = socket(AF_INET, SOCK_STREAM, 0);
    if (socket < 0) {
        printf("Error creating socket!\n");
        return -1;
    }
    memset(&server_address, 0, sizeof(server_address));
    server_address.sin_family = AF_INET;
    server_address.sin_addr.s_addr = htonl(INADDR_ANY);
    server_address.sin_port = htons(PORT);
    if (bind(socket, (struct sockaddr*)&server_address, sizeof(server_address)) < 0) {
        printf("Error binding socket!\n");
        return -1;
    }

    // Listen for incoming connections and handle them in separate threads.
    if (listen(socket, 3) < 0) {
        printf("Error listening on socket!\n");
        return -1;
    }
    while (true) {
        struct sockaddr_in client_address;
        int client_socket = accept(socket, (struct sockaddr*)&client_address, NULL);
        if (client_socket < 0) {
            printf("Error accepting connection!\n");
            return -1;
        }
        pthread_t thread;
        pthread_create(&thread, NULL, handle_connection, client_socket);
    }
    return 0;
}
