using namespace std;

namespace RandomGenerator {
    class MTGenerator {
    public:
        MTGenerator(unsigned long seed = 0) : mt_(), mti_(0) {
            // Initialize the Mersenne Twister with the given seed.
            if (seed == 0) {
                seed = randomSeed();
            }
            init_genrand(seed);
        }

        ~MTGenerator() {
            // Clean up any resources used by the RNG.
        }

        static MTGenerator& getInstance() {
            // Return a reference to the global instance of the RNG.
        }

        void seed(unsigned long seed) {
            // Seed the RNG with the given value.
            init_genrand(seed);
        }

        unsigned long randomUInt() {
            // Generate a uniformly distributed random integer in the range [0, 2^32-1].
            return genrand_int32();
        }

        double randomDouble() {
            // Generate a uniformly distributed random double in the range [0.0, 1.0).
            return static_cast<double>(genrand_real2()) / 4294967296.0;
        }

    private:
        mt19937 mt_; // The Mersenne Twister state machine.
        int mti_; // The index of the next random number to be generated.

        unsigned long randomSeed() {
            // Generate a seed value using system entropy.
            return static_cast<unsigned long>(time(0));
        }

        void init_genrand(unsigned long s) {
            // Initialize the Mersenne Twister state machine with the given seed.
            mt_.seed(s);
            mti_ = 1;
        }

        unsigned long genrand_int32() {
            // Generate a uniformly distributed random integer in the range [0, 2^32-1].
            return static_cast<unsigned long>(mt_() & 4294967295);
        }

        double genrand_real2() {
            // Generate a uniformly distributed random double in the range [0.0, 1.0).
            return static_cast<double>(genrand_int32()) / 4294967296.0;
        }
    };
}
```
