using System;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json;
using static System.Console;

public class GraphDataModule {
  private const string PreferencesServiceUrl = "https://preferences-service.example/api";
  private const string AuthenticationServiceUrl = "https://authentication-service.example/api";
  private const string NotificationServiceUrl = "https://notification-service.example/api";

  public async Task<GraphData> GetGraphDataAsync(string graphId) {
    // Retrieve graph data from cloud-based configuration service
    var graphDataRequest = new HttpRequestMessage(HttpMethod.Get, $"{PreferencesServiceUrl}/graphs/{graphId}");
    var graphDataResponse = await SendHttpRequestAsync(graphDataRequest);

    if (graphDataResponse.StatusCode == System.Net.HttpStatusCode.OK) {
      return JsonConvert.DeserializeObject<GraphData>(await graphDataResponse.Content.ReadAsStringAsync());
    } else {
      throw new Exception($"Error retrieving graph data: {graphDataResponse.StatusCode}");
    }
  }

  public async Task<UserPreferences> GetUserPreferencesAsync(string userId) {
    // Retrieve user preferences from preferences service
    var userPreferencesRequest = new HttpRequestMessage(HttpMethod.Get, $"{PreferencesServiceUrl}/users/{userId}");
    var userPreferencesResponse = await SendHttpRequestAsync(userPreferencesRequest);

    if (userPreferencesResponse.StatusCode == System.Net.HttpStatusCode.OK) {
      return JsonConvert.DeserializeObject<UserPreferences>(await userPreferencesResponse.Content.ReadAsStringAsync());
    } else {
      throw new Exception($"Error retrieving user preferences: {userPreferencesResponse.StatusCode}");
    }
  }

  public async Task<AuthenticationToken> GetAuthenticationTokenAsync() {
    // Retrieve authentication token from authentication service
    var authenticationTokenRequest = new HttpRequestMessage(HttpMethod.Post, $"{AuthenticationServiceUrl}/token");
    var authenticationTokenResponse = await SendHttpRequestAsync(authenticationTokenRequest);

    if (authenticationTokenResponse.StatusCode == System.Net.HttpStatusCode.OK) {
      return JsonConvert.DeserializeObject<AuthenticationToken>(await authenticationTokenResponse.Content.ReadAsStringAsync());
    } else {
      throw new Exception($"Error retrieving authentication token: {authenticationTokenResponse.StatusCode}");
    }
  }

  public async Task<Notification> GetNotificationAsync(string notificationId) {
    // Retrieve notification from notification service
    var notificationRequest = new HttpRequestMessage(HttpMethod.Get, $"{NotificationServiceUrl}/notifications/{notificationId}");
    var notificationResponse = await SendHttpRequestAsync(notificationRequest);

    if (notificationResponse.StatusCode == System.Net.HttpStatusCode.OK) {
      return JsonConvert.DeserializeObject<Notification>(await notificationResponse.Content.ReadAsStringAsync());
    } else {
      throw new Exception($"Error retrieving notification: {notificationResponse.StatusCode}");
    }
  }

  private async Task<HttpResponseMessage> SendHttpRequestAsync(HttpRequestMessage request) {
    var httpClient = new HttpClient();

    try {
      return await httpClient.SendAsync(request);
    } catch (Exception e) {
      WriteLine($"Error sending HTTP request: {e}");
      throw;
    } finally {
      httpClient.Dispose();
    }
  }
}
```
