    MessageQueue *queue = (MessageQueue *) malloc(sizeof(MessageQueue));
    pthread_mutex_init(&queue->mutex, NULL);
    pthread_cond_init(&queue->cond, NULL);
    queue->messages = (LogMessage *) malloc(sizeof(LogMessage) * MAX_NUM_MESSAGES);
    queue->num_messages = 0;
    queue->max_messages = MAX_NUM_MESSAGES;
    WorkerData workers[MAX_NUM_WORKERS];
    for (int i = 0; i < MAX_NUM_WORKERS; i++) {
        workers[i].worker_id = i;
        workers[i].socket = socket(AF_INET, SOCK_STREAM, 0);
        workers[i].buffer = (char *) malloc(SOCKET_BUFFER_SIZE);
        workers[i].buffer_size = SOCKET_BUFFER_SIZE;
        workers[i].queue = queue;
        pthread_mutex_init(&workers[i].mutex, NULL);
        pthread_cond_init(&workers[i].cond, NULL);
    }
    // Start worker threads
    for (int i = 0; i < MAX_NUM_WORKERS; i++) {
        if (pthread_create(&(workers[i].tid), NULL, worker_function, &workers[i])) {
            logging(1, "Error creating worker thread");
        }
    }
    // Initialize socket data and message processing functions
    SocketData *socket_data = (SocketData *) malloc(sizeof(SocketData));
    socket_data->socket = socket(AF_INET, SOCK_STREAM, 0);
    socket_data->buffer = (char *) malloc(SOCKET_BUFFER_SIZE);
    socket_data->buffer_size = SOCKET_BUFFER_SIZE;
    // Start receiving and processing messages
    while (1) {
        receive_socket_data(socket_data);
        process_message(socket_data->buffer, socket_data->size);
        add_to_queue(queue, socket_data->buffer);
        pthread_cond_wait(&queue->cond, &queue->mutex);
    }
    return 0;
}
```

