const filterTransactions = async ({ age, transactions, weightedSum }) => {
  const metrics = {};
  // Calculate maximum weighted sum and corresponding transaction ID
  const maxWeightedSum = Math.max(...transactions.map((transaction) => transaction.weightedSum));
  const transactionID = transactions.find((transaction) => transaction.weightedSum === maxWeightedSum).id;
