    res.status(200).json({ message: 'Fields updated successfully' });
  } catch (error) {
    console.log(`Error updating fields for ${resourceId}:`, error);
    res.status(500).json({ message: 'Server error while updating fields' });
  }
});

app.post('/refresh', async (req, res) => {
  // Handle POST requests to /refresh
  const { resourceId, url, body } = req.body;
  try {
    // Make API call and retrieve data
    const response = await axios.post(url, body);
    const data = response.data;
    // Update field values in dialog based on resource ID and URL
    updateFields(resourceId, data);
    res.status(201).json({ message: 'Fields updated successfully' });
  } catch (error) {
    console.log(`Error updating fields for ${resourceId}:`, error);
    res.status(500).json({ message: 'Server error while updating fields' });
  }
});

// Update field values in dialog based on resource ID and URL
function updateFields(resourceId, data) {
  // Retrieve field values from dialog for the given resource ID
  const fieldValues = getFieldValues(resourceId);
  // Update field values with new data from API response
  for (const key in data) {
    if (fieldValues[key]) {
      fieldValues[key] = data[key];
    } else {
      console.log(`Could not find field ${key} for resource ID ${resourceId}`);
    }
  }
  // Update field values in dialog with updated values
  setFieldValues(resourceId, fieldValues);
}

// Retrieve field values from dialog for the given resource ID
function getFieldValues(resourceId) {
  const fields = document.querySelectorAll(`[data-resource-id="${resourceId}"]`);
  const fieldValues = {};
  fields.forEach((field) => {
    fieldValues[field.name] = field.value;
  });
  return fieldValues;
}

// Update field values in dialog with new values
function setFieldValues(resourceId, fieldValues) {
  const fields = document.querySelectorAll(`[data-resource-id="${resourceId}"]`);
  for (const key in fieldValues) {
    const field = fields.find((field) => field.name === key);
    if (field) {
      field.value = fieldValues[key];
    } else {
      console.log(`Could not find field ${key} for resource ID ${resourceId}`);
    }
  }
}
