#include <ctime>
#include <unistd.h>
#include <openssl/aes.h>
#include <openssl/rand.h>
#include <openssl/sha.h>
#include "secure_dynamic_octree.hpp"

using namespace std;

const int MAX_THREADS = 16; // maximum number of threads for concurrent updates and queries
const int MAX_NODE_SIZE = 256; // maximum size of a node in the octree (in bytes)
const int MIN_NODE_CAPACITY = 100; // minimum capacity of a node in the octree (in number of entries)
const int MAX_NODE_CAPACITY = 1000; // maximum capacity of a node in the octree (in number of entries)
const int MEMORY_QUOTA = 5 * 1024 * 1024; // maximum amount of memory allowed for the octree (in bytes)
const int MAX_IV_LENGTH = 16; // maximum length of an Initialization Vector (IV) used for AES-256-CBC encryption
const int KEY_SIZE = 32; // size of a cryptographic key used for AES-256-CBC encryption
const int IV_SIZE = 16; // size of an Initialization Vector (IV) used for AES-256-CBC encryption

SecureDynamicOctree::SecureDynamicOctree(int capacity, int memoryQuota) {
    this->capacity = capacity;
    this->memoryQuota = memoryQuota;
    this->nodeCapacity = MAX_NODE_CAPACITY;
}

void SecureDynamicOctree::init() {
    // initialize the octree with a single root node
    Node* rootNode = new Node(nullptr, 0, 0);
    this->rootNode = rootNode;

    // initialize the node pool
    this->nodePool.resize(this->capacity * this->nodeCapacity);

    // initialize the threadpool for concurrent updates and queries
    this->threadPool.init();
}

void SecureDynamicOctree::insert(int key, int value) {
    Node* leafNode = findLeafNode(key);

    if (leafNode == nullptr) {
        // insert a new leaf node if the key is not present in the octree
        leafNode = createNewNode(key, value);
    } else {
        // update an existing leaf node with the given value
        leafNode->value = value;
    }
}

void SecureDynamicOctree::update(int key, int value) {
    Node* leafNode = findLeafNode(key);

    if (leafNode != nullptr) {
        // update an existing leaf node with the given value
        leafNode->value = value;
    } else {
        // insert a new leaf node with the given key and value
        createNewNode(key, value);
    }
}

void SecureDynamicOctree::remove(int key) {
    Node* leafNode = findLeafNode(key);

    if (leafNode != nullptr) {
        // remove the existing leaf node with the given key
        deleteLeafNode(leafNode);
    }
}

int SecureDynamicOctree::query(int key) {
    Node* leafNode = findLeafNode(key);

    if (leafNode != nullptr) {
        // return the value of an existing leaf node with the given key
        return leafNode->value;
    } else {
        // return -1 if the key is not present in the octree
        return -1;
    }
}

bool SecureDynamicOctree::isEmpty() {
    return this->rootNode == nullptr;
}

int SecureDynamicOctree::size() {
    int size = 0;

    // traverse all leaf nodes in the octree and count their number
    Node* node = this->rootNode;
    while (node != nullptr) {
        if (node->leftChild == nullptr && node->rightChild == nullptr) {
            size++;
        }
        node = node->parent;
    }

    return size;
}

void SecureDynamicOctree::clear() {
    // reset the octree to an empty state
    this->rootNode = nullptr;
    this->nodePool.clear();
}

SecureDynamicOctree::~SecureDynamicOctree() {
    // delete all nodes in the octree recursively
    deleteNode(this->rootNode);
    this->rootNode = nullptr;
}

void SecureDynamicOctree::createNewNode(int key, int value) {
    Node* newNode = createNode(key, value);

    // insert the new node into the octree
    if (this->rootNode == nullptr) {
        this->rootNode = newNode;
    } else {
        insertNode(newNode);
    }
}

void SecureDynamicOctree::insertNode(Node* node) {
    // split the root node into two child nodes if it is too large to fit in memory
    int size = node->leftChild == nullptr && node->rightChild == nullptr ? 1 : 2;
    int capacity = this->nodeCapacity * (int)ceil((double)size / this->nodeCapacity);

    if (this->rootNode != nullptr && getMemoryUsage() + sizeof(Node) * capacity > this->memoryQuota) {
        // split the root node into two child nodes recursively
        splitNode(this->rootNode, capacity);
    }

    // insert the new node into the octree
    if (node->key < this->rootNode->key) {
        // insert the new node as a left child of the current root node
        Node* child = this->rootNode;
        this->rootNode = createNode(this->rootNode->key, this->rootNode->value);
        this->rootNode->leftChild = child;
        this->rootNode->rightChild = node;
    } else {
        // insert the new node as a right child of the current root node
        Node* child = this->rootNode;
        this->rootNode = createNode(this->rootNode->key, this->rootNode->value);
        this->rootNode->rightChild = child;
        this->rootNode->leftChild = node;
    }
}

void SecureDynamicOctree::deleteLeafNode(Node* leafNode) {
    // remove the leaf node from the octree
    if (leafNode == this->rootNode) {
        // reset the root node to nullptr
        this->rootNode = nullptr;
    } else {
        Node* parent = leafNode->parent;

        if (parent->leftChild == leafNode) {
            // delete the left child of the parent node
            parent->leftChild = nullptr;
        } else {
            // delete the right child of the parent node
            parent->rightChild = nullptr;
        }

        // recursively delete the leaf node and its children if they are empty
        deleteNode(leafNode);
    }
}

void SecureDynamicOctree::splitNode(Node* node, int capacity) {
    Node* parent = node->parent;
    int size = node->leftChild == nullptr && node->rightChild == nullptr ? 1 : 2;

    if (size <= capacity) {
        // split the current node into two child nodes recursively
        for (int i = 0; i < size / 2; i++) {
            Node* newNode = createNode(node->key + 2 * i, node->value);

            if (i == 0) {
                // insert the first child as a left child of the current node
                node->leftChild = newNode;
            } else {
                // insert the second child as a right child of the current node
                node->rightChild = newNode;
            }
        }
    } else {
        // split the parent node into two child nodes recursively
        for (int i = 0; i < size / 2; i++) {
            Node* newNode = createNode(parent->key + 2 * i, parent->value);

            if (i == 0) {
                // insert the first child as a left child of the current node
                parent->leftChild = newNode;
            } else {
                // insert the second child as a right child of the current node
                parent->rightChild = newNode;
            }
        }
    }
}

SecureDynamicOctree::Node* SecureDynamicOctree::findLeafNode(int key) {
    Node* node = this->rootNode;

    while (node != nullptr) {
        if (key < node->key) {
            // move to the left child of the current node
            node = node->leftChild;
        } else if (key > node->key) {
            // move to the right child of the current node
            node = node->rightChild;
        } else {
            // return the current leaf node if the key is found
            break;
        }
    }

    return node;
}

void SecureDynamicOctree::createNode(int key, int value) {
    // create a new node in the node pool
    Node* node = &this->nodePool[this->nodeIndex];
    this->nodeIndex++;

    // initialize the fields of the new node
    node->key = key;
    node->value = value;
    node->leftChild = nullptr;
    node->rightChild = nullptr;
}

void SecureDynamicOctree::deleteNode(Node* node) {
    // recursively delete the left and right children of the current node
    if (node->leftChild != nullptr) {
        deleteNode(node->leftChild);
    }

    if (node->rightChild != nullptr) {
        deleteNode(node->rightChild);
    }
}

void SecureDynamicOctree::splitNode(Node* node, int capacity) {
    // recursively split the left and right children of the current node
    for (int i = 0; i < size / 2; i++) {
        Node* newNode = createNode(parent->key + 2 * i, parent->value);

        if (i == 0) {
            // insert the first child as a left child of the current node
            parent->leftChild = newNode;
        } else {
            // insert the second child as a right child of the current node
            parent->rightChild = newNode;
        }
    }
}

size_t SecureDynamicOctree::getMemoryUsage() {
    return sizeof(Node) * this->nodeIndex;
}']

