import java.util.concurrent.*;
import java.util.logging.*;
import com.google.common.cache.*;

public class TransactionProcessor {
  private final Logger logger = Logger.getLogger(TransactionProcessor.class.getName());
  private final Cache<String, Double> cache = CacheBuilder.newBuilder()
      .maximumSize(1000)
      .expireAfterAccess(60, TimeUnit.SECONDS)
      .build();
  private final Queue<Transaction> transactionQueue = new ConcurrentLinkedQueue<>();

  public void processTransaction(Transaction transaction) {
    if (isValidTransaction(transaction)) {
      logger.info("Processing transaction: " + transaction);
      cache.put(transaction.getAccountId(), transaction.getValue());
      transactionQueue.add(transaction);
    } else {
      logger.warning("Invalid transaction: " + transaction);
    }
  }

  private boolean isValidTransaction(Transaction transaction) {
    // Check if the transaction meets filtering criteria, including age, frequency within the last 5 seconds, a weighted sum threshold, and account priority levels.
    long currentTime = System.currentTimeMillis();
    long lastTransactionTime = cache.getIfPresent(transaction.getAccountId());
    if (lastTransactionTime != null && currentTime - lastTransactionTime <= 5000) {
      return false;
    }
    if (transaction.getValue() < 100) {
      return false;
    }
    // Check account priority levels and apply threshold based on priorities.
    if (transaction.getPriority().equals("HIGH")) {
      return transaction.getValue() >= 1000;
    } else if (transaction.getPriority().equals("MEDIUM")) {
      return transaction.getValue() >= 500;
    } else {
      return true;
    }
  }
}
