    CombatSystem(vector<IAttackPattern*> attack_patterns, unordered_map<string, IAttackPattern*> attack_factories) : attack_patterns_(attack_patterns), attack_factories_(attack_factories) {
        last_attack_time_ = chrono::duration_cast<chrono::seconds>(chrono::system_clock::now().time_since_epoch()).count();
        cooldown_period_ = 1; // default cooldown period in seconds
    }

    ~CombatSystem() {
        for (auto& it : attack_patterns_) {
            delete it;
        }
        for (auto& it : attack_factories_) {
            delete it.second;
        }
    }

    void selectAttack() {
        // prevent consecutive repetition of the same pattern by checking cooldown period
        if (chrono::duration_cast<chrono::seconds>(chrono::system_clock::now().time_since_epoch()).count() - last_attack_time_ < cooldown_period_) {
            return;
        }

        // select attack pattern based on probabilities
