        // update last attack time and cooldown period based on selected pattern
        IAttackPattern* attack = attack_patterns_[index];
        last_attack_time_ = chrono::duration_cast<chrono::seconds>(chrono::system_clock::now().time_since_epoch()).count();
        cooldown_period_ = attack->getCooldownPeriod();

        // perform attack using selected pattern
