```c++
#include <iostream>
#include <string>
#include <chrono>
#include <thread>
#include <vector>
#include <unordered_map>
#include <memory>

// External attack database REST API endpoint
const std::string ATTACK_DB_ENDPOINT = "https://example.com/attack-db";

// Attack mode enum class
enum class AttackMode {
    SINGLE_TARGET, // Single-target attacks
    AREA_EFFECT,  // Area-of-effect attacks
    DASH          // Dash attack
};

// Cooldown timer class
class CooldownTimer {
public:
    CooldownTimer(std::chrono::seconds cooldown) : cooldown_(cooldown) {}

    bool isCooldownActive() const {
        return std::chrono::steady_clock::now() - lastAttackTime_ < cooldown_;
    }

    void reset() {
        lastAttackTime_ = std::chrono::steady_clock::now();
    }

private:
    // Cooldown period
    const std::chrono::seconds cooldown_;

    // Last attack time
    std::chrono::time_point<std::chrono::steady_clock> lastAttackTime_;
};

// GameCharacter class
class GameCharacter {
public:
    GameCharacter(std::string name, int level) : name_(name), level_(level) {}

    void initialize() {
        // Initialize cooldown timer and attack mode
        cooldownTimer_ = std::make_unique<CooldownTimer>(std::chrono::seconds(3));
        attackMode_ = AttackMode::SINGLE_TARGET;

        // Initialize attack database
        attackDatabase_ = std::make_shared<AttackDatabase>();

        // Fetch initial attack list from attack database
        fetchAttackList();
    }

    void selectAttack() {
        // Check if cooldown period has expired
        if (cooldownTimer_->isCooldownActive()) {
            std::cout << "Cooldown active" << std::endl;
            return;
        }

        // Query attack database for random attack ID based on current game state and character settings
        const int attackId = selectRandomAttack(attackDatabase_->getAttacks());

        // Log attack details for debugging purposes
        logAttackDetails(attackId, attackDatabase_->getAttack(attackId));

        // Update cooldown timer and last attack time
        cooldownTimer_->reset();
        lastAttackTime_ = std::chrono::steady_clock::now();
    }

    void switchAttackMode() {
        // Switch to next available attack mode in the order of single-target, area-of-effect, dash
        if (attackMode_ == AttackMode::SINGLE_TARGET) {
            attackMode_ = AttackMode::AREA_EFFECT;
        } else if (attackMode_ == AttackMode::AREA_EFFECT) {
            attackMode_ = AttackMode::DASH;
        } else {
            attackMode_ = AttackMode::SINGLE_TARGET;
        }
    }

    void resetCooldown() {
        // Reset cooldown timer if a special event occurs, such as completing a level or encountering a boss
        cooldownTimer_->reset();
    }

private:
    // Character name and level
    std::string name_;
    int level_;

    // Cooldown timer and last attack time
    std::unique_ptr<CooldownTimer> cooldownTimer_;
    std::chrono::time_point<std::chrono::steady_clock> lastAttackTime_;

    // Attack mode enum class
    AttackMode attackMode_;

    // External attack database shared pointer
    std::shared_ptr<AttackDatabase> attackDatabase_;
};
```
To implement the `GameCharacter` class, we need to define the necessary data structures and methods for managing attacks, cooldowns, and switching attack modes. The initialization method should initialize the character's name and level, create a unique pointer for the cooldown timer, and fetch the initial attack list from the external attack database.

The `selectAttack()` method should check if the cooldown period has expired, query the attack database for a random attack ID based on current game state and character settings, log the attack details for debugging purposes, update the cooldown timer and last attack time, and return the selected attack ID.

The `switchAttackMode()` method should switch to the next available attack mode in the order of single-target, area-of-effect, dash.

The `resetCooldown()` method should reset the cooldown timer if a special event occurs, such as completing a level or encountering a boss.

To integrate with external systems like user authentication, inventory management, and game state tracking, we can use a REST API endpoint for fetching attack data and other relevant information from the attack database. We can also use shared pointers to manage memory and avoid memory leaks.']

