    // Constructor
    ConnectionPool(const std::vector<std::string>& db_urls, const std::unordered_map<std::string, int>& db_slas)
        : db_urls_(db_urls), db_slas_(db_slas), conn_pool_(db_urls.size()) { }

    // Destructor
    ~ConnectionPool() {
        for (auto& conn : conn_pool_) {
            if (conn) {
                conn->close();
            }
        }
    }

    // Get a connection from the pool
    std::shared_ptr<Connection> getConnection(const std::string& db_url, const int& sla) {
        std::lock_guard<std::mutex> lock(conn_pool_mutex_);
        auto it = conn_pool_.find(db_url);
        if (it == conn_pool_.end()) {
            throw std::runtime_error("Invalid database URL");
        }
        auto& pool = it->second;
        if (!pool.empty()) {
            // Use an existing connection from the pool
            auto conn = pool.front();
            pool.pop_front();
            return conn;
        } else {
            // Create a new connection if the pool is empty
            auto conn = std::make_shared<Connection>(db_url);
            return conn;
        }
    }

    // Release a connection back to the pool
    void releaseConnection(const std::string& db_url, const std::shared_ptr<Connection>& conn) {
        std::lock_guard<std::mutex> lock(conn_pool_mutex_);
        auto it = conn_pool_.find(db_url);
        if (it == conn_pool_.end()) {
            throw std::runtime_error("Invalid database URL");
        }
        it->second.push_back(conn);
    }

