        ~Connection() {
            if (conn_) {
                conn_->close();
            }
        }

        // Connect to the database
        void connect(const std::string& db_url) {
            conn_ = std::make_shared<DBConnection>(db_url);
        }

        // Close the connection
        void close() {
            if (conn_) {
                conn_.reset();
            }
        }

        // Check the health of the connection
        bool isHealthy() {
            return !conn_ || conn_->isHealthy();
