int tiffDecode(const char *filename, tiffMetadata_t *metadata) {
    // Read the TIFF header and retrieve the image dimensions
    size_t imageSize = readTiffHeader(filename, &metadata->bitsPerSample, &metadata->samplesPerPixel);
    if (imageSize == 0) {
        return -1;
    }

