    }

    // Allocate a buffer to store the decompressed image data
    uint8_t *imageData = malloc(imageSize);
    if (imageData == NULL) {
        return -4;
    }

    // Decompress the image data using the chosen algorithm
    size_t decompressedSize = decompressImageData(imageData, imageSize, decompressionInfo->buffer, decompressionInfo->bufferSize);
    if (decompressedSize == 0) {
        return -5;
    }

    // Free the buffer used for decompression
    free(decompressionInfo->buffer);
    decompressionInfo->buffer = NULL;

    // Update the metadata structure with the decompressed image data and size
    metadata->buffer = imageData;
    metadata->bufferSize = decompressedSize;

    return 0;
}

// Function to process a TIFF image using a given compression method
uint8_t *tiffProcess(const uint8_t *imageData, size_t dataSize, uint16_t compressionType) {
    // Check if the compression method is supported
    if (!isCompressionMethodSupported(compressionType)) {
        return NULL;
    }

    // Retrieve the decompression algorithm and buffer size for the given compression type
    decompressionInfo_t *decompressionInfo = getDecompressionAlgorithmInfo(compressionType);
    if (decompressionInfo == NULL) {
        return NULL;
    }

    // Decompress the image data using the chosen algorithm
    size_t decompressedSize = decompressImageData(imageData, dataSize, decompressionInfo->buffer, decompressionInfo->bufferSize);
    if (decompressedSize == 0) {
        return NULL;
    }

    // Free the buffer used for decompression
    free(decompressionInfo->buffer);
    decompressionInfo->buffer = NULL;

    // Allocate a new buffer to store the processed image data
    uint8_t *processedImageData = malloc(decompressedSize);
    if (processedImageData == NULL) {
        return NULL;
    }

    // Process the decompressed image data
    size_t processedSize = processImageData(processedImageData, decompressedSize);
    if (processedSize == 0) {
        free(processedImageData);
        return NULL;
    }

    return processedImageData;
}

// Function to read the TIFF header and retrieve the image dimensions
size_t readTiffHeader(const char *filename, uint8_t *bitsPerSample, uint8_t *samplesPerPixel) {
    // Open the file stream for reading
    FILE *fileStream = fopen(filename, "rb");
    if (fileStream == NULL) {
        return 0;
    }

    // Read the TIFF header from the file stream
    uint16_t magicNumber;
    fread(&magicNumber, sizeof(uint16_t), 1, fileStream);
    if (magicNumber != 42) {
        fclose(fileStream);
        return 0;
    }

    // Read the image dimensions from the file stream
    uint32_t width, height;
    fread(&width, sizeof(uint32_t), 1, fileStream);
    fread(&height, sizeof(uint32_t), 1, fileStream);

    // Close the file stream
    fclose(fileStream);

    // Calculate the image size and allocate a buffer for the decompressed data
    size_t imageSize = width * height;
    uint8_t *buffer = malloc(imageSize);
    if (buffer == NULL) {
        return 0;
    }

    // Return the image dimensions and buffer to the caller
    *bitsPerSample = 8;
    *samplesPerPixel = 3;
    return imageSize;
}

// Function to decompress a TIFF image using the chosen compression algorithm
size_t decompressImageData(uint8_t *imageData, size_t dataSize, uint8_t *buffer, size_t bufferSize) {
    // Check if the buffer is large enough for the decompressed data
    if (dataSize > bufferSize) {
        return 0;
    }

    // Decompress the image data using the chosen algorithm
    int result = decompressImageData(imageData, dataSize, buffer, bufferSize);
    if (result != 0) {
        return 0;
    }

    return dataSize;
}

// Function to process a TIFF image and generate compressed output
size_t processImageData(uint8_t *imageData, size_t dataSize) {
    // Check if the buffer is large enough for the processed data
    if (dataSize < MIN_COMPRESSION_SPEED || dataSize > MAX_COMPRESSION_SPEED) {
        return 0;
    }

    // Process the image data using a compression algorithm
    int result = compressImageData(imageData, dataSize);
    if (result != 0) {
        return 0;
    }

    return dataSize;
}

// Function to check if a compression method is supported by the library
bool isCompressionMethodSupported(uint16_t compressionType) {
