    std::string get_encoding(const std::string& content_type) {
        // Get the appropriate encoding for the given Content-Type header
        return "identity";
    }

    // Helper function to handle caching of responses
    void cache_response(const CacheEntry& entry) {
        // Insert the response into the cache if it is valid and within the maximum cache size limit
        if (USE_EXTERNAL_CACHING) {
            m_cache.insert(entry);
        } else {
            m_internal_cache.emplace(request.url, entry);
        }
    }

    // Helper function to retrieve a response from the cache
    CacheEntry get_cached_response(const std::string& url) {
        // Get the cached response if available and not expired
        if (USE_EXTERNAL_CACHING) {
            return m_cache.get(url);
        } else {
            auto it = m_internal_cache.find(url);
            if (it != m_internal_cache.end() && it->second.expiry > std::chrono::system_clock::now()) {
                return it->second;
            }
        }
        return CacheEntry();
    }

private:
    HttpClient m_http_client; // HTTP client instance
    CachingServiceClient m_cache; // Caching service client instance
    std::unordered_map<std::string, CacheEntry> m_internal_cache; // Internal cache for storing responses
    std::mutex m_mutex; // Mutex for synchronizing access to the internal cache
    std::condition_variable m_cv; // Condition variable for signaling when a new entry is available in the cache
};
