            System.out.println("Warning: Failed to delete file " + file.getName() + ": " + e.getMessage());
        }
    }

    public static void executeCommand(String command) {
        // Execute external scripts or commands with customizable command-line arguments, validating inputs to prevent injection attacks
        if (command == null || command.trim().isEmpty()) {
            throw new IllegalArgumentException("Invalid command");
        }

        try {
            Process process = Runtime.getRuntime().exec(command);
            // Handle exceptions gracefully, logging stack traces for critical failures but providing clear error messages for end-users
            if (process == null) {
                throw new IllegalStateException("Failed to execute command: " + command);
            }
        } catch (Exception e) {
            System.out.println("Error executing command: " + command + "\n" + e.getMessage());
        }
    }

    public static boolean deleteFile(String filePath) throws TimeoutException {
        // Implement a method to check if a specified file exists and safely delete it if necessary, handling cases where the file is in use or missing
        File file = new File(filePath);
        try {
            if (file.exists()) {
                boolean deleted = file.delete();
                if (!deleted) {
                    throw new TimeoutException("Failed to delete file " + file.getName() + ": timed out");
                }
            }
        } catch (Exception e) {
            // Log detailed messages for each operation, including warnings for non-critical issues like missing files
            System.out.println("Warning: Failed to delete file " + file.getName() + ": " + e.getMessage());
        }
    }

    public static void performFileOperation(String filePath) throws TimeoutException {
        // Implement a method to perform file operations, such as checking if the file exists and safely deleting it if necessary, handling cases where the file is in use or missing
        deleteFile(filePath);
    }

    public static void executeCommandWithTimeout(String command) throws TimeoutException {
        // Implement a method to execute commands with a timeout, validating inputs to prevent injection attacks
        if (command == null || command.trim().isEmpty()) {
            throw new IllegalArgumentException("Invalid command");
        }

        try {
            Process process = Runtime.getRuntime().exec(command);
            // Handle exceptions gracefully, logging stack traces for critical failures but providing clear error messages for end-users
            if (process == null) {
                throw new IllegalStateException("Failed to execute command: " + command);
            }

            int exitCode = process.waitFor(TIMEOUT_SECONDS, TimeUnit.SECONDS);
            if (exitCode != 0) {
                throw new TimeoutException("Command execution timed out");
            }
        } catch (Exception e) {
            System.out.println("Error executing command: " + command + "\n" + e.getMessage());
        }
    }

    public static void performOperation(String filePath, String command) throws TimeoutException {
        // Implement a method to perform operations that require file checks and/or command execution, handling cases where the file is in use or missing
        deleteFile(filePath);
        executeCommandWithTimeout(command);
    }

    public static void handleError(Throwable t) {
        // Develop a robust error handling framework that can adapt to unexpected conditions, ensuring minimal downtime and quick recovery
        if (t instanceof TimeoutException) {
            System.out.println("Timeout occurred");
        } else if (t instanceof Exception) {
            System.out.println("Error occurred: " + t.getMessage());
        }
    }
