using StreamIngestor;

namespace StreamIngestor
{
    public class StreamIngestor : IStreamIngestor
    {
        private readonly List<IMessageBroker> messageBrokers = new List<IMessageBroker>();

        public void AddMessageBroker(IMessageBroker messageBroker)
        {
            this.messageBrokers.Add(messageBroker);
        }

        public async Task IngestStreamAsync(string streamName, Stream stream, CancellationToken cancellationToken = default)
        {
            var tasks = new List<Task>();

            foreach (var messageBroker in this.messageBrokers)
            {
                tasks.Add(messageBroker.PublishMessageAsync(streamName, stream, cancellationToken));
            }

            await Task.WhenAll(tasks);
        }
    }
}
```

