    std::string input;
    std::vector<std::string> output;

    // Loop until the user inputs a string that is within the size limit
    while (true) {
        // Prompt the user to enter a string
        std::cout << "Enter a string: ";
        std::getline(std::cin, input);

        // Check if the input exceeds the size limit
        if (checkSizeLimit(input, 10)) {
            // If it does, print an error message and continue looping
            std::cout << "Error: Input string exceeds the size limit." << std::endl;
            continue;
        } else {
            // If not, add the input to the output vector
            output.push_back(input);
            break;
        }
    }

    // Print the contents of the output vector
