import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

public class PduPoolManager {
    private final ConcurrentHashMap<Long, NFAPI_CRC_INDICATION_PDU_T> pduMap;
    private final AtomicInteger pduCount;
    private final int maxPduCount;

    public PduPoolManager(int maxPduCount) {
        this.pduMap = new ConcurrentHashMap<>();
        this.pduCount = new AtomicInteger();
        this.maxPduCount = maxPduCount;
    }

    private boolean isValidRX_UE_INFORMATION_TAG(int tag) {
        return (tag >= 0 && tag < RX_UE_INFORMATION_TAG.values().length);
    }

    private boolean isValidRNTI(long rnti) {
        return (rnti >= 0 && rnti <= 65535L);
    }

    public void addPdu(NFAPI_CRC_INDICATION_PDU_T pdu, int rxUeInfoTag, long rnti) {
        if (!isValidRX_UE_INFORMATION_TAG(rxUeInfoTag)) {
            throw new IllegalArgumentException("Invalid RX_UE_INFORMATION_TAG: " + rxUeInfoTag);
        }
        if (!isValidRNTI(rnti)) {
            throw new IllegalArgumentException("Invalid RNTI: " + rnti);
        }
        pduMap.putIfAbsent(pdu.getPduId(), pdu);
        pduCount.incrementAndGet();
    }

    public NFAPI_CRC_INDICATION_PDU_T getPdu(int rxUeInfoTag, long rnti) {
        if (!isValidRX_UE_INFORMATION_TAG(rxUeInfoTag)) {
            throw new IllegalArgumentException("Invalid RX_UE_INFORMATION_TAG: " + rxUeInfoTag);
        }
        if (!isValidRNTI(rnti)) {
            throw new IllegalArgumentException("Invalid RNTI: " + rnti);
        }
        return pduMap.getOrDefault(rxUeInfoTag, rnti, null);
    }

    public void removePdu(NFAPI_CRC_INDICATION_PDU_T pdu) {
        if (pdu == null) {
            throw new IllegalArgumentException("Invalid PDU: " + pdu);
        }
        pduMap.remove(pdu.getPduId());
        pduCount.decrementAndGet();
    }

    public int getNumPdus() {
        return pduCount.get();
    }

    public void clearPdus() {
        pduMap.clear();
        pduCount.set(0);
    }

    public boolean isEmpty() {
        return pduMap.isEmpty();
    }
}
