import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.Consumer;
import java.util.logging.Logger;

public class PduPoolManager {
  private static final Logger LOG = Logger.getLogger(PduPoolManager.class.getName());

  // Configurable parameters
  private int minSize = 10;
  private int maxSize = 100;
  private long expirationTimeMillis = 5 * 60 * 1000; // 5 minutes
  private Consumer<NFAPI_CRC_INDICATION_PDU_T> onExpireCallback;

  // Internal state
  private AtomicInteger size = new AtomicInteger(minSize);
  private ConcurrentHashMap<Long, NFAPI_CRC_INDICATION_PDU_T> pool = new ConcurrentHashMap<>();
  private AtomicReference<NFAPI_CRC_INDICATION_PDU_T> head = new AtomicReference<>();

  public PduPoolManager() {
    // Initialize the pool with the configured min/max sizes
    for (int i = 0; i < minSize; i++) {
      NFAPI_CRC_INDICATION_PDU_T pdu = new NFAPI_CRC_INDICATION_PDU_T();
      add(pdu);
    }

    // Start the expiration timer
    startExpirationTimer();
  }

  public void setOnExpireCallback(Consumer<NFAPI_CRC_INDICATION_PDU_T> callback) {
    this.onExpireCallback = callback;
  }

  // Add a PDU to the pool
  public boolean add(NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (pool.size() >= maxSize) {
      return false;
    }

    long timestamp = System.currentTimeMillis();
    pdu.timestamp = timestamp;
    pool.put(timestamp, pdu);

    // Update the head pointer to the newest PDU
    if (head == null || head.get().timestamp < timestamp) {
      head.set(pdu);
    }

    return true;
  }

  // Remove an expired PDU from the pool
  public void removeExpired() {
    long currentTime = System.currentTimeMillis();
    while (head != null && head.get().timestamp + expirationTimeMillis < currentTime) {
      NFAPI_CRC_INDICATION_PDU_T pdu = head.getAndSet(null);
      pool.remove(pdu.timestamp);

      if (onExpireCallback != null) {
        onExpireCallback.accept(pdu);
      }
    }
  }

  // Get the next PDU from the pool, or allocate a new one if necessary
  public NFAPI_CRC_INDICATION_PDU_T get() {
    removeExpired();

    NFAPI_CRC_INDICATION_PDU_T pdu = head.getAndSet(null);
    if (pdu == null) {
      // Allocate a new PDU if the pool is empty
      pdu = new NFAPI_CRC_INDICATION_PDU_T();

      // Add the PDU to the pool for later use
      add(pdu);
    }

    return pdu;
  }

  // Release a PDU back to the pool
  public void release(NFAPI_CRC_INDICATION_PDU_T pdu) {
    long timestamp = System.currentTimeMillis();
    pdu.timestamp = timestamp;

    head.set(pdu);
  }

  // Start the expiration timer to periodically check for expired PDUS
  private void startExpirationTimer() {
    new Thread(() -> {
      while (true) {
        try {
          removeExpired();
          Thread.sleep(expirationTimeMillis);
        } catch (InterruptedException e) {
          LOG.info("Expiration timer interrupted");
        }
      }
    }).start();
  }
}
```
