import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

public class PduPoolManagerTest {
  private PduPoolManager manager;

  @BeforeEach
  public void setUp() {
    this.manager = new PduPoolManager();
  }

  @Test
  public void testAddAndGet() {
    NFAPI_CRC_INDICATION_PDU_T pdu = new NFAPI_CRC_INDICATION_PDU_T();
    manager.add(pdu);

    Assertions.assertEquals(1, manager.size());

    NFAPI_CRC_INDICATION_PDU_T retrievedPdu = manager.get();
    Assertions.assertSame(retrievedPdu, pdu);
  }

  @Test
  public void testExpiration() {
    manager.add(new NFAPI_CRC_INDICATION_PDU_T());

    Assertions.assertEquals(1, manager.size());

    long currentTime = System.currentTimeMillis();
    while (manager.head == null || manager.head.get().timestamp + 500 < currentTime) {
      // Wait for the PDU to expire
      Thread.sleep(10);
    }

    Assertions.assertEquals(0, manager.size());
  }

  @Test
  public void testRelease() {
    NFAPI_CRC_INDICATION_PDU_T pdu = new NFAPI_CRC_INDICATION_PDU_T();
    manager.add(pdu);

    Assertions.assertEquals(1, manager.size());

    manager.release(pdu);

    Assertions.assertEquals(1, manager.size());
  }
}
