import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class ResourceService {
    private static final int CONFLICT_RETRIES = 3;
    private static final int CONFLICT_BACKOFF_MS = 1000; // 1 second
    private static final int LOCK_TIMEOUT_MS = 5000; // 5 seconds

    public void updateResource(String resourceName, String resourceDescription) {
        Lock lock = new ReentrantLock();
        while (true) {
            try {
                if (!lock.tryLock(LOCK_TIMEOUT_MS, TimeUnit.MILLISECONDS)) {
                    throw new ResourceUpdateException("Failed to acquire lock after " + LOCK_TIMEOUT_MS + " milliseconds.");
                }
                makeRequestToExternalAPI(resourceName);
                break;
            } catch (IOException e) {
                if (retryCount < CONFLICT_RETRIES) {
                    retryCount++;
                    continue;
                } else {
                    throw new ResourceUpdateException("Failed to update resource after " + CONFLICT_RETRIES + " retries.");
                }
            } finally {
                lock.unlock();
            }
        }
    }

    private void makeRequestToExternalAPI(String resourceName) throws IOException {
        // implement request to external API
    }
}
