```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Xml;
using System.Xml.Linq;
using System.Threading;

namespace ConfigManager
{
    public class XmlConfigManager
    {
        private static readonly Dictionary<string, string> _settings = new Dictionary<string, string>();

        public static void LoadConfig(string filePath)
        {
            try
            {
                var xmlDoc = XDocument.Load(filePath);
                var rootElement = xmlDoc.Root;
                foreach (var element in rootElement.Elements())
                {
                    _settings[element.Name] = element.Value;
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Failed to load config from file '{filePath}': {ex.Message}");
            }
        }

        public static void SaveConfig(string filePath)
        {
            try
            {
                var xmlDoc = new XDocument();
                var rootElement = new XElement("root");
                foreach (var key in _settings.Keys)
                {
                    rootElement.Add(new XElement(key, _settings[key]));
                }
                xmlDoc.Add(rootElement);
                xmlDoc.Save(filePath);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Failed to save config to file '{filePath}': {ex.Message}");
            }
        }

        public static string GetSetting(string key)
        {
            return _settings[key];
        }

        public static void SetSetting(string key, string value)
        {
            _settings[key] = value;
        }
    }
}
