#include <unistd.h>

#define MAX_INT 2147483647
#define MIN_INT -2147483648
#define INT_SIZE sizeof(int)
#define DEFAULT_CACHE_SIZE 500

typedef struct {
    int value;
    int count;
} cache_t;

cache_t *cache = NULL;
size_t cache_size = 0;
pthread_mutex_t cache_lock;

void initialize_cache(int size) {
    assert(size > 0);
    cache_size = size;
    cache = (cache_t *) malloc(sizeof(cache_t) * cache_size);
    for (int i = 0; i < cache_size; i++) {
        cache[i].value = MIN_INT;
        cache[i].count = 0;
    }
}

void clear_cache() {
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < cache_size; i++) {
        cache[i].value = MIN_INT;
        cache[i].count = 0;
    }
    pthread_mutex_unlock(&cache_lock);
}

void add_to_cache(int value) {
    int index = hash(value) % cache_size;
    pthread_mutex_lock(&cache_lock);
    while (cache[index].count > 0 && cache[index].value != value) {
        index++;
        index %= cache_size;
    }
    if (cache[index].count == 0) {
        cache[index].value = value;
        cache[index].count++;
    } else {
        cache[index].count++;
    }
    pthread_mutex_unlock(&cache_lock);
}

int get_from_cache(int value) {
    int index = hash(value) % cache_size;
    pthread_mutex_lock(&cache_lock);
    while (cache[index].count > 0 && cache[index].value != value) {
        index++;
        index %= cache_size;
    }
    int result = -1;
    if (cache[index].count > 0) {
        result = cache[index].value;
    }
    pthread_mutex_unlock(&cache_lock);
    return result;
}

int hash(int value) {
    // Simple hash function, can be improved
    return value % cache_size;
}

void process_file(const char *filename) {
    int fd = open(filename, O_RDONLY);
    if (fd < 0) {
        printf("Error: could not open file %s\n", filename);
        return;
    }
    size_t len = lseek(fd, 0, SEEK_END);
    char *buffer = (char *) malloc(len + 1);
    int read = pread(fd, buffer, len, 0);
    if (read < 0) {
        printf("Error: could not read from file %s\n", filename);
        return;
    }
    buffer[len] = '\0';
    close(fd);
    int value = -1;
    for (int i = 0; i < len; i++) {
        if (buffer[i] >= '0' && buffer[i] <= '9') {
            value = value * 10 + buffer[i] - '0';
        } else {
            add_to_cache(value);
            value = -1;
        }
    }
}

void process_data(const char *filename) {
    initialize_cache(DEFAULT_CACHE_SIZE);
    clear_cache();
    process_file(filename);
    int max_value = MIN_INT;
    int second_max_value = MIN_INT;
    size_t total_count = 0;
    size_t duplicate_count = 0;
    for (int i = 0; i < cache_size; i++) {
        if (cache[i].count > 0) {
            total_count += cache[i].count;
            if (max_value < cache[i].value) {
                second_max_value = max_value;
                max_value = cache[i].value;
            } else if (second_max_value < cache[i].value && second_max_value != MIN_INT) {
                second_max_value = cache[i].value;
            }
        }
    }
    float mean = total_count > 0 ? (float) max_value / total_count : -1.0;
    float median = total_count > 0 ? (total_count % 2 == 0 ? (max_value + second_max_value) / 2.0 : (float) max_value) : -1.0;
    float stddev = total_count > 1 ? sqrt((total_count * (total_count - 1)) / 12.0 * pow(mean - median, 2)) : -1.0;
    printf("Maximum value: %d\n", max_value);
    printf("Second maximum value: %d\n", second_max_value);
    printf("Total count: %zu\n", total_count);
    printf("Duplicate count: %zu\n", duplicate_count);
    printf("Mean: %f\n", mean);
    printf("Median: %f\n", median);
    printf("Standard deviation: %f\n", stddev);
}

int main(int argc, char **argv) {
    if (argc < 2) {
        printf("Usage: %s file_name\n", argv[0]);
        return 1;
    }
    process_data(argv[1]);
}
```

