// Utility classes for dynamic scaling and resource management
class ResourceManager {
public:
    static constexpr size_t DEFAULT_CPU_COUNT = std::thread::hardware_concurrency();
    static constexpr size_t MIN_CPU_COUNT = 1;
    static constexpr size_t MAX_CPU_COUNT = 8;
    static constexpr float CPU_UTILIZATION_THRESHOLD = 0.75f;

private:
    std::mutex mtx_;
    std::condition_variable cv_;
    bool isRunning_ = false;
    size_t cpuCount_ = DEFAULT_CPU_COUNT;
    float utilizationRate_ = 0.0f;

public:
    ResourceManager() = default;

    void start() {
        if (!isRunning_) {
            isRunning_ = true;
            std::thread t([this] { run(); });
            t.detach();
        }
    }

    void stop() {
        isRunning_ = false;
        cv_.notify_all();
    }

    bool isRunning() const {
        return isRunning_;
    }

    size_t getCpuCount() const {
        std::unique_lock<std::mutex> lk(mtx_);
        return cpuCount_;
    }

    float getUtilizationRate() const {
        std::unique_lock<std::mutex> lk(mtx_);
        return utilizationRate_;
    }

private:
    void run() {
        while (isRunning_) {
            // Check if CPU utilization exceeds the threshold
            float cpuUtilization = 0.0f;
            for (int i = 0; i < 5; ++i) {
                cpuUtilization += static_cast<float>(std::clock()) / CLOCKS_PER_SEC;
            }

            // Adjust CPU count if necessary
            std::unique_lock<std::mutex> lk(mtx_);
            if (cpuCount_ < MAX_CPU_COUNT && cpuUtilization > CPU_UTILIZATION_THRESHOLD) {
                ++cpuCount_;
            } else if (cpuCount_ > MIN_CPU_COUNT && cpuUtilization < 1.0f / CPU_UTILIZATION_THRESHOLD) {
                --cpuCount_;
            }

            // Update utilization rate
            utilizationRate_ = cpuUtilization / cpuCount_;

            // Sleep for a short time before checking again
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
        }
    }
};

