        for (size_t i = 0; i < MAX_RETRIES + 1; ++i) {
            try {
                // Save the data to the file
                std::ofstream outfile(filePath_, std::ios_base::out | std::ios_base::trunc);
                if (outfile.is_open()) {
                    outfile << data;
                    outfile.close();
                    return true;
                } else {
                    // Log an error message and retry if necessary
                    std::cerr << "Failed to save file: " << filePath_ << std::endl;
                }
            } catch (const std::exception& e) {
                // Log an error message and retry if necessary
                std::cerr << "Failed to write data to file: " << e.what() << std::endl;
            }

            // Sleep before retrying the request
            std::this_thread::sleep_for(RETRY_DELAY);
        }

        return false;
    }
};
