// Initialize the NFAPI_RX_INDICATION_PDU_ARRAY.
void initNFAPI_RX_INDICATION_PDU_ARRAY(NFAPI_RX_INDICATION_PDU_ARRAY *array) {
    array->capacity = 1024;
    array->size = 0;
    array->array = malloc(sizeof(NFAPI_RX_INDICATION_PDU_T) * array->capacity);
}

// Add a new NFAPI_RX_INDICATION_PDU_T structure to the array.
void addNFAPI_RX_INDICATION_PDU(NFAPI_RX_INDICATION_PDU_ARRAY *array, char *ue_id, char *rrc_state, int channel, double snr, long timestamp) {
    if (array->size == array->capacity) {
        // Reallocate the memory for the array.
        size_t new_capacity = array->capacity * 2;
        NFAPI_RX_INDICATION_PDU_T *new_array = realloc(array->array, sizeof(NFAPI_RX_INDICATION_PDU_T) * new_capacity);
        if (new_array == NULL) {
            // Handle the error case.
        }
        array->array = new_array;
        array->capacity = new_capacity;
    }
    NFAPI_RX_INDICATION_PDU_T *pdu = &array->array[array->size++];
    pdu->ue_id = strdup(ue_id);
    pdu->rrc_state = strdup(rrc_state);
    pdu->channel = channel;
    pdu->snr = snr;
    pdu->timestamp = timestamp;
}

