NFAPI_RX_INDICATION_PDU_T getNFAPI_RX_INDICATION_PDU(NFAPI_RX_INDICATION_PDU_ARRAY *array, size_t n) {
    return array->array[n];
}

// Free the memory used by the NFAPI_RX_INDICATION_PDU_ARRAY.
void freeNFAPI_RX_INDICATION_PDU_ARRAY(NFAPI_RX_INDICATION_PDU_ARRAY *array) {
