// Asynchronous File I/O Library

#include <iostream>
#include <string>
#include <vector>
#include <mutex>
#include <thread>
#include <future>
#include <chrono>
#include <stdexcept>
#include <algorithm>
#include <cstdlib>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <stdio.h>
#include <cstring>

// Custom Data Structures
struct Node {
  int fd;
  size_t offset;
  size_t length;
};

struct Buffer {
  char* data;
  size_t capacity;
  size_t size;
  size_t used;
};

struct Metadata {
  size_t node_count;
  std::vector<Node> nodes;
  std::mutex metadata_lock;
};

// Global Variables
const int BUFFER_SIZE = 1024 * 1024; // 1MB buffer size
int MAX_NODES = 16; // maximum number of nodes per file
Metadata* global_metadata = new Metadata();
std::mutex global_lock;

// Function Declarations
void init_buffer(Buffer* buffer);
void destroy_buffer(Buffer* buffer);
size_t read_file(const char* path, size_t offset, size_t length);
size_t write_file(const char* path, size_t offset, const char* data, size_t length);
size_t flush_file(const char* path);
void init_metadata(Metadata* metadata);
void destroy_metadata(Metadata* metadata);
void update_metadata(Metadata* metadata, int fd, size_t offset, size_t length);
int open_file(const char* path);
int close_file(const char* path);

// Function Definitions
void init_buffer(Buffer* buffer) {
  buffer->data = (char*)malloc(BUFFER_SIZE);
  buffer->capacity = BUFFER_SIZE;
  buffer->size = 0;
  buffer->used = 0;
}

void destroy_buffer(Buffer* buffer) {
  free(buffer->data);
}

size_t read_file(const char* path, size_t offset, size_t length) {
  std::lock_guard<std::mutex> guard(global_lock);
  int fd = open_file(path);
  if (fd < 0) return -1;
  size_t total_bytes_read = 0;
  while (total_bytes_read < length) {
    Buffer buffer;
    init_buffer(&buffer);
    ssize_t bytes_read = pread(fd, buffer.data, std::min(BUFFER_SIZE, length - total_bytes_read), offset + total_bytes_read);
    if (bytes_read < 0) {
      close(fd);
      destroy_buffer(&buffer);
      return bytes_read;
    } else if (bytes_read == 0) break;
    buffer.size = bytes_read;
    update_metadata(global_metadata, fd, offset + total_bytes_read, buffer.size);
    std::copy(buffer.data, buffer.data + buffer.size, reinterpret_cast<char*>(&total_bytes_read));
    destroy_buffer(&buffer);
  }
  close(fd);
  return total_bytes_read;
}

size_t write_file(const char* path, size_t offset, const char* data, size_t length) {
  std::lock_guard<std::mutex> guard(global_lock);
  int fd = open_file(path);
  if (fd < 0) return -1;
  size_t total_bytes_written = 0;
  while (total_bytes_written < length) {
    Buffer buffer;
    init_buffer(&buffer);
    ssize_t bytes_written = pwrite(fd, data + total_bytes_written, std::min(BUFFER_SIZE, length - total_bytes_written), offset + total_bytes_written);
    if (bytes_written < 0) {
      close(fd);
      destroy_buffer(&buffer);
      return bytes_written;
    } else if (bytes_written == 0) break;
    buffer.size = bytes_written;
    update_metadata(global_metadata, fd, offset + total_bytes_written, buffer.size);
    std::copy(buffer.data, buffer.data + buffer.size, reinterpret_cast<char*>(&total_bytes_written));
    destroy_buffer(&buffer);
  }
  close(fd);
  return total_bytes_written;
}

size_t flush_file(const char* path) {
  std::lock_guard<std::mutex> guard(global_lock);
  int fd = open_file(path);
  if (fd < 0) return -1;
  size_t total_bytes_flushed = 0;
  while (total_bytes_flushed < global_metadata->node_count) {
    Node node = global_metadata->nodes[total_bytes_flushed];
    ssize_t bytes_flushed = fsync(fd);
    if (bytes_flushed < 0) {
      close(fd);
      return bytes_flushed;
    } else if (bytes_flushed == 0) break;
    total_bytes_flushed++;
  }
  close(fd);
  return total_bytes_flushed;
}

void init_metadata(Metadata* metadata) {
  metadata->node_count = 0;
}

void destroy_metadata(Metadata* metadata) {}

void update_metadata(Metadata* metadata, int fd, size_t offset, size_t length) {
  Node node;
  node.fd = fd;
  node.offset = offset;
  node.length = length;
  metadata->nodes[metadata->node_count] = node;
  metadata->node_count++;
}

int open_file(const char* path) {
  return open(path, O_RDWR | O_CREAT, S_IRUSR | S_IWUSR);
}

int close_file(const char* path) {
  int fd = open_file(path);
  if (fd < 0) return -1;
  return close(fd);
}
```

This code uses a global lock to synchronize access to the metadata structure, which is not thread-safe. To fix this issue, we can use a per-file lock instead of a global lock. We can also use a mutex object instead of a raw C++ mutex to make it easier to use and manage the locks.

Here's an example of how we can modify the code to use a per-file lock:
```c++
#include <mutex>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

struct Node {
  int fd;
  size_t offset;
  size_t length;
};

struct Metadata {
  int node_count;
  std::vector<Node> nodes;
};

// Function Declarations
void init_buffer(Buffer* buffer);
void destroy_buffer(Buffer* buffer);
size_t read_file(const char* path, size_t offset, size_t length);
size_t write_file(const char* path, size_t offset, const char* data, size_t length);
size_t flush_file(const char* path);
void init_metadata(Metadata* metadata);
void destroy_metadata(Metadata* metadata);
void update_metadata(Metadata* metadata, int fd, size_t offset, size_t length);
int open_file(const char* path);
int close_file(const char* path);

// Function Definitions
void init_buffer(Buffer* buffer) {
  buffer->data = (char*)malloc(BUFFER_SIZE);
  buffer->capacity = BUFFER_SIZE;
  buffer->size = 0;
  buffer->used = 0;
}

void destroy_buffer(Buffer* buffer) {
  free(buffer->data);
}

size_t read_file(const char* path, size_t offset, size_t length) {
  std::lock_guard<std::mutex> guard(path_locks[path]);
  int fd = open_file(path);
  if (fd < 0) return -1;
  size_t total_bytes_read = 0;
  while (total_bytes_read < length) {
    Buffer buffer;
    init_buffer(&buffer);
    ssize_t bytes_read = pread(fd, buffer.data, std::min(BUFFER_SIZE, length - total_bytes_read), offset + total_bytes_read);
    if (bytes_read < 0) {
      close(fd);
      destroy_buffer(&buffer);
      return bytes_read;
    } else if (bytes_read == 0) break;
    buffer.size = bytes_read;
    update_metadata(global_metadata, fd, offset + total_bytes_read, buffer.size);
    std::copy(buffer.data, buffer.data + buffer.size, reinterpret_cast<char*>(&total_bytes_read));
    destroy_buffer(&buffer);
  }
  close(fd);
  return total_bytes_read;
}

size_t write_file(const char* path, size_t offset, const char* data, size_t length) {
  std::lock_guard<std::mutex> guard(path_locks[path]);
  int fd = open_file(path);
  if (fd < 0) return -1;
  size_t total_bytes_written = 0;
  while (total_bytes_written < length) {
    Buffer buffer;
    init_buffer(&buffer);
    size_t bytes_to_write = std::min(BUFFER_SIZE, length - total_bytes_written);
    memcpy(buffer.data, data + total_bytes_written, bytes_to_write);
    ssize_t bytes_written = pwrite(fd, buffer.data, bytes_to_write, offset + total_bytes_written);
    if (bytes_written < 0) {
      close(fd);
      return -1;
    } else if (bytes_written == 0) break;
    total_bytes_written += bytes_written;
  }
  close(fd);
  return total_bytes_written;
}

size_t flush_file(const char* path) {
  std::lock_guard<std::mutex> guard(path_locks[path]);
  int fd = open_file(path);
  if (fd < 0) return -1;
  size_t total_bytes_flushed = 0;
  while (total_bytes_flushed < global_metadata.nodes[path].length) {
    Buffer buffer;
    init_buffer(&buffer);
    size_t bytes_to_flush = std::min(BUFFER_SIZE, global_metadata.nodes[path].length - total_bytes_flushed);
    ssize_t bytes_flushed = pwrite(fd, buffer.data, bytes_to_flush, global_metadata.nodes[path].offset + total_bytes_flushed);
    if (bytes_flushed < 0) {
      close(fd);
      return -1;
    } else if (bytes_flushed == 0) break;
    total_bytes_flushed += bytes_flushed;
  }
  close(fd);
  return total_bytes_flushed;
}

void init_metadata(Metadata* metadata) {
  metadata->node_count = 0;
}

void destroy_metadata(Metadata* metadata) {}

void update_metadata(Metadata* metadata, int fd, size_t offset, size_t length) {
  Node node;
  node.fd = fd;
  node.offset = offset;
  node.length = length;
  metadata->nodes[metadata->node_count] = node;
  metadata->node_count++;
}

int open_file(const char* path) {
  std::lock_guard<std::mutex> guard(path_locks[path]);
  return open(path, O_RDWR | O_CREAT, S_IRUSR | S_IWUSR);
}

int close_file(const char* path) {
  std::lock_guard<std::mutex> guard(path_locks[path]);
  int fd = open_file(path);
  if (fd < 0) return -1;
  return close(fd);
}
