#include <cppconn/driver.h>
#include <cppconn/exception.h>
#include <cppconn/resultset.h>
#include <cppconn/prepared_statement.h>

// Define the NFAPI_CRC_INDICATION_PDU_T structure
struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
};

// Define the connection pool for database connections
class ConnectionPool {
  private:
    std::map<int, MYSQL*> connections_; // map of connections by thread id
    std::mutex mutex_;                  // mutex to protect concurrent access

  public:
    ConnectionPool();
    ~ConnectionPool();

    // Get a connection from the pool or create one if necessary
    MYSQL* getConnection();

    // Release a connection back to the pool
    void releaseConnection(MYSQL*);
};

// Initialize the connection pool
ConnectionPool::ConnectionPool() {
  for (int i = 0; i < MAX_CONNECTIONS; i++) {
    connections_.emplace(i, nullptr);
  }
}

// Destroy the connection pool
ConnectionPool::~ConnectionPool() {
  // Close and release all connections in the pool
  for (auto it = connections_.begin(); it != connections_.end(); ++it) {
    MYSQL* conn = it->second;
    if (conn != nullptr) {
      mysql_close(conn);
      delete conn;
    }
  }
}

// Get a connection from the pool or create one if necessary
MYSQL* ConnectionPool::getConnection() {
  std::lock_guard<std::mutex> lock(mutex_);

  // Try to get an existing connection from the pool
  for (auto it = connections_.begin(); it != connections_.end(); ++it) {
    int threadId = it->first;
    MYSQL* conn = it->second;

    if (conn == nullptr || mysql_ping(conn) != 0) {
      // Create a new connection and add it to the pool
      connections_.emplace(threadId, new MYSQL());

      conn = connections_[threadId];
      int ret = mysql_init(conn);
      if (ret != 0) {
        printf("Error initializing MySQL connection: %s\n", mysql_error(conn));
        delete conn;
        return nullptr;
      }

      const char* host = "localhost";
      const char* user = "root";
      const char* password = "";
      const char* db = "crc_indications";
      ret = mysql_real_connect(conn, host, user, password, db, 0, nullptr, 0);
      if (ret != 0) {
        printf("Error connecting to MySQL database: %s\n", mysql_error(conn));
        delete conn;
        return nullptr;
      }

      // Set the connection to use the binary protocol
      unsigned long clientFlags = CLIENT_PROTOCOL_41 | CLIENT_PLUGIN_AUTH | CLIENT_MULTI_RESULTS;
      ret = mysql_set_client_option(conn, MYSQL_OPT_PROTOCOL, &clientFlags);
      if (ret != 0) {
        printf("Error setting MySQL client options: %s\n", mysql_error(conn));
        delete conn;
        return nullptr;
      }

      // Set the connection to use utf8 encoding
      ret = mysql_set_character_set(conn, "utf8");
      if (ret != 0) {
        printf("Error setting MySQL character set: %s\n", mysql_error(conn));
        delete conn;
        return nullptr;
      }
    }

    // Return the connection to the pool
    return conn;
  }

  // No available connections, create a new one and add it to the pool
  MYSQL* conn = new MYSQL();
  int ret = mysql_init(conn);
  if (ret != 0) {
    printf("Error initializing MySQL connection: %s\n", mysql_error(conn));
    delete conn;
    return nullptr;
  }

  const char* host = "localhost";
  const char* user = "root";
  const char* password = "";
  const char* db = "crc_indications";
  ret = mysql_real_connect(conn, host, user, password, db, 0, nullptr, 0);
  if (ret != 0) {
    printf("Error connecting to MySQL database: %s\n", mysql_error(conn));
    delete conn;
    return nullptr;
  }

  // Set the connection to use the binary protocol
  unsigned long clientFlags = CLIENT_PROTOCOL_41 | CLIENT_PLUGIN_AUTH | CLIENT_MULTI_RESULTS;
  ret = mysql_set_client_option(conn, MYSQL_OPT_PROTOCOL, &clientFlags);
  if (ret != 0) {
    printf("Error setting MySQL client options: %s\n", mysql_error(conn));
    delete conn;
    return nullptr;
  }

  // Set the connection to use utf8 encoding
  ret = mysql_set_character_set(conn, "utf8");
  if (ret != 0) {
    printf("Error setting MySQL character set: %s\n", mysql_error(conn));
    delete conn;
    return nullptr;
  }

  // Add the new connection to the pool
  connections_.emplace(MAX_CONNECTIONS, conn);
  return conn;
}

// Release a connection back to the pool
void ConnectionPool::releaseConnection(MYSQL* conn) {
  std::lock_guard<std::mutex> lock(mutex_);

  // Check if the connection is already in the pool
  for (auto it = connections_.begin(); it != connections_.end(); ++it) {
    MYSQL* otherConn = it->second;
    if (otherConn == conn) {
      return;
    }
  }

  // Add the connection to the pool
  connections_.emplace(conn);
}

// The function that generates a list of CRC indications based on a given input vector
std::vector<CRCIndication> generateCRCIndications(const std::vector<double>& inputVector) {
  // Initialize the output vector with capacity to hold all possible CRC indications
  std::vector<CRCIndication> outputVector;

  // Get a connection from the pool
  MYSQL* conn = ConnectionPool::getConnection();
  if (conn == nullptr) {
    printf("Error getting MySQL connection from pool\n");
    return {};
  }

  try {
    // Create a prepared statement for querying CRC indications
    std::string sql = "SELECT * FROM crc_indications WHERE input_vector = ?";
    MYSQL_STMT* stmt = mysql_stmt_init(conn);
    if (stmt == nullptr) {
      printf("Error initializing MySQL statement\n");
      ConnectionPool::releaseConnection(conn);
      return {};
    }

    int ret = mysql_stmt_prepare(stmt, sql.c_str(), sql.length());
    if (ret != 0) {
      printf("Error preparing MySQL statement: %s\n", mysql_stmt_error(stmt));
      ConnectionPool::releaseConnection(conn);
      return {};
    }

    // Bind the input vector to the prepared statement
    MYSQL_BIND bind[1];
    memset(bind, 0, sizeof(bind));
    bind[0].buffer_type = MYSQL_TYPE_STRING;
    bind[0].buffer = (char*)inputVector.data();
    bind[0].buffer_length = inputVector.size() * sizeof(double);
    ret = mysql_stmt_bind_param(stmt, bind);
    if (ret != 0) {
      printf("Error binding input vector to MySQL statement: %s\n", mysql_stmt_error(stmt));
      ConnectionPool::releaseConnection(conn);
      return {};
    }

    // Execute the prepared statement and fetch the results
    ret = mysql_stmt_execute(stmt);
    if (ret != 0) {
      printf("Error executing MySQL statement: %s\n", mysql_error(conn));
      ConnectionPool::releaseConnection(conn);
      return {};
    }

    MYSQL_BIND result[1];
    memset(result, 0, sizeof(result));
    ret = mysql_stmt_bind_result(stmt, result);
    if (ret != 0) {
      printf("Error binding MySQL statement results: %s\n", mysql_stmt_error(stmt));
      ConnectionPool::releaseConnection(conn);
      return {};
    }

    // Fetch the CRC indications from the result set
    unsigned long* lengths;
    double* values;
    while (true) {
      lengths = new unsigned long[1];
      values = new double[1];

      ret = mysql_stmt_fetch_column(stmt, result, 0, 0);
      if (ret == 0) {
        break;
      } else if (ret != MYSQL_DATA_TRUNCATED && ret != MYSQL_NO_DATA) {
        printf("Error fetching MySQL statement results: %s\n", mysql_stmt_error(stmt));
        delete[] lengths;
        delete[] values;
        ConnectionPool::releaseConnection(conn);
        return {};
      }

      outputVector.push_back(CRCIndication(inputVector, *lengths / sizeof(double), values));

      delete[] lengths;
      delete[] values;
    }
  } catch (...) {
    ConnectionPool::releaseConnection(conn);
    return {};
  }

  // Release the connection back to the pool
  ConnectionPool::releaseConnection(conn);

  return outputVector;
