    "thread_safe_operations": True,
    "asynchronous_processing": True
}

def hash_file(filepath: str, algorithm: str) -> str:
    """Hashes a file using the specified algorithm."""
    if algorithm not in ALGORITHMS:
        raise ValueError("Unsupported hash algorithm")
    with open(filepath, "rb") as f:
        data = f.read()
    return getattr(hashlib, algorithm)(data).hexdigest()

def upload_file(filepath: str) -> str:
    """Uploads a file to the cloud storage."""
    filename = os.path.basename(filepath)
    with open(filepath, "rb") as f:
        response = requests.post(f"{STORAGE_DIR}/{filename}", data=f)
        if not response.ok:
            raise Exception("Failed to upload file")
    return filename

def store_hash(filename: str, hashvalue: str) -> None:
    """Stores the hash value in the metadata repository."""
    response = requests.post(f"{METADATA_REPO}/{filename}", json={"hash": hashvalue})
    if not response.ok:
        raise Exception("Failed to store hash")

def retrieve_hash(filename: str) -> str:
    """Retrieves the hash value from the metadata repository."""
    response = requests.get(f"{METADATA_REPO}/{filename}")
    if not response.ok:
        raise Exception("Failed to retrieve hash")
    return response.json()["hash"]

def check_cache(filename: str) -> bool:
    """Checks the cache for a pre-computed hash value."""
    return filename in CACHE

def compute_hash(filepath: str, algorithm: str) -> str:
    """Computes the hash value of a file using the specified algorithm."""
    if check_cache(filepath):
        return retrieve_hash(filepath)
    else:
        hashvalue = hash_file(filepath, algorithm)
        store_hash(filepath, hashvalue)
        return hashvalue

def handle_error(e: Exception) -> None:
    """Handles errors by logging and notifying."""
    logging.error(f"{type(e).__name__}: {str(e)}")
    notify("Error in file hashing utility", str(e))

def hash_file_async(filepath: str, algorithm: str) -> None:
    """Hashes a file asynchronously using the specified algorithm."""
    try:
        hashvalue = compute_hash(filepath, algorithm)
        store_hash(filepath, hashvalue)
    except Exception as e:
        handle_error(e)

def hash_files(files: List[str], algorithms: List[str]) -> None:
    """Hashes a list of files using the specified algorithms."""
    for file in files:
        with ThreadPoolExecutor() as executor:
            futures = [executor.submit(hash_file_async, file, algorithm) for algorithm in algorithms]
        for future in as_completed(futures):
