};

// Define the maximum number of structures to generate and persist
#define MAX_NFAPI_CRC_INDICATIONS 1000000

// Define the buffer size for the CRC indication data
#define BUFFER_SIZE (sizeof(struct NFAPI_CRC_INDICATION_PDU_T) * MAX_NFAPI_CRC_INDICATIONS)

// Define the function to generate and persist the CRC indications
int generateAndPersistCrcIndications(uint16_t rnti_start, uint16_t rnti_end, uint8_t *buffer) {
    // Iterate over the range of RNTIs
    for (uint16_t i = rnti_start; i <= rnti_end; ++i) {
        struct NFAPI_CRC_INDICATION_PDU_T crc_indication;
        crc_indication.rnti = i;
        // Generate the CRC indication data for the current RNTI
        generateCrcIndication(&crc_indication);
        // Persist the CRC indication data in the buffer
        persistCrcIndication(buffer, &crc_indication);
    }
    return 0;
}

// Define the function to generate a single CRC indication structure
void generateCrcIndication(struct NFAPI_CRC_INDICATION_PDU_T *crc_indication) {
    // Generate randomized data for the CRC indication
    crc_indication->crc_indication[0] = (uint8_t)(rand() % 256);
    crc_indication->crc_indication[1] = (uint8_t)(rand() % 256);
}

// Define the function to persist the CRC indication data in the buffer
void persistCrcIndication(uint8_t *buffer, struct NFAPI_CRC_INDICATION_PDU_T *crc_indication) {
    // Calculate the offset for the current structure in the buffer
    uint32_t offset = (crc_indication - buffer) / sizeof(struct NFAPI_CRC_INDICATION_PDU_T);
    // Persist the CRC indication data at the calculated offset
    memcpy(buffer + offset * sizeof(struct NFAPI_CRC_INDICATION_PDU_T), crc_indication, sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
}

int main() {
