    uint16_t rnti_start = 0;
    uint16_t rnti_end = MAX_NFAPI_CRC_INDICATIONS - 1;
    // Allocate a buffer for the CRC indication data
    uint8_t *buffer = (uint8_t *)malloc(BUFFER_SIZE);
    // Generate and persist the CRC indications in the buffer
    generateAndPersistCrcIndications(rnti_start, rnti_end, buffer);
