import (
	"fmt"
	"os"
	"time"

	"github.com/aws/aws-sdk-go/aws"
	"github.com/aws/aws-sdk-go/aws/session"
	"github.com/aws/aws-sdk-go/service/s3"
)

type fileProcessor struct {
	session *session.Session
}

func newFileProcessor() (*fileProcessor, error) {
	sess, err := session.NewSession(&aws.Config{
		Region: aws.String("us-west-2")},
	)
	if err != nil {
		return nil, fmt.Errorf("failed to create new AWS session: %w", err)
	}
	return &fileProcessor{session: sess}, nil
}

func (fp *fileProcessor) processFile(key string) error {
	svc := s3.New(fp.session)
	input := &s3.GetObjectInput{
		Bucket: aws.String("my-bucket"),
		Key:    aws.String(key),
	}

	result, err := svc.GetObject(input)
	if err != nil {
		return fmt.Errorf("failed to get object from S3: %w", err)
	}
	defer result.Body.Close()

	// Perform hashing and other operations on the file stream
	fileStream := result.Body.(aws.ReadSeekCloser)

	hasher := md5.New()
	if _, err := io.Copy(hasher, fileStream); err != nil {
		return fmt.Errorf("failed to hash object: %w", err)
	}
	fmt.Println("MD5 hash:", hasher.Sum(nil))

	hasher = sha256.New()
	if _, err := io.Copy(hasher, fileStream); err != nil {
		return fmt.Errorf("failed to hash object: %w", err)
	}
	fmt.Println("SHA256 hash:", hasher.Sum(nil))

	// Upload the processed file back to S3
	uploadInput := &s3.PutObjectInput{
		Body:   fileStream,
		Bucket: aws.String("my-bucket"),
		Key:    aws.String(key),
	}
	if _, err := svc.PutObject(uploadInput); err != nil {
		return fmt.Errorf("failed to upload object to S3: %w", err)
	}

	return nil
}

func main() {
	// Create a new file processor
	fp, err := newFileProcessor()
	if err != nil {
		fmt.Println("Failed to create file processor: ", err)
		os.Exit(1)
	}

	// Process the file
	key := "my-file.txt"
	err = fp.processFile(key)
	if err != nil {
		fmt.Println("Failed to process file: ", err)
		os.Exit(1)
	}

	// Print the hashes
	hasher := md5.New()
	if _, err := io.Copy(hasher, fp.session.Config.Credentials.Retrieve); err != nil {
		fmt.Println("Failed to get credentials: ", err)
		os.Exit(1)
	}
	fmt.Println("MD5 hash of file credentials:", hasher.Sum(nil))

	hasher = sha256.New()
	if _, err := io.Copy(hasher, fp.session.Config.Credentials.Retrieve); err != nil {
		fmt.Println("Failed to get credentials: ", err)
		os.Exit(1)
	}
	fmt.Println("SHA256 hash of file credentials:", hasher.Sum(nil))
}']

