    char* payload;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a list of NFAPI_CRC_INDICATION_PDU_T structures
static NFAPI_CRC_INDICATION_PDU_T *list = NULL;

// Define the list size and CRCFLAG range configuration variables
static int listSize = 0;
static int crcFlagRange = 0;

// Initialize the list with the configured size and CRCFLAG range
void initList(int listSize_, int crcFlagRange_) {
    // Check if the input parameters are valid
    if (listSize_ <= 0 || crcFlagRange_ < MIN_CRCFLAG || crcFlagRange_ > MAX_CRCFLAG) {
        printf("Invalid configuration: listSize=%d, crcFlagRange=%d\n", listSize_, crcFlagRange_);
        exit(1);
    }

    // Allocate memory for the list
    list = (NFAPI_CRC_INDICATION_PDU_T*) malloc(listSize_*sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        printf("Failed to allocate memory for the list\n");
        exit(1);
    }

    // Initialize the list elements
    for (int i = 0; i < listSize_; i++) {
        list[i].crcFlag = MIN_CRCFLAG + (rand() % crcFlagRange_);
        list[i].payload = NULL;
    }

    // Set the list size and CRCFLAG range configuration variables
    listSize = listSize_;
    crcFlagRange = crcFlagRange_;
}

// Release the list memory
void releaseList() {
    // Free the list elements' payload pointers
    for (int i = 0; i < listSize; i++) {
        free(list[i].payload);
    }

    // Free the list memory
    free(list);
}

// Add a new element to the list
void addElement(NFAPI_CRC_INDICATION_PDU_T element) {
    // Check if the list is full
    if (listSize == 0 || list[listSize-1].crcFlag < MIN_CRCFLAG + crcFlagRange - 1) {
        // Allocate memory for the new payload
        size_t payloadSize = strlen(element.payload) + 1;
        char* newPayload = (char*) malloc(payloadSize);
        if (!newPayload) {
            printf("Failed to allocate memory for the new payload\n");
            exit(1);
        }

        // Copy the element's payload to the new payload
        memcpy(newPayload, element.payload, payloadSize);

        // Set the new payload pointer in the list element
        list[listSize].payload = newPayload;
    } else {
        printf("The list is full\n");
        exit(1);
    }
}

// Remove an element from the list
void removeElement(int index) {
    // Check if the index is valid
    if (index < 0 || index >= listSize) {
        printf("Invalid index: %d\n", index);
        exit(1);
    }

    // Free the removed element's payload pointer
    free(list[index].payload);

    // Shift all elements after the index to fill the gap
    for (int i = index + 1; i < listSize; i++) {
        list[i-1] = list[i];
    }

    // Decrease the list size
    listSize--;
}

// Set the CRCFLAG range configuration variable
void setCRCRange(int crcFlagRange_) {
    // Check if the input parameter is valid
    if (crcFlagRange_ < MIN_CRCFLAG || crcFlagRange_ > MAX_CRCFLAG) {
