using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using NFADeviceStreamProcessor.Database;
using NFADeviceStreamProcessor.Models;
using NFADeviceStreamProcessor.Utils;

namespace NFADeviceStreamProcessor
{
    public class StreamProcessorService
    {
        private readonly IConnectionPool _connectionPool;
        private readonly ILogger _logger;
        private readonly List<string> _dataSources = new List<string>();
        private readonly Dictionary<string, Tuple<int, DateTime>> _sourceLastUpdateTime = new Dictionary<string, Tuple<int, DateTime>>();
        private readonly ConcurrentDictionary<string, Packet> _incomingPackets = new ConcurrentDictionary<string, Packet>();
        private readonly ConcurrentDictionary<string, List<Packet>> _outgoingPackets = new ConcurrentDictionary<string, List<Packet>>();

        public StreamProcessorService(IConnectionPool connectionPool, ILogger logger)
        {
            _connectionPool = connectionPool;
            _logger = logger;
        }

        public async Task AddDataSourceAsync(string dataSourceName)
        {
            if (!_dataSources.Contains(dataSourceName))
            {
                _dataSources.Add(dataSourceName);
            }

            await UpdateLastUpdateTimeAsync(dataSourceName);
        }

        public async Task RemoveDataSourceAsync(string dataSourceName)
        {
            if (_dataSources.Contains(dataSourceName))
            {
                _dataSources.Remove(dataSourceName);
            }
        }

        public async Task ProcessPacketAsync(Packet packet, string sourceName = null)
        {
            var incomingPacket = new Packet(packet.Payload, sourceName ?? packet.SourceName);
            _incomingPackets[incomingPacket.Id] = incomingPacket;

            if (_outgoingPackets.ContainsKey(incomingPacket.Id))
            {
                var outgoingPackets = _outgoingPackets[incomingPacket.Id];
                outgoingPackets.Add(incomingPacket);
            }
            else
            {
                var outgoingPackets = new List<Packet>();
                outgoingPackets.Add(incomingPacket);
                _outgoingPackets[incomingPacket.Id] = outgoingPackets;
            }
        }

        public async Task ProcessBatchAsync()
        {
            foreach (var dataSource in _dataSources)
            {
                var sourceLastUpdateTime = await GetSourceLastUpdateTimeAsync(dataSource);
                if (sourceLastUpdateTime != null && DateTime.UtcNow - sourceLastUpdateTime >= TimeSpan.FromMinutes(40))
                {
                    var packets = await FetchPacketsAsync(dataSource, sourceLastUpdateTime);
                    foreach (var packet in packets)
                    {
                        if (_incomingPackets.ContainsKey(packet.Id))
                        {
                            var incomingPacket = _incomingPackets[packet.Id];
                            if (incomingPacket.SourceName == null)
                            {
                                incomingPacket.SourceName = packet.SourceName;
                            }
                            else if (incomingPacket.SourceName != packet.SourceName)
                            {
                                throw new Exception("Inconsistent source names for packets with same ID");
                            }

                            incomingPacket.Payload += packet.Payload;
                        }
                        else
                        {
                            _incomingPackets[packet.Id] = packet;
                        }
                    }
                }
            }

            var outgoingPackets = new List<Packet>();
            foreach (var packet in _incomingPackets)
            {
                if (!_outgoingPackets.ContainsKey(packet.Value.Id))
                {
                    outgoingPackets.Add(packet.Value);
                }
            }

            var dbContext = new DatabaseContext(_connectionPool);
            await dbContext.ProcessPacketsAsync(outgoingPackets);
        }

        private async Task<List<Packet>> FetchPacketsAsync(string dataSource, DateTime lastUpdateTime)
        {
            var packets = new List<Packet>();
            using (var dbContext = new DatabaseContext(_connectionPool))
            {
                packets.AddRange(await dbContext.GetNewPacketsAsync(dataSource, lastUpdateTime));
            }
            return packets;
        }

        private async Task UpdateLastUpdateTimeAsync(string dataSource)
        {
            var sourceLastUpdateTime = await GetSourceLastUpdateTimeAsync(dataSource);
            if (sourceLastUpdateTime != null && DateTime.UtcNow - sourceLastUpdateTime >= TimeSpan.FromMinutes(40))
            {
                _sourceLastUpdateTime[dataSource] = new Tuple<int, DateTime>(_sourceLastUpdateTime[dataSource].Item1 + 1, DateTime.UtcNow);
            }
        }

        private async Task<DateTime?> GetSourceLastUpdateTimeAsync(string dataSource)
        {
            var sourceLastUpdateTime = _sourceLastUpdateTime.ContainsKey(dataSource) ? _sourceLastUpdateTime[dataSource] : null;
            if (sourceLastUpdateTime == null)
            {
                using (var dbContext = new DatabaseContext(_connectionPool))
                {
                    sourceLastUpdateTime = await dbContext.GetSourceLastUpdateTimeAsync(dataSource);
                }
                _sourceLastUpdateTime[dataSource] = sourceLastUpdateTime;
            }
            return sourceLastUpdateTime?.Item2;
        }
    }
}']

