using System;
using System.Collections.Generic;
using System.Data.SqlClient;
using System.Threading;
using System.Threading.Tasks;

namespace ProcessNFAPacketStream
{
    public class PacketProcessor
    {
        private readonly IConnectionPool _connectionPool;
        private readonly ILogger _logger;

        public PacketProcessor(IConnectionPool connectionPool, ILogger logger)
        {
            _connectionPool = connectionPool;
            _logger = logger;
        }

        public async Task ProcessPacketStreamAsync(IEnumerable<byte[]> packetStream, CancellationToken cancellationToken = default)
        {
            var processedResults = new List<ProcessedResult>();
            foreach (var packet in packetStream)
            {
                try
                {
                    var result = await ProcessPacketAsync(packet, cancellationToken);
                    if (result != null)
                    {
                        processedResults.Add(result);
                    }
                }
                catch (Exception ex) when (ex is ArgumentException || ex is InvalidOperationException)
                {
                    _logger.LogError($"Error processing packet: {ex.Message}");
                }
            }
        }

        private async Task<ProcessedResult> ProcessPacketAsync(byte[] packet, CancellationToken cancellationToken = default)
        {
            using var conn = await _connectionPool.GetConnectionAsync(cancellationToken);
            using var cmd = new SqlCommand("INSERT INTO Packets (Data) VALUES (@data)", conn);
            cmd.Parameters.AddWithValue("@data", packet);
            return await cmd.ExecuteNonQueryAsync(cancellationToken);
        }
    }
