        public async Task ProcessDeviceDataAsync(IEnumerable<DeviceData> deviceData)
        {
            // Use a configurable batch size to optimize performance
            var batchSize = Configuration["BatchSize"];

            // Create a queue of incoming packets for processing
            var packetQueue = new ConcurrentQueue<Packet>(deviceData.Select(p => p.AsPacket()));

            // Process packets in batches using a separate thread
            await Task.Run(() => ProcessPacketsAsync(packetQueue, int.Parse(batchSize)));
        }

        private async Task ProcessPacketsAsync(ConcurrentQueue<Packet> packetQueue, int batchSize)
        {
            // Loop until the queue is empty or a shutdown signal is received
            while (!packetQueue.IsEmpty || !_cancellationTokenSource.IsCancellationRequested)
            {
                // Retrieve a batch of packets from the queue
                var packetBatch = new List<Packet>();
                for (int i = 0; i < batchSize && packetQueue.TryDequeue(out Packet packet); i++)
                {
                    packetBatch.Add(packet);
                }

                // Process the packets asynchronously using a separate task
                await Task.Run(() => ProcessPacketsAsync(packetBatch));
            }
        }

        private async Task ProcessPacketsAsync(List<Packet> packetBatch)
        {
            // Use a connection pool to minimize latency and optimize performance
            using var connection = _dbContext.GetDbConnection();
            connection.Open();

            // Use data compression and deduplication techniques to enhance storage efficiency without affecting real-time performance
            var compressedPackets = packetBatch.Select(p => CompressPacket(p)).ToList();
            var deduplicatedPackets = DeduplicatePackets(compressedPackets);

            // Insert the packets into the database using a transaction
            await _dbContext.BeginTransactionAsync();
            try
            {
                foreach (var packet in deduplicatedPackets)
                {
                    await _dbContext.InsertAsync(packet);
                }
                await _dbContext.CommitTransactionAsync();
            }
            catch (Exception ex)
            {
                await _dbContext.RollbackTransactionAsync();
                throw;
            }
        }

        private Packet CompressPacket(Packet packet)
        {
            // Implement data compression technique here
            return packet;
        }

        private List<Packet> DeduplicatePackets(List<Packet> packets)
        {
            // Implement deduplication technique here
            return packets;
        }
    }
}
