class StreamingDataProcessor {
public:
    explicit StreamingDataProcessor(const std::string& name);
    ~StreamingDataProcessor();

    void addSource(const std::string& sourceName, const std::string& adapterName, const std::string& dataFormat, bool isActive = true);
    void removeSource(const std::string& sourceName);
    void startProcessing();
    void stopProcessing();

private:
    struct SourceInfo {
        std::string name;
        std::shared_ptr<DataAdapter> adapter;
        std::unique_ptr<DataParser> parser;
        bool isActive = true;
    };

    using SourceMap = std::unordered_map<std::string, SourceInfo>;
    using ParserQueue = std::vector<std::shared_ptr<DataParser>>;

    void processSource(const std::string& sourceName);
    void handleConnectionTimeout(const std::string& sourceName);
    void handleReconnectionFailure(const std::string& sourceName);
    void handleAuthenticationFailure(const std::string& sourceName);
    bool isSourceActive(const std::string& sourceName) const;

private:
    std::mutex _mutex;
    std::condition_variable _cv;
    std::vector<std::thread> _threads;
    SourceMap _sources;
    ParserQueue _parserQueue;
};
```
```
// StreamingDataProcessor.cpp
#include "StreamingDataProcessor.h"

StreamingDataProcessor::StreamingDataProcessor(const std::string& name) : _name(name) {}

void StreamingDataProcessor::addSource(const std::string& sourceName, const std::string& adapterName, const std::string& dataFormat, bool isActive) {
    std::lock_guard<std::mutex> lock(_mutex);
    _sources.emplace(sourceName, SourceInfo{sourceName, nullptr, nullptr, isActive});
}

void StreamingDataProcessor::removeSource(const std::string& sourceName) {
    std::lock_guard<std::mutex> lock(_mutex);
    _sources.erase(sourceName);
}

void StreamingDataProcessor::startProcessing() {
    std::unique_lock<std::mutex> lock(_mutex);
    for (const auto& source : _sources) {
        processSource(source.first);
    }
}

void StreamingDataProcessor::stopProcessing() {
    std::lock_guard<std::mutex> lock(_mutex);
    _threads.clear();
    _parserQueue.clear();
}
