namespace GraphService
{
    public class GraphService : IGraphService
    {
        private readonly IPreferencesService _preferencesService;
        private readonly IAuthenticationService _authenticationService;
        private readonly INotificationService _notificationService;
        private readonly ILogger _logger;

        public GraphService(
            IPreferencesService preferencesService,
            IAuthenticationService authenticationService,
            INotificationService notificationService,
            ILogger logger)
        {
            _preferencesService = preferencesService;
            _authenticationService = authenticationService;
            _notificationService = notificationService;
            _logger = logger;
        }

        public async Task<Graph> GetGraph(string graphId)
        {
            // Retrieve graph from cloud-based configuration service
            var graph = await _preferencesService.GetGraphAsync(graphId);

            if (graph == null)
            {
                return null;
            }

            // Process and cache graph data
            Graph cachedGraph = new Graph();
            foreach (var node in graph.Nodes)
            {
                var cachedNode = new Node()
                {
                    Id = node.Id,
                    Label = node.Label,
                    Edges = node.Edges.Select(e => e.Id).ToList(),
                };

                cachedGraph.Nodes.Add(cachedNode);
            }

            return cachedGraph;
        }

        public async Task<List<string>> GetGraphIds()
        {
            // Retrieve list of graph IDs from cloud-based configuration service
            var graphIds = await _preferencesService.GetGraphIdsAsync();
            return graphIds;
        }
    }
}
