def aggregate_dataframes(dataframes: List[DataFrame]):
    # Aggregate data from multiple DataFrames
    df = dataframes[0].copy()
    for i in range(1, len(dataframes)):
        df = pd.merge(df, dataframes[i], on=["id", "timestamp"], how="outer")
    return df

def process_dataframe(df: DataFrame):
