    source_names = ["api", "database", "webhook", "kafka"]
    dfs = []
    for source_name in source_names:
        df = get_dataframe_from_source(source_name)
        if not df.empty:
            dfs.append(df)

    if len(dfs) == 0:
        return None
    else:
        return aggregate_dataframes(dfs)

def update_cache():
    # Update cache with latest DataFrame from all sources
    source_names = ["api", "database", "webhook", "kafka"]
    dfs = []
    for source_name in source_names:
        df = get_dataframe_from_source(source_name)
        if not df.empty:
            dfs.append(df)

    if len(dfs) == 0:
        return None
    else:
        latest_df = aggregate_dataframes(dfs)
        DataFrameAggregator["latest"] = latest_df
        return latest_df

def get_cached_dataframe():
    # Get cached DataFrame from all sources
    if "latest" in DataFrameAggregator:
        return DataFrameAggregator["latest"].copy()
    else:
        return None

def main():
    # Main function for the service
    while True:
        # Update cache with latest data from all sources
        update_cache()

        # Process cached data
        df = get_cached_dataframe()
        if df is not None:
            process_dataframe(df)
