import java.util.*;
import java.io.*;
import java.sql.*;
import org.apache.commons.lang3.tuple.Pair;
import org.apache.commons.pool2.impl.GenericObjectPool;

public class DataService {
    private static final GenericObjectPool<Connection> connectionPool = new GenericObjectPool<>();
    private static final Map<String, Pair<Integer, String>> metadataRepository = new HashMap<>();

    public void init() throws IOException {
        // Load metadata from external repository into memory
        for (File file : File.listRoots()) {
            if (file.getName().endsWith(".data")) {
                metadataRepository.put(file.getAbsolutePath(), new Pair<>(file.length(), file.lastModified()));
            }
        }
    }

    public void shutdown() {
        // Close all open connections and release resources
        connectionPool.close();
    }

    private Connection getConnection(String filePath) throws SQLException {
        Connection connection = connectionPool.borrowObject();
        try {
            Pair<Integer, String> metadata = metadataRepository.get(filePath);
            if (metadata == null || !isValidVersion(connection, metadata.getLeft())) {
                connectionPool.returnObject(connection);
                throw new IOException("Invalid file format or version");
            }
        } catch (IOException | SQLException e) {
            connectionPool.returnObject(connection);
            throw e;
        }
        return connection;
    }

    private boolean isValidVersion(Connection connection, int version) throws SQLException {
        // Check if the file format and version are supported by the database driver
        return connection.getMetaData().supportsTransactionIsolationLevel(Connection.TRANSACTION_SERIALIZABLE);
    }

    public void readFromFile(String filePath, int offset, int length) throws IOException {
        // Validate parameters and handle errors
        if (offset < 0 || length <= 0) {
            throw new IllegalArgumentException("Offset or length is negative");
