use std::{
    net::SocketAddr,
    sync::Arc,
    time::Duration,
};
use tokio::{
    io::AsyncReadExt,
    net::TcpStream,
};
use http_client::{
    client::Client,
    request::Request,
    response::Response,
};
use tracing::info;

#[derive(Debug)]
struct HttpClient {
    client: Client,
}

impl HttpClient {
    fn new() -> Self {
        let mut client = Client::new();
        client.set_max_redirects(5);
        client.set_timeout(Duration::from_secs(30));

        Self { client }
    }

    async fn execute(&mut self, request: &Request) -> Result<Response> {
        let url = request.url();
        info!("Executing HTTP request to {}", url);

        let mut response = self.client.execute(request).await?;

        if !response.success() {
            info!("Received non-successful HTTP status code: {}", response.status());

            // Handle redirect or other non-successful responses here
        }

        Ok(response)
    }
}
```

