# Define caching mechanism
def get_cached_image(image: bytes) -> Optional[bytes]:
    # Check if image is in cache
    bucket_name = f"{get_tenant_id()}-bucket"
    blob_name = f"{datetime.now().timestamp()}".encode()
    try:
        blob = storage_client.bucket(bucket_name).blob(blob_name)
        if blob.exists():
            return blob.download_as_bytes()
        else:
            return None
    except Exception as e:
        logger.error(f"Failed to retrieve image from cache: {e}")
        return None

# Define API endpoints
@app.route("/image", methods=["POST"])
def handle_image():
    # Get tenant ID and validate request headers
    tenant_id = get_tenant_id()
    if not tenant_id:
        return Response(status=401)
    # Process image using ML Engine
    image = request.files["image"]
    transformed_image = transform_image(image)
    # Save transformed image to cloud storage
    bucket_name = f"{tenant_id}-bucket"
    blob = storage_client.bucket(bucket_name).blob(f"{datetime.now().timestamp()}".encode())
    with BytesIO() as buffer:
        Image.fromarray(transformed_image, "RGB").save(buffer, format="JPEG")
        buffer.seek(0)
        blob.upload_from_file(buffer)
    # Return transformed image URL
    return Response(url=f"https://storage.googleapis.com/{bucket_name}/{blob_name}")

@app.route("/image/<path:blob_name>", methods=["GET"])
def get_image(blob_name):
    # Get tenant ID and validate request headers
    tenant_id = get_tenant_id()
    if not tenant_id:
        return Response(status=401)
    # Retrieve image from cloud storage
    bucket_name = f"{tenant_id}-bucket"
    try:
        blob = storage_client.bucket(bucket_name).blob(blob_name)
        if blob.exists():
            return Response(blob.download_as_bytes(), mimetype="image/jpeg")
        else:
            return Response(status=404)
    except Exception as e:
        logger.error(f"Failed to retrieve image from cloud storage: {e}")
        return Response(status=500)

@app.route("/image", methods=["DELETE"])
def delete_images():
    # Get tenant ID and validate request headers
    tenant_id = get_tenant_id()
    if not tenant_id:
        return Response(status=401)
    # Delete images from cloud storage
    bucket_name = f"{tenant_id}-bucket"
    try:
        blobs = storage_client.list_blobs(bucket_name)
        for blob in blobs:
            if blob.name.startswith(f"{datetime.now().timestamp()}"):
                blob.delete()
        return Response(status=200)
    except Exception as e:
        logger.error(f"Failed to delete images from cloud storage: {e}")
        return Response(status=500)

@app.route("/image/retention", methods=["GET"])
def get_retention_policy():
    # Get tenant ID and validate request headers
    tenant_id = get_tenant_id()
    if not tenant_id:
        return Response(status=401)
    # Retrieve retention policy from cache or cloud storage
    bucket_name = f"{tenant_id}-bucket"
    blob_name = "retention_policy.json"
    try:
        cached_blob = get_cached_image(f"{bucket_name}/{blob_name}")
        if cached_blob:
            return Response(cached_blob, mimetype="application/json")
        else:
            blob = storage_client.bucket(bucket_name).blob(blob_name)
            if blob.exists():
                return Response(blob.download_as_bytes(), mimetype="application/json")
            else:
                return Response(status=404)
    except Exception as e:
        logger.error(f"Failed to retrieve retention policy from cloud storage: {e}")
        return Response(status=500)

@app.route("/image/retention", methods=["PUT"])
def set_retention_policy():
    # Get tenant ID and validate request headers
    tenant_id = get_tenant_id()
    if not tenant_id:
        return Response(status=401)
    # Set retention policy in cache and cloud storage
    bucket_name = f"{tenant_id}-bucket"
    blob_name = "retention_policy.json"
    try:
        blob = storage_client.bucket(bucket_name).blob(blob_name)
        if not blob.exists():
            blob.upload_from_string("{}", content_type="application/json")
        else:
            return Response(status=409)
        # Save retention policy to cache
        with BytesIO() as buffer:
            json.dump(request.get_json(), buffer)
            buffer.seek(0)
            set_cached_image(f"{bucket_name}/{blob_name}", buffer.getvalue())
        return Response(status=201)
    except Exception as e:
        logger.error(f"Failed to set retention policy in cloud storage: {e}")
        return Response(status=500)
```

This is a Python script that provides an API for image transformation and caching using Google Cloud Storage. It allows you to upload, retrieve, and delete images from the cloud storage bucket associated with your tenant ID. Additionally, it includes functionality for setting and retrieving retention policies for images in the cloud storage bucket.

The script first defines several functions that handle the core logic of image transformation and caching: `transform_image()`, which uses the ML Engine to perform image transformation on a given image; `get_cached_image()`, which checks if an image is already cached and returns its contents if it exists; and `set_cached_image()`, which saves an image to the cache.

The script then defines several API endpoints that handle incoming requests: `/image`, which handles image uploads, retrievals, and deletions; `/image/<path:blob_name>`, which handles image retrievals; and `/image/retention`, which handles retention policy settings and retrievals. Each endpoint calls the corresponding functions to perform its actions.

The script also includes a `get_tenant_id()` function that validates incoming requests and extracts the tenant ID from the request headers. This is necessary because all API requests must be authorized using a service account key, which includes the tenant ID in the header of each request.']

