// Function to find the new state list in a given finite state automaton (FSA)
void find_new_state_list(char** states, int num_states, char* current_state, char* next_state) {
    // Initialize an empty state list
    char** new_states = malloc(num_states * sizeof(char*));
    int new_num_states = 0;

    // Iterate through the states in the FSA
    for (int i = 0; i < num_states; i++) {
        // If the current state is not the same as the next state, add it to the new list
        if (strcmp(current_state, next_state) != 0) {
            new_states[new_num_states++] = states[i];
        }
    }

    // Return the new state list
    return new_states;
}

