#include <chrono>
#include <atomic>

class StreamingDataProcessor {
public:
    StreamingDataProcessor(const std::vector<std::string>& sources, const std::string& outputFile);
    ~StreamingDataProcessor();

    void startProcessing();
    void stopProcessing();

private:
    // Data structure to store information about each source
    struct SourceInfo {
        std::string name;
        bool isActive;
        int connectionAttempts;
        std::chrono::time_point<std::chrono::system_clock> lastConnectionTime;
        std::vector<char> buffer;
    };

    // Function to process incoming data from a source
    void processData(const std::string& sourceName, const char* data, size_t length);

    // Function to handle errors and reconnection attempts for a specific source
    void handleError(const std::string& sourceName, int errorCode);

    // Thread function to read from sources and process the data
    static void* processingThreadFunction(void* args);

    // Mutex to protect concurrent access to the sourceInfo map
    std::mutex sourceMutex;

    // Condition variable to signal when new data is available for processing
    std::condition_variable dataAvailableCondVar;

    // Map of sources and their corresponding information
    std::unordered_map<std::string, SourceInfo> sourceInfoMap;

    // Vector of all active sources
    std::vector<std::string> activeSources;

    // File output stream to write processed data to
    std::ofstream outputFileStream;

    // Thread pool to handle processing tasks concurrently
    std::thread_pool threadPool;

    // Atomic variable to signal when processing is stopped
    std::atomic<bool> stopProcessingFlag;
};

#endif /* STREAMINGDATAPROCESSOR_H */
