// StreamingDataProcessor.cpp
#include "StreamingDataProcessor.h"

StreamingDataProcessor::StreamingDataProcessor(const std::vector<std::string>& sources, const std::string& outputFile) : stopProcessingFlag(false) {
    // Initialize sourceInfoMap and activeSources with the given sources
    for (const auto& source : sources) {
        SourceInfo info;
        info.name = source;
        info.isActive = true;
        info.connectionAttempts = 0;
        info.lastConnectionTime = std::chrono::system_clock::now();
        sourceInfoMap[source] = info;
        activeSources.push_back(source);
    }

    // Open the output file stream for writing
    outputFileStream.open(outputFile, std::ios::binary);
}

StreamingDataProcessor::~StreamingDataProcessor() {
    stopProcessing();
}

void StreamingDataProcessor::startProcessing() {
    threadPool = std::thread_pool(std::thread::hardware_concurrency());

    for (const auto& source : activeSources) {
