    stopProcessingFlag = true;

    // Wait for all threads to finish
    threadPool.join();
}

void StreamingDataProcessor::processSource(const std::string& source) {
    while (!stopProcessingFlag) {
        std::unique_lock<std::mutex> lock(sourceMutex);
        dataAvailableCondVar.wait(lock, [this, source]() { return stopProcessingFlag || !sourceInfoMap[source].buffer.empty(); });

        if (stopProcessingFlag) {
            break;
        }

        // Process the buffered data from the source
        processData(source, sourceInfoMap[source].buffer.data(), sourceInfoMap[source].buffer.size());

        // Clear the buffer and signal that the data has been processed
        sourceInfoMap[source].buffer.clear();
        dataAvailableCondVar.notify_all();
    }
}

