using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using Amazon.S3;
using Amazon.S3.Model;
using Azure.Storage.Blobs;
using Azure.Storage.Blobs.Models;
using Microsoft.Identity.Client;

namespace HighPerformanceSecureService
{
    public class DataService
    {
        private readonly string _clientId;
        private readonly string _clientSecret;
        private readonly string _tenantId;
        private readonly string _region;
        private readonly string _bucketName;
        private readonly string _containerName;
        private readonly AesGcm _aesGcm;
        private readonly Dictionary<string, byte[]> _keyCache = new();

        public DataService(string clientId, string clientSecret, string tenantId, string region, string bucketName, string containerName)
        {
            _clientId = clientId;
            _clientSecret = clientSecret;
            _tenantId = tenantId;
            _region = region;
            _bucketName = bucketName;
            _containerName = containerName;
            _aesGcm = new AesGcm();
        }

        public async Task<IEnumerable<string>> GetDataAsync()
        {
            var accessToken = await GetAccessTokenAsync();
            var blobClient = new BlobContainerClient(new Uri($"https://{_bucketName}.blob.core.windows.net/{_containerName}"), accessToken);
            var blobItems = blobClient.GetBlobs();
            var dataList = new List<string>();

            foreach (var blobItem in blobItems)
            {
                using var memoryStream = new MemoryStream();
                await blobItem.DownloadToAsync(memoryStream, true);
                var decryptedData = _aesGcm.Decrypt(memoryStream.GetBuffer());
                dataList.Add(Encoding.UTF8.GetString(decryptedData));
            }

            return dataList;
        }

        public async Task<string> GetDataByIdAsync(string id)
        {
            var accessToken = await GetAccessTokenAsync();
            var blobClient = new BlobContainerClient(new Uri($"https://{_bucketName}.blob.core.windows.net/{_containerName}"), accessToken);
            var blobItem = blobClient.GetBlobs().FirstOrDefault(x => x.Properties.Id == id);

            if (blobItem == null)
            {
                return null;
            }

            using var memoryStream = new MemoryStream();
            await blobItem.DownloadToAsync(memoryStream, true);
            var decryptedData = _aesGcm.Decrypt(memoryStream.GetBuffer());
            return Encoding.UTF8.GetString(decryptedData);
        }

        public async Task<string> AddDataAsync(string data)
        {
            var accessToken = await GetAccessTokenAsync();
            var blobClient = new BlobContainerClient(new Uri($"https://{_bucketName}.blob.core.windows.net/{_containerName}"), accessToken);
            using var memoryStream = new MemoryStream();
            await _aesGcm.EncryptAsync(memoryStream, Encoding.UTF8.GetBytes(data));
            var blobItem = blobClient.UploadBlob(memoryStream.ToArray());
            return blobItem.Properties.Id;
        }

        public async Task<string> UpdateDataAsync(string id, string data)
        {
            var accessToken = await GetAccessTokenAsync();
            var blobClient = new BlobContainerClient(new Uri($"https://{_bucketName}.blob.core.windows.net/{_containerName}"), accessToken);
            using var memoryStream = new MemoryStream();
            await _aesGcm.EncryptAsync(memoryStream, Encoding.UTF8.GetBytes(data));
            var blobItem = blobClient.UploadBlob(id, memoryStream.ToArray());
            return blobItem.Properties.Id;
        }

        public async Task<string> DeleteDataAsync(string id)
        {
            var accessToken = await GetAccessTokenAsync();
            var blobClient = new BlobContainerClient(new Uri($"https://{_bucketName}.blob.core.windows.net/{_containerName}"), accessToken);
            var blobItem = blobClient.GetBlobs().FirstOrDefault(x => x.Properties.Id == id);

            if (blobItem != null)
            {
                await blobItem.DeleteAsync();
                return id;
            }

            return null;
        }

        private async Task<string> GetAccessTokenAsync()
        {
            var clientApplication = ConfidentialClientApplicationBuilder.Create(_clientId)
                .WithTenantId(_tenantId)
                .WithClientSecret(_clientSecret)
                .Build();
            var authenticationResult = await clientApplication.AcquireTokenForClient(new[] { "https://storage.azure.com/.default" })
                                                               .ExecuteAsync()
                                                               .ConfigureAwait(false);
            return authenticationResult.AccessToken;
        }
    }
}
```
