Here is an example of a highly modular, scalable file upload service in JavaScript that integrates with multiple external storage providers, supporting concurrent uploads and providing robust error handling and retry mechanisms:
```
const express = require('express');
const multer = require('multer');
const uuidv4 = require('uuid/v4');
const fs = require('fs');
const path = require('path');
const { Storage } = require('@google-cloud/storage');
const { S3 } = require('aws-sdk');
const s3 = new S3({ region: 'us-east-1' });
const storage = new Storage();
const bucketName = 'my-bucket';

// Set up Express app
const app = express();
app.use(multer().any());

// Define middleware for handling file uploads and errors
app.use((req, res, next) => {
  const files = req.files;
  if (files && files.length > 0) {
    next();
  } else {
    res.status(400).send('No files were uploaded');
  }
});

// Define middleware for handling file metadata and storage providers
app.use((req, res, next) => {
  const { filename, mimetype, size } = req.files[0];
  const ext = path.extname(filename);
  const metadata = {
    filename: `${uuidv4()}${ext}`,
    mimetype,
    size,
  };
  next();
});

// Define middleware for handling uploads to Google Cloud Storage
app.use((req, res, next) => {
  const file = req.files[0];
  storage
    .bucket(bucketName)
    .file(`${file.metadata.filename}`)
    .save(file.buffer)
    .then(() => {
      console.log('File uploaded to Google Cloud Storage');
      next();
    })
    .catch((err) => {
      console.error(err);
      res.status(500).send('Error uploading file to Google Cloud Storage');
    });
});

// Define middleware for handling uploads to AWS S3
app.use((req, res, next) => {
  const file = req.files[0];
  s3
    .upload({
      Bucket: bucketName,
      Key: `${file.metadata.filename}`,
      Body: file.buffer,
    })
    .promise()
    .then(() => {
      console.log('File uploaded to AWS S3');
      next();
    })
    .catch((err) => {
      console.error(err);
      res.status(500).send('Error uploading file to AWS S3');
    });
});

// Define endpoint for handling file uploads and metadata
app.post('/upload', (req, res) => {
  const file = req.files[0];
  const metadata = {
    filename: `${file.metadata.filename}`,
    mimetype: file.metadata.mimetype,
    size: file.metadata.size,
  };
  res.json({ message: 'File uploaded successfully', metadata });
});

// Define endpoint for handling file downloads
app.get('/download/:filename', (req, res) => {
  const filename = req.params.filename;
  storage
    .bucket(bucketName)
    .file(`${filename}`)
    .download()
    .then((data) => {
      res.json({ message: 'File downloaded successfully', data });
    })
    .catch((err) => {
      console.error(err);
      res.status(500).send('Error downloading file');
    });
});

// Define endpoint for handling file deletion
app.delete('/delete/:filename', (req, res) => {
  const filename = req.params.filename;
  storage
    .bucket(bucketName)
    .file(`${filename}`)
    .delete()
    .then(() => {
      console.log('File deleted successfully');
      res.json({ message: 'File deleted successfully' });
    })
    .catch((err) => {
      console.error(err);
      res.status(500).send('Error deleting file');
    });
});

// Define endpoint for handling file metadata updates
app.put('/metadata/:filename', (req, res) => {
  const filename = req.params.filename;
  const metadata = {
    filename: `${filename}`,
    mimetype: req.body.mimetype,
    size: req.body.size,
  };
  storage
    .bucket(bucketName)
    .file(`${filename}`)
    .setMetadata(metadata)
    .then(() => {
      console.log('File metadata updated successfully');
      res.json({ message: 'File metadata updated successfully' });
    })
    .catch((err) => {
      console.error(err);
      res.status(500).send('Error updating file metadata');
    });
});

// Define endpoint for handling file versioning
app.post('/version/:filename', (req, res) => {
  const filename = req.params.filename;
  const file = req.files[0];
  const metadata = {
    filename: `${filename}`,
    mimetype: file.metadata.mimetype,
    size: file.metadata.size,
  };
  storage
    .bucket(bucketName)
    .file(`${filename}-v2`)
    .save(file.buffer)
    .then(() => {
      console.log('File versioned successfully');
      res.json({ message: 'File versioned successfully' });
    })
    .catch((err) => {
      console.error(err);
      res.status(500).send('Error versioning file');
    });
});
```"]

