use std::env;
use tokio::runtime::Runtime;
use tokio_postgres::NoTls;
use tokio_postgres::error::Error;
use tokio_postgres::row::Row;
use serde::Deserialize;

#[derive(Deserialize, Debug)]
struct Employee {
    name: String,
    city: String,
    address: String,
}

fn main() -> Result<(), Error> {
    let args: Vec<String> = env::args().collect();

    if args.len() != 2 {
        println!("Usage: {} <supervisor_id>", args[0]);
        return Ok(());
    }

    // Create a connection pool to the PostgreSQL database
    let mut rt = Runtime::new().unwrap();
    let db_url = "postgres://user:password@localhost/database";
    let (pool, conn) = rt.block_on(async {
        tokio_postgres::connect(&db_url, NoTls).await?;
    });

    // Prepare the SQL query to fetch employee details from the Employees table
    let sql = "SELECT name, city, address FROM Employees WHERE supervisor_id = $1";
    let mut stmt = conn.prepare(sql).await?;

    // Execute the query with the input supervisor ID as a parameter
    let rows = rt.block_on(async {
        let (rows, _) = stmt.query(&[&args[1]]).await?;
        Ok::<_, Error>(rows)
    });

    // Loop over the results and print them to the console
    for row in rows.iter() {
        let employee: Employee = row.try_get("name")?;
        println!("{}", employee);
    }

    // Clean up resources
    rt.shutdown();
    Ok(())
}
```
This code uses the `tokio` crate to run asynchronous tasks and the `tokio-postgres` crate to connect to a PostgreSQL database. It also uses the `serde` crate for serializing and deserializing JSON data.

The main function first parses the command line arguments to get the input supervisor ID. It then creates a connection pool to the PostgreSQL database using the `tokio_postgres::connect` function, which returns a future that must be awaited before we can use the connection.

Once the connection is established, we prepare an SQL query to fetch employee details from the `Employees` table where the supervisor ID matches the input argument. We then execute the query using the `tokio_postgres::query` function, which returns a future that will yield the results of the query.

We loop over the results and print them to the console using the `println!` macro. We also serialize the employee data into the `Employee` struct using the `serde` crate's `try_get` method.

Finally, we clean up resources by shutting down the runtime using the `tokio::runtime::Runtime::shutdown` method.']

