using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using System.Xml.Linq;
using System.Net.Http;
using Newtonsoft.Json.Linq;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;

namespace ConfigManager
{
    public class ConfigurationManager : IConfigurationManager
    {
        private readonly HttpClient _httpClient = new HttpClient();
        private readonly ILogger<ConfigurationManager> _logger;
        private readonly Dictionary<string, JObject> _configCache = new Dictionary<string, JObject>();
        private readonly object _cacheLock = new object();

        public ConfigurationManager(ILogger<ConfigurationManager> logger)
        {
            _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        }

        public async Task<JObject> GetConfigAsync(string configId, string serviceName, CancellationToken cancellationToken = default)
        {
            if (configId == null)
                throw new ArgumentNullException(nameof(configId));
            if (serviceName == null)
                throw new ArgumentNullException(nameof(serviceName));

            // Check cache for config first
            JObject config;
            lock (_cacheLock)
            {
                if (_configCache.TryGetValue(configId, out config))
                    return config;
            }

            // Fetch new config from external service
            try
            {
                using (var response = await _httpClient.GetAsync($"{serviceName}/config/{configId}", cancellationToken).ConfigureAwait(false))
                {
                    if (!response.IsSuccessStatusCode)
                        throw new Exception($"Failed to fetch config from service '{serviceName}'");

                    var content = await response.Content.ReadAsStringAsync().ConfigureAwait(false);
                    JObject json = JObject.Parse(content);

                    lock (_cacheLock)
                    {
                        _configCache[configId] = json;
                    }

                    return json;
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to fetch config from service '{ServiceName}'", serviceName);
                throw;
            }
        }

        public async Task<JObject> GetConfigAsync(string configId, CancellationToken cancellationToken = default) => await GetConfigAsync(configId, null, cancellationToken).ConfigureAwait(false);

        public void Dispose() => _httpClient.Dispose();
    }
}
```

