// Define the structure for the state list
struct StateList {
    int *states;
    size_t num_states;
};

// Define the function to dynamically generate a state list from a given finite state automaton (FSA)
struct StateList* generateStateList(int *initial_states, size_t num_initial_states, FSA *fsa, int start_state, int last_state) {
    // Allocate memory for the state list
    struct StateList *list = malloc(sizeof(struct StateList));
    if (!list) {
        return NULL;
    }

    // Initialize the number of states to 0
    list->num_states = 0;

    // Allocate memory for the state array
    list->states = malloc(sizeof(int) * num_initial_states);
    if (!list->states) {
        free(list);
        return NULL;
    }

    // Iterate over the initial states and add them to the state list
    for (size_t i = 0; i < num_initial_states; ++i) {
        int current_state = initial_states[i];
        if (current_state > last_state || current_state < start_state) {
            // Skip invalid states or states outside the range of the FSA
            continue;
        }
        list->states[list->num_states++] = current_state;
    }

    // Iterate over the transitions in the FSA and add new states to the state list
    for (int i = start_state; i <= last_state; ++i) {
        int num_transitions = getNumTransitions(fsa, i);
        for (int j = 0; j < num_transitions; ++j) {
            int next_state = getNextState(fsa, i, j);
            if (next_state > last_state || next_state < start_state) {
                // Skip invalid states or states outside the range of the FSA
                continue;
            }
            if (!containsState(list, list->num_states, next_state)) {
                list->states[list->num_states++] = next_state;
            }
        }
    }

    // Filter the state list using a callback function for input symbols
    int num_filtered_states = filterStates(list, list->num_states, fsa);

    // Reallocate memory for the filtered state array
    list->states = realloc(list->states, sizeof(int) * num_filtered_states);
    if (!list->states) {
        free(list);
        return NULL;
    }

    // Update the number of states in the state list
    list->num_states = num_filtered_states;

    return list;
}

