class HighPerformanceCache:
    def __init__(self, cache_size=1024, eviction_strategy="lru"):
        self.cache = {}
        self.cache_size = cache_size
        self.eviction_strategy = eviction_strategy
        self.hit_count = 0
        self.miss_count = 0
        self.hit_ratio = None

    def get(self, key):
        if key in self.cache:
            self.hit_count += 1
            return self.cache[key]
        else:
            self.miss_count += 1
            return None

    def put(self, key, value):
        if len(self.cache) >= self.cache_size:
            self._evict()
        self.cache[key] = value

    def _evict(self):
        if self.eviction_strategy == "lru":
            # Evict the least recently used item
            for key in sorted(self.cache, key=lambda k: self.cache[k]["last_accessed"]):
                del self.cache[key]
        elif self.eviction_strategy == "fifo":
            # Evict the first item added to the cache
            del self.cache[list(self.cache)[0]]
        else:
            raise ValueError("Invalid eviction strategy")

    def get_metrics(self):
        return {
            "hit_count": self.hit_count,
            "miss_count": self.miss_count,
            "hit_ratio": round(self.hit_count / (self.hit_count + self.miss_count), 2)
        }
```
