using System;
using System.Collections.Generic;
using System.Data;
using System.Linq;
using System.Threading.Tasks;

namespace FlexibleStringProcessor
{
    public class PipelineConfigManager
    {
        private readonly List<PipelineConfiguration> _configurations = new List<PipelineConfiguration>();

        public void AddConfiguration(PipelineConfiguration configuration)
        {
            _configurations.Add(configuration);
        }

        public bool RemoveConfiguration(string name)
        {
            return _configurations.RemoveAll(c => c.Name == name) > 0;
        }

        public PipelineConfiguration GetConfiguration(string name)
        {
            return _configurations.FirstOrDefault(c => c.Name == name);
        }

        public void UpdateConfiguration(PipelineConfiguration configuration)
        {
            var existingConfig = GetConfiguration(configuration.Name);
            if (existingConfig != null)
            {
                existingConfig.Version = configuration.Version;
            }
            else
            {
                AddConfiguration(configuration);
            }
        }
    }

    public class PipelineConfiguration
    {
        public string Name { get; set; }
        public int Version { get; set; }
        public List<PipelineStage> Stages { get; set; } = new List<PipelineStage>();
    }

    public class PipelineStage
    {
        public string Name { get; set; }
        public Func<string, string> Processor { get; set; }
    }

    public class StringProcessor : IDisposable
    {
        private readonly List<PipelineConfiguration> _configurations = new List<PipelineConfiguration>();
        private readonly PipelineConfigManager _pipelineConfigManager;

        public StringProcessor(PipelineConfigManager pipelineConfigManager)
        {
            _pipelineConfigManager = pipelineConfigManager;
        }

        public void ProcessString(string input)
        {
            var currentConfiguration = GetCurrentConfiguration();
            if (currentConfiguration != null)
            {
                foreach (var stage in currentConfiguration.Stages)
                {
                    input = stage.Processor(input);
                }
            }
            else
            {
                input = input;
            }
        }

        public void Dispose()
        {
            _pipelineConfigManager?.Dispose();
        }

        private PipelineConfiguration GetCurrentConfiguration()
        {
            return _pipelineConfigManager.GetConfiguration("default");
        }
    }
}
```
