// UserPreferenceManager.cs
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;
using Newtonsoft.Json;

namespace DynamicEcommercePlatform
{
    public class UserPreferenceManager
    {
        private readonly ILogger _logger;
        private readonly IConfiguration _configuration;
        private readonly IDictionary<string, object> _preferences;

        public UserPreferenceManager(ILogger<UserPreferenceManager> logger, IConfiguration configuration)
        {
            _logger = logger;
            _configuration = configuration;
            _preferences = new Dictionary<string, object>();
        }

        public void Initialize()
        {
            _logger.LogInformation("Initializing UserPreferenceManager...");
            LoadPreferences();
        }

        private void LoadPreferences()
        {
            // Load preferences from configuration file.
            var preferencesJson = _configuration["preferences"];
            if (string.IsNullOrEmpty(preferencesJson))
            {
                return;
            }

            try
            {
                var preferences = JsonConvert.DeserializeObject<IDictionary<string, object>>(preferencesJson);
                _preferences = preferences;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to load preferences.");
            }
        }

        public void SetPreference(string key, object value)
        {
            if (!_preferences.ContainsKey(key))
            {
                return;
            }

            _preferences[key] = value;
        }

        public object GetPreference(string key)
        {
            if (!_preferences.ContainsKey(key))
            {
                return null;
            }

            return _preferences[key];
        }
    }
}
