  // Clean up the files and resources
  close_files();

  return 0;
}

void init_files() {
  // Initialize the semaphore for the cache lock
  semaphore_init(&cache_lock, 1);

  // Load the file names from the configuration file
  FILE *config_file = fopen("config.txt", "r");
  assert(config_file != NULL);

  char line[MAX_PATH_LENGTH];
  while (fgets(line, MAX_FILE_NAME_LENGTH, config_file) != NULL) {
    if (strlen(line) > 0 && line[strlen(line) - 1] == '\n') {
      line[strlen(line) - 1] = '\0';
    }
    strcpy(file_names[num_files], line);
    num_files++;
  }

  fclose(config_file);
}

void close_files() {
  // Free the memory for the file names and paths
  free(file_names);
  free(file_paths);

  // Destroy the semaphore for the cache lock
  semaphore_destroy(&cache_lock);
}

void process_file(char *file_path) {
  // Open the file and read its contents into memory
  int fd = open(file_path, O_RDONLY);
  assert(fd != -1);

  char buffer[BUFFER_SIZE];
  int size;
  while ((size = read(fd, buffer, BUFFER_SIZE)) > 0) {
    // Process the data in the buffer
    // ...
  }

  close(fd);
}

void find_max(int *data, int size) {
  // Initialize the max and second-max values to the first element in the array
  max_value = data[0];
  second_max_value = max_value;

  // Iterate over the rest of the elements in the array
  for (int i = 1; i < size; ++i) {
    if (data[i] > max_value) {
      second_max_value = max_value;
      max_value = data[i];
    } else if (data[i] > second_max_value) {
      second_max_value = data[i];
    }
  }
}

void print_results() {
