  printf("Largest value: %d\n", max_value);
  printf("Second-largest value: %d\n", second_max_value);

  // Print metadata about the dataset, including total count, duplicate presence, and statistical summaries
  printf("Total count: %d\n", total_count);
  printf("Duplicate presence: %s\n", duplicate_present ? "yes" : "no");
  printf("Mean: %.2f\n", mean);
  printf("Median: %d\n", median);
  printf("Standard deviation: %.2f\n", standard_deviation);

  // Print the histogram of the dataset, if requested
  if (histogram_size > 0) {
    create_histogram(data, size);
  }
}

void create_histogram(int *data, int size) {
  // Calculate the histogram of the data using a bin size and range specified by the user
  int histogram[HISTOGRAM_SIZE];
  memset(histogram, 0, sizeof(histogram));

  for (int i = 0; i < size; ++i) {
    int bin = data[i] / HISTOGRAM_BIN_SIZE;
    histogram[bin]++;
  }

  // Print the histogram
  printf("Histogram:\n");
  for (int i = 0; i < HISTOGRAM_SIZE; ++i) {
    if (histogram[i] > 0) {
      printf("%d: %d\n", i * HISTOGRAM_BIN_SIZE, histogram[i]);
    }
  }
}
