        private readonly List<Uri> _cache = new List<Uri>();
        private readonly object _lockObject = new object();

        public async Task<XDocument> ParseAsync(string uri)
        {
            var cacheKey = GetCacheKey(uri);
            if (_memoryCache.Contains(cacheKey))
            {
                return (XDocument)_memoryCache[cacheKey];
            }

            try
            {
