import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantReadWriteLock;

import org.apache.commons.lang3.exception.ExceptionUtils;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import com.example.exceptions.AuthenticationException;
import com.example.exceptions.AuthorizationException;
import com.example.exceptions.OAuth2Exception;
import com.example.exceptions.TokenValidationException;
import com.example.models.User;
import com.example.repositories.UserRepository;
import com.example.services.JwtService;
import com.example.utils.CryptoUtils;
import com.example.utils.OAuth2Utils;

/**
 * UserAuthentication service for a multi-tenant SaaS application that supports OAuth 2.0 and JWT-based authentication.
 */
@Service
public class UserAuthenticationService {

    /**
     * The user repository used to retrieve user information from the database.
     */
    @Autowired
    private UserRepository userRepository;

    /**
     * The JWT service used to issue and validate JWT tokens.
     */
    @Autowired
    private JwtService jwtService;

    /**
     * The global session store used to maintain session consistency across multiple AWS regions.
     */
    @Autowired
    private ConcurrentHashMap<String, String> sessionStore;

    /**
     * The executor service used to manage background tasks and optimize request distribution via an auto-scaling load balancer.
     */
    private ExecutorService executorService = Executors.newCachedThreadPool();

    /**
     * The lock used to synchronize shared resources safely and efficiently.
     */
    private Lock lock = new ReentrantReadWriteLock().writeLock();

    /**
     * Attempts to authenticate the user with the given username and password. If successful, returns a JWT token for the user.
     * @param username The username of the user attempting to authenticate.
     * @param password The password of the user attempting to authenticate.
     * @return A JWT token for the user if authentication is successful, or null otherwise.
     * @throws AuthenticationException If an error occurs during authentication, such as invalid credentials or a system failure.
     */
    public String authenticate(String username, String password) throws AuthenticationException {
        try {
            User user = userRepository.findByUsername(username);
            if (user == null || !CryptoUtils.verifyPassword(password, user.getHashedPassword())) {
                throw new AuthenticationException("Invalid credentials");
            }
            return jwtService.issueToken(user);
        } catch (OAuth2Exception | TokenValidationException e) {
            // Log the error and propagate it upstream
            System.out.println(e);
            throw new AuthenticationException(e);
        }
    }

    /**
     * Attempts to authenticate the user with the given OAuth 2.0 access token. If successful, returns a JWT token for the user.
     * @param accessToken The access token issued by an IDP for the user attempting to authenticate.
     * @return A JWT token for the user if authentication is successful, or null otherwise.
     * @throws AuthenticationException If an error occurs during authentication, such as invalid credentials or a system failure.
     */
    public String authenticateWithOAuth2(String accessToken) throws AuthenticationException {
        try {
            User user = OAuth2Utils.getUserFromAccessToken(accessToken);
            return jwtService.issueToken(user);
        } catch (OAuth2Exception | TokenValidationException e) {
            // Log the error and propagate it upstream
            System.out.println(e);
            throw new AuthenticationException(e);
        }
    }

    /**
     * Attempts to authorize the user with the given JWT token. If successful, returns a JWT token for the user.
     * @param jwtToken The JWT token issued by this service or an IDP for the user attempting to authenticate.
     * @return A JWT token for the user if authentication is successful, or null otherwise.
     * @throws AuthorizationException If an error occurs during authorization, such as invalid credentials or a system failure.
     */
    public String authorize(String jwtToken) throws AuthorizationException {
        try {
            User user = jwtService.validateToken(jwtToken);
            return jwtService.issueToken(user);
        } catch (OAuth2Exception | TokenValidationException e) {
            // Log the error and propagate it upstream
            System.out.println(e);
            throw new AuthorizationException(e);
        }
    }

    /**
     * Refreshes the user's JWT token by issuing a new one with the same expiration time as the original token.
     * @param jwtToken The JWT token issued by this service or an IDP for the user attempting to authenticate.
     * @return A refreshed JWT token for the user, or null otherwise.
     * @throws AuthenticationException If an error occurs during authentication, such as invalid credentials or a system failure.
     */
    public String refreshToken(String jwtToken) throws AuthenticationException {
        try {
            User user = jwtService.validateToken(jwtToken);
            return jwtService.issueRefreshedToken(user, jwtToken);
        } catch (OAuth2Exception | TokenValidationException e) {
            // Log the error and propagate it upstream
            System.out.println(e);
            throw new AuthenticationException(e);
        }
    }

    /**
     * Revokes the user's JWT token by removing it from the global session store.
     * @param jwtToken The JWT token issued by this service or an IDP for the user attempting to authenticate.
     * @throws AuthenticationException If an error occurs during authentication, such as invalid credentials or a system failure.
     */
    public void revoke(String jwtToken) throws AuthenticationException {
        try {
            User user = jwtService.validateToken(jwtToken);
            sessionStore.remove(user.getId());
        } catch (OAuth2Exception | TokenValidationException e) {
            // Log the error and propagate it upstream
            System.out.println(e);
            throw new AuthenticationException(e);
        }
    }
}']

