        // Initialize the frame pool and frame buffers
        for (int i = 0; i < FRAME_POOL_SIZE; ++i) {
            framePool.push_back(std::make_unique<Frame>());
        }
        for (int i = 0; i < NUM_THREADS; ++i) {
            frameBuffers.push_back(std::make_shared<FrameBuffer>());
        }
    }

    ~StreamingMediaDecoder() {}

    void setVideoResolutionAdjustmentStrategy(VideoResolutionAdjustmentStrategy strategy) {
        resolutionAdjustmentStrategy = strategy;
    }

    void addABSAlgorithm(std::unique_ptr<ABSAlgorithm> algorithm) {
        absAlgorithms.push_back(std::move(algorithm));
    }

    std::unique_ptr<FrameBuffer> decodeNextFrame() {
        // Acquire the frame pool mutex and wait for a frame to become available
        std::lock_guard<std::mutex> lock{framePoolMutex};
        while (isFramePoolFull.load()) {
            framePoolConditionVar.wait(lock);
        }

        // Decode the next frame from the CDN
        auto frame = cdnMetrics.decodeNextFrame();

        // Adjust the video resolution and frame rate based on CDN performance metrics and device capabilities
        if (resolutionAdjustmentStrategy) {
            adjustVideoResolutionAndFrameRate(frame);
        }

        // Apply adaptive bitrate streaming algorithms to optimize performance
        for (auto& absAlgorithm : absAlgorithms) {
            frame = absAlgorithm->apply(frame);
        }

        // Add the decoded frame to the frame buffer
        auto frameBuffer = frameBuffers[threadIdx].get();
        frameBuffer->addFrame(std::move(frame));

        // Release the frame pool mutex and notify other threads of available frames
        isFramePoolFull.store(true);
        framePoolConditionVar.notify_all();
    }

