    void initialize(vector<shared_ptr<Pipeline>> pipelines) {
        if (initialized_) {
            return;
        }

        for (auto& pipeline : pipelines) {
            pipelines_.push_back(pipeline);
        }

        initialized_ = true;
    }

    // Returns the list of processing pipelines in the data ingestion platform.
    vector<shared_ptr<Pipeline>> getPipelines() const { return pipelines_; }

    // Handles a new data stream by passing it through the appropriate processing pipeline and returns the result.
    string handleStream(shared_ptr<Stream> input) {
        if (!initialized_) {
            throw runtime_error("Data ingestion platform not initialized");
        }

        for (auto& pipeline : pipelines_) {
            input = pipeline->process(input);
        }

        return input->getFormat();
    }

private:
    vector<shared_ptr<Pipeline>> pipelines_;  // List of processing pipelines in the data ingestion platform.
    bool initialized_;                       // Flag indicating whether the data ingestion platform is initialized.
};
