    public class ConfigurationManager
    {
        private readonly Dictionary<string, object> _config = new Dictionary<string, object>();
        private readonly List<ConfigurationProvider> _providers = new List<ConfigurationProvider>();
        private readonly ILogger _logger;

        public ConfigurationManager(ILogger logger)
        {
            _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        }

        public void AddProvider(ConfigurationProvider provider)
        {
            if (provider == null)
                throw new ArgumentNullException(nameof(provider));

            _providers.Add(provider);
        }

        public T GetValue<T>(string key, T defaultValue = default)
        {
            if (_config.TryGetValue(key, out object value))
                return (T)value;

            return defaultValue;
        }

        public void Load()
        {
            _logger.LogInformation("Loading configuration...");

            foreach (var provider in _providers)
            {
                var config = provider.GetConfig();
                if (config != null)
                    _config.Add(provider.Name, config);
            }
        }

        public void Save()
        {
            _logger.LogInformation("Saving configuration...");

            foreach (var provider in _providers)
            {
                var config = GetValue<object>(provider.Name);
                if (config != null)
                    provider.SaveConfig(config);
            }
        }

        public void Refresh()
        {
            Load();
            Save();
        }
    }
}
```
