#include <iostream>
#include <string>
#include <vector>
#include <memory>
#include <mutex>
#include <thread>
#include <condition_variable>
#include <unordered_map>
#include <unordered_set>
#include <cassert>

using namespace std;

// Forward declarations
class MarketDataStream;
class TradingEngine;
class TradingRule;
class TradingStrategy;

struct MarketData {
    // Market data fields...
};

// Interface for market data streams
class MarketDataStream {
public:
    virtual ~MarketDataStream() {}
    virtual void subscribe(TradingEngine& engine) = 0;
    virtual void unsubscribe(TradingEngine& engine) = 0;
    virtual void update(const MarketData& data) = 0;
};

// Trading engine for executing trading strategies
class TradingEngine {
public:
    TradingEngine();
    ~TradingEngine() {}
    void addMarketDataStream(std::unique_ptr<MarketDataStream> stream);
    void removeMarketDataStream(const std::string& name);
    void addTradingRule(std::shared_ptr<TradingRule> rule);
    void removeTradingRule(const std::string& name);
    void addTradingStrategy(std::unique_ptr<TradingStrategy> strategy);
    void execute();
private:
    std::unordered_map<std::string, std::shared_ptr<MarketDataStream>> streams_;
    std::vector<std::shared_ptr<TradingRule>> rules_;
    std::vector<std::unique_ptr<TradingStrategy>> strategies_;
};

// Trading rule for determining trading decisions based on market data
class TradingRule {
public:
    virtual ~TradingRule() {}
    virtual bool evaluate(const MarketData& data) = 0;
};

// Tradling strategy for executing trades based on trading rules
class TradingStrategy {
public:
    virtual ~TradingStrategy() {}
    virtual void execute(const MarketData& data) = 0;
};

TradingEngine::TradingEngine() {
}

void TradingEngine::addMarketDataStream(std::unique_ptr<MarketDataStream> stream) {
    streams_.emplace(stream->getName(), std::move(stream));
}

void TradingEngine::removeMarketDataStream(const std::string& name) {
    auto it = streams_.find(name);
    if (it != streams_.end()) {
        it->second.reset();
        streams_.erase(it);
    }
}

void TradingEngine::addTradingRule(std::shared_ptr<TradingRule> rule) {
    rules_.emplace_back(rule);
}

void TradingEngine::removeTradingRule(const std::string& name) {
    for (auto it = rules_.begin(); it != rules_.end(); ++it) {
        if ((*it)->getName() == name) {
            rules_.erase(it);
            break;
        }
    }
}

void TradingEngine::addTradingStrategy(std::unique_ptr<TradingStrategy> strategy) {
    strategies_.emplace_back(std::move(strategy));
}

void TradingEngine::execute() {
    // Loop over all market data streams and evaluate trading rules
    for (auto& stream : streams_) {
        auto data = stream.second->getData();
        if (!data) continue;
        for (auto& rule : rules_) {
            if (rule->evaluate(*data)) {
                // If a trading rule is satisfied, execute the corresponding trading strategy
                for (auto& strategy : strategies_) {
                    if (strategy->getName() == rule->getName()) {
                        strategy->execute(*data);
                        break;
                    }
                }
            }
        }
    }
}

