int main() {
    TradingEngine engine;
    ExchangeMarketDataStream stream("stream1", "exchange1");
    engine.addMarketDataStream(std::move(stream));
    MarketConditionRule rule("rule1", "exchange1", 0.5);
    engine.addTradingRule(std::make_shared<MarketConditionRule>("rule1", "exchange1", 0.5));
    SignalTradingStrategy strategy("strategy1", "exchange1", 0.5);
    engine.addTradingStrategy(std::move(strategy));
