if args.environment == 'dev':
    config_file = os.path.join(os.getcwd(), 'config', 'dev')
else:
    config_file = os.path.join(os.getcwd(), 'config', 'prod')

config = json.load(open(config_file, 'r'))
if args.environment == 'dev':
    overrides = json.load(open('config/overrides', 'r'))
else:
    overrides = {}

# Apply environment-specific overrides to the configuration
for key, value in overrides.items():
    config[key] = value

# Set up the Celery task queue for managing asynchronous processing of configuration updates
celery = Celery('configuration_tool', broker='amqp://guest:guest@localhost:5672//')

