// Real-timeDataAggregation.js
class RealTimeDataAggregator {
  constructor() {
    this.statistics = {};
    this.thresholds = {};
  }

  addThreshold(name, threshold) {
    this.thresholds[name] = threshold;
  }

  processIncomingData(data) {
    const statistics = data.reduce((acc, item) => {
      if (!this.statistics[item]) {
        this.statistics[item] = { count: 0 };
      }
      this.statistics[item].count++;
      return acc;
    }, {});
    const aggregatedStatistics = Object.keys(this.statistics).map((key) => {
      const value = this.statistics[key];
      return { key, count: value.count };
    });
    return aggregatedStatistics;
  }
}
