const asyncReducer = new AsyncReducer((task, callback) => {
  const dataSource = task.dataSource;
  const adapter = new SystemAdapter();
  adapter.getData(dataSource, (error, data) => {
    if (error) {
      console.error(`Error fetching data from ${dataSource}: ${error}`);
      callback(null);
    } else {
      const aggregator = new RealTimeDataAggregator();
      aggregator.addThreshold('mean', 50);
      aggregator.addThreshold('median', 75);
      const aggregatedStatistics = aggregator.processIncomingData(data);
      callback(aggregatedStatistics);
    }
  });
});
