    temp_path.set_extension("temp");
    std::fs::rename(filename, &temp_path)?;
    thread::sleep(std::time::Duration::new(1, 0)); // Sleep for a second to avoid racing with the API
    renamer.api_url(&format!("{}/rename-file?name={}", self.api_url, temp_path.file_name().unwrap().to_string_lossy()));

    Ok(())
}
```
You can then use the `tokio::spawn` function to spawn a new task for each file in the list and rename it asynchronously:
