  public void sendMessage(String message, String user) {
    try {
      XMPPConnection xmppConnection = getXMPPConnection(user);
      Message msg = new Message();
      msg.setBody(message);
      msg.setTo(xmppConnection.getUser());
      xmppConnection.sendPacket(msg);
    } catch (SmackException | InterruptedException e) {
      System.err.println("Error sending message: " + e.getMessage());
    }
  }

  private XMPPConnection getXMPPConnection(String user) throws SmackException, InterruptedException {
    XMPPConnection xmppConnection = xmppConnections.get(user);
    if (xmppConnection == null) {
      xmppConnection = new XMPPConnection();
      ConnectionConfiguration config = new ConnectionConfiguration(XMPP_ROOM_JID, user);
      config.setPacketReplyTimeout(CONNECTION_TIMEOUT);
      xmppConnection.connect(config);
      xmppConnections.put(user, xmppConnection);
    }
    return xmppConnection;
