      String payload = (String) json.get("payload");
      String senderJID = (String) json.get("sender");

      // Send the message to the appropriate messaging provider based on the sender's JID
      if (senderJID.contains("@xmpp")) {
        sendMessageToXMPP(payload, senderJID);
      } else if (senderJID.contains("@mqtt")) {
        sendMessageToMQTT(payload, senderJID);
      } else if (senderJID.contains("@amqp")) {
        sendMessageToAMQP(payload, senderJID);
      }
    } catch (JsonProcessingException e) {
      System.err.println("Error parsing JSON message: " + e.getMessage());
    }
