  private void sendMessageToXMPP(String payload, String senderJID) throws SmackException, InterruptedException {
    XMPPConnection xmppConnection = getXMPPConnection(senderJID);
    Message msg = new Message();
    msg.setBody(payload);
    msg.setTo(xmppConnection.getUser());
    xmppConnection.sendPacket(msg);
  }

  private void sendMessageToMQTT(String payload, String senderJID) {
    MqttClient mqttClient = getMQTTClient(senderJID);
    try {
      mqttClient.publish(payload, new byte[0], 0, false);
    } catch (MqttException e) {
      System.err.println("Error publishing message to MQTT: " + e.getMessage());
    }
