    public class ImageProcessingService
    {
        private readonly IConfiguration _config;
        private readonly ILogger<ImageProcessingService> _logger;
        private readonly Dictionary<string, object> _cache = new Dictionary<string, object>();
        private readonly ObjectPool<HttpClient> _httpClientPool = new ObjectPool<HttpClient>(() => { return new HttpClient(); }, 5);
        private readonly MemoryCache _memoryCache = new MemoryCache(new MemoryCacheOptions());
        private readonly FileSystemWatcher _fileSystemWatcher;

        public ImageProcessingService(IConfiguration config, ILogger<ImageProcessingService> logger)
        {
            _config = config;
            _logger = logger;
            _fileSystemWatcher = new FileSystemWatcher(_config["Storage:Path"]);
            _fileSystemWatcher.Changed += OnFileChanged;
            _fileSystemWatcher.Created += OnFileChanged;
            _fileSystemWatcher.Deleted += OnFileChanged;
            _fileSystemWatcher.Renamed += OnFileChanged;
        }

        public async Task<Stream> ProcessImage(string imagePath, string cacheKey)
        {
            // Check if the image is in the cache
            if (_cache.ContainsKey(cacheKey))
            {
                return (Stream)_cache[cacheKey];
            }

            // Fetch the image from the remote storage
            Stream stream = null;
            try
            {
                string url = _config["Storage:Url"];
                HttpClient client = _httpClientPool.Get();
                HttpResponseMessage response = await client.GetAsync(url + "/" + imagePath);
                if (response.IsSuccessStatusCode)
                {
                    stream = await response.Content.ReadAsStreamAsync();
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to fetch image from remote storage");
            }

            // Process the image if we got a valid stream
            if (stream != null)
            {
                try
                {
                    using MemoryStream memoryStream = new MemoryStream();
                    Image image = Image.FromStream(stream);
                    image.Save(memoryStream, ImageFormat.Png);
                    memoryStream.Position = 0;
                    _cache[cacheKey] = memoryStream;
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Failed to process image");
                }
            }

            return stream;
        }

        public async Task<Stream> ProcessImage(string imagePath, string cacheKey, Func<Stream, Stream> processor)
        {
            // Check if the image is in the cache
            if (_cache.ContainsKey(cacheKey))
            {
                return (Stream)_cache[cacheKey];
            }

            // Fetch the image from the remote storage
            Stream stream = null;
            try
            {
                string url = _config["Storage:Url"];
                HttpClient client = _httpClientPool.Get();
                HttpResponseMessage response = await client.GetAsync(url + "/" + imagePath);
                if (response.IsSuccessStatusCode)
                {
                    stream = await response.Content.ReadAsStreamAsync();
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to fetch image from remote storage");
            }

            // Process the image if we got a valid stream
            if (stream != null)
            {
                try
                {
                    using MemoryStream memoryStream = new MemoryStream();
                    processor(stream).CopyTo(memoryStream);
                    memoryStream.Position = 0;
                    _cache[cacheKey] = memoryStream;
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Failed to process image");
                }
            }

            return stream;
        }

        public void OnFileChanged(object source, FileSystemEventArgs e)
        {
            // Check if the changed file is in the cache
            string cacheKey = GetCacheKey(e.FullPath);
            if (_cache.ContainsKey(cacheKey))
            {
                _logger.LogInformation("Clearing cache for image: " + e.FullPath);
                _cache[cacheKey] = null;
            }
        }

        private string GetCacheKey(string path)
        {
            return Path.GetFileNameWithoutExtension(path);
        }
    }
}
