        while (true) {
            unique_lock<mutex> lock(queue_.getMutex());
            if (queue_.getTasks().empty()) {
                conditionVariable_.wait(lock);
            }
            size_t task = queue_.getTasks()[0];
            queue_.removeTask(task);
            lock.unlock();
            processTask(task);
        }
    }

private:
    WorkQueue& queue_;
    condition_variable conditionVariable_;
};
