['```java
import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

public class UnionFind {
  private Map<Integer, Integer> parent;
  private Map<Integer, Integer> rank;

  public UnionFind(int[] arr) {
    parent = new HashMap<>();
    rank = new HashMap<>();
    for (int i = 0; i < arr.length; i++) {
      parent.put(i, i);
      rank.put(i, 1);
    }
  }

  public int find(int x) {
    while (x != parent.get(x)) {
      parent.put(x, find(parent.get(x)));
      x = parent.get(x);
    }
    return x;
  }

  public void union(int x, int y) {
    int rootX = find(x);
    int rootY = find(y);
    if (rootX == rootY) return;

    if (rank.get(rootX) < rank.get(rootY)) {
      parent.put(rootX, rootY);
    } else if (rank.get(rootX) > rank.get(rootY)) {
      parent.put(rootY, rootX);
    } else {
      parent.put(rootX, rootY);
      rank.put(rootY, rank.get(rootY) + 1);
    }
  }

  public int numDisjointPairs(int[] arr) {
    UnionFind uf = new UnionFind(arr);
    int count = 0;
    for (int i = 0; i < arr.length - 1; i++) {
      for (int j = i + 1; j < arr.length; j++) {
        if (!uf.sameSet(i, j)) {
          uf.union(i, j);
          count++;
        }
      }
    }
    return count;
  }
}
```
This implementation uses a Union-Find data structure to efficiently check for disjointness between pairs of elements in the array. The `find` method finds the root element of a set by traversing up the tree until it reaches a node with no parent, and the `union` method merges two sets by attaching one set to the other. The `numDisjointPairs` method uses this data structure to find the number of disjoint pairs in the array.']

