```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <sys/stat.h>
#include <errno.h>

#define MAX_FILE_PATH_LEN 1024
#define DEFAULT_BIN_SIZE 50
#define DEFAULT_RANGE -1 // -1 means no range constraint
#define DEFAULT_HISTOGRAM_LEVELS 50

// Structure to represent an integer with metadata
typedef struct {
    int value;
    int count;
} IntMetadata;

// Structure to represent a histogram of integer frequencies
typedef struct {
    int binSize;
    int range[2];
    double mean;
    double median;
    double stddev;
    int counts[DEFAULT_HISTOGRAM_LEVELS];
} Histogram;

// Structure to represent the configuration of the library function
typedef struct {
    char *filePaths[MAX_FILE_PATH_LEN];
    int fileCount;
    int binSize;
    int range[2];
    int histogramLevels;
} Config;

// Structure to represent the state of the library function
typedef struct {
    IntMetadata *metadata;
    Histogram *histogram;
    int metadataCount;
    int histogramCount;
} State;

// Function to parse command-line arguments and configure the library function
void configure(Config *config, int argc, char **argv) {
    // Initialize default values for configuration options
    config->filePaths[0] = "";
    config->fileCount = 1;
    config->binSize = DEFAULT_BIN_SIZE;
    config->range[0] = DEFAULT_RANGE;
    config->histogramLevels = DEFAULT_HISTOGRAM_LEVELS;

    // Parse command-line arguments and update configuration options
    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "-f") == 0) {
            config->filePaths[0] = argv[++i];
        } else if (strcmp(argv[i], "-n") == 0) {
            config->fileCount = atoi(argv[++i]);
        } else if (strcmp(argv[i], "-b") == 0) {
            config->binSize = atoi(argv[++i]);
        } else if (strcmp(argv[i], "-r") == 0) {
            config->range[0] = atoi(argv[++i]);
            config->range[1] = atoi(argv[++i]);
        } else if (strcmp(argv[i], "-h") == 0) {
            config->histogramLevels = atoi(argv[++i]);
        }
    }
}

// Function to initialize the state of the library function
void init(State *state, Config *config) {
    // Initialize metadata and histogram structures
    state->metadata = (IntMetadata *) malloc(sizeof(IntMetadata) * config->fileCount);
    state->histogram = (Histogram *) malloc(sizeof(Histogram));

    // Set default values for histogram variables
    state->histogram->binSize = config->binSize;
    state->histogram->range[0] = config->range[0];
    state->histogram->range[1] = config->range[1];
    state->histogram->mean = 0;
    state->histogram->median = 0;
    state->histogram->stddev = 0;

    // Initialize histogram counts and metadata
    for (int i = 0; i < DEFAULT_HISTOGRAM_LEVELS; ++i) {
        state->histogram->counts[i] = 0;
        state->metadata[i].value = 0;
        state->metadata[i].count = 0;
    }
}

// Function to process a single file and update the state of the library function
void processFile(State *state, Config *config) {
    // Open the file and read its contents
    FILE *file = fopen(config->filePaths[0], "r");
    if (file == NULL) {
        printf("Error: failed to open file %s\n", config->filePaths[0]);
        return;
    }

    // Read the contents of the file and update the state
    while (!feof(file)) {
        int value = fgetc(file);
        if (value != '\n') {
            state->metadata[state->metadataCount].value = value;
            state->metadata[state->metadataCount].count++;
            state->histogram->counts[value / config->binSize]++;
        } else {
            state->metadataCount++;
        }
    }

    // Close the file and update the histogram statistics
    fclose(file);
    state->histogram->mean = 0;
    for (int i = 0; i < config->histogramLevels; ++i) {
        state->histogram->mean += state->histogram->counts[i] * i;
    }
    state->histogram->median = 0;
    for (int i = 0; i < config->histogramLevels; ++i) {
        if (state->histogram->mean > state->histogram->counts[i]) {
            state->histogram->median = i;
        }
    }
    state->histogram->stddev = 0;
    for (int i = 0; i < config->histogramLevels; ++i) {
        state->histogram->stddev += pow(i - state->histogram->median, 2);
    }
}

// Function to print the results of the library function
void printResults(State *state, Config *config) {
    // Print the largest and smallest values in the dataset
    printf("Largest value: %d\n", state->metadata[0].value);
    printf("Smallest value: %d\n", state->metadata[state->metadataCount - 1].value);

    // Print the histogram statistics
    for (int i = config->histogramLevels; i > 0; --i) {
        if (state->histogram->counts[i] != 0) {
            printf("Histogram: %d - %d: %d\n", i * config->binSize, (i + 1) * config->binSize, state->histogram->counts[i]);
        }
    }
}

// Function to free the memory allocated by the library function
void freeMemory(State *state) {
    // Free metadata and histogram structures
    free(state->metadata);
    free(state->histogram);
}

int main(int argc, char **argv) {
    // Initialize configuration and state variables
    Config config;
    State state;
    init(&state, &config);

    // Parse command-line arguments and update configuration options
    configure(&config, argc, argv);

    // Process each file in the dataset and update the state
    for (int i = 0; i < config.fileCount; ++i) {
        processFile(&state, &config);
    }

    // Print the results of the library function
    printResults(&state, &config);

    // Free memory allocated by the library function
    freeMemory(&state);
    return 0;
}
```

This code uses a `Config` structure to store configuration options for the library function, and a `State` structure to store the current state of the dataset. The `init()` function initializes the metadata and histogram structures, and the `processFile()` function processes each file in the dataset and updates the state accordingly. Finally, the `printResults()` function prints the results of the library function to standard output.

The code also includes a `configure()` function that parses command-line arguments and updates the configuration options accordingly. This function is used to configure the behavior of the library function before processing the data. For example, it can be used to specify the bin size for the histogram or the range of values to include in the analysis.

The code also includes a `freeMemory()` function that frees any memory allocated by the library function when it is finished using it. This is important to ensure that memory is properly released when the library function is no longer needed.

This is just one possible implementation of a histogram library, and there are many variations on this basic idea. Some libraries may use different data structures or algorithms for computing the histogram statistics, while others may provide additional functionality such as the ability to save the results to a file or perform statistical analysis on the data.']

