}
}
class MqttClient {
private final String uri; // URI of the MQTT broker
private final int timeout; // Timeout (in seconds) for establishing connections
private final List<MqttClientConnection> connections = new ArrayList<>(); // List of active MQTT client connections
public MqttClient(String uri, int timeout) {
this.uri = uri;
this.timeout = timeout;
}
public void connect() {
// Establish a connection to the MQTT broker
MqttClientConnection mqttClientConnection = new MqttClientConnection(this.uri, this.timeout);
mqttClientConnection.connect();
// Add the connection to the list of active connections
this.connections.add(mqttClientConnection);
}
public void subscribe(String topic) {
// Subscribe to the specified topic on all established connections
for (MqttClientConnection mqttClientConnection : this.connections) {
mqttClientConnection.subscribe(topic);
}
}
}
class MqttClientConnection {
private final String uri; // URI of the MQTT broker
private final int timeout; // Timeout (in seconds) for establishing connections
private final InputStream inputStream; // Input stream for receiving data from the MQTT broker
private final OutputStream outputStream; // Output stream for sending data to the MQTT broker
public MqttClientConnection(String uri, int timeout) {
this.uri = uri;
this.timeout = timeout;
}
public void connect() {
// Establish a connection to the MQTT broker
try {
this.inputStream = new Socket(uri).getInputStream();
this.outputStream = new Socket(uri).getOutputStream();
} catch (IOException e) {
e.printStackTrace();
}
}
public void subscribe(String topic) {
// Send a subscription request to the MQTT broker for the specified topic
try {
byte[] buffer = ("SUBSCRIBE " + topic + "\n").getBytes();
this.outputStream.write(buffer);
} catch (IOException e) {
e.printStackTrace();
}
}
public void publish(String message) {
// Send a message to the MQTT broker for the specified topic
try {
byte[] buffer = ("PUBLISH " + message + "\n").getBytes();
this.outputStream.write(buffer);
} catch (IOException e) {
e.printStackTrace();
}
}
}
class IoTDataHandler implements HttpExchange {
private final MqttClient mqttClient; // MQTT client for receiving data
public IoTDataHandler(MqttClient mqttClient) {
this.mqttClient = mqttClient;
}
@Override
public void handle(HttpExchange exchange) throws IOException {
// Handle incoming HTTP requests from WebSockets clients
if (exchange.getRequestMethod().equals("POST")) {
try {
String body = new String(exchange.getRequestBody().readAllBytes());
this.mqttClient.publish(body); // Publish the received data to the MQTT broker
} catch (IOException e) {
e.printStackTrace();
}
} else {
// Handle incoming WebSocket messages from clients
String message = exchange.getRequestURI().toString();
if (message.equals("/iotdata")) {
try {
// Send data received over MQTT to all connected WebSockets clients
byte[] buffer = new byte[INPUT_DATA_BATCH_SIZE];
int readBytes;
while ((readBytes = this.mqttClient.inputStream.read(buffer)) > 0) {
String messageReceived = new String(buffer, 0, readBytes);
exchange.getResponseBody().write(messageReceived.getBytes());
exchange.close(); // Close the WebSocket connection after sending the data
}
} catch (IOException e) {
e.printStackTrace();
}
} else {
// Handle other incoming WebSocket messages from clients
}
}
}
}
class WebSocketServer implements Runnable {
private final String endpoint; // Endpoint for receiving WebSocket connections
private final int timeout; // Timeout (in seconds) for establishing WebSocket connections
private final List<WebSocket> webSockets = new ArrayList<>(); // List of active WebSocket connections
public WebSocketServer(String endpoint, int timeout) {
this.endpoint = endpoint;
this.timeout = timeout;
}
public void start() {
// Start the WebSocket server on a separate thread
new Thread(this).start();
}
@Override
public void run() {
while (true) {
try {
WebSocket webSocket = new WebSocket(this.endpoint, this.timeout); // Establish a WebSocket connection
webSocket.connect(); // Connect to the endpoint
// Add the WebSocket connection to the list of active connections
this.webSockets.add(webSocket);
} catch (IOException e) {
e.printStackTrace();
}
}
}
}
class WebSocket {
private final String endpoint; // Endpoint for receiving WebSocket connections
private final int timeout; // Timeout (in seconds) for establishing WebSocket connections
private final InputStream inputStream; // Input stream for receiving data from the WebSocket connection
private final OutputStream outputStream; // Output stream for sending data to the WebSocket connection
public WebSocket(String endpoint, int timeout) {
this.endpoint = endpoint;
this.timeout = timeout;
}
public void connect() throws IOException {
// Establish a connection to the WebSocket server
this.inputStream = new Socket(this.endpoint).getInputStream();
this.outputStream = new Socket(this.endpoint).getOutputStream();
}
public void send(String message) {
// Send a message to all connected clients over the WebSocket connection
try {
byte[] buffer = ("MESSAGE " + message + "\n").getBytes();
this.outputStream.write(buffer);
} catch (IOException e) {
e.printStackTrace();
}
}
