// renderPersistentCRCIndicationsFooter function definition
function renderPersistentCRCIndicationsFooter(ueIdentifiers, rntiValues) {
  // Initialize variables and data structures
  let footerElements = [];
  const crcIndications = {};
  const ueToRntiMap = new Map();
  const rntiToUeMap = new Map();

  // Iterate over UE identifiers and RNTI values, generating CRC indications and updating maps
  for (const ueId of ueIdentifiers) {
    const rntiValue = rntiValues[ueId];
    if (!crcIndications[rntiValue]) {
      crcIndications[rntiValue] = [];
    }
    const ueToRntiMap.set(ueId, rntiValue);
    const rntiToUeMap.set(rntiValue, ueId);
  }

  // Generate footer elements for CRC indications
  for (const rntiValue in crcIndications) {
    const ueIds = [];
    for (const ueId of ueToRntiMap.keys()) {
      if (ueToRntiMap.get(ueId) === rntiValue) {
        ueIds.push(ueId);
      }
    }
    const footerElement = {
      type: 'crc-indication',
      rntiValue,
      ueIds,
    };
    footerElements.push(footerElement);
  }

  // Return the generated footer elements
  return footerElements;
}
