        if (config_.enableBuffering) {
            bufferEntry(entry);
        } else {
            sendToExternalService(entry);
        }
    }

    void flush() {
        if (config_.enableBuffering) {
            std::unique_lock<std::mutex> lock(bufferMutex_);
            while (!buffer_.empty()) {
                const auto& entry = buffer_.front();
                sendToExternalService(entry);
                buffer_.pop_front();
            }
        }
    }

private:
    void bufferEntry(const LogEntry& entry) {
        std::unique_lock<std::mutex> lock(bufferMutex_);
        buffer_.push_back(entry);
        if (buffer_.size() >= config_.bufferSize) {
            flush();
        }
    }

