// Enums
enum ResponseBodyStrategy {
    ReadOnly,
    Writeable
};

enum ConnectionStatus {
    Open,
    Closed
};

// Structs
struct RequestContext {
    string url;
    int statusCode;
    ResponseBodyStrategy responseBodyStrategy;
    map<string, string> headers;
    vector<string> queryParams;
    CURL *curlHandle;
    ConnectionStatus connectionStatus;
};

struct ConnectionPoolEntry {
    CURL *curlHandle;
    RequestContext requestContext;
    int retryCount;
};

// Global Variables
vector<ConnectionPoolEntry> connectionPool;
map<string, string> rateLimitingQuotas;
int concurrentRequests = 0;
bool shutdownSignal = false;
bool externalRateLimitEnabled = true;
bool sslTerminationEnabled = true;

// Function Prototypes
void handleSigInt(int signal);
void handleSigTerm(int signal);
void configureSsl();
void initConnectionPool();
void destroyConnectionPool();
void sendRequest(const RequestContext &requestContext, const string &url, int statusCode, ResponseBodyStrategy responseBodyStrategy);
void receiveResponse(CURL *curlHandle, char *buffer, size_t bufferSize, size_t *nread);
