    public interface ICache<T> {
        bool TryGetValue(T key, out bool value);
        void AddOrUpdate(T key, bool value);
    }

    public class InMemoryCache : ICache<decimal> {
        private readonly Dictionary<decimal, bool> _cache = new Dictionary<decimal, bool>();

        public bool TryGetValue(decimal key, out bool value) {
            if (_cache.ContainsKey(key)) {
                return _cache[key];
            } else {
                value = false;
                return false;
            }
