```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <semaphore.h>

// Constants for semaphore operations
#define SEMAPHORE_NAME "semaphore"
#define SEMAPHORE_VALUE 0
#define MAX_CONCURRENT_REQUESTS 100
#define MIN_THREADS 5
#define MAX_THREADS 20

// Structure to hold semaphore information
struct semaphore {
    char* name; // Semaphore name
    int value; // Current semaphore value
    int max_requests; // Maximum number of concurrent requests
    int min_threads; // Minimum number of threads to use for processing requests
    int max_threads; // Maximum number of threads to use for processing requests
    pthread_t* thread_ids; // Array of thread IDs used for processing requests
    sem_t sem; // Semaphore structure
};

// Function to initialize the semaphore
void init_semaphore(struct semaphore* sem) {
    // Create a new semaphore with initial value 0
    sem->sem = sem_open(SEMAPHORE_NAME, O_CREAT, 0644, SEMAPHORE_VALUE);
    if (sem->sem == SEM_FAILED) {
        perror("Error creating semaphore");
        exit(1);
    }
    // Initialize the maximum number of concurrent requests
    sem->max_requests = MAX_CONCURRENT_REQUESTS;
    // Initialize the minimum and maximum numbers of threads to use for processing requests
    sem->min_threads = MIN_THREADS;
    sem->max_threads = MAX_THREADS;
    // Create an array to store thread IDs used for processing requests
    sem->thread_ids = malloc(sem->max_threads * sizeof(pthread_t));
}

// Function to acquire the semaphore and execute a critical section of code
void acquire_and_execute(struct semaphore* sem, void (*function)(void)) {
    // Acquire the semaphore lock
    if (sem_wait(&sem->sem) == -1) {
        perror("Error acquiring semaphore");
        exit(1);
    }
    // Execute the critical section of code
    function();
    // Release the semaphore lock
    if (sem_post(&sem->sem) == -1) {
        perror("Error releasing semaphore");
        exit(1);
    }
}

// Function to destroy the semaphore
void destroy_semaphore(struct semaphore* sem) {
    // Close the semaphore
    if (sem_close(&sem->sem) == -1) {
        perror("Error closing semaphore");
        exit(1);
    }
    // Remove the semaphore from the system
    if (sem_unlink(SEMAPHORE_NAME) == -1) {
        perror("Error unlinking semaphore");
        exit(1);
    }
}

// Main function to demonstrate usage of semaphore
int main() {
    // Initialize the semaphore structure
    struct semaphore sem;
    init_semaphore(&sem);

    // Acquire and execute a critical section of code
    acquire_and_execute(&sem, () {
        printf("Executing critical section\n");
    });

    // Destroy the semaphore
    destroy_semaphore(&sem);

    return 0;
}
