// Define the maximum size of the array for storing NFAPI_CRC_INDICATION_PDU_T structures
#define MAX_ARRAY_SIZE 10000

// Define the structure for the NFAPI_CRC_INDICATION_PDU_T data type
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the function for generating an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* generateNfarCrcIndications(size_t numElements) {
    // Validate the input parameter
    if (numElements > MAX_ARRAY_SIZE) {
        printf("Error: The number of elements is greater than the maximum allowed size\n");
        return NULL;
    }

    // Allocate memory for the array of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*) malloc(numElements * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Initialize the array with random values for the RX_UE_INFORMATION_TAG and CRC_INDICATION_REL8_TAG
    for (size_t i = 0; i < numElements; i++) {
        array[i].RX_UE_INFORMATION_TAG = rand() % MAX_RX_UE_INFORMATION_TAG;
        array[i].CRC_INDICATION_REL8_TAG = rand() % MAX_CRC_INDICATION_REL8_TAG;
    }

    // Return the allocated array
    return array;
}

// Define the function for computing the MD5 hash of a given string input
char* getMd5Hash(const char* input) {
    // Validate the input parameter
    if (input == NULL) {
        printf("Error: The input parameter is null\n");
        return NULL;
    }

    // Initialize the MD5 hash context
    MD5_CTX md5Ctx;
    MD5_Init(&md5Ctx);

    // Update the MD5 hash context with the input string
    MD5_Update(&md5Ctx, input, strlen(input));

    // Finalize the MD5 hash and obtain the resulting digest
    unsigned char md5Digest[MD5_DIGEST_LENGTH];
    MD5_Final(md5Digest, &md5Ctx);

    // Allocate memory for the resulting string
    size_t md5Len = MD5_DIGEST_LENGTH * 2 + 1;
    char* md5Str = (char*) malloc(md5Len);

    // Convert the digest to a hexadecimal string
    for (size_t i = 0; i < MD5_DIGEST_LENGTH; i++) {
        sprintf(&md5Str[i * 2], "%02x", md5Digest[i]);
    }

    // Return the resulting hexadecimal string
    return md5Str;
}
