using System;
using System.Security.Cryptography;
using System.Threading.Tasks;
using System.Net.Http;
using System.Net.Http.Headers;
using System.IO;
using System.Text;
using System.Collections.Generic;
using Newtonsoft.Json;

namespace ConsoleApp {
    class Program {
        static void Main(string[] args) {
            // Define the external REST API endpoint URL
            string apiUrl = "https://example.com/api";

            // Define the maximum number of concurrent background tasks
            int maxConcurrentTasks = 10000;

            // Create a list to store the job submission results
            List<string> results = new List<string>();

            // Define a function for submitting jobs asynchronously and handling errors
            async Task SubmitJob(string url, string json) {
                try {
                    using (var client = new HttpClient()) {
                        var request = new HttpRequestMessage() {
                            Method = HttpMethod.Post,
                            RequestUri = new Uri(url),
                            Content = new StringContent(json, Encoding.UTF8, "application/json")
                        };
                        request.Headers.Add("Authorization", "Bearer <YOUR_API_TOKEN>");
                        var response = await client.SendAsync(request);
                        if (response.IsSuccessStatusCode) {
                            results.Add(await response.Content.ReadAsStringAsync());
                        } else {
                            Console.WriteLine($"Error: {response.StatusCode} - {response.ReasonPhrase}");
                        }
                    }
                } catch (Exception ex) {
                    Console.WriteLine(ex.Message);
                }
            }

            // Define a function for generating an array of NFAPI_CRC_INDICATION_PDU_T structures
            List<NFAPI_CRC_INDICATION_PDU_T> GenerateNfarCrcIndications(int numElements) {
                if (numElements > MAX_ARRAY_SIZE) {
                    throw new ArgumentOutOfRangeException("The number of elements is greater than the maximum allowed size");
                }
                List<NFAPI_CRC_INDICATION_PDU_T> array = new List<NFAPI_CRC_INDICATION_PDU_T>(numElements);
                Random random = new Random();
                for (int i = 0; i < numElements; i++) {
                    array.Add(new NFAPI_CRC_INDICATION_PDU_T() {
                        RX_UE_INFORMATION_TAG = random.Next(MAX_RX_UE_INFORMATION_TAG),
                        CRC_INDICATION_REL8_TAG = random.Next(MAX_CRC_INDICATION_REL8_TAG)
                    });
                }
                return array;
            }

            // Define a function for converting an array of NFAPI_CRC_INDICATION_PDU_T structures to JSON format
            string ConvertToJson(List<NFAPI_CRC_INDICATION_PDU_T> array) {
                return JsonConvert.SerializeObject(array, Formatting.Indented);
            }

            // Define a function for submitting jobs asynchronously and handling errors
            async Task SubmitJobs(string url, List<NFAPI_CRC_INDICATION_PDU_T> array) {
                try {
                    using (var client = new HttpClient()) {
                        var request = new HttpRequestMessage() {
                            Method = HttpMethod.Post,
                            RequestUri = new Uri(url),
                            Content = new StringContent(ConvertToJson(array), Encoding.UTF8, "application/json")
                        };
                        request.Headers.Add("Authorization", "Bearer <YOUR_API_TOKEN>");
                        var response = await client.SendAsync(request);
                        if (response.IsSuccessStatusCode) {
                            results.Add(await response.Content.ReadAsStringAsync());
                        } else {
                            Console.WriteLine($"Error: {response.StatusCode} - {response.ReasonPhrase}");
                        }
                    }
                } catch (Exception ex) {
                    Console.WriteLine(ex.Message);
                }
            }

            // Define a function for generating a list of jobs and submitting them asynchronously
            async Task GenerateJobs() {
                List<NFAPI_CRC_INDICATION_PDU_T> array = GenerateNfarCrcIndications(MAX_ARRAY_SIZE);
                Console.WriteLine($"Generated {array.Count} jobs");
                foreach (var item in array) {
                    await SubmitJobs(apiUrl, item);
                }
            }

            // Generate a list of jobs and submit them asynchronously
            await GenerateJobs();

            // Print the job submission results
            Console.WriteLine("Submission Results:");
            foreach (var result in results) {
                Console.WriteLine(result);
            }
        }
    }
}
