// renderPersistentCRCIndicationsFooter function
function renderPersistentCRCIndicationsFooter(ueIdentifiers, rnti, crcIndications) {
  // Initialize variables
  const footerSection = document.createElement("footer");
  let generatedRNTI = false;
  let generatedCRCIndications = false;

  // Handle input parameters
  if (!Array.isArray(ueIdentifiers) || !Array.isArray(rnti) || !Array.isArray(crcIndications)) {
    return console.error("Invalid input parameters");
  }

  // Iterate over UE identifiers and RNTI values, generating footer sections for each
  ueIdentifiers.forEach((ueIdentifier, index) => {
    if (rnti[index] && crcIndications[index]) {
      generatedRNTI = true;
      generatedCRCIndications = true;

      // Create footer section for the current UE identifier and RNTI value
      const footerSectionForUE = document.createElement("footer");
      footerSectionForUE.innerHTML = `
        <div class="ue-identifier">${ueIdentifier}</div>
        <div class="rnti-value">${rnti[index]}</div>
        <div class="crc-indications">${crcIndications[index]}</div>
      `;

      // Append the footer section to the DOM
      footerSection.appendChild(footerSectionForUE);
    }
  });

  // If neither RNTI nor CRC indications were generated, return an error message
  if (!generatedRNTI || !generatedCRCIndications) {
    return console.error("No valid data found for UE identifiers");
  }

  // Return the footer section element
  return footerSection;
}
