@Service
public class PokemonWeaknessServiceImpl implements PokemonWeaknessService {
    private static final String REDIS_CACHE_NAME = "pokemon-weaknesses";
    private static final int DEFAULT_TTL = 60 * 60; // 1 hour
    private static final long MAX_ENTRIES = 50000L;

    @Autowired
    private PokemonDataLoader pokemonDataLoader;

    @Autowired
    @Qualifier("redisCacheManager")
    private CacheManager cacheManager;

    // Redis connection configuration
    private static final JedisPoolConfig REDIS_POOL_CONFIG = new JedisPoolConfig();
    private static final String REDIS_HOST = "localhost";
    private static final int REDIS_PORT = 6379;
    private static final int REDIS_TIMEOUT = 2000;
    private static final boolean USE_SSL = false;

    // API endpoints and configuration
    private static final String POKEAPI_ENDPOINT = "https://pokeapi.co/api/v2/type/";
    private static final String KANAS_ENDPOINT = "http://www.pokemonweakness.com/api/types/";
    private static final int POKEAPI_TIMEOUT = 500; // ms
    private static final int KANAS_TIMEOUT = 1000; // ms
    private static final int MAX_ATTEMPTS = 3;
    private static final long DELAY_BETWEEN_ATTEMPTS = 1000L;

    // Caches for API responses and type data
    private Cache<String, PokemonWeaknessReport> weaknessCache;
    private Cache<String, PokemonTypeData> typeCache;

    // Read-write lock for concurrent access to shared resources
    private ReentrantReadWriteLock readWriteLock = new ReentrantReadWriteLock();

    @Override
    public void init() {
        weaknessCache = cacheManager.getCache(REDIS_CACHE_NAME);
        typeCache = cacheManager.getCache("pokemon-types");

        if (weaknessCache == null) {
            weaknessCache = CacheBuilder.newBuilder()
                    .expireAfterWrite(DEFAULT_TTL, TimeUnit.SECONDS)
                    .maximumSize(MAX_ENTRIES)
                    .build();
            cacheManager.putCache("pokemon-weaknesses", weaknessCache);
        }

        if (typeCache == null) {
            typeCache = CacheBuilder.newBuilder()
                    .expireAfterWrite(DEFAULT_TTL, TimeUnit.SECONDS)
                    .maximumSize(MAX_ENTRIES)
                    .build();
            cacheManager.putCache("pokemon-types", typeCache);
        }
    }

    @Override
    public PokemonWeaknessReport getWeaknessReportForPokemon(String pokemonName) {
        // Get the type of the given pokemon from the type cache
        PokemonTypeData pokemonType = getTypeDataForPokemon(pokemonName);
        if (pokemonType == null) {
            return new PokemonWeaknessReport();
        }

        // Get the weakness report for the given pokemon type from the cache or API
        PokemonWeaknessReport weaknessReport = getWeaknessReportForType(pokemonType.getType());
        if (weaknessReport == null) {
            return new PokemonWeaknessReport();
        }

        // Update the weakness report with the given pokemon's individual weaknesses
        updateWeaknessReportWithPokemon(weaknessReport, pokemonType.getIndividualWeaknesses());

        return weaknessReport;
    }

    private PokemonTypeData getTypeDataForPokemon(String pokemonName) {
        // Get the type of the given pokemon from the cache or API
        String type = null;
        for (int attempt = 1;; attempt++) {
            try {
                Pair<String, PokemonTypeData> typeDataPair = pokemonDataLoader.getTypeForPokemon(pokemonName);
                if (typeDataPair == null) {
                    throw new InvalidPokemonTypeException("Invalid pokemon name: " + pokemonName);
                } else {
                    return typeDataPair.getValue();
                }
            } catch (ApiCallException e) {
                if (attempt >= MAX_ATTEMPTS) {
                    throw new IOException(e);
                } else {
                    try {
                        Thread.sleep(DELAY_BETWEEN_ATTEMPTS);
                    } catch (InterruptedException ie) {
                        // ignore
                    }
                }
            }
        }
    }

    private PokemonWeaknessReport getWeaknessReportForType(String type) {
        // Get the weakness report for the given type from the cache or API
        PokemonWeaknessReport weaknessReport = null;
        for (int attempt = 1;; attempt++) {
            try {
                weaknessReport = pokemonDataLoader.getWeaknessReportForType(type);
                if (weaknessReport == null) {
                    throw new InvalidPokemonTypeException("Invalid type: " + type);
                } else {
                    return weaknessReport;
                }
            } catch (ApiCallException e) {
                if (attempt >= MAX_ATTEMPTS) {
                    throw new IOException(e);
                } else {
                    try {
                        Thread.sleep(DELAY_BETWEEN_ATTEMPTS);
                    } catch (InterruptedException ie) {
                        // ignore
                    }
                }
            }
        }
    }

    private void updateWeaknessReportWithPokemon(PokemonWeaknessReport weaknessReport, List<String> individualWeaknesses) {
        for (String weakness : individualWeaknesses) {
            if (!weaknessReport.containsKey(weakness)) {
                weaknessReport.put(weakness, 0);
            }

            int count = weaknessReport.get(weakness) + 1;
            weaknessReport.put(weakness, count);
        }
    }
}']

