```c
// Semaphore Library Implementation File
#include "semaphore.h"

#include <errno.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

// Semaphore implementation using pthreads and a mutex
struct semaphore {
    int value; // Current resource count
    int max_value; // Maximum allowed resource count
    pthread_mutex_t mutex; // Mutex to protect the semaphore
};

// Initialize a new semaphore with the given initial value
semaphore_t *semaphore_init(int value) {
    semaphore_t *sema = malloc(sizeof(semaphore_t));
    if (sema == NULL) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    sema->value = value;
    sema->max_value = INT_MAX;

    int status = pthread_mutex_init(&sema->mutex, NULL);
    if (status != 0) {
        perror("pthread_mutex_init");
        exit(EXIT_FAILURE);
    }

    return sema;
}

// Acquire a resource from the semaphore, blocking if necessary
void semaphore_acquire(semaphore_t *sema, int resource) {
    pthread_mutex_lock(&sema->mutex);
    while (sema->value < resource) {
        // Block until the requested resources are available
        pthread_cond_wait(&sema->cond, &sema->mutex);
    }
    sema->value -= resource;
    pthread_mutex_unlock(&sema->mutex);
}

// Release a previously acquired resource
void semaphore_release(semaphore_t *sema, int resource) {
    pthread_mutex_lock(&sema->mutex);
    sema->value += resource;
    if (sema->value > sema->max_value) {
        // Cap the value to prevent overflow
        sema->value = sema->max_value;
    }
    pthread_cond_broadcast(&sema->cond);
    pthread_mutex_unlock(&sema->mutex);
}

// Destroy a semaphore and release all resources
void semaphore_destroy(semaphore_t *sema) {
    pthread_mutex_destroy(&sema->mutex);
    free(sema);
}
```']

