using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;
using Newtonsoft.Json;
using RestSharp;

namespace GeospatialMicroservice
{
    public class Program
    {
        private static readonly ILogger Logger = LogManager.CreateLogger<Program>();

        private static readonly Dictionary<string, SatelliteProvider> Providers = new Dictionary<string, SatelliteProvider>();
        private static readonly NoSqlDatabase Database = new NoSqlDatabase();

        public static void Main(string[] args)
        {
            var serviceCollection = new ServiceCollection()
                .AddOptions()
                .Configure<DataPipelineOptions>(Configuration.GetSection("DataPipeline"))
                .AddSingleton(typeof(ILogger), typeof(Logger))
                .AddSingleton(typeof(IDataTransformer), typeof(DataTransformer));

            var serviceProvider = serviceCollection.BuildServiceProvider();

            // Initialize providers and data pipeline
            foreach (var provider in Configuration.GetSection("Providers").GetChildren())
            {
                var name = provider["Name"];
                var url = provider["Url"];
                var format = Enum.Parse<DataFormat>(provider["Format"]);

                var satelliteProvider = new SatelliteProvider(name, url, format);
                Providers.Add(name, satelliteProvider);
            }

            // Start data processing loop
            while (true)
            {
                try
                {
                    ProcessData();
                }
                catch (Exception ex)
                {
                    Logger.LogError(ex, "Unhandled exception in main loop");
                }
            }
        }

        private static async Task ProcessData()
        {
            // Ingest data from providers
            foreach (var provider in Providers.Values)
            {
                try
                {
                    var data = await RestClient.GetAsync<string>(provider.Url);
                    var parsedData = ParseData(data, provider.Format);
                    Database.WriteData(parsedData);
                }
                catch (Exception ex)
                {
                    Logger.LogError(ex, $"Failed to ingest data from {provider.Name}");
                }
            }
        }

        private static async Task<object> ParseData(string data, DataFormat format)
        {
            switch (format)
            {
                case DataFormat.CSV:
                    return await CsvParser.ParseAsync(data);
                case DataFormat.JSON:
                    return JsonConvert.DeserializeObject<object>(data);
                default:
                    throw new NotImplementedException("Unsupported data format");
            }
        }
    }
}
