import java.io.ObjectInputStream;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class FSA {
    private final ConcurrentHashMap<String, MoSTState> states = new ConcurrentHashMap<>();

    public void loadStateFromFSA(ObjectInputStream inputStream) throws IOException {
        ExecutorService executor = Executors.newSingleThreadExecutor();
        Object object = null;
        while ((object = inputStream.readObject()) != null) {
            if (object instanceof MoSTState) {
                MoSTState state = (MoSTState) object;
                states.putIfAbsent(state.getId(), state);
            } else {
                // Handle non-MoSTState objects as needed
            }
        }
        executor.shutdown();
    }

    public void addState(String id, MoSTState state) {
        states.putIfAbsent(id, state);
    }

    public void removeState(String id) {
        states.remove(id);
    }

    public boolean containsState(String id) {
        return states.containsKey(id);
    }

    public int size() {
        return states.size();
    }
}
