// Get request with params
let response = client.get("/path", &[("param1", "value1"), ("param2", "value2")])?;
println!("{}", response);

// Post request with body
let response = client.post("/path", b"{\"key\": \"value\"}")?;
println!("{}", response);
```
You can also disable certificate verification for trusted environments:
```rust
