```
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;

namespace DynamicCacheManager
{
    public class CacheGeneratorSettings
    {
        public int Seed { get; set; } = 10;
        public float MinimumValue { get; set; } = -10.0f;
        public float MaximumValue { get; set; } = 10.0f;
        public DistributionType DistributionType { get; set; } = DistributionType.Uniform;
    }

    public enum DistributionType
    {
        Uniform,
        Normal,
        Poisson
    }

    public class DynamicCacheGenerator
    {
        private readonly ILogger<DynamicCacheGenerator> _logger;
        private readonly CacheGeneratorSettings _settings;

        public DynamicCacheGenerator(ILogger<DynamicCacheGenerator> logger, CacheGeneratorSettings settings)
        {
            _logger = logger;
            _settings = settings;
        }

        public async Task<float[]> GenerateRandomValuesAsync(int count)
        {
            var random = new Random(_settings.Seed);
            var values = Enumerable.Range(0, count).Select(x => random.NextFloat(_settings.MinimumValue, _settings.MaximumValue)).ToArray();
            return await Task.FromResult(values);
        }

        public async Task<int[]> GenerateRandomIntValuesAsync(int count)
        {
            var random = new Random(_settings.Seed);
            var values = Enumerable.Range(0, count).Select(x => random.Next(_settings.MinimumValue, _settings.MaximumValue)).ToArray();
            return await Task.FromResult(values);
        }

        public async Task<IEnumerable<T>> GenerateRandomValuesAsync<T>(int count) where T : struct
        {
            var random = new Random(_settings.Seed);
            var values = Enumerable.Range(0, count).Select(x => GetRandomValue<T>(random)).ToArray();
            return await Task.FromResult(values);
        }

        private T GetRandomValue<T>(Random random) where T : struct
        {
            if (typeof(T) == typeof(float))
            {
                return (T)(object)random.NextFloat(_settings.MinimumValue, _settings.MaximumValue);
            }
            else if (typeof(T) == typeof(int))
            {
                return (T)(object)random.Next(_settings.MinimumValue, _settings.MaximumValue);
            }
            else
            {
                throw new ArgumentException("Unsupported type", nameof(T));
            }
        }
    }
}
```
