// Modular C++ application that integrates with multiple third-party cloud storage services
class CloudStorage {
public:
    // Constructor for the CloudStorage class
    CloudStorage(const std::vector<std::string>& service_names) : services_(service_names) {}

    // Upload a file to one of the supported cloud storage services
    void uploadFile(const std::string& filepath, const std::string& service_name) {
        // Get the service instance for the specified name
        auto service = getServiceInstance(service_name);
        // Check if the service is available and throw an exception if not
        checkServiceAvailability(service);
        // Upload the file to the service
        service->uploadFile(filepath);
    }

    // Download a file from one of the supported cloud storage services
    void downloadFile(const std::string& filepath, const std::string& service_name) {
        // Get the service instance for the specified name
        auto service = getServiceInstance(service_name);
        // Check if the service is available and throw an exception if not
        checkServiceAvailability(service);
        // Download the file from the service
        service->downloadFile(filepath);
    }

private:
    // Get a service instance for the specified name
    std::shared_ptr<CloudStorageService> getServiceInstance(const std::string& service_name) {
        // Find the service instance for the specified name in the services vector
        auto it = std::find_if(services_.begin(), services_.end(), [&](auto&& service) {
            return service->getName() == service_name;
        });
        if (it != services_.end()) {
            // Return the found service instance
            return *it;
        } else {
            // Throw an exception if no service instance was found
            throw std::invalid_argument("No such service: " + service_name);
        }
    }

    // Check if a service is available and throw an exception if not
    void checkServiceAvailability(const std::shared_ptr<CloudStorageService>& service) {
        if (!service->isAvailable()) {
            // Throw an exception if the service is not available
            throw std::runtime_error("Service unavailable: " + service->getName());
        }
    }

    // Vector of supported cloud storage services
    std::vector<std::shared_ptr<CloudStorageService>> services_;
};

// Cloud storage service interface
class CloudStorageService {
public:
    virtual ~CloudStorageService() = default;

    // Get the name of the service
    virtual const std::string& getName() const = 0;

    // Check if the service is available
    virtual bool isAvailable() const = 0;

    // Upload a file to the cloud storage service
    virtual void uploadFile(const std::string& filepath) = 0;

    // Download a file from the cloud storage service
    virtual void downloadFile(const std::string& filepath) = 0;
};

// AWS S3 service implementation
class AwsS3Service : public CloudStorageService {
public:
    AwsS3Service() : client_(Aws::MakeShared<Aws::S3::S3Client>(Aws::Auth::AWSCredentials("", ""))) {}

    const std::string& getName() const override { return "aws-s3"; }

    bool isAvailable() const override { return client_->ListBuckets(); }

    void uploadFile(const std::string& filepath) override {
        auto request = Aws::MakeShared<Aws::S3::Model::PutObjectRequest>(filepath);
        request->SetBody(filepath);
        request->SetContentLength(std::filesystem::file_size(filepath));
        client_->PutObject(*request);
    }

    void downloadFile(const std::string& filepath) override {
        auto request = Aws::MakeShared<Aws::S3::Model::GetObjectRequest>(filepath);
        request->SetBucket("bucket-name");
        request->SetKey("object-key");
        client_->GetObject(*request, filepath);
    }

private:
    Aws::S3::S3Client client_;
};

// Google Cloud Storage service implementation
class GcsService : public CloudStorageService {
public:
    const std::string& getName() const override { return "gcs"; }

    bool isAvailable() const override { return false; }

    void uploadFile(const std::string& filepath) override {
        // Implement upload logic for GCS
    }

