// Dynamic priority queue system that prioritizes tasks based on file metadata, user-defined importance levels, and current service availability
class PriorityQueue {
public:
    PriorityQueue() : services_(getSupportedServices()) {}

    void enqueue(const std::string& filepath, int priority = 0) {
        // Get the service instance for the specified file
        auto service = getServiceInstanceForFile(filepath);
        // Add the task to the queue with the corresponding priority level
        tasks_.emplace_back(Task{service, filepath, priority});
    }

    void dequeue() {
        // Remove and return the highest-priority task from the queue
        auto& task = tasks_.front();
        services_.erase(task.service);
        tasks_.pop_front();
    }

private:
    std::vector<std::shared_ptr<CloudStorageService>> getSupportedServices() {
        return {AwsS3Service(), GcsService(), ABSService()};
    }

    std::shared_ptr<CloudStorageService> getServiceInstanceForFile(const std::string& filepath) {
        // Determine the service instance to use based on the file metadata
        return services_.front();
    }

    struct Task {
        std::shared_ptr<CloudStorageService> service;
        std::string filepath;
        int priority;
    };

    std::vector<Task> tasks_;
    std::set<std::shared_ptr<CloudStorageService>> services_;
};']

