}

// Function to handle errors and retries for storing metadata in the database
void store_metadata_with_retries(converted_file_t *cf) {
    int retry_count = 0;
    while (retry_count < CONVERSION_RETRY_LIMIT) {
        if (store_metadata(cf) == 0) {
            return;
        } else {
            retry_count++;
            log("Retrying storage of metadata for file: %s\n", cf->filename);
            usleep(pow(2, retry_count) * RETRY_DELAY_MS * 1000);
        }
    }
}

// Function to process a single image file and convert it to PDF format
void process_file(const char *input_filename) {
    // Create the output filename for the converted PDF document
    size_t len = strlen(input_filename);
    char *output_filename = (char *) malloc(len + 5);
    if (output_filename == NULL) {
        log("ERROR: Failed to allocate memory for output filename\n");
        return;
    }
    memcpy(output_filename, input_filename, len);
    memcpy(output_filename + len, ".pdf", 5);

    // Retrieve the image file from cloud storage and render it as a PDF document
    char *image_file = get_image_file_with_retries(input_filename);
    if (image_file == NULL) {
        log("ERROR: Failed to retrieve image file for %s\n", input_filename);
        free(output_filename);
        return;
    }
    render_pdf_with_retries(image_file, output_filename);
    free(image_file);

    // Convert the PDF document to a binary format and store its metadata in the database
    int status = convert_file_with_retries(output_filename, output_filename);
    if (status != 0) {
        log("ERROR: Failed to convert file %s\n", input_filename);
        free(output_filename);
        return;
    } else {
        converted_file_t *cf = NULL;
        for (size_t i = 0; i < num_converted_files; i++) {
            if (strcmp(converted_files[i].filename, input_filename) == 0) {
                cf = &converted_files[i];
                break;
            }
        }

        if (cf != NULL) {
            store_metadata_with_retries(cf);
        } else {
            log("ERROR: Failed to store metadata for file %s\n", input_filename);
        }
    }
}

