// KafkaProducer.java
import org.apache.kafka.clients.producer.KafkaProducer;
import org.apache.kafka.clients.producer.ProducerRecord;

public class KafkaProducer {
    private final KafkaProducer<String, String> producer;

    public KafkaProducer() {
        this.producer = new KafkaProducer<>(getProperties());
    }

    public void send(String topic, String message) {
        ProducerRecord<String, String> record = new ProducerRecord<>(topic, null, message);
        producer.send(record);
    }

    private Properties getProperties() {
        Properties properties = new Properties();
        properties.put("bootstrap.servers", "localhost:9092");
        properties.put("key.serializer", "org.apache.kafka.common.serialization.StringSerializer");
        properties.put("value.serializer", "org.apache.kafka.common.serialization.StringSerializer");
        return properties;
    }
}

// KafkaConsumer.java
import org.apache.kafka.clients.consumer.KafkaConsumer;
import org.apache.kafka.clients.consumer.ConsumerRecords;

public class KafkaConsumer {
    private final KafkaConsumer<String, String> consumer;

    public KafkaConsumer() {
        this.consumer = new KafkaConsumer<>(getProperties());
    }

    public void consume(String topic) {
        consumer.subscribe(Collections.singletonList(topic));
        while (true) {
            ConsumerRecords<String, String> records = consumer.poll(Duration.ofMillis(100));
            for (ConsumerRecord<String, String> record : records) {
                System.out.println("Received message: " + record.value());
            }
        }
    }

    private Properties getProperties() {
        Properties properties = new Properties();
        properties.put("bootstrap.servers", "localhost:9092");
        properties.put("key.deserializer", "org.apache.kafka.common.serialization.StringDeserializer");
        properties.put("value.deserializer", "org.apache.kafka.common.serialization.StringDeserializer");
        return properties;
    }
}

// EventProcessor.java
import java.util.ArrayList;
import java.util.List;

public class EventProcessor {
    private final KafkaProducer producer;
    private final List<Event> events = new ArrayList<>();

    public EventProcessor(KafkaProducer producer) {
        this.producer = producer;
    }

    public void processEvents() {
        for (Event event : events) {
            producer.send("events", event.toString());
        }
    }

    public void addEvent(Event event) {
        events.add(event);
    }
}

