import java.util.List;

public class Event {
    private final String topic;
    private final List<String> message;

    public Event(String topic, List<String> message) {
        this.topic = topic;
        this.message = message;
    }

    @Override
    public String toString() {
        return "Event{" +
                "topic='" + topic + '\'' +
                ", message=" + message +
                '}';
