    ue_metadata->crcFlag = strdup(pdu->crcIndicationReL8.crcFlag ? "true" : "false");
    addUeMetadataToCache(pool, ue_metadata);

    // Clean up and return the metadata
    curl_easy_cleanup(curl);
    return ue_metadata;
}

// Callback function for writing the UE metadata to a file
size_t writeUeMetadataCallback(void *ptr, size_t size, size_t nmemb, void *userdata) {
    char **ue_metadata = (char**)userdata;
    if (*ue_metadata == NULL) {
        *ue_metadata = malloc(size * nmemb);
    } else {
        *ue_metadata = realloc(*ue_metadata, size * nmemb + 1);
    }

    memcpy(*ue_metadata, ptr, size * nmemb);
    (*ue_metadata)[size * nmemb] = '\0';

    return size * nmemb;
}
