// Structure to represent a network protocol
typedef struct {
    const char* name;
    void (*process_packet)(void* packet, size_t length);
    void* params;
} protocol_t;

// Global list of protocols
protocol_t* protocols = NULL;
size_t num_protocols = 0;

// Function to add a new protocol to the list
int add_protocol(const char* name, void (*process_packet)(void* packet, size_t length), void* params) {
    // Check if the name is already in use
    for (size_t i = 0; i < num_protocols; ++i) {
        if (strcmp(name, protocols[i].name) == 0) {
            return -1;
        }
    }

    // Allocate memory for the new protocol
    protocol_t* new_protocol = malloc(sizeof(protocol_t));
    if (!new_protocol) {
        return -2;
    }

    // Set the name, process packet function, and parameters
    new_protocol->name = name;
    new_protocol->process_packet = process_packet;
    new_protocol->params = params;

    // Add the protocol to the list
    num_protocols++;
    protocols = realloc(protocols, num_protocols * sizeof(protocol_t));
    if (!protocols) {
        free(new_protocol);
        return -3;
    }
    protocols[num_protocols-1] = new_protocol;

    // Success
    return 0;
}

// Function to initialize a network stack and discover supported protocols
int init_network_stack(void* net_stack) {
    // Check if the network stack is already initialized
    if (net_stack) {
        return -1;
    }

    // Initialize the network stack
    net_stack = malloc(sizeof(struct net_stack));
    if (!net_stack) {
        return -2;
    }

    // Discover supported protocols
    int num_supported_protocols = 0;
    char* supported_protocols[10];
    for (size_t i = 0; i < 10; ++i) {
        if (discover_supported_protocol(i)) {
            supported_protocols[num_supported_protocols++] = supported_protocols[i];
        }
    }

    // Initialize each supported protocol
    for (size_t i = 0; i < num_supported_protocols; ++i) {
        int status = init_protocol(supported_protocols[i], net_stack);
        if (status != 0) {
            return -3;
        }
    }

    // Success
    return 0;
}

// Function to initialize a single protocol
int init_protocol(const char* name, void* net_stack) {
    // Check if the network stack is already initialized
    if (!net_stack) {
        return -1;
    }

    // Find the protocol in the list of supported protocols
    for (size_t i = 0; i < num_protocols; ++i) {
        if (strcmp(name, protocols[i].name) == 0) {
            return protocols[i].process_packet(net_stack);
        }
    }

    // Protocol not found
    return -2;
}

// Function to handle a received packet and route it to the appropriate protocol handler
int process_packet(void* packet, size_t length) {
