    if (!net_stack) {
        return -1;
    }

    // Determine which protocol the packet belongs to and route it to its handler
    for (size_t i = 0; i < num_protocols; ++i) {
        if (is_packet_for_protocol(packet, length, protocols[i].name)) {
            return protocols[i].process_packet(packet, length);
        }
    }

    // Protocol not found
    return -2;
}

// Function to determine if a received packet belongs to a specific protocol
int is_packet_for_protocol(void* packet, size_t length, const char* name) {
    // Check if the network stack is initialized
    if (!net_stack) {
        return -1;
    }

    // Check if the protocol is supported by the network stack
    for (size_t i = 0; i < num_protocols; ++i) {
        if (strcmp(name, protocols[i].name) == 0) {
            return is_packet_for_protocol(packet, length, protocols[i].params);
        }
    }

    // Protocol not supported
    return -2;
}

// Function to handle version mismatches or missing components
int handle_version_mismatch(void* packet, size_t length) {
    // Check if the network stack is initialized
    if (!net_stack) {
