            return (float)(minimum + (maximum - minimum) * random.NextDouble());
        }

        private List<float> GenerateMultipleValues(int minimum, int maximum, int count)
        {
            Random random = new Random(_settings.Seed);
            List<float> values = new List<float>(count);
            for (int i = 0; i < count; i++)
            {
                values.Add(GenerateSingleValue(minimum, maximum));
            }
            return values;
        }

        private float[,] Generate2DArray(int minimum, int maximum, int rows, int columns)
        {
            Random random = new Random(_settings.Seed);
            float[,] array = new float[rows, columns];
            for (int i = 0; i < rows; i++)
            {
                for (int j = 0; j < columns; j++)
                {
                    array[i, j] = GenerateSingleValue(minimum, maximum);
                }
            }
            return array;
        }

        private float[][] GenerateJaggedArray(int minimum, int maximum, int rows)
        {
            Random random = new Random(_settings.Seed);
            float[][] jaggedArray = new float[rows][];
            for (int i = 0; i < rows; i++)
            {
                jaggedArray[i] = GenerateMultipleValues(minimum, maximum, random.Next(5, 10));
            }
            return jaggedArray;
        }
    }
}

