// Define a struct to hold the key-value pairs
typedef struct {
    int key;
    char* value;
} kv_pair;

// Define a list of kv_pairs to store the data
static List<kv_pair> data = NULL;

// Define a mutex to protect concurrent access to the data
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to add a key-value pair to the list
void add_key(int key, char* value) {
    // Acquire the mutex before modifying the data
    pthread_mutex_lock(&lock);

    // Check if the key already exists in the list
    for (int i = 0; i < data.size(); i++) {
        if (data[i].key == key) {
            // Update the value if the key already exists
            free(data[i].value);
            data[i].value = strdup(value);
            break;
        }
    }

    // Add the key-value pair to the list if it doesn't exist
    if (data.size() == 0 || i == data.size()) {
        kv_pair p = {key, strdup(value)};
        data.push_back(p);
    }

    // Release the mutex after modifying the data
    pthread_mutex_unlock(&lock);
}

// Function to get the value of a key from the list
char* get_value(int key) {
    // Acquire the mutex before accessing the data
    pthread_mutex_lock(&lock);

    // Check if the key exists in the list
    for (int i = 0; i < data.size(); i++) {
        if (data[i].key == key) {
            // Return the value of the key if it exists
            char* value = strdup(data[i].value);
            pthread_mutex_unlock(&lock);
            return value;
        }
    }

    // Release the mutex after accessing the data
    pthread_mutex_unlock(&lock);

    // Return NULL if the key doesn't exist
    return NULL;
}

// Function to compute the MD5 hash of a string
char* md5(char* input) {
    char* hash = (char*)malloc(MD5_DIGEST_LENGTH * 2 + 1);
    memset(hash, 0, MD5_DIGEST_LENGTH * 2 + 1);
    MD5((unsigned char*)input, strlen(input), (unsigned char*)hash);
    return hash;
}
