// Define the struct for storing key-value pairs
struct kv_pair {
    int key;
    char *value;
};

// Define the cache entry structure
struct cache_entry {
    int key;
    char *value;
    long expiry_time; // Unix timestamp of when the cache entry will expire
};

// Define the cache data structure
struct cache {
    struct cache_entry **entries;
    size_t capacity;
    size_t num_entries;
};

// Define the database connection
sqlite3 *db;

// Define the lock for protecting the cache
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

// Initialize the cache with a given capacity
void init_cache(size_t capacity) {
    // Allocate memory for the cache entries
    struct cache *cache = malloc(sizeof(struct cache));
    if (cache == NULL) {
        perror("malloc");
        exit(1);
    }
    cache->capacity = capacity;
    cache->num_entries = 0;
    cache->entries = calloc(capacity, sizeof(struct cache_entry *));
    if (cache->entries == NULL) {
        perror("calloc");
        exit(1);
    }
}

// Insert a new key-value pair into the cache
void insert_into_cache(int key, char *value) {
    pthread_mutex_lock(&cache_lock);
    struct cache_entry *new_entry = malloc(sizeof(struct cache_entry));
    if (new_entry == NULL) {
        perror("malloc");
        exit(1);
    }
    new_entry->key = key;
    new_entry->value = value;
    long expiry_time = time(NULL) + 3600; // Expire in one hour
    new_entry->expiry_time = expiry_time;
    struct cache *cache = get_cache();
    if (cache->num_entries == cache->capacity) {
        // Evict the least recently used entry if the cache is full
        int evicted_key = 0;
        long min_expiry_time = expiry_time;
        for (size_t i = 0; i < cache->num_entries; i++) {
            if (cache->entries[i]->expiry_time < min_expiry_time) {
                evicted_key = cache->entries[i]->key;
                min_expiry_time = cache->entries[i]->expiry_time;
            }
        }
        free(cache->entries[evicted_key]);
        cache->num_entries--;
    }
    cache->num_entries++;
    cache->entries[key] = new_entry;
    pthread_mutex_unlock(&cache_lock);
}

// Get a value from the cache by key
char *get_from_cache(int key) {
    struct cache *cache = get_cache();
    if (cache->num_entries == 0) {
        return NULL;
    }
    pthread_mutex_lock(&cache_lock);
    for (size_t i = 0; i < cache->num_entries; i++) {
        if (cache->entries[i]->key == key) {
            char *value = cache->entries[i]->value;
            long expiry_time = cache->entries[i]->expiry_time;
            if (expiry_time < time(NULL)) {
                // Entry has expired, evict it from the cache
                free(cache->entries[key]);
                cache->num_entries--;
            } else {
                return value;
            }
        }
    }
    pthread_mutex_unlock(&cache_lock);
    return NULL;
}

// Update the expiry time of a cache entry
void update_expiry_time(int key, long new_expiry_time) {
    struct cache *cache = get_cache();
    pthread_mutex_lock(&cache_lock);
    for (size_t i = 0; i < cache->num_entries; i++) {
        if (cache->entries[i]->key == key) {
            cache->entries[i]->expiry_time = new_expiry_time;
            break;
        }
    }
    pthread_mutex_unlock(&cache_lock);
}

// Evict all expired entries from the cache
void evict_expired_entries(struct cache *cache) {
    for (size_t i = 0; i < cache->num_entries; i++) {
        if (cache->entries[i]->expiry_time < time(NULL)) {
            free(cache->entries[i]);
            cache->num_entries--;
        }
    }
}

// Close the cache and free all resources
void close_cache() {
    struct cache *cache = get_cache();
    pthread_mutex_lock(&cache_lock);
    for (size_t i = 0; i < cache->num_entries; i++) {
        free(cache->entries[i]);
    }
    free(cache->entries);
    free(cache);
    pthread_mutex_unlock(&cache_lock);
}
```
