// Define the struct for the CRC indication PDU
typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t rx_ue_information_tag; // The tag for the RX UE information
    uint32_t rnti; // The Received Network Temporary Identifier
    uint32_t crc_indication_rel8_tag; // The tag for the CRC indication REL8
    uint8_t crcflag; // The CRC flag
} NFAPI_CRC_INDICATION_PDU_T;

// Define a linked list node for the CRC indications
typedef struct CRC_INDICATION_NODE {
    NFAPI_CRC_INDICATION_PDU_T pdu; // The CRC indication PDU
    struct CRC_INDICATION_NODE* next; // Pointer to the next node in the linked list
} CRC_INDICATION_NODE;

// Define a linked list for the CRC indications
typedef struct {
    CRC_INDICATION_NODE* head; // The head of the linked list
    pthread_mutex_t mutex; // Mutex to protect the linked list
} CRC_INDICATION_LIST;

// Define a thread-safe function for adding a CRC indication to the linked list
void add_crc_indication(CRC_INDICATION_LIST* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->mutex);
    CRC_INDICATION_NODE* node = malloc(sizeof(CRC_INDICATION_NODE));
    if (node == NULL) {
        printf("Error: Out of memory\n");
        return;
    }
    node->pdu = pdu;
    node->next = list->head;
    list->head = node;
    pthread_mutex_unlock(&list->mutex);
}

// Define a thread-safe function for deleting a CRC indication from the linked list
void delete_crc_indication(CRC_INDICATION_LIST* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->mutex);
    CRC_INDICATION_NODE* current = list->head;
    while (current != NULL && current->pdu.rx_ue_information_tag != pdu.rx_ue_information_tag) {
        current = current->next;
    }
    if (current == NULL) {
        printf("Error: CRC indication not found\n");
        return;
    }
    list->head = current->next;
    free(current);
    pthread_mutex_unlock(&list->mutex);
}

// Define a thread-safe function for traversing the linked list of CRC indications
void traverse_crc_indications(CRC_INDICATION_LIST* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T)) {
    pthread_mutex_lock(&list->mutex);
    CRC_INDICATION_NODE* current = list->head;
    while (current != NULL) {
        callback(current->pdu);
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
}
