#include <iostream>
#include <vector>
#include <unordered_map>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <future>
#include <chrono>

using namespace std;

struct ConnectionState {
  int connectionId;
  string remoteAddress;
  long establishedTime;
  long lastActiveTime;
  string status;
};

class ConnectionManager {
public:
  ConnectionManager();
  ~ConnectionManager();

  void addConnection(int connectionId, const string& remoteAddress);
  void updateConnectionStatus(int connectionId, const string& status);
  void removeConnection(int connectionId);

  int getActiveConnectionsCount() const;
  int getOldestConnectionId() const;
  int getNewestConnectionId() const;

private:
  unordered_map<int, ConnectionState> connections_;
  mutex mtx_;
  condition_variable cv_;
};

ConnectionManager::ConnectionManager() {
  // Initialize the connection manager with an empty map.
  connections_.clear();
}

ConnectionManager::~ConnectionManager() {}

void ConnectionManager::addConnection(int connectionId, const string& remoteAddress) {
  // Lock the mutex to ensure thread safety during connection addition.
  unique_lock<mutex> lock(mtx_);

  // Add the new connection to the map.
  connections_.emplace(connectionId, ConnectionState{connectionId, remoteAddress, getCurrentTime(), getCurrentTime(), "NEW"});

  // Notify all threads waiting for a new connection to be added.
  cv_.notify_all();
}

void ConnectionManager::updateConnectionStatus(int connectionId, const string& status) {
  // Lock the mutex to ensure thread safety during connection update.
  unique_lock<mutex> lock(mtx_);

  // Update the connection's status in the map.
  connections_.at(connectionId).status = status;
}

void ConnectionManager::removeConnection(int connectionId) {
  // Lock the mutex to ensure thread safety during connection removal.
  unique_lock<mutex> lock(mtx_);

  // Remove the connection from the map.
  connections_.erase(connectionId);
}

int ConnectionManager::getActiveConnectionsCount() const {
  // Lock the mutex to ensure thread safety during connection count retrieval.
  unique_lock<mutex> lock(mtx_);

  // Return the number of active connections in the map.
  return connections_.size();
}

int ConnectionManager::getOldestConnectionId() const {
  // Lock the mutex to ensure thread safety during oldest connection retrieval.
  unique_lock<mutex> lock(mtx_);

  // Return the ID of the oldest connection in the map.
  return connections_.empty() ? -1 : connections_.begin()->first;
}

int ConnectionManager::getNewestConnectionId() const {
  // Lock the mutex to ensure thread safety during newest connection retrieval.
  unique_lock<mutex> lock(mtx_);

  // Return the ID of the newest connection in the map.
  return connections_.empty() ? -1 : connections_.rbegin()->first;
}

long getCurrentTime() {
  // Returns the current time in milliseconds since epoch.
  return chrono::duration_cast<chrono::milliseconds>(chrono::system_clock::now().time_since_epoch()).count();
}
