import org.eclipse.jetty.websocket.servlet.WebSocketServlet;
import org.eclipse.jetty.websocket.servlet.WebSocketServletFactory;

public class WebSocketServer implements WebSocketCreator {
  private final ExecutorService executor = Executors.newCachedThreadPool();
  private final Set<WebSocket> connections = new CopyOnWriteArraySet<>();

  @Override
  public void configure(WebSocketServletFactory factory) {
    factory.register(this);
  }

  @Override
  public WebSocket createWebSocket(ServletUpgradeRequest request, ServletUpgradeResponse response) {
    return new WebSocketAdapter() {
      @Override
      protected void onOpen(WebSocket websocket) {
        connections.add(websocket);
      }

      @Override
      protected void onClose(WebSocket websocket) {
        connections.remove(websocket);
      }

      @Override
      protected void onMessage(WebSocket websocket, String message) {
        executor.execute(() -> {
          // handle incoming WebSocket message
        });
      }
    };
  }
}
