#define MAX_N 10000 // maximum number of events to process

typedef struct {
    uint16_t rx_ue_information_tag;
    uint32_t rnti;
    uint8_t crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

void generateAndValidateCrcIndications(int n, int *rx_ue_information_tags, int *rntis, bool **crcflaugs) {
    if (n < 0) {
        // error: invalid input parameter "n"
        printf("Error: invalid input parameter \"n\"\n");
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T *crc_indication_pdus = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * n);
    if (crc_indication_pdus == NULL) {
        // error: memory allocation failed
        printf("Error: memory allocation failed\n");
        return;
    }

    for (int i = 0; i < n; ++i) {
        crc_indication_pdus[i].rx_ue_information_tag = rx_ue_information_tags[i];
        crc_indication_pdus[i].rnti = rntis[i];
        crcflaugs[i] = rand() % 2 == 0; // randomly set CRCFLAG to true or false
    }

    bool success = false;
    int retries = 3;
    while (retries-- > 0 && !success) {
        // try validation up to three times with pauses between attempts
        for (int i = 0; i < n; ++i) {
            if (!crc_indication_pdus[i].crflag == crcflaugs[i]) {
                // error: CRCFLAG does not match expected value
                printf("Error: CRCFLAG does not match expected value\n");
                break;
            }
        }
        if (success) {
            break;
        } else {
            printf("Validation failed, pausing for %d seconds before retrying...\n", retries + 1);
            sleep(retries + 1);
        }
    }

    free(crc_indication_pdus);
