using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Caching.Memory;
using Microsoft.Extensions.Logging;
using Newtonsoft.Json;

namespace UEConnectionService
{
    [ApiController]
    [Route("[controller]")]
    public class UEController : ControllerBase
    {
        private readonly IUEService _ueService;
        private readonly ILogger<UEController> _logger;
        private readonly IMemoryCache _memoryCache;

        public UEController(IUEService ueService, ILogger<UEController> logger, IMemoryCache memoryCache)
        {
            _ueService = ueService;
            _logger = logger;
            _memoryCache = memoryCache;
        }

        [HttpGet("{imsi}")]
        public async Task<IActionResult> GetUEStatus(string imsi)
        {
            // Try to retrieve UE status from cache
            var cachedUeStatus = await _memoryCache.GetAsync($"ue-status:{imsi}", CancellationToken.None);
            if (cachedUeStatus != null)
            {
                return Ok(cachedUeStatus);
            }

            // If cache miss, retrieve from UE service and update cache
            var ueStatus = await _ueService.GetUEStatusAsync(imsi);
            await _memoryCache.SetAsync($"ue-status:{imsi}", ueStatus, TimeSpan.FromMinutes(15));
            return Ok(ueStatus);
        }

        [HttpPost("{imsi}/connect")]
        public async Task<IActionResult> ConnectUE([FromRoute] string imsi)
        {
            var connected = await _ueService.ConnectAsync(imsi);
            if (connected)
            {
                return Ok();
            }
            else
            {
                return BadRequest("Failed to connect UE");
            }
        }

        [HttpPost("{imsi}/disconnect")]
        public async Task<IActionResult> DisconnectUE([FromRoute] string imsi)
        {
            var disconnected = await _ueService.DisconnectAsync(imsi);
            if (disconnected)
            {
                return Ok();
            }
            else
            {
                return BadRequest("Failed to disconnect UE");
            }
        }
    }
}
