namespace UEConnectionService.Caching
{
    public class CacheManager : ICacheManager
    {
        private readonly ILogger<CacheManager> _logger;
        private readonly IMemoryCache _memoryCache;
        private readonly IDatabaseContext _databaseContext;
        private readonly IConfiguration _configuration;

        public CacheManager(ILogger<CacheManager> logger, IMemoryCache memoryCache, IDatabaseContext databaseContext, IConfiguration configuration)
        {
            _logger = logger;
            _memoryCache = memoryCache;
            _databaseContext = databaseContext;
            _configuration = configuration;
        }

        public async Task<T> GetAsync<T>(string key) where T : class
        {
            try
            {
                var cache = await _memoryCache.GetOrCreateAsync(key, async (k) =>
                {
                    // Try to retrieve from database
                    var entity = await _databaseContext.Set<T>().FindAsync(k);
                    if (entity != null)
                    {
                        return entity;
                    }
                    else
                    {
                        return null;
                    }
                });
                if (cache != null)
                {
                    return cache as T;
                }
                else
                {
                    throw new Exception("Failed to retrieve data from cache");
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to retrieve data from cache");
                throw;
            }
        }

        public async Task<bool> SetAsync<T>(string key, T value) where T : class
        {
            try
            {
                var cache = await _memoryCache.GetOrCreateAsync(key, (k) =>
                {
                    return value;
                });
                if (cache != null)
                {
                    return true;
                }
                else
                {
                    throw new Exception("Failed to set data in cache");
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to set data in cache");
                throw;
            }
        }
    }
}
