        {
            _logger = logger;
            _configuration = configuration;
        }

        public async Task<TResponse> PostAsync<TRequest, TResponse>(string path, TRequest requestBody) where TRequest : class where TResponse : class
        {
            try
            {
                var baseUrl = _configuration["RestClient:BaseUrl"];
                using (var client = new HttpClient())
                {
                    var url = $"{baseUrl}{path}";
                    var response = await client.PostAsync(url, new StringContent(JsonConvert.SerializeObject(requestBody)));
                    if (response.IsSuccessStatusCode)
                    {
                        var responseBody = await response.Content.ReadAsStringAsync();
                        return JsonConvert.DeserializeObject<TResponse>(responseBody);
                    }
                    else
                    {
                        throw new Exception("Failed to post data");
                    }
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to post data");
                throw;
            }
        }

        public async Task<TResponse> GetAsync<TResponse>(string path) where TResponse : class
        {
            try
            {
                var baseUrl = _configuration["RestClient:BaseUrl"];
                using (var client = new HttpClient())
                {
                    var url = $"{baseUrl}{path}";
                    var response = await client.GetAsync(url);
                    if (response.IsSuccessStatusCode)
                    {
                        var responseBody = await response.Content.ReadAsStringAsync();
                        return JsonConvert.DeserializeObject<TResponse>(responseBody);
                    }
                    else
                    {
                        throw new Exception("Failed to get data");
