  std::mutex mtx;

  // Condition variable to signal when new connections are added or removed
  std::condition_variable cv;

  // List of active connections with associated PDU messages
  std::vector<ConnectionState> connections;

  // Map of UE IDs to indices in the connections list
  std::unordered_map<uint64_t, size_t> ue_id_to_idx;
};

// Implement the constructor for the ConnectionManager class
ConnectionManager::ConnectionManager() {
  // Initialize the mutex and condition variable
  mtx = std::mutex();
  cv = std::condition_variable();

  // Initialize the list of connections and UE ID to index map
  connections = {};
  ue_id_to_idx = {};
}

// Implement the add_connection method for the ConnectionManager class
void ConnectionManager::add_connection(uint64_t ue_id, const std::string& pdu) {
  // Acquire the lock on the mutex
  std::unique_lock<std::mutex> lck(mtx);

  // Create a new connection state and add it to the list
  connections.push_back({ue_id, pdu});

  // Update the UE ID to index map
  ue_id_to_idx[ue_id] = connections.size() - 1;

  // Notify any waiting threads that a new connection has been added
  cv.notify_all();
}

// Implement the remove_connection method for the ConnectionManager class
