  // Acquire the lock on the mutex
  std::unique_lock<std::mutex> lck(mtx);

  // Find the index of the connection with the specified UE ID in the list
  auto it = ue_id_to_idx.find(ue_id);
  if (it != ue_id_to_idx.end()) {
    // Remove the connection state and associated PDU message from the list
    connections.erase(connections.begin() + it->second);

    // Update the UE ID to index map
    ue_id_to_idx.erase(it);
  }

  // Notify any waiting threads that a connection has been removed
  cv.notify_all();
}

// Implement the get_connection method for the ConnectionManager class
ConnectionState ConnectionManager::get_connection(uint64_t ue_id) {
  // Acquire the lock on the mutex
  std::unique_lock<std::mutex> lck(mtx);

  // Find the index of the connection with the specified UE ID in the list
  auto it = ue_id_to_idx.find(ue_id);
  if (it != ue_id_to_idx.end()) {
    return connections[it->second];
  } else {
    // Return an empty connection state if no matching UE ID is found
    ConnectionState empty;
    empty.ue_id = -1;
    empty.pdu = "";
    return empty;
  }
}

// Implement the handle_message method for the ConnectionManager class
void ConnectionManager::handle_message(const std::string& msg) {
  // Acquire the lock on the mutex
  std::unique_lock<std::mutex> lck(mtx);

  // Parse the gRPC message and extract the UE ID and PDU message
  uint64_t ue_id;
  std::string pdu;
  if (!parse_message(msg, &ue_id, &pdu)) {
    // Log an error if the message could not be parsed correctly
    std::cout << "Error parsing gRPC message" << std::endl;
    return;
  }

  // Find the index of the connection with the specified UE ID in the list
  auto it = ue_id_to_idx.find(ue_id);
  if (it != ue_id_to_idx.end()) {
    // Update the PDU message for the found connection state
    connections[it->second].pdu = pdu;

    // Notify any waiting threads that a new PDU message has been received
    cv.notify_all();
  } else {
    // Add a new connection state and associated PDU message if no matching UE ID is found
    add_connection(ue_id, pdu);

    // Notify any waiting threads that a new connection has been added
    cv.notify_all();
  }
}
