    struct list_node* prev;
    struct list_node* next;
    NFAPI_CRC_INDICATION_PDU_T data;
} ListNode;

// Doubly Linked List structure for managing collection of NFAPI_CRC_INDICATION_PDU_T instances
typedef struct {
    ListNode* head;
    ListNode* tail;
    size_t num_elements;
    pthread_mutex_t lock; // Fine-grained locks for thread safety
} DoublyLinkedList;

// Initializes a new Doubly Linked List with a given capacity.
void InitializeDoublyLinkedList(DoublyLinkedList* list, size_t capacity) {
    if (list == NULL || capacity < 1) {
        return;
    }

    list->head = (ListNode*)malloc(sizeof(ListNode));
    list->tail = (ListNode*)malloc(sizeof(ListNode));
    list->num_elements = 0;
    pthread_mutex_init(&list->lock, NULL); // Initialize fine-grained locks for thread safety

    list->head->prev = NULL;
    list->head->next = list->tail;
    list->head->data = (NFAPI_CRC_INDICATION_PDU_T){0};

    list->tail->prev = list->head;
    list->tail->next = NULL;
    list->tail->data = (NFAPI_CRC_INDICATION_PDU_T){0};
}

// Inserts a new NFAPI_CRC_INDICATION_PDU_T instance into the Doubly Linked List.
void Insert(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (list == NULL || data.RNTI == NULL || data.CRC_INDICATION < 0) {
        return;
    }

    pthread_mutex_lock(&list->lock); // Acquire fine-grained lock for thread safety

    ListNode* node = (ListNode*)malloc(sizeof(ListNode));
    node->data = data;

    if (list->head == NULL || list->tail == NULL) {
        // List is empty, insert as head and tail
        node->prev = NULL;
        node->next = NULL;

        list->head = node;
        list->tail = node;
    } else {
        // Insert at tail
        ListNode* current_tail = list->tail;
        ListNode* next_node = (ListNode*)malloc(sizeof(ListNode));

        next_node->data = (NFAPI_CRC_INDICATION_PDU_T){0};
        next_node->prev = current_tail;
        next_node->next = NULL;

        list->tail = next_node;
        current_tail->next = next_node;
    }

    pthread_mutex_unlock(&list->lock); // Release fine-grained lock
}

// Deletes a NFAPI_CRC_INDICATION_PDU_T instance from the Doubly Linked List.
void Delete(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (list == NULL || data.RNTI == NULL || data.CRC_INDICATION < 0) {
        return;
    }

    pthread_mutex_lock(&list->lock); // Acquire fine-grained lock for thread safety

    ListNode* current_node = list->head;
    while (current_node != NULL) {
        if (strcmp(data.RNTI, current_node->data.RNTI) == 0 && data.CRC_INDICATION == current_node->data.CRC_INDICATION) {
            // Found node to delete, remove from list
            ListNode* prev_node = current_node->prev;
            ListNode* next_node = current_node->next;

            if (prev_node != NULL && next_node != NULL) {
                // Node has a predecessor and successor, update links
                prev_node->next = next_node;
                next_node->prev = prev_node;

                free(current_node);
                current_node = next_node;
            } else if (prev_node == NULL && next_node != NULL) {
                // Node is the head, update head and remove link to successor
                list->head = next_node;
                free(current_node);
                current_node = next_node;
            } else if (prev_node != NULL && next_node == NULL) {
                // Node is the tail, update tail and remove link to predecessor
                list->tail = prev_node;
                free(current_node);
                current_node = prev_node;
            } else {
                // Node is both head and tail, clear list
                list->head = NULL;
                list->tail = NULL;

                free(current_node);
                current_node = NULL;
            }
        }

        current_node = current_node->next;
    }

    pthread_mutex_unlock(&list->lock); // Release fine-grained lock
}

// Returns the number of NFAPI_CRC_INDICATION_PDU instances in the Doubly Linked List.
size_t Size(DoublyLinkedList* list) {
    if (list == NULL) {
        return 0;
    }

    pthread_mutex_lock(&list->lock); // Acquire fine-grained lock for thread safety

    size_t num_elements = list->num_elements;

    pthread_mutex_unlock(&list->lock); // Release fine-grained lock

    return num_elements;
}

// Prints all NFAPI_CRC_INDICATION_PDU instances in the Doubly Linked List.
void Print(DoublyLinkedList* list) {
    if (list == NULL) {
        return;
    }

    pthread_mutex_lock(&list->lock); // Acquire fine-grained lock for thread safety

    ListNode* current_node = list->head;
    while (current_node != NULL) {
        printf("%d ", current_node->data.CRC_INDICATION);
        current_node = current_node->next;
    }

    pthread_mutex_unlock(&list->lock); // Release fine-grained lock
}
