        return pdu;
    } else {
        // Release the mutex and return early to avoid overwriting existing PDUs
        pthread_mutex_unlock(&pdu_table_lock);
        return NULL;
    }
}

// Check if a given sequence number is valid for adding or updating a PDCP PDU
int check_sn(int sn) {
    // Acquire the mutex to ensure thread-safe access to the PDU table
    pthread_mutex_lock(&pdu_table_lock);

    // Check if the requested sequence number is valid
    if (sn >= 0 && sn < MAX_NUM_PDCP_PDU) {
        // Return true if the requested sequence number is valid
        pthread_mutex_unlock(&pdu_table_lock);
        return 1;
    } else {
        // Release the mutex and return false to avoid overwriting existing PDUs
        pthread_mutex_unlock(&pdu_table_lock);
        return 0;
    }
}

// Check if a given sequence number is valid for deleting a PDCP PDU
int check_sn_del(int sn) {
    // Acquire the mutex to ensure thread-safe access to the PDU table
    pthread_mutex_lock(&pdu_table_lock);

    // Check if the requested sequence number is valid for deletion
    if (sn >= 0 && sn < MAX_NUM_PDCP_PDU) {
        // Return true if the requested sequence number is valid for deletion
        pthread_mutex_unlock(&pdu_table_lock);
        return 1;
    } else {
        // Release the mutex and return false to avoid overwriting existing PDUs
        pthread_mutex_unlock(&pdu_table_lock);
        return 0;
    }
}

// Get the number of PDCP PDUs in the library's main data structure
int num_PDCP_PDUs() {
    // Acquire the mutex to ensure thread-safe access to the PDU table
    pthread_mutex_lock(&pdu_table_lock);

    // Count the number of non-NULL elements in the library's main data structure
    int count = 0;
    for (int i = 0; i < MAX_NUM_PDCP_PDU; i++) {
        if (pdu_table[i] != NULL) {
            count++;
        }
    }

    // Release the mutex and return the number of PDCP PDUs
    pthread_mutex_unlock(&pdu_table_lock);
    return count;
}']

