// Define the data structures for LTE PDCP PDUs and key-value pairs
typedef struct {
    char *data;
    size_t size;
} LTE_PDCP_PDU_T;

typedef struct {
    int key;
    char *value;
} KeyValuePair;

// Define the collection of LTE PDCP PDUs and key-value pairs
struct PduCollection {
    size_t num_pdus;
    LTE_PDCP_PDU_T *pdu_list;
    size_t num_kvps;
    KeyValuePair *kvp_list;
};

// Define the locking mechanisms for protecting the collection
semaphore_t pdu_collection_lock;
semaphore_t kvp_collection_lock;

// Define the function to add a new LTE PDCP PDU to the collection
int ltecommlib_add_pdus(struct PduCollection *coll, size_t num_pdus, LTE_PDCP_PDU_T *pdu_list) {
    // Lock the collection before modifying it
    semaphore_wait(&pdu_collection_lock);

    // Add the new PDUS to the collection
    coll->num_pdus += num_pdus;
    if (coll->num_pdus > 0) {
        coll->pdu_list = realloc(coll->pdu_list, coll->num_pdus * sizeof(*coll->pdu_list));
        memcpy(&coll->pdu_list[coll->num_pdus - num_pdus], pdu_list, num_pdus * sizeof(*pdu_list));
    }

    // Unlock the collection after modifying it
    semaphore_post(&pdu_collection_lock);
}

// Define the function to add a new key-value pair to the collection
int ltecommlib_add_kvps(struct PduCollection *coll, size_t num_kvps, KeyValuePair *kvp_list) {
    // Lock the collection before modifying it
    semaphore_wait(&kvp_collection_lock);

    // Add the new key-value pairs to the collection
    coll->num_kvps += num_kvps;
    if (coll->num_kvps > 0) {
        coll->kvp_list = realloc(coll->kvp_list, coll->num_kvps * sizeof(*coll->kvp_list));
        memcpy(&coll->kvp_list[coll->num_kvps - num_kvps], kvp_list, num_kvps * sizeof(*kvp_list));
    }

    // Unlock the collection after modifying it
    semaphore_post(&kvp_collection_lock);
}

// Define the function to update an existing LTE PDCP PDU in the collection
int ltecommlib_update_pdus(struct PduCollection *coll, size_t num_pdus, LTE_PDCP_PDU_T *pdu_list) {
    // Lock the collection before modifying it
    semaphore_wait(&pdu_collection_lock);

    // Update the existing PDUS in the collection
    for (size_t i = 0; i < num_pdus; ++i) {
        bool found = false;
        for (size_t j = 0; j < coll->num_pdus; ++j) {
            if (coll->pdu_list[j].key == pdu_list[i].key) {
                memcpy(&coll->pdu_list[j], &pdu_list[i], sizeof(*coll->pdu_list));
                found = true;
                break;
            }
        }
        if (!found) {
            printf("Failed to update PDCP PDU with key %d\n", pdu_list[i].key);
        }
    }

    // Unlock the collection after modifying it
    semaphore_post(&pdu_collection_lock);
}

// Define the function to delete an existing LTE PDCP PDU from the collection
int ltecommlib_delete_pdus(struct PduCollection *coll, size_t num_keys) {
    // Lock the collection before modifying it
    semaphore_wait(&pdu_collection_lock);

    // Delete the existing PDUS from the collection
    for (size_t i = 0; i < num_keys; ++i) {
        bool found = false;
        for (size_t j = 0; j < coll->num_pdus; ++j) {
            if (coll->pdu_list[j].key == keys[i]) {
                memmove(&coll->pdu_list[j], &coll->pdu_list[j + 1], (coll->num_pdus - j - 1) * sizeof(*coll->pdu_list));
                coll->num_pdus--;
                found = true;
                break;
            }
        }
        if (!found) {
            printf("Failed to delete PDCP PDU with key %d\n", keys[i]);
        }
    }

    // Unlock the collection after modifying it
    semaphore_post(&pdu_collection_lock);
}
