#include <vector>
#include <unordered_map>
#include <string>
#include <chrono>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <atomic>

// Define a struct to represent a connection state
struct ConnectionState {
    int connectionId;
    std::string remoteAddress;
    std::chrono::time_point<std::chrono::system_clock> establishedTime, lastActiveTime;
    bool status;
};

// Define a class to manage the collection of connection states
class ConnectionManager {
private:
    // Use a vector to store the connections in chronological order by their establishment time
    std::vector<ConnectionState> connections;

    // Use an unordered_map to quickly look up the status of a connection based on its ID
    std::unordered_map<int, bool> connectionStatuses;

    // Mutex and condition variable for synchronizing access to the connections vector and updating the connection statuses map
    std::mutex mtx;
    std::condition_variable cv;

    // Atomic variables for tracking the total number of active connections and the oldest and newest connection IDs
    std::atomic<int> numActiveConnections;
    std::atomic<int> oldestConnectionId, newestConnectionId;

public:
    ConnectionManager() : numActiveConnections(0), oldestConnectionId(-1), newestConnectionId(-1) {}

    // Add a new connection to the collection of connections and update the status map
    void addConnection(const int connectionId, const std::string& remoteAddress) {
        mtx.lock();
        ConnectionState state = {connectionId, remoteAddress, std::chrono::system_clock::now(), std::chrono::system_clock::now(), true};
        connections.push_back(state);
        connectionStatuses[connectionId] = true;
        numActiveConnections++;
        if (oldestConnectionId == -1 || oldestConnectionId > connectionId) {
            oldestConnectionId = connectionId;
        }
        newestConnectionId = connectionId;
        mtx.unlock();
    }

    // Remove a connection from the collection of connections and update the status map
    void removeConnection(const int connectionId) {
        mtx.lock();
        auto it = std::find_if(connections.begin(), connections.end(), [connectionId](const ConnectionState& state) { return state.connectionId == connectionId; });
        if (it != connections.end()) {
            // Update the status map
            connectionStatuses[connectionId] = false;
            numActiveConnections--;
            // Remove the connection from the vector
            connections.erase(it);
        }
        mtx.unlock();
    }

    // Return a copy of the connection state for a given ID
    ConnectionState getConnectionState(const int connectionId) {
        mtx.lock();
        auto it = std::find_if(connections.begin(), connections.end(), [connectionId](const ConnectionState& state) { return state.connectionId == connectionId; });
        if (it != connections.end()) {
            mtx.unlock();
            return *it;
        } else {
            mtx.unlock();
            return {};
        }
    }

    // Update the status of a connection based on an external API response
    void updateConnectionStatus(const int connectionId, const bool status) {
        mtx.lock();
        auto it = std::find_if(connections.begin(), connections.end(), [connectionId](const ConnectionState& state) { return state.connectionId == connectionId; });
        if (it != connections.end()) {
            // Update the status in both the vector and the map
            it->status = status;
            connectionStatuses[connectionId] = status;
        }
        mtx.unlock();
    }

    // Return a copy of the status of a given connection ID
    bool getConnectionStatus(const int connectionId) {
        mtx.lock();
        auto it = std::find_if(connections.begin(), connections.end(), [connectionId](const ConnectionState& state) { return state.connectionId == connectionId; });
        if (it != connections.end()) {
            mtx.unlock();
            return it->status;
        } else {
            mtx.unlock();
            return false;
        }
    }

    // Return the total number of active connections
    int getNumActiveConnections() {
        mtx.lock();
        int num = numActiveConnections;
        mtx.unlock();
        return num;
    }

    // Return a copy of the oldest connection ID
    int getOldestConnectionId() {
        mtx.lock();
        int id = oldestConnectionId;
        mtx.unlock();
        return id;
    }

    // Return a copy of the newest connection ID
    int getNewestConnectionId() {
        mtx.lock();
        int id = newestConnectionId;
        mtx.unlock();
        return id;
    }

    // Return a copy of all active connections
    std::vector<ConnectionState> getActiveConnections() {
        std::vector<ConnectionState> states;
        mtx.lock();
        for (auto it = connections.begin(); it != connections.end(); ++it) {
            if (it->status == true) {
                states.push_back(*it);
            }
        }
        mtx.unlock();
        return states;
    }
};']

