using System;
using System.Threading.Tasks;

namespace DynamicRandomValueGenerator
{
    public class RandomGeneratorSettings
    {
        private readonly int _seed = 0;
        private readonly DistributionType _distributionType = DistributionType.Uniform;
        private readonly float _minimumBound = 0f;
        private readonly float _maximumBound = 1f;
        private readonly bool _adaptiveSampling = true;
        private readonly int _fallbackInterval = 5000; // 5 seconds

        public RandomGeneratorSettings(int seed, DistributionType distributionType, float minimumBound, float maximumBound)
        {
            _seed = seed;
            _distributionType = distributionType;
            _minimumBound = minimumBound;
            _maximumBound = maximumBound;
        }

        public int Seed => _seed;
        public DistributionType DistributionType => _distributionType;
        public float MinimumBound => _minimumBound;
        public float MaximumBound => _maximumBound;
        public bool AdaptiveSampling => _adaptiveSampling;
        public int FallbackInterval => _fallbackInterval;
    }

    public class DynamicRandomGenerator : IDisposable
    {
        private readonly RandomGeneratorSettings _settings;
        private readonly IExternalDataService _externalDataService;
        private readonly ILogger _logger;

        public DynamicRandomGenerator(RandomGeneratorSettings settings, IExternalDataService externalDataService, ILogger logger)
        {
            _settings = settings;
            _externalDataService = externalDataService;
            _logger = logger;
        }

        public async Task<float> GenerateFloat()
        {
            try
            {
                float value = await _externalDataService.GetRandomValueAsync(_settings.Seed, _settings.DistributionType);
                return value;
            }
            catch (Exception ex) when (ex is NetworkException || ex is TimeoutException)
            {
                if (_settings.AdaptiveSampling && _externalDataService.IsAdaptable)
                {
                    // fallback to local random generation
                    float value = await GenerateFloat();
                    return value;
                }
                else
                {
                    throw ex;
                }
            }
        }

        public async Task<int> GenerateInt()
        {
            try
            {
                int value = await _externalDataService.GetRandomValueAsync(_settings.Seed, _settings.DistributionType);
                return value;
            }
            catch (Exception ex) when (ex is NetworkException || ex is TimeoutException)
            {
                if (_settings.AdaptiveSampling && _externalDataService.IsAdaptable)
                {
                    // fallback to local random generation
                    int value = await GenerateInt();
                    return value;
                }
                else
                {
                    throw ex;
                }
            }
        }

        public async Task<T> GenerateCustomType<T>() where T : struct
        {
            try
            {
                T value = await _externalDataService.GetRandomValueAsync(_settings.Seed, _settings.DistributionType);
                return value;
            }
            catch (Exception ex) when (ex is NetworkException || ex is TimeoutException)
            {
                if (_settings.AdaptiveSampling && _externalDataService.IsAdaptable)
                {
                    // fallback to local random generation
                    T value = await GenerateCustomType<T>();
                    return value;
                }
                else
                {
                    throw ex;
                }
            }
        }

        public async Task<float[]> GenerateFloatCollection(int count)
        {
            try
            {
                float[] values = await _externalDataService.GetRandomValuesAsync(_settings.Seed, _settings.DistributionType, count);
                return values;
            }
            catch (Exception ex) when (ex is NetworkException || ex is TimeoutException)
            {
                if (_settings.AdaptiveSampling && _externalDataService.IsAdaptable)
                {
                    // fallback to local random generation
                    float[] values = await GenerateFloatCollection(count);
                    return values;
                }
                else
                {
                    throw ex;
                }
            }
        }

        public async Task<int[]> GenerateIntCollection(int count)
        {
            try
            {
                int[] values = await _externalDataService.GetRandomValuesAsync(_settings.Seed, _settings.DistributionType, count);
                return values;
            }
            catch (Exception ex) when (ex is NetworkException || ex is TimeoutException)
            {
                if (_settings.AdaptiveSampling && _externalDataService.IsAdaptable)
                {
                    // fallback to local random generation
                    int[] values = await GenerateIntCollection(count);
                    return values;
                }
                else
                {
                    throw ex;
                }
            }
        }

        public async Task<T[]> GenerateCustomTypeCollection<T>(int count) where T : struct
        {
            try
            {
                T[] values = await _externalDataService.GetRandomValuesAsync(_settings.Seed, _settings.DistributionType, count);
                return values;
            }
            catch (Exception ex) when (ex is NetworkException || ex is TimeoutException)
            {
                if (_settings.AdaptiveSampling && _externalDataService.IsAdaptable)
                {
                    // fallback to local random generation
                    T[] values = await GenerateCustomTypeCollection<T>(count);
                    return values;
                }
                else
                {
                    throw ex;
                }
            }
        }

        public void Dispose()
        {
            _externalDataService.Dispose();
        }
    }

    public class ExternalDataService : IDisposable
    {
        private readonly RandomGeneratorSettings _settings;
        private readonly HttpClient _httpClient;

        public ExternalDataService(RandomGeneratorSettings settings)
        {
            _settings = settings;
            _httpClient = new HttpClient();
        }

        public async Task<float> GetRandomValueAsync()
        {
            string url = $"https://random-data-api.com/api/random_number?min={_settings.Min}&max={_settings.Max}";
            var response = await _httpClient.GetAsync(url);
            response.EnsureSuccessStatusCode();
            return await response.Content.ReadAsAsync<float>();
        }

        public async Task<int> GetRandomValueAsync()
        {
            string url = $"https://random-data-api.com/api/random_number?min={_settings.Min}&max={_settings.Max}";
            var response = await _httpClient.GetAsync(url);
            response.EnsureSuccessStatusCode();
            return await response.Content.ReadAsAsync<int>();
        }

        public async Task<T> GetRandomValueAsync<T>() where T : struct
        {
            string url = $"https://random-data-api.com/api/random_number?min={_settings.Min}&max={_settings.Max}";
            var response = await _httpClient.GetAsync(url);
            response.EnsureSuccessStatusCode();
            return await response.Content.ReadAsAsync<T>();
        }

        public async Task<float[]> GetRandomValuesAsync(int count)
        {
            string url = $"https://random-data-api.com/api/random_numbers?count={count}&min={_settings.Min}&max={_settings.Max}";
            var response = await _httpClient.GetAsync(url);
            response.EnsureSuccessStatusCode();
            return await response.Content.ReadAsAsync<float[]>();
        }

        public async Task<int[]> GetRandomValuesAsync(int count)
        {
            string url = $"https://random-data-api.com/api/random_numbers?count={count}&min={_settings.Min}&max={_settings.Max}";
            var response = await _httpClient.GetAsync(url);
            response.EnsureSuccessStatusCode();
            return await response.Content.ReadAsAsync<int[]>();
        }

        public async Task<T[]> GetRandomValuesAsync<T>(int count) where T : struct
        {
            string url = $"https://random-data-api.com/api/random_numbers?count={count}&min={_settings.Min}&max={_settings.Max}";
            var response = await _httpClient.GetAsync(url);
            response.EnsureSuccessStatusCode();
            return await response.Content.ReadAsAsync<T[]>();
        }

        public bool IsAdaptable => true;

        public void Dispose()
        {
            _httpClient.Dispose();
        }
    }
}
