#define MAX_CACHE_SIZE 1024 // Default cache size
#define CRC_INDICATION_REL8_TAG 1
#define RX_UE_INFORMATION_TAG 2
#define RNTI_TAG 3
#define NFAPI_CRC_INDICATION_PDU_T_STRUCT_SIZE sizeof(NFAPI_CRC_INDICATION_PDU_T)
typedef struct {
    pthread_t thread;
    sem_t* sem;
} worker_data_t;

typedef struct {
    uint32_t size; // array size
    NFAPI_CRC_INDICATION_PDU_T* buffers[MAX_CACHE_SIZE];
    uint16_t head; // head of the buffer
    uint16_t tail; // tail of the buffer
} buffer_t;

typedef struct {
    pthread_mutex_t mutex; // mutex for protecting shared data structures
    int cache_size; // size of the cache
    buffer_t* buffers[MAX_CACHE_SIZE]; // array of buffers
} crcindication_t;

void init(crcindication_t* crcindication) {
    assert(crcindication != NULL);
    memset(crcindication, 0, sizeof(*crcindication));
    pthread_mutex_init(&crcindication->mutex, NULL);
}

int insert_item(crcindication_t* crcindication, NFAPI_CRC_INDICATION_PDU_T* item) {
    assert(crcindication != NULL);
    assert(item != NULL);
    pthread_mutex_lock(&crcindication->mutex);
    buffer_t* buffers = crcindication->buffers[item->RNTI];
    if (buffers == NULL) {
        printf("Insufficient RNTI availability\n");
        pthread_mutex_unlock(&crcindication->mutex);
        return -1;
    }
    buffers->tail = (buffers->tail + 1) % crcindication->cache_size;
    NFAPI_CRC_INDICATION_PDU_T* buff = buffers->buffers[buffers->tail];
    memcpy(buff, item, sizeof(*item));
    pthread_mutex_unlock(&crcindication->mutex);
}

void clear_cache(crcindication_t* crcindication) {
    assert(crcindication != NULL);
    pthread_mutex_lock(&crcindication->mutex);
    for (int i = 0; i < MAX_CACHE_SIZE; ++i) {
        buffer_t* buffers = crcindication->buffers[i];
        if (buffers == NULL) continue;
        free(buffers);
    }
    pthread_mutex_unlock(&crcindication->mutex);
}
