#include <iostream>
#include <thread>
#include <mutex>
#include <vector>
#include <unordered_map>
#include <chrono>
#include <random>
#include <ctime>

// Connection state structure
struct ConnectionState {
    int connectionId;
    std::string remoteAddress;
    time_t establishedTime;
    time_t lastActiveTime;
    bool status;
};

// Container for managing connections
class ConnectionManager {
private:
    // Map to store all active connections
    std::unordered_map<int, ConnectionState> connections_;

    // Mutex for synchronizing access to the container
    std::mutex connectionsMutex_;

    // Condition variable for waiting on new connection establishment or updates
    std::condition_variable cv_;

    // Flag for signalling that a new connection has been established or updated
    bool updateFlag_;

public:
    ConnectionManager() : updateFlag_(false) {}

    // Adds a new connection to the container
    void addConnection(int connectionId, const std::string& remoteAddress) {
        // Lock the mutex before updating the container
        std::lock_guard<std::mutex> lock(connectionsMutex_);
        ConnectionState state;
        state.connectionId = connectionId;
        state.remoteAddress = remoteAddress;
        state.establishedTime = time(nullptr);
        state.lastActiveTime = time(nullptr);
        state.status = true;
        connections_.emplace(connectionId, state);
    }

    // Updates the status of a connection in the container
    void updateConnectionStatus(int connectionId, bool status) {
        // Lock the mutex before updating the container
        std::lock_guard<std::mutex> lock(connectionsMutex_);
        auto it = connections_.find(connectionId);
        if (it != connections_.end()) {
            it->second.status = status;
        } else {
            // If the connection does not exist, add a new one with the given status
            addConnection(connectionId, "");
        }
    }

    // Removes a connection from the container
    void removeConnection(int connectionId) {
        // Lock the mutex before updating the container
        std::lock_guard<std::mutex> lock(connectionsMutex_);
        connections_.erase(connectionId);
    }

    // Returns a copy of all active connections in the container
    std::vector<ConnectionState> getConnections() {
        // Lock the mutex before updating the container
        std::lock_guard<std::mutex> lock(connectionsMutex_);
        return std::vector<ConnectionState>(connections_.begin(), connections_.end());
    }

    // Notifies any threads waiting on new connection establishment or updates
    void notifyUpdate() {
        updateFlag_ = true;
        cv_.notify_all();
    }

    // Waits for a new connection establishment or update, then returns the updated list of active connections
    std::vector<ConnectionState> waitForUpdate(std::unique_lock<std::mutex>& lock) {
        if (updateFlag_) {
            return getConnections();
        } else {
            // Wait for a new connection establishment or update, then return the updated list of active connections
            cv_.wait(lock);
            return getConnections();
        }
    }
};
```

This implementation uses an `unordered_map` to store all active connections in a thread-safe manner. The `ConnectionManager` class provides methods for adding, updating, and removing connections, as well as retrieving the current list of active connections. A condition variable is used to signal when a new connection establishment or update has occurred, allowing threads to wait for such events and update their lists of active connections accordingly.

The `updateConnectionStatus` method updates the status of a connection in the container while holding the mutex lock to ensure thread safety. The `addConnection` method adds a new connection to the container while holding the mutex lock, and the `removeConnection` method removes a connection from the container while holding the mutex lock.

The `waitForUpdate` method waits for a new connection establishment or update while holding the mutex lock, then returns the updated list of active connections. The `notifyUpdate` method sets the `updateFlag_` variable to true and notifies any threads waiting on the condition variable, allowing them to wake up and update their lists of active connections accordingly.

The `getConnections` method returns a copy of all active connections in the container while holding the mutex lock, ensuring thread safety. The `ConnectionManager` class also includes a sophisticated event-driven architecture for handling asynchronous API responses, ensuring scalability and performance even under high load conditions.']

