#include <iostream>
#include <vector>
#include <string>
#include <mutex>
#include <condition_variable>
#include <thread>

class SecureRandomGenerator {
public:
    // Constructor
    SecureRandomGenerator(int seed = 1, int range = 100) : _seed(seed), _range(range) {}

    // Generate a random number within the specified range
    int generate() {
        std::lock_guard<std::mutex> lock(_mtx);
        _mersenneTwister.seed(_seed);
        return (_mersenneTwister() % _range) + 1;
    }

private:
    // Mersenne Twister algorithm
    std::mt19937_64 _mersenneTwister;

    // Seed value and range bounds
    int _seed, _range;

    // Mutex for concurrent access
    std::mutex _mtx;
};
