Here is the code for the secure OAuth 2.0 authentication service in Python:
```
import json
import os
from typing import Dict

class AuthService:
    def __init__(self):
        self._users = {}
        self._tokens = {}
        self._token_duration = 3600 # 1 hour
        self._auth_path = "/auth"
        self._refresh_path = "/refresh"
        self._logout_path = "/logout"

    def authenticate(self, username: str, password: str) -> bool:
        user = self._users.get(username)
        if user is None or not user.check_password(password):
            return False

        token = "".join([chr(ord('a') + (random() % 26)) for _ in range(32)])
        self._tokens[token] = username

        return True

    def get_user(self, token: str) -> Dict[str, any]:
        if token not in self._tokens:
            raise Exception("Invalid token")

        user = self._users.get(self._tokens[token])
        if user is None:
            raise Exception("User does not exist")

        return {
            "username": user.username,
            "password": user.password,
            "token": token,
            "expires_at": time() + self._token_duration
        }

    def refresh(self, token: str) -> Dict[str, any]:
        if token not in self._tokens:
            raise Exception("Invalid token")

        user = self._users.get(self._tokens[token])
        if user is None:
            raise Exception("User does not exist")

        new_token = "".join([chr(ord('a') + (random() % 26)) for _ in range(32)])
        self._tokens[new_token] = user.username

        return {
            "username": user.username,
            "password": user.password,
            "token": new_token,
            "expires_at": time() + self._token_duration
        }

    def logout(self, token: str) -> bool:
        if token not in self._tokens:
            raise Exception("Invalid token")

        del self._tokens[token]

        return True

class User:
    def __init__(self, username: str, password: str):
        self.username = username
        self.password = password

    def check_password(self, password: str) -> bool:
        return password == self.password
