use std::thread;
use std::time::Instant;
use std::sync::{Arc, Mutex};
use tokio::runtime::Runtime;
use tokio::time::sleep;
use log4rs;
use blueslip;

struct TestRunner {
    module_name: String,
    test_suite: Vec<TestCase>,
    api_endpoints: HashMap<String, String>,
    max_parallel_tests: usize,
}

impl TestRunner {
    fn new(module_name: String, test_suite: Vec<TestCase>, api_endpoints: HashMap<String, String>, max_parallel_tests: usize) -> Self {
        Self {
            module_name,
            test_suite,
            api_endpoints,
            max_parallel_tests,
        }
    }

    async fn run_test(&self, test_case: TestCase) -> Result<(), anyhow::Error> {
        let start = Instant::now();
        let result = self.execute_test(test_case).await?;
        blueslip::info!("Test completed in {:?}", start.elapsed());
        Ok(result)
    }

    async fn execute_test(&self, test_case: TestCase) -> Result<(), anyhow::Error> {
        let api_endpoint = self.api_endpoints.get(&test_case.api).unwrap();
        let result = call_api(api_endpoint);
        match result {
            Ok(response) => {
                blueslip::info!("API response: {:?}", response);
                if response.status == 200 {
                    self.execute_test_case(&test_case).await?;
                } else {
                    anyhow::bail!("Unexpected status code: {}", response.status);
                }
            }
            Err(error) => {
                blueslip::error!("API call failed with error: {:?}", error);
                self.retry_test(&test_case).await?;
            }
        }
    }

    async fn retry_test(&self, test_case: &TestCase) -> Result<(), anyhow::Error> {
        let api_endpoint = self.api_endpoints.get(&test_case.api).unwrap();
        let result = call_api(api_endpoint);
        match result {
            Ok(response) => {
                blueslip::info!("API response: {:?}", response);
                if response.status == 200 {
                    self.execute_test_case(&test_case).await?;
                } else {
                    anyhow::bail!("Unexpected status code: {}", response.status);
                }
            }
            Err(error) => {
                blueslip::error!("API call failed with error: {:?}", error);
                self.retry_test(&test_case).await?;
            }
        }
    }

    async fn execute_test_case(&self, test_case: &TestCase) -> Result<(), anyhow::Error> {
        let api_endpoint = self.api_endpoints.get(&test_case.api).unwrap();
        let result = call_api(api_endpoint);
        match result {
            Ok(response) => {
                blueslip::info!("API response: {:?}", response);
                if response.status == 200 {
                    self.execute_test_case(&test_case).await?;
                } else {
                    anyhow::bail!("Unexpected status code: {}", response.status);
                }
            }
            Err(error) => {
                blueslip::error!("API call failed with error: {:?}", error);
                self.retry_test(&test_case).await?;
            }
        }
    }
}

struct TestCase {
    name: String,
    api: String,
    params: HashMap<String, String>,
}

impl TestCase {
    fn new(name: String, api: String, params: HashMap<String, String>) -> Self {
        Self {
            name,
            api,
            params,
        }
    }
}

fn main() -> Result<(), anyhow::Error> {
    let mut rt = Runtime::new().unwrap();
    let module_name = "module1".to_string();
    let test_suite: Vec<TestCase> = vec![
        TestCase::new("test1".to_string(), "api1".to_string(), HashMap::new()),
        TestCase::new("test2".to_string(), "api2".to_string(), HashMap::new()),
    ];
    let api_endpoints: HashMap<String, String> = vec![
        ("api1".to_string(), "http://localhost:8080".to_string()),
        ("api2".to_string(), "http://localhost:8081".to_string()),
    ]
    .into_iter()
    .collect();
    let max_parallel_tests = 5;

    let test_runner = TestRunner::new(module_name, test_suite, api_endpoints, max_parallel_tests);
    rt.block_on(test_runner.run())?;
}
