// Set up the backpressure mechanism
const BackPressure = (config) => {
  const { rate, burstSize } = config;
  let counter = 0;
  let throttle = false;

  // Check if we need to throttle or not
  function checkThrottle() {
    if (counter >= rate) {
      throttle = true;
      return true;
    } else {
      throttle = false;
      return false;
    }
  }

  // Increment the counter and check for throttling
  function incrementCounter() {
    if (throttle) {
      // Wait until the counter resets
      while (throttle) {
        await sleep(100);
      }
    }
    counter++;
  }

  // Sleep for a given amount of time
  function sleep(ms) {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }

  // Return the checkThrottle and incrementCounter functions
  return { checkThrottle, incrementCounter };
};

// Set up the storage mechanism
const Storage = (config) => {
  const { bucket } = config;
  let uploading = false;

  // Check if we're currently uploading data
  function isUploading() {
    return uploading;
  }

  // Set the uploading flag to true
  function setUploading(value) {
    uploading = value;
  }

  // Upload the data to cloud storage
  async function upload(data, metadata) {
    if (isUploading()) {
      // Wait until the current upload finishes
      while (isUploading()) {
        await sleep(100);
      }
    }

    setUploading(true);
    try {
      const response = await axios.put(`https://storage.googleapis.com/${bucket}`, data, metadata);
      if (response.status === 200) {
        console.log('Data uploaded successfully');
      } else {
        console.error(`Upload failed with status code ${response.status}`);
      }
    } catch (err) {
      console.error(err);
    } finally {
      setUploading(false);
    }
  }

  // Sleep for a given amount of time
  function sleep(ms) {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }

  // Return the isUploading and upload functions
  return { isUploading, upload };
};

