import logging
from multiprocessing import Pool
import time
import threading

class LogAggregator:
    def __init__(self):
        self.semaphore = threading.Semaphore(1)

    def aggregate_logs(self, log_files):
        # Extract the latest log entry per unique IP address from the given list of log files
        aggregated_logs = {}
        for file in log_files:
            with open(file, "r") as f:
                for line in f.readlines():
                    data = json.loads(line)
                    ip_address = data["ip_address"]
                    timestamp = data["timestamp"]
                    service_name = data["service_name"]
                    log_level = data["log_level"]

                    if ip_address not in aggregated_logs:
                        # No previous entry for this IP address, add a new one
                        aggregated_logs[ip_address] = {
                            "timestamp": timestamp,
                            "service_name": service_name,
                            "log_level": log_level
                        }
                    else:
                        # There is already an entry for this IP address, check if it's older than the current one
                        previous_timestamp = aggregated_logs[ip_address]["timestamp"]
                        if timestamp > previous_timestamp:
                            # Update the existing entry with the new timestamp and log level
                            aggregated_logs[ip_address]["timestamp"] = timestamp
                            aggregated_logs[ip_address]["log_level"] = log_level

        return aggregated_logs

    def process_log_file(self, file):
        # Parse the log file and extract the latest log entry per unique IP address
        try:
            with self.semaphore:
                logs = self.aggregate_logs([file])
                for ip_address, data in logs.items():
                    # Log the aggregated data to a third-party logging service if necessary
                    pass
        except Exception as e:
            logging.error(f"Error processing log file {file}: {e}")

    def process_log_files(self, files):
        # Process the given list of log files in parallel using multi-threading or async/await
        with Pool() as pool:
            pool.map(self.process_log_file, files)

if __name__ == "__main__":
    aggregator = LogAggregator()
    files = ["log1.txt", "log2.txt", "log3.txt"]
    aggregator.process_log_files(files)']

