namespace DynamicCacheManager
{
    public class CacheGeneratorSettings
    {
        private readonly ILogger<CacheGeneratorSettings> _logger;
        private readonly int _minimumBound;
        private readonly int _maximumBound;
        private readonly float _distributionType;
        private readonly int _seed;

        public CacheGeneratorSettings(ILogger<CacheGeneratorSettings> logger, int minimumBound, int maximumBound, float distributionType, int seed)
        {
            _logger = logger;
            _minimumBound = minimumBound;
            _maximumBound = maximumBound;
            _distributionType = distributionType;
            _seed = seed;
        }

        public Random GetRandom()
        {
            return new Random(_seed);
        }
    }

    public class DynamicCacheGenerator
    {
        private readonly ILogger<DynamicCacheGenerator> _logger;
        private readonly CacheGeneratorSettings _settings;
        private readonly List<int> _cache = new List<int>();
        private readonly object _lock = new object();

        public DynamicCacheGenerator(ILogger<DynamicCacheGenerator> logger, CacheGeneratorSettings settings)
        {
            _logger = logger;
            _settings = settings;
        }

        public async Task<int> GenerateRandomIntAsync()
        {
            int value = 0;
            lock (_lock)
            {
                if (_cache.Count > 0)
                {
                    value = _cache[0];
                    _cache.RemoveAt(0);
                }
                else
                {
                    Random random = _settings.GetRandom();
                    int maximumBound = _settings._maximumBound;
                    if (_settings._distributionType == DistributionType.Uniform)
                    {
                        value = random.Next(0, maximumBound);
                    }
                    else if (_settings._distributionType == DistributionType.Normal)
                    {
                        double mean = (double)_minimumBound + ((double)_maximumBound - _minimumBound) / 2;
                        double standardDeviation = Math.Sqrt(((double)_maximumBound - _minimumBound) / 12);
                        value = (int)(random.NextGaussian(mean, standardDeviation) * maximumBound);
                    }
                }
            }
            return value;
        }

