Here is the Python code that would accomplish the same task as the previous Java example, using the `KafkaConsumer` class to subscribe to a Kafka topic and the `AnomalyDetectionEngineClient` class to perform anomaly detection on incoming messages. The `DataStoreServiceClient` class is used to add each message to a data store service.
```
import json
import logging
from kafka import KafkaConsumer
from anomaly_detection_engine.clients import AnomalyDetectionEngineClient
from data_store_service.clients import DataStoreServiceClient

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

def main():
    # Initialize Kafka consumer properties and create a new instance of the KafkaConsumer class
    bootstrap_servers = ['localhost:9092']
    group_id = 'my-consumer-group'
    auto_offset_reset = 'earliest'
    value_deserializer = lambda m: json.loads(m.decode('utf-8'))
    consumer = KafkaConsumer(bootstrap_servers=bootstrap_servers, group_id=group_id, auto_offset_reset=auto_offset_reset, value_deserializer=value_deserializer)

    # Subscribe to the data source topic
    topics = ['my-data-topic']
    consumer.subscribe(topics)

    # Initialize anomaly detection engine client properties and create a new instance of the AnomalyDetectionEngineClient class
    detection_engine_url = 'http://localhost:8080'
    model_id = 'my-model-id'
    api_timeout = 5000 # milliseconds
    detection_threshold = 0.9
    minimum_window_size = 10
    maximum_anomaly_age = 3600000 # milliseconds
    anomaly_detection_engine_client = AnomalyDetectionEngineClient(detection_engine_url, model_id)

    # Initialize data store service client properties and create a new instance of the DataStoreServiceClient class
    data_store_url = 'http://localhost:8081'
    topic_name = 'my-data-topic'
    batch_size = 5
    maximum_batch_age = 3600000 # milliseconds
    data_store_service_client = DataStoreServiceClient(data_store_url, topic_name)

    while True:
        try:
            messages = consumer.poll(1000)
            for message in messages:
                logger.info('Incoming message: {}'.format(message.value))
                try:
                    # Perform anomaly detection on the incoming message
                    response = anomaly_detection_engine_client.detect_anomalies(message.value)

                    if response != None and response['status'] == 200:
                        # Add the incoming message to the data store service client
                        data_store_service_client.add_data(message.value, batch_size, maximum_batch_age)
                    else:
                        logger.error('Error processing anomaly detection request')
                except Exception as e:
                    logger.error('Error processing incoming message', exc_info=True)
        except KeyboardInterrupt:
            break

if __name__ == '__main__':
    main()
