    std::mutex mutex_;

public:
    // Constructor to initialize the network event manager
    NetworkEventsManager() : events_(std::vector<NetworkEvent>()), mutex_(std::mutex()) {}

    // Function to enqueue a new network event
    void enqueueEvent(const NetworkEvent& event) {
        std::lock_guard<std::mutex> lock(mutex_);
        events_.emplace_back(event);
    }

    // Function to dequeue an event from the front of the queue
    bool dequeueEvent(NetworkEvent& event) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (events_.size() == 0) {
            return false;
        }

        event = events_.front();
        events_.erase(events_.begin());
        return true;
    }

    // Function to mark an event as processed
    void markEventProcessed(const NetworkEvent& event) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto it = events_.begin(); it != events_.end(); ++it) {
            if (*it == event) {
                it->setProcessed();
            }
        }
    }
