// Define a struct to hold the NFAPI_CRC_INDICATION_PDU_T data
typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    CRCFLAG crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a dynamic pool of NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    int size; // Size of the pool
    int capacity; // Capacity of the pool
    NFAPI_CRC_INDICATION_PDU_T* data; // Array to store the PDUs
    pthread_mutex_t mutex; // Mutex for thread-safe access
} CrcIndicationPool;

// Function to create a new pool of NFAPI_CRC_INDICATION_PDU_T structures
CrcIndicationPool* createPool(int capacity) {
    CrcIndicationPool* pool = (CrcIndicationPool*) malloc(sizeof(CrcIndicationPool));
    if (pool == NULL) {
        // Handle allocation failure
    }
    pool->size = 0;
    pool->capacity = capacity;
    pool->data = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * capacity);
    if (pool->data == NULL) {
        // Handle allocation failure
    }
    pthread_mutex_init(&pool->mutex, NULL);
    return pool;
}

// Function to destroy a pool of NFAPI_CRC_INDICATION_PDU_T structures
void destroyPool(CrcIndicationPool* pool) {
    if (pool == NULL) {
        return;
    }
    pthread_mutex_destroy(&pool->mutex);
    free(pool->data);
    free(pool);
}

// Function to add a new PDU to the pool
