class TextStreamProcessor:
    def __init__(self):
        self.event_queue = []
        self.processing_pipeline = []
        self.data_retention_policies = {}
        self.concurrency_lock = concurrent.futures.ThreadPoolExecutor(max_workers=300)

    def add_event(self, event):
        self.event_queue.append(event)

    def process_events(self):
        while len(self.event_queue) > 0:
            event = self.event_queue.pop()
            for processor in self.processing_pipeline:
                try:
                    event = processor.process(event)
                except Exception as e:
                    print("Error processing event", str(e))
                    break

    def add_processor(self, processor):
        self.processing_pipeline.append(processor)

    def remove_processor(self, processor):
        if processor in self.processing_pipeline:
            self.processing_pipeline.remove(processor)

    def set_data_retention_policy(self, policy):
        self.data_retention_policies[policy] = []

    def get_data_retention_policy(self, policy):
        if policy in self.data_retention_policies:
            return self.data_retention_policies[policy]
        else:
            return None

    def process_events_async(self):
        while len(self.event_queue) > 0:
            event = self.event_queue.pop()
            for processor in self.processing_pipeline:
                try:
                    future = self.concurrency_lock.submit(processor.process, event)
                    future.add_done_callback(self.on_future_complete)
                except Exception as e:
                    print("Error processing event", str(e))
                    break

    def on_future_complete(self, future):
        try:
            event = future.result()
            self.event_queue.append(event)
        except Exception as e:
            print("Error processing event", str(e))

    def wait_for_events(self, timeout=None):
        if len(self.event_queue) > 0:
            return True
        else:
            time.sleep(timeout)
            return False
