    }

    // Check if there are any pending requests to persist the data store
    if (datastore.num_pdus > 0 && time(NULL) - persistence_interval >= datastore.last_persist_time) {
      persist_pdus(&datastore);
    }

    // Generate a new random RNTI value and create a new cache entry
    uint16_t rnti = rand() % 65536;
    CACHE_ENTRY_T *cache_entry = malloc(sizeof(CACHE_ENTRY_T));
    cache_entry->pdu.rx_ue_information_tag = 0xFFFF; // Random value for the RX_UE_INFORMATION_TAG field
    cache_entry->pdu.rnti = rnti; // Set the RNTI value to the new random value
    cache_entry->pdu.crc_indication_rel8_tag = 0xFFFF; // Random value for the CRC_INDICATION_REL8_TAG field
    cache_entry->pdu.crcf = rand() % 256; // Set a random value for the CRCF field
    cache_entry->timestamp = time(NULL); // Set the timestamp to the current time
    cache_entry->in_use = 1; // Mark the entry as in use
    cache.num_entries++; // Increment the number of entries in the cache

