}

void cache_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
  // Acquire a lock on the cache and data store
  pthread_mutex_lock(&cache.mutex);
  pthread_mutex_lock(&datastore.mutex);

  // Check if the cache is full
  if (cache.num_entries == MAX_CACHE_SIZE) {
    handle_error("Cache is full");
    return;
  }

  // Generate a new random RNTI value and create a new cache entry
  uint16_t rnti = rand() % 65536;
  CACHE_ENTRY_T *cache_entry = malloc(sizeof(CACHE_ENTRY_T));
  cache_entry->pdu.rx_ue_information_tag = pdu->rx_ue_information_tag; // Copy the RX_UE_INFORMATION_TAG field from the given PDU
  cache_entry->pdu.rnti = rnti; // Set the RNTI value to the new random value
  cache_entry->pdu.crc_indication_rel8_tag = pdu->crc_indication_rel8_tag; // Copy the CRC_INDICATION_REL8_TAG field from the given PDU
  cache_entry->pdu.crcf = pdu->crcf; // Copy the CRCF field from the given PDU
  cache_entry->timestamp = time(NULL); // Set the timestamp to the current time
  cache_entry->in_use = 1; // Mark the entry as in use
  cache.num_entries++; // Increment the number of entries in the cache

  // Add the new cache entry to the cache
  cache.entries[cache.num_entries - 1] = cache_entry;

  // Release the lock on the cache and data store
  pthread_mutex_unlock(&datastore.mutex);
  pthread_mutex_unlock(&cache.mutex);

  // Log the creation of the new cache entry
  if (logging_level >= 1) {
    char message[256];
    sprintf(message, "New cache entry created with RNTI value %d", rnti);
    log(message);
  }
