void persist_pdus(DATASTORE_T *datastore) {
  // Acquire a lock on the data store
  pthread_mutex_lock(&datastore.mutex);

  // Persist the data store to disk
  FILE *fp = fopen("datastore.txt", "w");
  for (int i = 0; i < datastore->num_pdus; i++) {
    fprintf(fp, "%d %d %d %d\n", datastore->pdus[i].rx_ue_information_tag, datastore->pdus[i].rnti, datastore->pdus[i].crc_indication_rel8_tag, datastore->pdus[i].crcf);
  }
  fclose(fp);

  // Update the last persist time
  datastore->last_persist_time = time(NULL);

  // Release the lock on the data store
  pthread_mutex_unlock(&datastore.mutex);
}

void handle_error(char *message) {
  log(message);
  exit(1);
}

void log(char *message) {
