void log_message(const char* format, ...) {
    va_list args;
    va_start(args, format);

    int len = vsnprintf(NULL, 0, format, args);
    if (len < 0) {
        return;
    }

    char* buffer = malloc((size_t)len + 1);
    if (!buffer) {
        return;
    }

    vsnprintf(buffer, len + 1, format, args);
    va_end(args);

    // Write message to error log
    fputs(buffer, stderr);
    free(buffer);
}
