    public:
        Manager(int numPdus, unsigned seed, bool enableLogging, float backoffFactor) : numPdus_(numPdus), seed_(seed), enableLogging_(enableLogging), backoffFactor_(backoffFactor) {}

        ~Manager() {
            // Destructor implementation
        }

        void generatePdus(int numPdus) {
            for (int i = 0; i < numPdus; ++i) {
                PHY_TEST_PDU pdu;
                pdu.id = i;
                pdu.signalStrength = std::uniform_real_distribution<double>(0, 1)(rng_);
                pdu.dataPayload = "Hello World!";
                pdus_.push_back(pdu);
            }
        }

        void sendPdus() {
            for (const auto& pdu : pdus_) {
                std::cout << "Sending PDU: " << pdu.id << ", signal strength: " << pdu.signalStrength << ", data payload: " << pdu.dataPayload << std::endl;
            }
        }

        void configureBackoff(float backoffFactor) {
            this->backoffFactor_ = backoffFactor;
        }

