#include <chrono>
#include <thread>
#include <mutex>
#include <condition_variable>

using namespace std;

// Define constants for the aggregation rules and threshold value
const string AGGREGATION_RULES = "sum,avg,count";
const int THRESHOLD_VALUE = 100;

// Struct to represent a log entry
struct LogEntry {
    long timestamp;
    string data;
};

// Function to read the binary log file and parse its contents
void readLogFile(ifstream& input, vector<LogEntry>& entries) {
    // Read the log file line by line
    string line;
    while (getline(input, line)) {
        // Extract the timestamp and data from the current line
        long timestamp = stol(line.substr(0, 19));
        string data = line.substr(23);

        // Add the log entry to the vector of entries
        LogEntry entry;
        entry.timestamp = timestamp;
        entry.data = data;
        entries.push_back(entry);
    }
}

// Function to generate an aggregated report file from the parsed log data
void generateReportFile(const vector<LogEntry>& entries, const string& outputFile) {
    // Open the output file in write mode
    ofstream output(outputFile);

    // Create a map to store the aggregated statistics and anomaly detection results
    map<string, double> stats;
    vector<pair<string, int>> anomalies;

    // Iterate over the log entries and aggregate the data
    for (const LogEntry& entry : entries) {
        // Extract the timestamp and data from the current log entry
        long timestamp = entry.timestamp;
        string data = entry.data;

        // Update the aggregated statistics and anomaly detection results based on the given rules
        for (const string& rule : AGGREGATION_RULES) {
            if (rule == "sum") {
                stats[rule] += stod(data);
            } else if (rule == "avg") {
                stats[rule] = stats[rule] + stod(data);
            } else if (rule == "count") {
                ++stats[rule];
            }
        }

        // Check for anomalies based on the threshold value
        double value = stod(data);
        if (value > THRESHOLD_VALUE) {
            anomalies.push_back({data, timestamp});
        }
    }

    // Write the aggregated statistics and anomaly detection results to the output file
    for (const auto& entry : stats) {
        output << entry.first << " = " << entry.second << endl;
    }
    output << "Anomalies:" << endl;
    for (const auto& entry : anomalies) {
        output << entry.first << " at " << entry.second << endl;
    }
}

// Main function to read the log file, parse its contents, and generate an aggregated report file
int main(int argc, char* argv[]) {
    // Check the number of command-line arguments
    if (argc != 5) {
        cerr << "Usage: " << argv[0] << " <input log file> <output report file> <aggregation rules> <threshold value>" << endl;
        return 1;
    }

    // Read the input log file and parse its contents
    ifstream input(argv[1]);
    vector<LogEntry> entries;
    readLogFile(input, entries);

    // Generate the aggregated report file from the parsed log data
    generateReportFile(entries, argv[2]);

    return 0;
}
