import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.logging.Logger;

public class SecureStringProcessor {
    private static final Logger logger = Logger.getLogger(SecureStringProcessor.class.getName());

    // Truncate strings gracefully
    public String truncateToLength(String input, int maxLength) {
        if (input == null || input.length() <= maxLength) {
            return input;
        }

        int lastWordBoundary = 0;
        for (int i = 1; i <= maxLength; i++) {
            char c = input.charAt(i);
            if (c == ' ') {
                lastWordBoundary = i + 1;
            }
        }

        return input.substring(0, lastWordBoundary - 1) + "...";
    }

    // Hashing and validation
    private static final String HASHING_API_ENDPOINT = "https://third-party-hashing-api.com/hash";
    private static final int MAX_RETRIES = 3;
    private static final long BACKOFF_FACTOR = 2; // in milliseconds

    public void hashAndValidate(String input) {
        try {
            String truncatedInput = truncateToLength(input, MAX_LENGTH);
            String md5Hash = getMd5Hash(truncatedInput);
            if (!validateMd5Hash(md5Hash)) {
                throw new RuntimeException("Invalid MD5 hash: " + md5Hash);
            }
        } catch (IOException e) {
            logger.log(Level.WARNING, "Error hashing and validating input string", e);
        }
    }

    private String getMd5Hash(String input) throws IOException {
        String md5Hash = "";
        AtomicBoolean success = new AtomicBoolean();
        int retries = 0;

        while (!success.get() && retries < MAX_RETRIES) {
            try {
                HttpResponse<String> response = Unirest.post(HASHING_API_ENDPOINT)
                    .header("Content-Type", "application/json")
                    .body(input)
                    .asString();
                md5Hash = response.getBody();
                success.set(true);
            } catch (UnirestException e) {
                logger.log(Level.WARNING, "Error hashing input string", e);
                retries++;
                if (retries < MAX_RETRIES) {
                    try {
                        Thread.sleep(BACKOFF_FACTOR * retries);
                    } catch (InterruptedException ex) {
                        logger.log(Level.WARNING, "Error sleeping before retry", ex);
                    }
                }
            }
        }

        if (!success.get()) {
            throw new RuntimeException("Failed to hash input string after " + MAX_RETRIES + " retries");
        }

        return md5Hash;
    }

    private boolean validateMd5Hash(String md5Hash) throws IOException {
        try {
            HttpResponse<String> response = Unirest.get("https://third-party-hashing-api.com/validate")
                .queryString("md5", md5Hash)
                .asString();
            return response.getBody().equalsIgnoreCase("true");
        } catch (UnirestException e) {
            logger.log(Level.WARNING, "Error validating MD5 hash", e);
            return false;
        }
    }

    // Configuration management
    private static final String CONFIG_ENDPOINT = "https://config-service.com/config";
    private static final int MAX_CONFIGS = 3;

    public void loadConfigurations() {
        try {
            HttpResponse<String> response = Unirest.get(CONFIG_ENDPOINT)
                .queryString("oauth2", "bearer " + getOAuth2Token())
                .asString();
            String body = response.getBody();
            JSONObject configs = new JSONObject(body);
            if (configs != null && !configs.isEmpty() && configs.length() <= MAX_CONFIGS) {
