// Function to queue socket events and process them in parallel
void process_and_queue_socket_events(int max_events, int seed = -1) {
  // Initialize the worker threads
  for (int i = 0; i < max_events; ++i) {
    std::thread* thread = new std::thread(process_socket_event);
    worker_threads.push_back(thread);
  }

