  while (true) {
    // Retrieve an event from the message queue
    SocketEvent* event = retrieve_event();

    // Validate the event against predefined rules
    bool valid = validate_event(event);

    if (!valid) {
      // Log detailed error information if all retries fail
      std::stringstream err;
      err << "Error: Event validation failed for event " << event->id;
      log_error(err.str());
      continue;
    }

    // Acquire a lock on the event queue
    std::unique_lock<std::mutex> lock(event_queue_mutex);

    // Add the event to the queue
    event_queue.push(event);
    ++event_count;

    // Notify any waiting threads that an event has been added
    event_queue_cv.notify_all();
  }
}

