#include <sys/time.h>
#include <sys/stat.h>
#include <errno.h>

#define MAX_CACHE_SIZE 1000000
#define CACHE_ENTRY_EXPIRATION_TIME 60 // seconds
#define LOG_MESSAGE_LENGTH 4096

// Struct to represent cache entries
struct CacheEntry {
    char* file_path;
    struct stat stat_info;
    time_t expiration_time;
};

// Cache of recently accessed files
struct Cache {
    int size;
    struct CacheEntry* entries[MAX_CACHE_SIZE];
};

// Function to read and parse a file, returning the parsed contents as a string
char* read_and_parse_file(const char* file_path) {
    FILE* fp = fopen(file_path, "r");
    if (fp == NULL) {
        return NULL;
    }

    // Read the file into a buffer
    size_t file_size = 0;
    char* buffer = malloc(1);
    while (getc(fp) != EOF) {
        file_size++;
        buffer = realloc(buffer, file_size + 1);
        buffer[file_size - 1] = getc(fp);
        buffer[file_size] = '\0';
    }

    // Parse the contents of the file as a string
    char* parsed_contents = malloc(strlen(buffer));
    strcpy(parsed_contents, buffer);
    free(buffer);

    fclose(fp);

    return parsed_contents;
}

// Function to write an error message to the error log file
void log_critical_error(const char* message) {
    FILE* fp = fopen("error.log", "a");
    if (fp == NULL) {
        perror("Error opening error log file");
        return;
    }

    // Write the error message to the log file
    fprintf(fp, "%s\n", message);

    fclose(fp);
}

// Function to check if a cache entry is expired and needs to be updated
bool is_cache_entry_expired(struct CacheEntry* entry) {
    return time(NULL) > entry->expiration_time;
}

// Function to update a cache entry with the contents of a file
void update_cache_entry(const char* file_path, struct CacheEntry* entry) {
    // Read and parse the file
    char* parsed_contents = read_and_parse_file(file_path);
    if (parsed_contents == NULL) {
        log_critical_error("Failed to read or parse file");
        return;
    }

    entry->expiration_time = time(NULL) + CACHE_ENTRY_EXPIRATION_TIME;
    entry->file_path = malloc(strlen(file_path));
    strcpy(entry->file_path, file_path);
    entry->stat_info = stat(file_path, &entry->stat_info);
}

// Function to add a new cache entry for a file path
void add_cache_entry(const char* file_path) {
    // Check if the cache is full
    if (cache.size == MAX_CACHE_SIZE) {
        log_critical_error("Cache is full");
        return;
    }

    // Create a new cache entry for the file path
    struct CacheEntry* new_entry = malloc(sizeof(struct CacheEntry));
    update_cache_entry(file_path, new_entry);

    // Add the new cache entry to the cache
    cache.entries[cache.size] = new_entry;
    cache.size++;
}

// Function to find the largest and second-largest integers in a list of integers
void int_max_finder(int* list, size_t length) {
    // Initialize variables for the maximum and second-maximum values
    int max = INT_MIN;
    int second_max = INT_MIN;

    // Iterate over the list of integers and find the maximum and second-maximum values
    for (size_t i = 0; i < length; i++) {
        if (list[i] > max) {
            second_max = max;
            max = list[i];
        } else if (list[i] > second_max) {
            second_max = list[i];
        }
    }

    // Print the maximum and second-maximum values
    printf("Maximum: %d\n", max);
    printf("Second Maximum: %d\n", second_max);
}

// Function to process a file and find the largest and second-largest integers in it
void process_file(const char* file_path) {
    // Read and parse the file
    char* parsed_contents = read_and_parse_file(file_path);
    if (parsed_contents == NULL) {
        log_critical_error("Failed to read or parse file");
        return;
    }

    // Convert the contents of the file to a list of integers
    int* list = malloc(length * sizeof(int));
    for (size_t i = 0; i < length; i++) {
        list[i] = atoi(parsed_contents);
    }

    // Find the largest and second-largest integers in the list
    int_max_finder(list, length);
}

// Function to handle a request for a file path
void handle_request(const char* file_path) {
    // Check if the cache contains an entry for the requested file path
    struct CacheEntry* entry = get_cache_entry(file_path);
    if (entry != NULL && !is_cache_entry_expired(entry)) {
        // Print the contents of the cache entry
        process_file(entry->file_path);
    } else {
        // Add a new cache entry for the requested file path and process it
        add_cache_entry(file_path);
        process_file(file_path);
    }
}

// Function to handle multiple requests in parallel
void handle_multiple_requests(size_t num_requests) {
    // Create a list of file paths for the requests
    char* file_paths[num_requests];

    // Read and parse the file paths from stdin
    for (size_t i = 0; i < num_requests; i++) {
        scanf("%s", &file_paths[i]);
    }

    // Handle each request in parallel
    #pragma omp parallel for schedule(dynamic)
    for (size_t i = 0; i < num_requests; i++) {
        handle_request(file_paths[i]);
    }
}
