NFAPI_CRC_INDICATION_PDU_T* generateNfapiPduList(int n, int seed, int maxRnti) {
    // Initialize thread-safe random number generator with seed value
    srand(seed);

    // Allocate memory for array of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* pduList = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * n);
    if (!pduList) {
        printf("Error: Failed to allocate memory for NFAPI PDU list\n");
        return NULL;
    }

    // Initialize RX_UE_INFORMATION_TAG and CRC_INDICATION_REL8_TAG values randomly
    for (int i = 0; i < n; i++) {
