        pduList[i].crcIndicationRel8Tag.length = sizeof(CRC_INDICATION_REL8_TAG);
        pduList[i].crcIndicationRel8Tag.crcFlag = (rand() % 2) ? true : false; // Generate random CRCFLAG value
