                } else {
                    retry = false; // If data retrieval fails, break and retry later
                    break;
                }
            }
        }
        retries++;
    }
    if (retries >= 5 && !retry) {
        printf("Error: Exceeded maximum number of retries when retrieving predefined RX_UE_INFORMATION_TAG values\n");
        free(pduList); // Free memory if data retrieval fails too many times
        return NULL;
    }

    // Handle potential integration issues with external data source and implement error handling
    if (retry) {
        printf("Warning: Retried data retrieval %d time(s) before successfully integrating with external data source\n", retries - 1);
    } else if (!retry && !rntiUnique[pduList[i].rnti]) {
        printf("Error: Failed to integrate with external data source when retrieving predefined RX_UE_INFORMATION_TAG values\n");
        free(pduList); // Free memory if data integration fails
        return NULL;
    }

    pthread_mutex_unlock(&mutex);
    return pduList;
