    int sourceID;
    int destinationID;
    size_t dataSize;
} EventDetails;

// Define the function to initialize a dynamic list of NetworkEventPayload structures
void initNetworkEventList(size_t capacity, int* err) {
    // Check if the given capacity is valid and if it's within the limits of the current implementation
    if (capacity <= 0 || capacity > MAXIMUM_EVENT_CAPACITY) {
        *err = INVALID_EVENT_CAPACITY;
        return;
    }

    // Initialize the list with the given capacity
    NetworkEventPayload* eventList = (NetworkEventPayload*) malloc(sizeof(NetworkEventPayload) * capacity);
    if (!eventList) {
        *err = MEMORY_ALLOCATION_FAILED;
        return;
    }

    // Initialize the list with null elements
    for (size_t i = 0; i < capacity; ++i) {
        eventList[i].timestamp = 0;
        eventList[i].eventType = 0;
        memset(&(eventList[i].eventDetails), 0, sizeof(EventDetails));
    }

    // Set the initial size of the list to zero
    *size = 0;

    // Initialize the lock for concurrent access
    pthread_mutex_init(&lock, NULL);
}

// Define the function to add an event to the list
void addEvent(NetworkEventPayload* event, int* err) {
    // Check if the list is initialized and if it's within the limits of the current implementation
    if (!eventList || capacity <= 0 || capacity > MAXIMUM_EVENT_CAPACITY) {
        *err = INVALID_EVENT_LIST;
        return;
    }

    // Lock the list for concurrent access
    pthread_mutex_lock(&lock);

    // Check if the list is full and if it's within the limits of the current implementation
    if (*size == capacity) {
        *err = LIST_FULL;
        goto unlock;
    }

    // Copy the event to the next available position in the list
    memcpy(&eventList[*size], event, sizeof(NetworkEventPayload));

    // Increment the size of the list by one
    *size = *size + 1;

    // Unlock the list for concurrent access
unlock:
    pthread_mutex_unlock(&lock);
}

// Define the function to remove an event from the list
void removeEvent(NetworkEventPayload* event, int* err) {
    // Check if the list is initialized and if it's within the limits of the current implementation
    if (!eventList || capacity <= 0 || capacity > MAXIMUM_EVENT_CAPACITY) {
        *err = INVALID_EVENT_LIST;
        return;
    }

    // Lock the list for concurrent access
    pthread_mutex_lock(&lock);

    // Check if the event is present in the list and if it's within the limits of the current implementation
    size_t index = 0;
    while (index < *size && memcmp(&eventList[index], event, sizeof(NetworkEventPayload)) != 0) {
        index++;
    }
    if (index == *size) {
        *err = EVENT_NOT_FOUND;
        goto unlock;
    }

    // Shift the elements in the list one position to the left, starting from the removed event
    for (size_t i = index; i < *size - 1; ++i) {
        memcpy(&eventList[i], &eventList[i + 1], sizeof(NetworkEventPayload));
    }

    // Decrement the size of the list by one
    *size = *size - 1;

    // Unlock the list for concurrent access
unlock:
    pthread_mutex_unlock(&lock);
}

// Define the function to clear the list of events
void clearEvents(int* err) {
    // Check if the list is initialized and if it's within the limits of the current implementation
    if (!eventList || capacity <= 0 || capacity > MAXIMUM_EVENT_CAPACITY) {
        *err = INVALID_EVENT_LIST;
        return;
    }

    // Lock the list for concurrent access
    pthread_mutex_lock(&lock);

    // Clear the list of events by setting its size to zero
    *size = 0;

    // Unlock the list for concurrent access
    pthread_mutex_unlock(&lock);
}

// Define the function to print all the events in the list
