    if (!eventList || capacity <= 0 || capacity > MAXIMUM_EVENT_CAPACITY) {
        *err = INVALID_EVENT_LIST;
        return;
    }

    // Lock the list for concurrent access
    pthread_mutex_lock(&lock);

    // Print all the events in the list
