using namespace std;

// Custom concurrency control mechanism to minimize blocking and deadlocks.
class ResourceCache {
public:
    ResourceCache() {}

    // Add a new metric object to the cache.
    void addMetric(const ResourceUsageMetrics& metrics) {
        unique_lock<mutex> lock(_mutex);
        _metrics.push_back(metrics);
    }

    // Retrieve a specific metric object from the cache by timestamp.
    vector<ResourceUsageMetrics> getMetrics(int64_t timestamp) {
        unique_lock<mutex> lock(_mutex);
        vector<ResourceUsageMetrics> result;
        for (auto it = _metrics.begin(); it != _metrics.end(); ++it) {
            if ((*it).timestamp == timestamp) {
                result.push_back(*it);
            }
        }
        return result;
    }

    // Remove a specific metric object from the cache by timestamp.
    void removeMetric(int64_t timestamp) {
        unique_lock<mutex> lock(_mutex);
        for (auto it = _metrics.begin(); it != _metrics.end(); ++it) {
            if ((*it).timestamp == timestamp) {
                _metrics.erase(it);
                break;
            }
        }
    }

private:
    mutex _mutex;
    vector<ResourceUsageMetrics> _metrics;
};

// ResourceUsageMetrics class to store CPU usage, memory consumption, network I/O, and disk I/O.
class ResourceUsageMetrics {
public:
    int64_t timestamp;
    double cpuUsage;
    uint64_t memoryConsumption;
    uint64_t networkIO;
    uint64_t diskIO;
};

// Average, peak, and variance calculations for each metric type.
class MetricAggregator {
public:
    MetricAggregator() {}

    // Add a new metric object to the aggregator.
    void addMetric(const ResourceUsageMetrics& metrics) {
        unique_lock<mutex> lock(_mutex);
        _metrics.push_back(metrics);
        if (_metrics.size() > 1000) { // Threshold to prevent too much data in the cache.
            _metrics.pop_front();
        }
    }

    // Calculate and return the average value for a specific metric type.
    double getAverage(int64_t timestamp, MetricType type) {
        unique_lock<mutex> lock(_mutex);
        vector<ResourceUsageMetrics> metrics = getMetrics(timestamp);
        if (metrics.empty()) {
            return 0;
        }
        double sum = 0;
        for (auto it = metrics.begin(); it != metrics.end(); ++it) {
            sum += (*it).type == type ? (*it).value : 0;
        }
        return sum / metrics.size();
    }

    // Calculate and return the peak value for a specific metric type.
    double getPeak(int64_t timestamp, MetricType type) {
        unique_lock<mutex> lock(_mutex);
        vector<ResourceUsageMetrics> metrics = getMetrics(timestamp);
        if (metrics.empty()) {
            return 0;
        }
        double max = -1e30; // Initialize to a very small negative value.
        for (auto it = metrics.begin(); it != metrics.end(); ++it) {
            if ((*it).type == type && (*it).value > max) {
                max = (*it).value;
            }
        }
        return max;
    }

    // Calculate and return the variance for a specific metric type.
    double getVariance(int64_t timestamp, MetricType type) {
        unique_lock<mutex> lock(_mutex);
        vector<ResourceUsageMetrics> metrics = getMetrics(timestamp);
        if (metrics.empty()) {
            return 0;
        }
        double avg = getAverage(timestamp, type);
        double sum = 0;
        for (auto it = metrics.begin(); it != metrics.end(); ++it) {
            sum += pow((*it).type == type ? (*it).value - avg : 0, 2);
        }
        return sum / metrics.size() - 1;
    }

private:
    mutex _mutex;
    deque<ResourceUsageMetrics> _metrics;
};

// Eviction policy to dynamically adjust based on configurable time and size thresholds.
class EvictionPolicy {
public:
    EvictionPolicy(double timeThreshold, uint64_t sizeThreshold) {
        _timeThreshold = timeThreshold;
        _sizeThreshold = sizeThreshold;
    }

    // Check if a metric object should be evicted based on the policy.
    bool shouldEvict(const ResourceUsageMetrics& metrics) {
        return (metrics.timestamp < chrono::duration_cast<chrono::seconds>(chrono::steady_clock::now() - _timeThreshold).count()) ||
               (metrics.size > _sizeThreshold);
    }
};

// Main class to manage the cache and handle monitoring service interactions.
class ResourceCacheManager {
public:
    ResourceCacheManager(const vector<MonitoringService>& services) : _services(services) {}

    // Add a new metric object to the cache and notify the monitoring services.
    void addMetric(const ResourceUsageMetrics& metrics) {
        unique_lock<mutex> lock(_mutex);
        _cache.addMetric(metrics);
        for (auto service : _services) {
            if (!service->sendMetrics(metrics)) { // Send the metric to the monitoring service.
                cerr << "Failed to send metrics to monitoring service: " << service->getName() << endl;
            }
        }
    }

    // Retrieve a specific metric object from the cache by timestamp and notify the monitoring services.
    vector<ResourceUsageMetrics> getMetrics(int64_t timestamp) {
        unique_lock<mutex> lock(_mutex);
        auto metrics = _cache.getMetrics(timestamp);
        for (auto service : _services) {
            if (!service->sendMetrics(metrics)) { // Send the metric to the monitoring service.
                cerr << "Failed to send metrics to monitoring service: " << service->getName() << endl;
            }
        }
        return metrics;
    }

    // Calculate and return the average value for a specific metric type based on the cache.
    double getAverage(int64_t timestamp, MetricType type) {
        unique_lock<mutex> lock(_mutex);
        return _cache.getAverage(timestamp, type);
    }

    // Calculate and return the peak value for a specific metric type based on the cache.
    double getPeak(int64_t timestamp, MetricType type) {
        unique_lock<mutex> lock(_mutex);
        return _cache.getPeak(timestamp, type);
    }

    // Calculate and return the variance for a specific metric type based on the cache.
    double getVariance(int64_t timestamp, MetricType type) {
        unique_lock<mutex> lock(_mutex);
        return _cache.getVariance(timestamp, type);
    }

private:
    mutex _mutex; // Mutex to protect the cache and monitoring services.
    ResourceCache _cache; // Cache for the resource usage metrics.
    vector<MonitoringService> _services; // Vector of monitoring services to notify.
};
