    vector<MonitoringService> services = {
        new MonitoringService("service1", "localhost", 8080),
        new MonitoringService("service2", "localhost", 8081)
    };
    ResourceCacheManager cache(services);

    // Add some resource usage metrics to the cache.
    ResourceUsageMetrics metrics;
    metrics.cpu = 50;
    metrics.memory = 1000;
    metrics.disk = 2000;
