```c
#include <iostream>
#include <vector>
#include <map>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <future>

using namespace std;

// Metric types
enum class MetricType {
    CPU,
    MEMORY,
    NETWORK,
    DISK
};

// Metric data structure
struct Metric {
    MetricType type;
    unsigned long timestamp;
    double value;
};

// Cache data structure
struct CacheEntry {
    Metric metric;
    unsigned int frequency;
    unsigned int lastAccessTime;
};

// Eviction policy
enum class EvictionPolicy {
    LRU,
    LFU
};

// Cache implementation
class ResourceUsageCache {
public:
    ResourceUsageCache(unsigned int size = 1024) : cacheSize_(size), evictionPolicy_(EvictionPolicy::LRU) {}

    // Adds a new metric to the cache
    void addMetric(const Metric& metric) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (cache_.size() >= cacheSize_) {
            evict();
        }
        CacheEntry entry;
        entry.metric = metric;
        entry.frequency = 0;
        entry.lastAccessTime = chrono::system_clock::now().time_since_epoch().count();
        cache_.push_back(entry);
    }

    // Retrieves a metric from the cache by type and timestamp
    Metric getMetric(const MetricType& type, const unsigned long& timestamp) {
        std::unique_lock<std::mutex> lock(mutex_);
        for (auto it = cache_.begin(); it != cache_.end(); ++it) {
            if (it->metric.type == type && it->metric.timestamp == timestamp) {
                updateFrequency(it, 1);
                return it->metric;
            }
        }
        return Metric{};
    }

    // Removes a metric from the cache by type and timestamp
    void removeMetric(const MetricType& type, const unsigned long& timestamp) {
        std::unique_lock<std::mutex> lock(mutex_);
        for (auto it = cache_.begin(); it != cache_.end(); ++it) {
            if (it->metric.type == type && it->metric.timestamp == timestamp) {
                cache_.erase(it);
                return;
            }
        }
    }

private:
    // Evicts the least frequently used metric from the cache
    void evict() {
        std::unique_lock<std::mutex> lock(mutex_);
        auto it = std::max_element(cache_.begin(), cache_.end(), [](const CacheEntry& a, const CacheEntry& b) {
            return a.frequency < b.frequency;
        });
        if (it != cache_.end()) {
            cache_.erase(it);
        }
    }

    // Updates the frequency of a metric in the cache
    void updateFrequency(CacheEntry& entry, unsigned int delta) {
        std::unique_lock<std::mutex> lock(mutex_);
        entry.frequency += delta;
    }

    // Cache size
    const unsigned int cacheSize_;

    // Eviction policy
    const EvictionPolicy evictionPolicy_;

    // Mutex for thread safety
    std::mutex mutex_;

    // Vector of cache entries
    std::vector<CacheEntry> cache_;
};

// Main function
int main() {
    ResourceUsageCache cache(1024);

    // Add some metrics to the cache
    Metric cpuMetric{MetricType::CPU, 1586396574, 1.2};
    cache.addMetric(cpuMetric);
    Metric memoryMetric{MetricType::MEMORY, 1586396574, 1024};
    cache.addMetric(memoryMetric);
    Metric networkMetric{MetricType::NETWORK, 1586396574, 1024};
    cache.addMetric(networkMetric);
    Metric diskMetric{MetricType::DISK, 1586396574, 1024};
    cache.addMetric(diskMetric);

    // Retrieve a metric from the cache by type and timestamp
    Metric retrievedMetric = cache.getMetric(MetricType::CPU, 1586396574);

    // Remove a metric from the cache by type and timestamp
    cache.removeMetric(MetricType::MEMORY, 1586396574);

    return 0;
}
```
This implementation uses a vector of `CacheEntry` objects to store the metrics in the cache. Each `CacheEntry` object contains a `Metric` object, an integer frequency field to track how frequently the metric is accessed, and an integer timestamp field for easy retrieval by type and timestamp. The eviction policy can be set to either LRU (Least Recently Used) or LFU (Least Frequently Used), with tunable parameters for cache performance.

The `addMetric()` method adds a new metric to the cache, while the `getMetric()` method retrieves a metric from the cache by type and timestamp. The `removeMetric()` method removes a metric from the cache by type and timestamp.

All methods are thread-safe using a mutex for synchronization.']

