    new_pdu->RNTI = RNTI;
    new_pdu->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;

    // Add the new PDU to the array of PDUS
    pdu_array[num_pdus++] = new_pdu;

    return new_pdu;
}

// Function to retrieve a PDU from the list by RNTI
NFAPI_CRC_INDICATION_PDU_T* nfapi_pdu_manager_get_pdu(uint32_t RNTI) {
    // Iterate through the array of PDUS and find the one with the matching RNTI
    for (int i = 0; i < num_pdus; i++) {
        if (pdu_array[i]->RNTI == RNTI) {
            return pdu_array[i];
        }
    }

    // If no PDU was found, return NULL
    return NULL;
}

// Function to update a PDU in the list by RNTI
void nfapi_pdu_manager_update_pdu(uint32_t RNTI, uint16_t CRC_INDICATION_REL8_TAG) {
    // Find the PDU with the matching RNTI and update its CRC_INDICATION_REL8_TAG
    NFAPI_CRC_INDICATION_PDU_T* pdu = nfapi_pdu_manager_get_pdu(RNTI);
    if (pdu != NULL) {
        pdu->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    }
}

