void nfapi_pdu_manager_remove_pdu(uint32_t RNTI) {
    // Find the index of the PDU with the matching RNTI and remove it from the array
    for (int i = 0; i < num_pdus; i++) {
        if (pdu_array[i]->RNTI == RNTI) {
            free(pdu_array[i]);
            pdu_array[i] = pdu_array[--num_pdus];
            return;
        }
    }
}

// Function to retrieve the number of PDUS in the list
