        for (size_t i = 0; i < list->size - 1; i++) {
            if (list->data[i + 1] == data) {
                list->data[i] = list->data[i + 1];
            }
        }

        // Decrease the size of the list
        list->size--;
    }

    // Unlock the list
    pthread_mutex_unlock(&list->mutex);

    return 0;
}
