    int rnti;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Structure to store the cache data
typedef struct {
    int size;
    NFAPI_CRC_INDICATION_PDU_T *data;
} CACHE_T;

// Function to generate a random CRCFlag
bool generateCRCFlag(int seed) {
    // Generate a random number between 0 and 1 using the provided seed
    double r = rand() / (double) RAND_MAX;

    // Return true if the generated number is less than or equal to the threshold
    return r <= 0.5;
}

// Function to add a PDU to the cache
void addToCache(CACHE_T *cache, NFAPI_CRC_INDICATION_PDU_T pdu) {
    // Check if the cache is full
    if (cache->size == cache->data->capacity) {
        // If so, evict the oldest entry
        int index = 0;
        for (int i = 1; i < cache->size; i++) {
            if (cache->data[i].rx_ue_information_tag > cache->data[index].rx_ue_information_tag) {
                index = i;
            }
        }

        // Remove the evicted entry from the cache
        free(cache->data[index]);
        memmove(&cache->data[index], &cache->data[index + 1], (cache->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        cache->size--;
    }

    // Add the new PDU to the cache
    cache->data = realloc(cache->data, (cache->size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    memcpy(&cache->data[cache->size], &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    cache->size++;
}

// Function to retrieve a PDU from the cache
NFAPI_CRC_INDICATION_PDU_T *getFromCache(CACHE_T *cache, int rx_ue_information_tag) {
    // Iterate through the cache entries and find the matching one
    for (int i = 0; i < cache->size; i++) {
        if (cache->data[i].rx_ue_information_tag == rx_ue_information_tag) {
            return &cache->data[i];
        }
    }

    // If no matching entry is found, return NULL
    return NULL;
}

// Function to update the cache with new data
void updateCache(CACHE_T *cache, NFAPI_CRC_INDICATION_PDU_T pdu) {
    // Check if the PDU exists in the cache already
    int index = 0;
    for (int i = 1; i < cache->size; i++) {
        if (cache->data[i].rx_ue_information_tag == pdu.rx_ue_information_tag) {
            index = i;
            break;
        }
    }

    // If the PDU is already in the cache, update it
    if (index != 0) {
        memcpy(&cache->data[index], &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    } else {
        addToCache(cache, pdu);
    }
}

// Function to retrieve the largest integer in an array
int getLargestInteger(int *array, int size) {
    if (size == 0) {
        return INT_MIN;
    } else {
        return array[0];
    }
}

// Function to read a list of integers from standard input and print the largest one to standard output
void printLargestInteger(int n) {
    int *array = malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) {
        scanf("%d", &array[i]);
    }

    int largest = getLargestInteger(array, n);
    printf("%d\n", largest);

    free(array);
}

// Function to handle allocation failures and invalid inputs
void handleError(int error_code) {
    if (error_code == -1) {
        fprintf(stderr, "Allocation failure!\n");
    } else if (error_code == -2) {
        fprintf(stderr, "Invalid input!\n");
    }
}
