        token[i] = 'a' + (rand() % 26);
    }
    token[length] = '\0';
    return token;
}

// Function to generate a random refresh token
char* generate_refresh_token(int length) {
    char* token = (char*)malloc(length + 1);
    for (int i = 0; i < length; ++i) {
        token[i] = 'a' + (rand() % 26);
    }
    token[length] = '\0';
    return token;
}

