// Define the EventStructure struct to store event data
struct EventStructure {
    int timestamp;
    int sourceID;
    std::string category;
};

// Define a vector to store events
std::vector<EventStructure> events;

// Define a mutex and condition variable for thread-safe access to the event list
std::mutex mtx;
std::condition_variable cv;

// Define a timestamp generator class to generate unique timestamps
class TimestampGenerator {
public:
    int getTimestamp() {
        return std::chrono::high_resolution_clock::now().time_since_epoch().count();
    }
};

// Define a thread-safe event queue class to handle events in parallel
class EventQueue {
public:
    void push(EventStructure event) {
        std::unique_lock<std::mutex> lock(mtx);
        events.push_back(event);
        cv.notify_all();
    }

    void pop() {
        std::unique_lock<std::mutex> lock(mtx);
        if (!events.empty()) {
            EventStructure event = events[0];
            events.erase(events.begin());
            return event;
        }
        cv.wait(lock, [this] { return !events.empty(); });
    }
};

// Define a connection pool class to manage external connections
class ConnectionPool {
public:
    void addConnection(int connection) {
        std::unique_lock<std::mutex> lock(mtx);
        availableConnections.push_back(connection);
        cv.notify_all();
    }

    int getAvailableConnection() {
        std::unique_lock<std::mutex> lock(mtx);
        if (!availableConnections.empty()) {
            int connection = availableConnections[0];
            availableConnections.erase(availableConnections.begin());
            return connection;
        }
        cv.wait(lock, [this] { return !availableConnections.empty(); });
    }

private:
