        cache[event.timestamp].push_back(event);
        cv.notify_all();
    }

    std::vector<EventStructure> getEvents(int timestamp) {
        std::unique_lock<std::mutex> lock(mtx);
        if (cache.find(timestamp) != cache.end()) {
            return cache[timestamp];
        }
        cv.wait(lock, [this] { return !cache.empty(); });
    }

private:
    std::unordered_map<int, std::vector<EventStructure>> cache;
};

// Define a filtering mechanism class to filter events based on policies
class EventFilter {
